
INSERT INTO recipes (id, title, date, description, cooking_time, serving_size) VALUES
(251, '涼拌雞絲粉皮食譜', '2012-02-12', '在炎熱的天氣底下，一道富有中國地道特色的涼拌粉來得特別消暑。而眾多材料配搭和做法之中最受歡迎的一直都是今天這道涼拌雞絲粉皮，這道菜以青瓜和雞絲作配菜，拌上香滑的花生醬，不但別有風味而且更加是夏天的消暑佳品呢。', '', ' 2人'),
(257, '南瓜燜排骨', '2012-02-12', '我們常常喜歡在秋天吃南瓜。大多數朋友都愛吃南瓜甜點。但很少有人知道，南瓜​​其實適合多款豐富可口的菜餚。這南瓜燜排骨是一道很容易又美味的家常菜。如果你想在今年秋冬季嘗試新的菜式，就不妨嘗試我們的南瓜燜排骨吧。', '', ' 2人'),
(255, '韭蔥炒蛋', '2012-02-12', '除了中國菜之外，韭蔥都經常被用到日本菜和韓國菜當中。初吃韭蔥的人會發覺他有一種獨特帶點辣的味道，通常能為菜餚添上一種帶點甜味的口感。今次我們就是用韭蔥代替了平常慣用的洋蔥，做成一道美味又簡單的韭蔥炒蛋。', '', ' 2人'),
(248, '潮州沙爹牛河', '2012-02-12', '這款沙爹牛河是潮州的地道菜，主要是以沙爹醬炒以牛肉和河粉，而在這款食譜中則以白菜仔取代傳統慣用的芥蘭。', '', ' 2人'),
(249, '港式咖哩牛腩', '2012-02-12', '相信很多香港人都喜歡吃咖哩，其中當然以咖哩牛腩配以白飯或麵最受歡迎。雖然要煮出一鍋香濃軟熟的咖哩牛腩通常都得花上比較長的時間，但是當咖哩煮好的時候，那種香味和口感實在令人食指大動。今天這道咖哩牛腩的食譜雖然並不是以椰汁作佐料，但是椰汁可以減低咖哩的辣味，迎合不吃辣的朋友。', '', ' 3人'),
(252, '蠔油牛肉炒西蘭花', '2012-02-12', '今次我們要介紹的這道蠔油炒西蘭花不單是中國家庭中常見的家常菜,而且也是其中一道在國外也大行其道的常見中菜。蠔油炒西蘭花不單有營養而且味道鮮甜，既可口又健康。', '', ' 2人'),
(1249, '年年有魚', '2017-01-27', '農曆新年食譜', '', '2人'),
(1247, '八寶飯', '2017-01-29', '過年少不了的甜點農曆新年食譜', '1.5小時', ' 3人'),
(1608, '自家製牛肉腸粉', '2013-04-29', '', '30分鐘', ''),
(1244, '合家團圓', '2017-01-29', '----四喜丸子農曆新年食譜', '1小時', ' 4人'),
(94, '中式涼拌雞絲粉皮', '2011-12-03', '在炎熱的天氣底下，一道富有中國地道特色的涼拌粉來得特別消暑。而眾多材料配搭和做法之中最受歡迎的一直都是今天這道涼拌雞絲粉皮，這道菜以青瓜和雞絲作配菜，拌上香滑的花生醬，不但別有風味而且更加是夏天的消暑佳品呢。', '30分鐘', '2人'),
(98, '番茄煮紅衫魚', '2011-12-12', '如果你的小朋友不愛吃魚，你一定要試試這個食譜。我們用的是紅衫魚。紅衫魚是白魚。他們的肉質鮮嫩多汁，而且和濃郁的番茄醬很配。如果想為家人帶來更多的驚喜，你可以嘗試把魚肉起骨，讓小孩子更容易食。', '30分鐘', '2人'),
(102, '綠茶大理石蛋糕', '2011-12-27', '這種蛋糕漂亮而做法非常容易 ！這絕對是眾人的首選綠茶蛋糕食譜。一邊吃一邊喝一杯咖啡或是一杯冷牛奶就最配了 ！', '1.5小時', '3人'),
(103, '奶油芝士熱狗食譜', '2012-01-02', '我們熱愛這些奶油芝士熱狗。他們能作為一個簡單的孩子下午小食，甚至也是一個完整的快速早餐的理想選擇。最好吃的部分是奶油芝士！', '10分鐘', '2人'),
(104, '三文魚紅咖喱', '2012-01-02', '這咖哩是超級容易做的。你可以隨時隨意在 30 分鐘內準備一頓美餐!', '30分鐘', '2人'),
(119, '韓式煎餅', '2012-01-15', '這種又辣又香又美味的小食是傳統的韓國家庭料理。韓國人通常在下雨天為小孩子做這些煎餅。真的很有心思！', '30分鐘', '2人'),
(120, '韓國泡菜湯（豬肉版)', '2012-01-15', '韓國泡菜湯食譜可以好很多不同的做法。這個食譜使用了五花肉和少許奶來為這個湯變得更農而味道更加豐富。', '1小時', '2人'),
(121, '韓式炒牛肉', '2012-01-15', '傳統韓國用牛肉爲主的家常菜。配一大碗飯最佳的。', '1小時', '2人'),
(122, '火腿芝士庵列', '2012-01-15', '星期天或是平日大受歡迎的簡易火腿芝士庵列。', '30分鐘', '1人'),
(124, '肥牛香菇喇沙', '2012-01-15', '我們很愛吃喇沙湯麵。找到這個湯包之後，我們可以隨時都能夠輕鬆的煮一碗溫暖又美味的喇沙湯麵啦。', '30分鐘', '1人'),
(125, '素菜咖喱', '2012-01-15', '方便又好吃的超簡單\"半自家制\"素咖喱。', '30分鐘', '2人'),
(173, '日本炸豬排', '2012-01-21', '日式炸豬排是很容易準備！秘密是得到最新鮮的日本豬排（可在專賣店購買）！', '1小時', '2人'),
(175, '中式蝦仁炒蛋', '2012-01-22', '要在雞蛋全熟之前上碟。蝦仁含有豐富的蛋白質、鉀、碘、鎂、磷等礦物質及維生素A、氨茶鹼等成分，易消化，對健康極有裨益。', '30分鐘', '2人'),
(176, '潮州鹵水五花腩', '2012-01-22', '潮州鹵水食品包括許多令人垂涎的美食，有鹵水鵝、掌翼、五花腩、大腸等，都是飲酒佐膳的佳餚。這個簡易的鹵水五花腩食譜做法容易，味道香濃。下次煮飯時不妨試試啦！', '1.5小時', '2人'),
(177, '港式咖哩雞', '2012-01-23', '有許多品種的咖哩....印度，泰國和香港等。我們的食譜有豐富的椰奶味。做法簡單的和美味，適合做一個人的晚餐或者煮一大鍋作派對菜式也很配。', '1小時', '3人'),
(178, '炒豆乾肉絲', '2012-01-23', '豆干肉絲是另外一道家常菜。它是上海菜。做法簡單而味道較濃。喜歡吃辣的朋友就可以加點小辣椒，味道更香濃！', '30分鐘', '1人'),
(180, '朱古力布丁撻', '2012-01-23', '濃郁的朱古力布丁，脆酥餅底，配上新鮮奶油。超好味。', '1小時', '2人'),
(182, '草莓瑞士卷', '2012-01-23', '我們愛瑞士卷或果凍卷。它是一種海綿蛋糕卷。蛋糕是由雞蛋、 麵粉和糖，並在一個很淺的矩形烤盤烤。蛋糕上加果醬、 新鮮的水果或奶油、 卷起，和切成圓片。蛋糕源自從中央歐洲。', '1.5小時', '3人'),
(183, '香蕉核桃蛋糕', '2012-01-23', '香蕉蛋糕是软绵绵和甜甜的。主要的食材是用搗碎的香蕉。它是[快速麵包]的一種。因為做法简易因而使香蕉麵包大受歡迎。香蕉蛋糕味道可口，有益健康，及營養豐富。', '1小時', '2人'),
(184, '黑胡椒牛肉', '2012-01-23', '牛肉不是中菜中受歡迎的肉類。很少食譜會用到牛肉。在用紅肉烹調的菜式當中，黑胡椒牛肉很受歡迎。味道香濃和加用了有益的青紅椒。', '30分鐘', '1人'),
(185, '金菇肥牛肉卷', '2012-01-23', '這道菜看起來像很多功夫，但其實做法非常容易。\n\n<十五分鐘懶人版｜燒汁金菇豬肉卷>\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\n立即落單：燒汁金菇豬肉卷', '30分鐘', '2人'),
(186, '意大利菇拌麵', '2012-01-24', '美味的花生醬汁使這個冷麵食譜能成爲一份完美的下午小點心。', '30分鐘', '1人'),
(187, '潮州芥蘭炒飯', '2012-01-24', '原產於中國廣東省的芥蘭是很有中式風味的蔬菜，形態分枝挺直，帶有獨特風味，潮州菜中常會見到它的蹤影。將爽脆的芥蘭莖切粒，加入白飯中同炒，配以有潮州特色的橄欖菜調味，就可以成為簡單的午餐或晚餐。', '30分鐘', '2人'),
(188, '自家制芝士漢堡', '2012-01-24', '這食譜使用自家制全牛肉漢堡。漢堡扒帶有很香濃的牛肉味，比在超級市場買的好吃!', '30分鐘', '1人'),
(189, '金烤馬鈴薯', '2012-01-24', '這是奶油土豆菜。車打芝士的味道是非常豐富的。\"Gratin\" 起源于法國菜和通常在淺碟某種形式的準備。\"Gratin\"通常烤成金黄色而上菜時會保留在烤盤裏評常。', '1.5小時', '3人'),
(190, '黑松露車喱茄火腿沙拉', '2012-01-24', '做沙拉非常輕鬆和變化多。只要你能想到得到，就可以發明一個新的沙拉配搭。從番茄的甜味和鹹味的帕爾瑪火腿味道很配。再加上松露沙拉油就真的很好吃。', '30分鐘', '2人'),
(191, '芝士通心粉', '2012-01-24', '是小朋友們 的喜愛食品。它的食材簡單但並不是容易做的好吃。這個食譜就同大家分享一下做出美味的 的心得吧！', '30分鐘', '2人'),
(192, 'XO醬肥牛炒烏冬', '2012-01-24', '平常食烏冬都是以湯麵爲主。其實炒烏冬都非常好食因爲炒的烏冬很有口感。這個食譜加了肥牛來另到正個菜式更有香濃的牛肉汁。最後配上XO醬帶有的香味就能另你食不停口啦。', '30分鐘', '1人'),
(193, '番茄牛肉', '2012-01-24', '番茄牛肉是有名的廣東家常菜因爲它取了美味之外還含有豐富營養。', '30分鐘', '1人'),
(195, '煎蛋角', '2012-01-24', '蛋角的食材和簡單都很簡單，但你能用你的創意令這個菜式變得更有特色。今次我們做的是基本蛋角，用的是免治豬肉。你喜歡的話，可以加點冬菇或是菜葆。', '30分鐘', '2人'),
(196, '清湯素雞', '2012-01-24', '這是一個簡單的的素食譜。我們喜歡在中國的農曆新年期間和家人分享這個菜式。它的味道清淡而食材健康簡單。對豆腐愛好者來説他們就應該絕對愛食素雞了。他們能在街市購買得到。', '30分鐘', '2人'),
(198, '芒果糯米', '2012-01-25', '芒果糯米是泰國的著名甜品。下次有機會試做這個甜品的時候，吃飯時一定要留肚因爲你一吃就停不了口。', '30分鐘', '6人'),
(199, '藍莓核桃蛋糕', '2012-01-26', '這是藍莓忪餅的小改良版。我們加了一些碎核桃而且這個食譜額外松軟因為我們添加了奶油。脆堅果跟藍莓的味道非常配合。', '1小時', ''),
(201, '核桃牛油曲奇', '2012-01-26', '我們想出了這個食譜時是正在試圖複製我嫲嫲的核桃餅乾。需然這個食譜跟我的記憶中的還有點差別，但它們也有獨特令人吃不停手的吸引力。', '1小時', '4人'),
(205, '簡單肉球意粉', '2012-01-27', '在這個肉丸食譜裡添加了一些牛至（香葉Oregano）真的很特別。牛至給肉丸帶來更額外濃郁得香味。配合上我們所用的簡單番茄大蒜醬實在太美味呢。', '1小時', '4人'),
(206, '15 分鐘豌豆湯', '2012-01-27', '豌豆湯是夏季期間的經典凍或熱湯。我們現在更加喜歡它因爲這個食譜低脂肪而且做法非常簡單。烹調時間只需15 分鐘。', '10分鐘', '1人'),
(207, '自家製煙肉白汁意粉', '2012-01-27', '我們喜歡[卡爾博納]-意大利的蛋黃白汁意粉。這類意粉麵食將所有我們最喜歡的東西集合于一身，包括牛油、 重奶油和熏肉。我們為所有白汁意粉的粉絲寫了這個食譜。請大家慢慢欣賞吧!', '30分鐘', '2人'),
(208, '越式柚子蝦沙律', '2012-01-27', '這個越南風格的沙拉在炎熱的夏天吃就最佳。這個沙拉汁是以青寧為主要材料，所以味道非常開胃。配上鮮蝦的口感更是令人耳目一新。讓這個沙拉帶有東南亞地區的風味食材就是魚露和炸蔥頭片。', '30分鐘', '2人'),
(209, '越南粉卷', '2012-01-27', '這越式粉卷是任何夏季派對的完美選擇。', '30分鐘', '5人'),
(210, '花膠燜鮑角', '2012-01-27', '花膠燜鮑角是一道傳統的農曆新年菜式。預備花膠的時間比較長，所以如果想為親朋戚友煮這道菜的話，就要預先幾天開始發花膠啦。', '1.5小時', '5人'),
(211, '椒鹽三文魚腩', '2012-01-27', '香脆多汁的三文魚腩是一杯白葡萄酒或啤酒的完美搭配。', '30分鐘', '2人'),
(212, '咖喱牛筋腩', '2012-01-27', '我們很喜歡吃咖哩牛筋腩。需然烹調時間較長，但完成之後這道菜的味道會令每分鍾的心機和時間值得的。', '1.5小時', '2人'),
(214, '竹笙扒豆苗', '2012-01-31', '竹笙是一種著名的中菜食材，含有豐富的蛋白質而且低脂。他們還具有獨特的口感。還未吃過竹笙的朋友，下次不妨嘗試這個食譜，讓您的味蕾帶來一個新的體驗吧。', '1.5小時', '2人'),
(215, '糯米飯卷 (糍飯食譜)', '2012-02-01', '我們很喜歡吃糯米。所有用糯米為主要食材的食譜都好吃，包括糯米飯，荷葉飯，干炒糯米飯等。這是我們的第一個糯米食譜，所以主要簡單為中心。味道非常好，而做法簡易。', '1小時', '2人'),
(216, '越式魚露醋', '2012-02-01', '這是一種傳統的越南醬，適用于多道越南菜式。我們通常一次過做一大瓶醬汁然後儲存在冰箱裡，以便隨時滿足我們對吃越南菜的渴望。', '30分鐘', '2人'),
(217, '奶油大蒜青口', '2012-02-01', '這將是你做過最簡單而又最鮮美的青口。最重要的食材是質量好的牛油，而且需要用很多牛油！這道菜的醬汁非常好吃，配一些烤麵包就最完美了。', '30分鐘', '2人'),
(218, '自家制奶油班戟', '2012-02-01', '光薄薄餅配豐富國產果香醬 ... ... 的股份為週末甜完美早餐。', '30分鐘', '2人'),
(219, '迷你肉丸熱狗', '2012-02-02', '剩下的肉丸很有用圖，它們可以簡易地變成另一道菜式。這次我們用了肉丸做了一個簡單的迷你熱狗食譜。做法快之餘味道很好，小孩子超喜歡的！', '30分鐘', '3人'),
(220, '日式炸生蠔', '2012-02-02', '我們很喜歡吃蠔。不論是生的還是熟的，我們都喜歡蠔的味道。日式的酥炸生蠔做法簡單，最重要的是買到新鮮的蠔。用美國捅蠔的話就要記得洗乾清啦！', '30分鐘', '3人'),
(221, '簡單肉丸意粉', '2012-02-02', '這是簡易的肉丸意粉食譜。我們選用的是優質鮮肉腸，然後把它們煎成肉丸做肉丸意粉。味道非常好，需時少於一個小時。', '1小時', '2人'),
(222, '金槍魚刺身沙拉', '2012-02-02', '魚生沙侓做法簡單而顔色和味道都非常開胃。這次我們做的是用了金槍魚和三文魚刺身。沙侓油的食材用醬油和青檸汁所以很有亞太風味。', '30分鐘', '2人'),
(223, '自家製澳洲蟹餅', '2012-02-04', '在家中也可以享受到美味的蟹餅。這個食譜可以做晚餐或做派對的小食， 自家製澳洲蟹餅的做法簡單。最重要的是買到準備好的蟹肉。', '1小時', '2人'),
(224, '七味粉烤金槍魚', '2012-02-04', '這是我們最喜歡的沙侓因爲食材健康而且顔色漂亮。金槍魚的鮮紅色和沙侓葉的緑色很配。這個食譜做法簡單，只需十五分鍾就做好了！最重要的食材是多放日本的七味粉。', '30分鐘', '2人'),
(225, '意大利肉醬千層麵', '2012-02-04', '意大利肉醬千層麵是派對的熱門菜式因爲通常可以一次煮較多的分量，而且千層麵可以預先準備好然後上菜前再返熱。', '1.5小時', '2人'),
(226, '泡菜豆腐湯', '2012-02-04', '韓國的湯類食譜有很多。我們很最喜歡的是泡菜湯。這個食譜很簡單，味道非常濃。足夠滿足我們想吃香濃泡菜的意欲。', '30分鐘', '2人'),
(227, '番茄燴牛腩', '2012-02-04', '西式的燴牛腩是以番茄為主要食材。做法不煩復之餘，更何被雪藏。返熱時味道會更濃和入味，所以對關注健康的上班一族來說就很適合啦！', '1小時', '2人'),
(228, '沙爹牛河', '2012-02-05', '在中菜食譜裏有很多的河粉菜式。不論是湯類的還是炒粉面類，河粉做的菜式都帶有不同的口味。在衆多的食譜當中，我們的首選是沙爹牛河。濃濃的沙爹醬配上香滑的河粉，效果真的是令人無法低檔。', '30分鐘', '2人'),
(229, '星州炒米粉', '2012-02-05', '咖喱粉是這道菜的關鍵食材。甜的叉燒及鮮蝦通常會被添加到這道菜中。您可以輕鬆地把這個食譜改為素食麵條，只需以蔬菜取代叉燒便可以了。', '30分鐘', '2人'),
(230, '甜酸醬', '2012-02-05', '這是一個很傳統的中菜食譜。學會煮這個甜酸醬後，您可以使很多不同的菜，包括甜酸排骨和甜酸蝦等。', '30分鐘', '2人'),
(231, '自家製港式叉燒', '2012-02-05', '每個人都愛吃叉燒。叉燒的肉質鬆軟，多汁，香甜而美味。這次我們與你分享這個食譜能讓你在家中都可以簡易地煮出靚叉燒。\n\n<十五分鐘懶人版｜蜜汁燒叉燒>\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\n立即落單：蜜汁燒叉燒', '1小時', '2人'),
(234, '美國雪花牛肉炒雪豆', '2012-02-05', '牛肉炒雪豆是一道簡單的家常小菜。這個食譜我們用了美國優質的雪花牛肉。 美國牛肉脂肪比較高，所以炒起來比較香濃。', '30分鐘', '2人'),
(236, '中式春捲', '2012-02-05', '春捲的做法簡單，而且多元化。想做出好吃春卷，最重要是新鮮的食材。今天，我們做了兩種春卷包括簡單的蝦和蔬菜卷。', '30分鐘', '4人'),
(237, '鍋貼', '2012-02-05', '很多人都喜歡吃鍋貼。鍋貼可能是中式點心中最受歡迎的款式之一。我們這次跟大家分享一個簡單的鍋貼食譜。最特別的是鍋貼皮是自家制的。', '1小時', '2人'),
(239, '蒜蓉茄子', '2012-02-10', '蒜蓉茄子是一個簡單的中式素菜。 你只需要一些新鮮的茄子和大蒜。如果你喜歡吃辣的話，可以加點小紅椒。', '30分鐘', '2人'),
(240, '自家制炒飯', '2012-02-11', '自家制的炒飯比較好吃因爲可以加多些雞蛋而且用少油。味道比較好之餘更健康。平常炒飯的主要食材是蝦或是肉。這次我們用了叉燒。', '30分鐘', '1人'),
(241, '自家制豬腸粉', '2012-02-11', '腸粉是一道普片的點心。因爲腸粉的味道簡單，很少人會在家裏做。這次我們跟大家分享自家制腸粉的樂趣。其實自己做腸粉的食譜很簡單而且多元化。', '30分鐘', '2人'),
(243, '涼拌青瓜', '2012-02-11', '這些新鮮鬆脆的黃瓜是完美的下午小食或當炎熱的夏天晚餐的開胃菜。加一點少辣味道更可口。', '30分鐘', '2人'),
(244, '菠蘿咕嚕肉', '2012-02-11', '菠蘿咕嚕肉是中菜之中最有名的菜式之一。世界各地的人都會喜歡食咕嚕肉。這次我們跟大家分享一個傳統的菠蘿咕嚕肉食譜。以後就可以簡單地在家中享受到這一道著名的家常菜了。\n\n<十五分鐘懶人版｜三色椒菠蘿牛肉>\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\n立即落單：三色椒菠蘿牛肉', '1小時', '2人'),
(245, '鮮蝦雲吞', '2012-02-11', '雲吞是中國的著名小菜。平常可能多數在外面吃雲吞。其實在家裏自己做雲吞非常簡單而且你還可以照自己的口味配搭出喜歡的款式。', '30分鐘', '2人'),
(246, '台式鹽酥雞', '2012-02-11', '這是我們在臺灣最喜歡的小吃之一。我們這個食譜主要是用了大蒜和紅辣椒。添加了羅勒葉子的味道更香更好吃。', '30分鐘', '2人'),
(247, '中式檸檬雞', '2012-02-11', '這是美式版的中菜檸檬雞。美式版的檸檬雞味道較爲濃，醬汁的酸甜配飯最佳。這道檸檬雞是小孩子的受歡迎菜式。', '1小時', '2人'),
(253, '番茄薯仔湯', '2012-02-12', '在中式湯之中,大多數都是以雞湯、牛肉湯或是豬骨湯作湯底。今次我們要介紹的這款番茄薯仔湯不但做法簡單,而且營養豐富,美味可口。口感更深受小朋友喜愛,希望你也一樣喜歡這道番茄薯仔湯啦。\n\n<十五分鐘懶人版｜蕃茄肉碎薯仔湯>\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\n立即落單：蕃茄肉碎薯仔湯', '30分鐘', '6人'),
(259, '薯仔炆雞翼', '2012-02-13', '很多香港人小時候一定有試過媽媽做的薯仔炆雞翼吧，很多家庭都愛以這道簡單美味的食譜作家常菜。其實如果怕雞翼太肥膩，不 夠健康的話，也可選擇去皮的雞脾肉代替，一般這道菜比較少以雞胸代替，因為雞胸需要比較長時間熟透容易令肉質變乾。所以最好的選擇還是以去皮的雞脾肉代替雞翼。', '1小時', '2人'),
(260, '海鮮豆腐羹', '2012-02-13', '中國人的煲湯文化已經流傳已久，然而一般老火湯都要用上雞骨或豬骨，再用慢火花長時間煲成。如果要在短時間內準備一鍋湯的話，今天我們介紹的這款食譜就非常適合了。今天這道是豆腐海鮮湯，不但顏色鮮艷而且鮮味可口，湯裡用上海鮮和豆腐作主料，海鮮的鮮甜和細滑的豆腐的搭配不但受歡迎，而且這道食譜需要的時間也相當之短呢。', '1小時', '3人'),
(261, '番茄煮紅衫魚', '2012-02-13', '如果你的小朋友不愛吃魚，你一定要試試這個食譜。我們用的是紅衫魚。紅衫魚是白魚。他們的肉質鮮嫩多汁，而且和濃郁的番茄醬很配。如果想為家人帶來更多的驚喜，你可以嘗試把魚肉起骨，讓小孩子更容易食。', '30分鐘', '1人'),
(262, '番茄牛肉湯麵', '2012-02-13', '番茄牛肉湯既健康又美味，如果平常想輕鬆簡便的吃個午飯，在湯裡加上喜歡的粉麵就已經成為鮮味滿溢的一碗湯麵了。今次我們用上美國牛肉作為主料，喜歡的話其實也可加上其他牛肉或是牛腩作為配搭呢。', '1小時', '2人'),
(263, '合時南瓜煲仔飯', '2012-02-13', '隨著寒流將近，相信很多人已經開始想念一窩熱烘烘的煲仔飯那種香氣和味道了吧，其實煲仔飯除了我們常見的幾種之外，還有很多各式各樣的配搭可以嘗試，只要準備一個小鍋，隨手拈來的材料也可煮出一窩香氣撲鼻的煲仔飯呢，今次我們要做的這款就是南瓜雞肉冬菇飯，學成之後大家下次亦不妨用自己的配搭創造些新口味的煲仔飯，在今個冬天大展身手泡製美味煲仔飯呢！', '1小時', '1人'),
(264, '釀茄子炸豆腐', '2012-02-13', '飲茶的時候是不是很喜歡點各式各樣的點心呢？今次我們要來做的也是很多人喜歡在飲茶時叫的點心，炸釀茄子和炸豆腐，在家做點心能夠確保菜色少油之餘又健康，不妨一試呢！\n\n<十五分鐘懶人版｜百花煎釀茄子>\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\n立即落單：百花煎釀茄子', '30分鐘', '2人'),
(266, '牛油果醬', '2012-02-13', '我們很愛吃牛油果醬。這是起源于墨西哥的小吃。這個食譜做法很簡單。當你吃過自家制牛油果醬後，你就不會再買罐頭牛油果醬了。', '30分鐘', '2人'),
(267, '泰式燒豬頸肉', '2012-02-13', '香港人對豬頸肉情有獨鈡。豬頸肉比平常一般的豬肉多汁。這次我們更你分享一個用豬頸肉做的泰式小食，美味的香草和醬油配上慢烤的豬肉。', '30分鐘', '2人'),
(268, '意大利熏肉番茄迷你蛋餅', '2012-02-13', '迷你蛋餅是種意大利小吃，他是以肉類或其他香口的配料作餡，可作早餐之餘也可以當作輕便午餐，甚至在晚餐上奉客之用。今次我們就用鬆餅模做成這款意大利熏肉番茄迷你蛋餅，用來做派對小吃絕對一流。如果你有迷你的鬆餅模，甚至能做出可愛又可口的一口蛋餅呢！', '1小時', '3人'),
(270, '自家制越南牛河', '2012-02-16', '今日和大家分享一個非常特別的食譜-- 相信大家都很喜歡吃越南牛河。這一次我們從在中環開了新店的ChomChom 越南餐廳學了做簡單的越南牛河\"Pho Bo\"。大家可以在家裏都享受到美味的越南牛河啦。', '1小時', '2人'),
(285, '有機番茄煮牛肉', '2012-02-19', '如果意大利菜最著名的是番茄意粉的話，那中式番茄的代表作一定是這道番茄煮牛肉了。差不多是每個中式家庭一定會做的這道番茄牛肉，配上白飯，窩心之餘又令人想起家的味道呢。', '30分鐘', '2人'),
(289, '椰菜炒臘腸', '2012-02-21', '臘腸是道在冬天非常受歡迎的菜式，既甜且咸的味道配上椰菜簡直是完美的組合。', '30分鐘', '2人'),
(290, '蒜頭豆角炒橄欖菜', '2012-02-23', '這道是在中菜中很受歡迎的一道素菜，豆角爽脆的口感配上橄欖菜和蒜頭的香味既健康又可口。', '30分鐘', '2人'),
(291, '有機西蘭花白豆湯', '2012-02-23', '西式湯最吸引人和令人滿足的大概就是那種香濃細滑的滋味吧，今次我們要做的這款西蘭花白豆湯除了有以上特點之外，另一個特點就是用上了白豆而捨棄了傳統一般會用的芝士和忌廉做出濃稠的湯底。雖然湯底沒有用上這兩種材料，不過最後亦可加上適量芝士或濃忌廉令湯更美味呢。', '1小時', '2人'),
(295, '豆瓣醬炒白菜', '2012-02-27', '有沒有發覺中餐通常都有一道菜是素菜呢？一般來說都是用蒜炒或是用高湯配上新鮮蔬菜做成的。今次我們要做的這款豆醬煮白菜就加入了一點新意，用上潮式豆瓣醬加上新鮮有機白菜，可口之餘又夠營養。', '30分鐘', '1人'),
(296, '甜菜根沙拉', '2012-02-27', '甜菜根蘊含豐富的抗氧份成份和營養，其中包括有鐵、鎂、維他命C等等。一般來說生菜根都是以白煮或烘焙的方式來做的，而冷卻之後則可以作為沙拉食用。今次我們要做的就是用甜菜根做的這款簡易甜菜根沙拉。', '1小時', '2人'),
(297, '韓式泡菜炒飯', '2012-02-27', '韓式炒飯富有風味之餘又充滿特色，這道韓式炒飯就用上了各式糙米和糯米加上泡菜和蛋炒成，帶點辣味之餘口感又夠香口，一定要試一試呢。', '30分鐘', '2人'),
(300, '蔬菜泰式綠咖喱', '2012-03-01', '咖哩不但可口而且做法簡單， 今次我們要做的這款蔬菜咖哩就是用上homegrown foods的新鮮有機蔬菜， 加倍健康。', '30分鐘', '2人'),
(303, '簡易清湯牛尾', '2012-03-04', '之前我們曾經介紹過一道紅酒炆牛尾食譜，而今次我們要介紹的就是一道以清湯作底的牛尾湯。用來配以麵食簡直是一流呢！', '1.5小時', '2人'),
(305, '簡易白酒煮青口', '2012-03-10', '', '30分鐘', '2人'),
(306, '焗迷你有機番茄', '2012-03-09', '今次要做的這款焗迷你番茄非常適合在派對上跟家人和朋友們一起分享，番茄健康之餘而且色彩鮮艷，真正的色香味俱全呢！', '1小時', '3人'),
(310, '菜遠牛肉', '2012-03-17', '今天我們要做的這款就是在廣東菜中非常常見的菜色－菜遠牛肉。主要的食材是菜心和牛肉。', '30分鐘', '2人'),
(312, '鮑魚菇肉絲兩面黃', '2012-03-18', '在中菜料理當中，單單是麵的種類和煮化就已經非常多元化。今次的鮑魚菇肉絲兩面黃就是用炸的方法把麵炸至兩面金黃，再在麵餅上淋上以肉類或蔬菜烹調的肉汁，此道菜亦因此得名兩面黃。以這種方法烹調的麵外脆內軟，拌以肉汁就成為一道可口特別的佳餚。', '1小時', '2人'),
(313, '大理石綠茶鬆餅', '2012-03-18', '綠茶不但有益健康，而且綠茶口味的甜品近年來大行其道。其中最受歡迎的包括綠茶雪糕、綠茶布丁、綠茶蛋糕之類，是不是想起就已經很吸引呢？今天我們就是準備了一道綠茶大理石鬆餅的食譜給大家，這款綠茶鬆餅帶著淡淡的綠茶清甜，可口之餘也不失為健康的甜點選擇呢。', '1小時', '3人'),
(314, '泰式豬頸肉', '2012-03-18', '豬頸肉比較嫩同多汁，主要用於製作香腸。在意大利烹飪，醃豬頸肉被簡稱為guanciale。在亞洲烹飪，經常用可口的香草和醬油醃製，然後慢火加上蜂蜜烤。這個泰式豬頸肉食譜是一道很美味的小吃。', '1小時', '2人'),
(315, '竹笙扒唐生菜', '2012-03-18', '竹笙是種營養價值很高的配菜，而且跟很多不同的蔬菜都配合得完美無縫。今天我們介紹的這道竹笙扒唐生菜就是其中一種最受歡迎的中菜，竹笙本來獨有的口感和鮮甜加上唐生菜拌以輕量的醬汁就組成了這道清新中又帶點甘甜的蔬菜。', '1小時', '2人'),
(316, '健康香蕉蛋糕', '2012-03-18', '當你想吃一片蛋糕當早餐或是下午茶,而又怕一般的蛋糕不夠健康的時間,今次我們要介紹的這款香蕉蛋糕就非常適合了。這款香蕉蛋糕的食譜不用加牛油, 而酸忌廉和去脂奶能為蛋糕提供充足的水份令他變得軟滑鬆化。這麼健康的香蕉蛋糕就算多吃幾片也不用感到自責呢。', '1小時', '2人'),
(317, '豆瓣蝦仁炒菜心', '2012-03-18', '這是一道很常見的中式家常菜。這道菜很健康因爲以菜心爲主。平常的菜心煮法都比較清淡，但是這個食譜的調味較濃。辣豆瓣醬配菜心和蝦仁非常配。有機會不妨為你的家人做這道菜吧。', '30分鐘', '2人'),
(319, '魚香茄子', '2012-03-24', '鱼香茄子是一道常見川菜。魚香是川菜主要傳統味型之一。成菜具有魚香味，但其味並不来自魚，而是泡红辣椒、葱、薑、蒜、糖、鹽、醬油等調味品調制而成。此法源出於四川民間獨具特色的烹魚調味方法，而今已廣泛用於川味的熟菜中，具有鹹、酸、甜、辣、香、鲜和濃郁的葱、薑、蒜味的特色。\n\n<十五分鐘懶人版｜魚香茄子煲>\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\n立即落單：魚香茄子煲', '30分鐘', '2人'),
(322, '蜜糖甜菜沙律', '2012-03-26', '甜菜的營養價值非常豐富。甜菜熟食的時候通常會比較甜，而生食的時候除了比較爽脆之外也帶有一種微酸的味道。今次這款蜜糖甜菜沙律可用作前菜，配上一些比較油膩的主菜時就是一流之選了。', '30分鐘', '2人'),
(323, '清涼西瓜沙律', '2012-03-26', '西瓜一直以來都是受歡迎的消暑佳品，鮮甜的果肉加上爽脆的口感令人倍感涼快。今天我們要做的這款西瓜沙律就是用西瓜加上菲達芝士，沙律雖然做法簡單，但其實最重要的就是食材的配搭，這款西瓜沙律不但果味濃厚，而且加上了香濃的芝士之後更可以成為一道精緻的午餐或小食呢。', '30分鐘', '2人'),
(326, '法式吐司砂鍋', '2012-03-27', '砂窩除了是一般中菜常用到的砂窩之外，其實傳統的法國菜和英國菜也有砂窩類的菜式。這種叫Casserole的法菜通常是用大而深的盤放進焗爐裡烤，然後直接上菜。今次我們的食譜是用香甜的法式土司配上意式香腸，既傳統之餘又可口美味。', '1小時', '3人'),
(327, '生牛肉BLT沙拉', '2012-03-29', 'B.L.T.解作煙肉(Bacon)、生菜(Lettuce)、和番茄(Tomato)，我們今次要做的BLT則是以牛肉代替煙肉。這款生牛肉BLT沙拉不但容易準備，而且鮮甜健康，可以作午餐之餘又可作代替一頓輕便晚餐，非常吸引呢。', '30分鐘', '1人'),
(328, '彩色椰汁糕', '2012-03-29', '椰汁糕是一款普遍的中式甜點。我們這個食譜加了一點心思，做出來的效果除了好吃之外，顔色也更加鮮豔。', '1.5小時', '3人'),
(329, '自家制白汁雞皇飯', '2012-03-31', '白汁雞皇飯是很受歡迎的中式菜，簡單之餘又令人有滿足的感覺。不但大人喜歡小孩子也相當喜歡呢。', '1小時', '2人'),
(332, '三文魚生菜包', '2012-04-01', '用上有機蔬菜和三文魚做成的這款三文魚生菜包是不是很有創意呢？非常適合作為 下午茶或小食，亦是一道令人胃口大開的前菜。', '30分鐘', '2人'),
(333, '簡易健康有機羅宋湯', '2012-04-04', '這道有機羅宋湯非常適合在當家中購置了大量蔬菜又來不及消化的時候烹調，不但做康簡單健康，其香味及飽足感更令人食指大動呢。', '1小時', '3人'),
(335, '綠茶牛奶布丁', '2012-04-05', '我們很喜歡綠茶的食品 ！我們已經分享過的綠茶食譜有綠茶松餅、 綠茶蛋糕和這次的綠茶牛奶布丁 ！您可以提前準備這個甜品。這是一個完美的下午茶。', '1.5小時', '3人'),
(336, '貴妃雞', '2012-04-05', '貴妃雞算得上是最家傳戶曉的一道中國菜。時至今日，貴妃雞的食譜也變得多樣化，今次我們要介紹的食譜主要的不同是在最後掃上一層麻油，令雞變得更香口。貴妃雞通常可以預先準備，放在室溫之下保存，到食的時候切開食用即可。', '1小時', '2人'),
(337, '午餐肉煎蛋壽司', '2012-04-06', '午餐肉煎蛋壽司是夏威夷一款非常受歡迎又輕便的小食，他融合了日本傳統飯團的做法，配上午餐肉，成為了獨特的夏威夷小吃。他是以午餐肉作餡料，包上白飯和紫菜，簡單之餘又可口。', '1小時', '2人'),
(339, '火腿芝士一口薯餅', '2012-04-09', '我們今天要做的迷你薯餅，一般都是由薯條混以碎肉或其他材料再炸成的。今次我們的食譜則以火腿和芝士混以薯仔做成香口好吃的一口薯塊，除了用來作小食之外亦可作晚餐時的配菜呢。', '1小時', '3人'),
(340, '芥蘭火腿絲炒飯', '2012-04-12', '此道芥蘭火腿絲炒飯非常受小朋友歡迎，芥蘭加上西蘭花，不但健康而且口感爽脆，絕對可令平常討厭蔬菜的小朋友不知不覺吃下各種健康的蔬菜呢。而今次我們亦另外加入了火腿絲和蛋令炒飯變得更色香味俱全呢。', '30分鐘', '2人'),
(343, '雜錦串燒拼盤', '2012-04-16', '在派對上準備串燒作客用是個很好的選擇，不但可以用上各式各樣的材料，而且成品通常都香口吸引，今次我們就先提供幾款串燒的配搭，其實除了我們介紹的配搭之外，如果你想到任何更創新的配搭其實亦不妨一試呢！', '1小時', '3人'),
(344, '紅捲心菜炒梅頭肉', '2012-04-19', '紅捲心帶有微微的苦味，在一般中菜中並不常見。今次我們要做的這款紅捲心菜炒梅頭肉將梅頭肉用麻油醃製來中和紅捲心的苦味。另外亦會加上香菜再裝飾及調味。', '30分鐘', '2人'),
(345, '火龍果西米露', '2012-04-21', '西米露已經是大家耳熟能熟的甜品了吧。相信很多人最愛的西米露一般都是椰汁西米露或芋頭西米露。今次我們要做的這款就較為特別了，我們用上了紫色的火龍果肉，不單令西米露更加可口鮮甜，還加上了一抹紫紅色的色彩，成品不但好看而且非常美味呢。', '1小時', '2人'),
(346, '日式番茄沙律', '2012-04-22', '日式沙律比起一般沙律通常就是在醬料上比較多不同的變化，常用的有薑味醬油、柑橘醬油和麻醬。像沙律的這種冷盤最適合就是用上麻醬，濃滑又香口，其實麻醬除了用來做成沙律之外，用上麻醬作冷麵調味也非常美味呢。', '30分鐘', '2人'),
(347, '蘇格蘭有機馬鈴薯湯', '2012-04-22', '馬鈴薯湯幼滑香濃，這款蘇格蘭有機馬鈴薯湯就最適合一家大小在冬天的時候享用，這道源至蘇格蘭的馬鈴薯湯以馬鈴薯和韭菜作主要配料，有部份做法更會加上紅蔥頭或其他香料。今天我們要做的這款則沒有加上其他香料，僅僅在最後以一小塊香草作為點綴之用，因為這樣更能夠保存有機馬鈴薯的鮮甜味道。', '1小時', '2人'),
(348, '西蘭花炒海鮮', '2012-04-24', '今次我們要準備的這道西蘭花炒海鮮是一般中式宴會上常見的菜色， 西蘭花顏色鮮艷配上鮮味的海鮮非常受賓客的歡迎，大家也可以試試按照今次的食譜在家準備這道菜色跟你最愛的家人一起分享。', '30分鐘', '2人'),
(350, 'Soto Ayam 印尼雞湯麵', '2012-04-28', 'Soto Ayam是一種傳統的印尼菜。用上香濃撲鼻的香料做成湯底，加上煮到剛熟的鵪鶉蛋和雞肉，不但鮮味滿溢而且更帶有濃厚的東南亞菜味道。今次我們要介紹給大家的食譜用上剛熟的鵪鶉蛋加上雞脾肉，我們亦加上迷你紅蘿蔔作為調味及為這道菜添上多一道顏色。', '30分鐘', '2人'),
(351, '菠菜拌水煮三文魚', '2012-04-29', '三文魚不但營養豐富而且口味多變，煎焗炒燒都能帶出三文魚的鮮味和香味。而由於三文魚本身的營養，愈來愈多人建議進食三文魚作為健康食品。今次我們要煮的這道菠菜三文魚就是簡單得來又健康，可以作為生活忙碌的上班族下班之後想要下廚的一個很好的選擇呢。', '30分鐘', '1人'),
(352, '椰菜花炒黃金魚片頭', '2012-04-29', '通常一般的中國菜都很少用到椰菜，但其實椰菜跟很多中式炒菜都非常配合。所以我們今次就做了這道椰菜花炒黃金魚片頭，嘗試一下將椰菜跟中式炒菜的嶄新口感。', '30分鐘', '2人'),
(354, '玉米蛋花湯', '2012-05-01', '玉米蛋花湯是最快速的自製食譜之一。玉米蛋花湯做法簡單，而且健康和美味。你也可以加一些雞絲讓湯變得更香濃。', '10分鐘', '2人'),
(355, '簡易煎三文魚食譜', '2012-05-04', '煎魚不但健康，而且亦是道非常美味的菜色。一般最常見的通常有煎三文魚、鱈魚及煎比目魚。通常煎魚並不需要很多時間準備，只需將之煎至約8成熟即可。如是新鮮魚就更加應該採用簡單的烹調方法令其鮮味更加突出。\n\n<十五分鐘懶人版｜照燒汁三文魚扒>\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\n立即落單：照燒汁三文魚扒', '30分鐘', '1人'),
(356, '青瓜煮牛肉', '2012-05-05', '青瓜煮牛肉是道非常健康的家常菜，鮮艷又帶有鮮甜味的青瓜跟牛肉煮在一起也非常適合拌以白飯享用。', '30分鐘', '2人'),
(357, '釀意大利瓜食譜', '2012-05-05', '中國節慶最值得人期待的地方大概就是那一桌滿滿的傳統佳餚菜色了，其中一道比較常見的是釀節瓜，今天我們就要將他稍作改良，將原來的蔬菜換上意大利瓜，意大利瓜雖然清淡，卻有與別不同的鮮甜味道，而釀料我們則用上簡單鮮味的碎豬肉作餡，再用上清雞湯，實在是完美的配搭呢。', '1小時', '3人'),
(358, '簡易糖霜餅乾', '2012-05-05', '聖誕節，感恩節和萬聖節假期，糖霜餅乾都大受歡迎的。糖霜餅乾食譜通常讓你和朋友和孩子們裝點自己的餅乾，製作過程充滿樂趣。基本糖霜餅乾的麵團包括糖，麵粉，黃油，雞蛋，香草，泡打粉或者小蘇打。', '1小時', '3人'),
(360, '香辣蘆筍炒雙鮮', '2012-05-11', '蘆筍帶有天然的甜味，而且口感爽脆，是很多人喜愛的蔬菜。今次我們要做的這款香辣蘆筍炒雙鮮就在這種鮮甜味上加上香辣的味道，令這道菜變得更加色香菜俱全。', '30分鐘', '2人'),
(364, '日式牛柳配炸蒜片', '2012-05-15', '牛柳粒是多種牛肉之中最容易煮而且多變化的一種。牛柳粒可以用以慢火燉，燒烤，以及香炒。今次這個食譜，我們準備了一些高級美國牛柳粒，作適量的調味後再用大火煎至六成熟。最後，我們加些香脆可口的大蒜片讓這個菜式增添了一點日式風味。', '30分鐘', '2人'),
(366, '上湯浸紅莧菜', '2012-05-19', '紅莧菜對雙眼健康一般有著非常好的幫助，同時鮮艷的紅色亦能令人食欲大增。今次我們要做的這道上湯浸紅莧菜不但健康而且非常美味，做法亦很簡單呢。', '10分鐘', '1人'),
(384, '冬瓜火鴨粒湯', '2012-05-27', '冬瓜湯是一個餐廳常見的菜式。一般在喜興日子裏都會點冬瓜盅因爲他的做法反復，而且冬瓜盅給人的感覺是比較多功夫。今天跟大家分享的冬瓜湯食譜做法非常簡單。味道濃而不膩，一定要試試！', '30分鐘', '2人'),
(503, '有機青瓜煮蝦', '2012-05-31', '青瓜煮蝦是我們在炎熱的季節裏很喜歡的一道家常菜。它的做法簡單，味道清淡而且帶有青瓜的鮮甜和蝦的鮮味。大家不妨今晚就試試吧！', '30分鐘', '2人'),
(512, '基本燜冬菇', '2012-06-03', '冬菇味道鮮美而且營養豐富。乾的冬菇能夠保存一段很長的時間。我們通常都會有一些冬菇放在密封的容器内儲存。每當我們想將它添加到不同的食譜時非常方便。今次讓我們跟大家分享一個最基本的冬菇食譜。學會如何燜冬菇之後，你就可以慢慢創做許多不同的冬菇菜式啦！', '1小時', '2人'),
(514, '簡易芝士磨菇焗飯', '2012-06-06', '一道熱烘烘的焗飯絕對能在寒冬之中令你和令你的家人暖至心底，想像香濃的芝士加上濃郁的白汁，再拌以白飯，是不是想想已經覺得很吸引呢？如果平常家中有用剩的意粉醬，也可以在此食譜中物盡其用，沒有準備意粉醬也可跟據食譜中的方法做一些新鮮的忌廉汁，今天就一起來泡製一道美味又窩心的芝士磨菇焗飯吧！', '30分鐘', '2人'),
(520, '港式咖喱牛腩', '2012-06-11', '相信很多香港人都喜歡吃咖哩，其中當然以咖哩牛腩配以白飯或麵最受歡迎。雖然要煮出一鍋香濃軟熟的咖哩牛腩通常都得花上比較長的時間，但是當咖哩煮好的時候，那種香味和口感實在令人食指大動。今天這道咖哩牛腩的食譜雖然並不是以椰汁作佐料，但是椰汁可以減低咖哩的辣味，迎合不吃辣的朋友。', '1.5小時', '3人'),
(521, '健康絲瓜燜冬菇', '2012-06-11', '絲瓜味道清新，是一種很消暑的蔬菜。在中式料理中，絲瓜會在夏天是比較常用。絲瓜中含防止皮膚老化的B族維生素，增白皮膚的維生素C等成分，能保護皮膚、消除斑塊，使皮膚潔白、細嫩，是不可多得的美容佳品。', '30分鐘', '2人'),
(522, '清蒸鮮鮑魚', '2012-06-12', '在衆多的廣東海鮮菜式之中，清蒸鮮鮑魚一定是我們的最愛之一。鮮鮑魚的口感同乾鮑不一樣，它的味道更爲鮮甜。而且口感比較彈牙，實在是令人回味無窮。清蒸鮮鮑魚的做法非常簡單。所用的食材都是一精簡爲主，因爲全部的食材都是用來帶出每一隻鮑魚的鮮味。這個清蒸鮮鮑魚食譜宴客最佳。', '30分鐘', '3人'),
(529, '蠔油素雞雪豆', '2012-06-17', '素雞其實就是用黃豆製成的素食，今次我們要做的這款蠔油素雞雪豆就是用上素雞跟雪豆，如是素食者亦可用素食蠔油代替蠔油。', '30分鐘', '2人'),
(532, '簡易清酒煮蜆', '2012-06-18', '是一個簡單而味道清淡純的海鮮食譜。清酒經過煮熱後味道更加香濃，放入新鮮的蜆實在是絕配。上碟時加上一些紅辣椒粒，顏色更鮮豔之如也帶一點辣味。', '30分鐘', '2人'),
(533, '花雕蒸蟹', '2012-06-18', '蒸蟹是中式海鮮食譜中最簡單而受歡迎的烹飪方法。這個食譜非常簡單，最重要的是食材一定要新鮮。', '30分鐘', '2人'),
(535, '健康雪豆炒玉子豆腐', '2012-06-19', '玉子豆腐非常適合用來煮菜，滑溜豐富的口感用來煮各種配菜都很適合。今次我們要做的這款素菜就是用雪豆配上香滑的玉子豆腐。', '30分鐘', '3人'),
(545, '潮州食譜 - 紫菜魚蛋墨丸湯', '2012-06-22', '紫菜湯是一種很有潮州風味的家常菜，魚蛋和墨魚丸的卡路里低而且非常美味，今次做的紫菜魚蛋墨丸湯絕對稱得上健康美食呢。', '30分鐘', '2人'),
(555, '海鮮食譜 – 清蒸魚腩', '2012-06-26', '清蒸海鮮是廣東家常菜之中又好吃又簡單的烹飪方法。這次我們和大家一起分享一個簡單而且健康的清蒸魚腩食譜。要做出好吃的魚，一定要用新鮮的魚腩。還有就是放一點心機把薑絲和蔥絲切得幼細。', '30分鐘', '1人'),
(561, '簡易海鮮食譜 - 豉汁蒸帶子', '2012-06-27', '我們同大家都分享了不少清蒸海鮮食譜。不過在衆多的清蒸海鮮食譜當中，豉汁蒸帶子就一定是我們的最愛了。這個食譜不單指簡單。最好吃的地方就是放在帶子下面的粉絲因爲粉絲會吸盡這道菜的精華。簡直是令人食欲大增。', '30分鐘', '1人'),
(571, '豉椒蒸蟶子', '2012-07-02', '中式海鮮的食譜有更多不同種類的。在衆多的海鮮烹調方法當中，我們最喜歡的就是蒸海鮮。就單是蒸海鮮，中菜就有分清蒸，蒜茸蒸，花雕蒸，或者是豉汁蒸。這次我們和大家分享一個簡單而且非常美味的豉椒蒸蟶子食譜。大家下次想在家裏蒸海鮮的話就不妨試試這個食譜啦。', '30分鐘', '2人'),
(584, '簡易粥飯食譜 - 福建炒飯', '2012-07-04', '福建炒飯可算是我們最喜歡的炒飯之一。福建炒飯與一般的炒飯不一樣最特別的就是飯上面的冬菇蝦仁汁。冬菇蝦仁汁的食材非常豐富，有蝦仁，冬菇，瑤柱，得青菜粒。下次你準備煮炒飯的時候也不妨試試加這個食譜吧！', '30分鐘', '2人'),
(586, '螞蟻上樹', '2012-07-04', '螞蟻上樹得名至於菜中的肉碎像正爬上樹上的螞蟻一樣，而粉絲則像樹木的紋路。螞蟻上樹是道傳統既美味的中菜式，如嚐辣者亦可加入辣椒，作為小菜奉上簡直是一流呢。\n\n<十五分鐘懶人版｜螞蟻上樹>\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\n立即落單：螞蟻上樹', '30分鐘', '2人'),
(595, '簡易冷盤食譜 - 涼拌海帶絲', '2012-07-06', '海帶絲又一個非常獨特的口感。在中式食譜裏，海帶絲會常被用來做冷盤小食。這次和大家分享的涼拌海帶絲的做法簡單之餘，味道就更適合現時的炎熱天氣呢。', '30分鐘', '2人'),
(596, '上海菜食譜 – 簡易燻蛋', '2012-07-07', '上海燻蛋是道很歡迎的頭盤，一般來說都是用上鴨蛋製成。鴨蛋黃呈鮮橘色，味道亦比一般雞蛋濃郁，今次我們要做的就是這款用鴨蛋做的上海燻蛋。', '30分鐘', '4人'),
(599, '上海菜食譜 - 東坡肉', '2012-07-07', '\"東坡肉\"是很傳統的中國菜，來自浙江省。它使用五花肉，並需要長時間烹調。技術是慢慢把五花腩肉扽約 2-3 小時。東波肉的肉汁带有酒香，十分美味。', '1.5小時', '3人'),
(609, '鹹檸檬鴨湯', '2012-07-09', '鹹檸檬鴨湯是一個傳統的中式湯水食譜。鹹檸檬鴨湯源於潮州。夏天的天氣炎熱，大家進食時通常都比較無胃口，而鹹檸檬老鴨就具有醒胃解暑的功效。鹹檸檬鴨湯有開胃益脾的功效，能令人食慾大振。鹹檸檬有疏滯健胃的作用，而老鴨有滋陰補血的功效。', '1.5小時', '4人'),
(610, '上海食譜 – 簡易燻雞', '2012-07-09', '燻菜在上海食譜當中比較普偏。 今日和大家分享一個簡單的燻雞食譜。我們選用一隻豉油雞（可參考我們的豉油雞食譜），然後添加了一個簡單的步驟，讓這個菜式增添另一番風味。', '30分鐘', '3人'),
(611, '潮州食譜 - 蠔仔煎', '2012-07-10', '蠔仔煎是道很受歡迎的潮州菜式，用上鴨蛋跟蠔子煎成香脆美味的煎餅。蠔子一般在本地街市比較容易找到。', '30分鐘', '2人'),
(622, '椒鹽豆腐', '2012-07-15', '豆腐是種很健康的食材，有很多豆腐做出來的菜都非常美味。今天我們要做的就是椒鹽豆腐，香口惹味。做椒鹽豆腐一般建議用硬豆腐，因為炸完之後還能保持口感及形狀，所以比軟豆腐好。', '30分鐘', '2人'),
(625, '自家制蝦膠釀有機青椒', '2012-07-16', '今天我們準備了這些新鮮的有機青椒，非常適合加上自製的蝦餡做一道美味釀青椒。所以我們要做的就是這道刺激味蕾的自家制蝦膠釀青椒。', '30分鐘', '3人'),
(642, '油豆腐粉絲湯', '2012-07-18', '如果你想吃一頓簡單方便的午餐或晚餐，今次要做的這款油豆腐粉絲湯就非常適合了。美味的清湯加上豐富的配料選擇，足以令人食指大動呢。', '30分鐘', '2人'),
(660, '白果馬蹄豬肚湯', '2012-07-24', '一般人想到豬肚湯時，都會想起最常見的豬肚梅菜湯。今天，我們分享另外一道豬肚湯的食譜。這湯譜有白果和馬蹄，很適合炎熱的夏天，有助於減少身體裡多餘的水份。', '1.5小時', '3人'),
(664, '健康素食食譜 - 欖菜蓮藕生菜包', '2012-07-24', '欖菜蓮藕生菜包是道既健康又簡單的素菜，新鮮的蓮藕跟青豆非常配合，而欖菜則香味濃郁，令這道素材健康得來又非常美味。', '30分鐘', '2人'),
(665, '潮州食譜 - 滷水鴨（簡易版）', '2012-07-24', '滷水係中國粵菜同閩菜成日用嘅調味料，係一種用多種香料煮成嘅醬油。材料主要包括花椒、八角、陳皮、桂皮、甘草、草果、沙薑、薑、蔥、生抽、老抽同冰糖。今次我們要做的就是這款滷水鴨。', '1.5小時', '3人'),
(666, '簡易家常食譜 - 可樂雞翼', '2012-07-25', '今次我們要做的就是這款可樂雞翼，雖然食譜中用上可樂，但成品並不會有梳打水的味道。因為可樂是用來跟豉油作平衡，當中的成份亦可令雞翼變得更嫩滑。', '30分鐘', '1人'),
(667, '麻辣筍粒冬菇拌毛豆', '2012-07-25', '【健康前菜食譜】伊豆是道很好的食材，很適合作涼菜之用。伊豆本身有天然的甜味，可配搭的食材亦非常廣泛，包括蘑菇，竹筍，豆腐等等。今天我們就是要分享這道筍片冬菇拌毛豆，在炎熱的夏天帶給你這道美味的涼菜食譜。', '30分鐘', '2人'),
(680, '簡易家常菜食譜 - 南瓜燜排骨', '2012-07-30', '我們常常喜歡在秋天吃南瓜。大多數朋友都愛吃南瓜甜點。但很少有人知道，南瓜其實適合多款豐富可口的菜餚。這南瓜燜排骨是一道很容易又美味的家常菜。\n\n<十五分鐘懶人版｜味增南瓜排骨>\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\n立即落單：味增南瓜排骨', '1小時', '2人'),
(689, '台灣水瓜芋頭湯', '2012-07-31', '水瓜(亦稱絲瓜)性微寒，味甘，有清熱解暑的功效。而芋頭松化軟糯、甘香鮮美，中醫認為其有益胃、寬腸、通便、解毒、散結和調中化痰的作用，久服可補中益肝腎，療熱止渴，添精益髓。水瓜芋頭湯雖為素湯，但其香鬆軟滑，鮮甜可口，是一款家常靚湯，亦十分適合喜甘厭肥者的口味。在常飲老火湯時偶飲素湯也有益於身體。', '30分鐘', '2人'),
(735, '炒飯麵食譜 - 上海粗炒', '2012-08-13', '1950由於香港人並不喜食煎炸食物，所以較多人選擇經過本土化改良的上海粗炒久而久之，上海粗炒就成了一款十分常見的食品，代表了香港的上海麵食，並由華人餐廳傳向世界各地。', '30分鐘', '2人'),
(737, '冬菇肉絲燜大魚頭', '2012-08-13', '魚頭肉質細嫩、營養豐富，除了含蛋白質、脂肪、鈣、磷、鐵之外，還含豐富的不飽和脂肪酸，它對腦的發育尤為重要，此外常吃魚頭還可延緩腦力衰退。同時有健脾補氣、溫中暖胃、散熱的功效，尤其適合冬天食用。', '1小時', '2人'),
(742, '蒜茸炒紅莧菜', '2012-08-13', '紅莧菜產於每年的6-10月，紅莧菜富含多種人體需要的維生素和礦物質，且都是易被人體吸收的重要物質。同時對於增強體質，提高機體的免疫力，促進兒童生長發育，加快骨折癒合，減肥排毒，防止便秘都有很好的效果。', '10分鐘', '1人'),
(745, '揚州炒飯', '2012-08-13', '廣州式的揚州炒飯以“揚州”為名，卻非源於華東地區的揚州。它起源於清朝光緒年間的廣州，其後並在香港發揚光大，再傳到中國各地，並產生不少變種。清朝光緒年間的廣州，有一家叫聚春園的淮揚菜館，以蝦仁、叉燒和海參製作出一道“揚州鍋巴”。其後有酒樓將鍋巴改成炒飯，名為揚州炒飯，而揚州炒飯之名便廣傳開去。隨著時代的發展，由於海參價錢較昂貴，所以逐漸從揚州炒飯的食譜剔除', '10分鐘', '2人'),
(749, '核桃蝦', '2012-08-14', '【家常菜食譜】提到喜歡的中國菜，很多老外大概都會喜歡像左宗棠雞、芝麻雞、甜酸雞等之類帶有甜味的炸雞塊。如果家裡有老外朋友來作客，擔心會吃不慣一般的中國菜的話, 這道「核桃蝦球」就是一般外國朋友應該會很喜歡的中國菜。', '30分鐘', '2人'),
(750, '簡單健康食譜 – 鴨胸沙侓', '2012-08-14', '', '10分鐘', '2人'),
(751, '生炒糯米飯', '2012-08-14', '生炒糯米飯是中國粵菜的一道炒飯菜式，為廣東及港澳等地於秋冬時份常見的食品。正宗的生炒糯米飯的製作過程較為複雜。糯米在炒之前須先用水浸一個晚上，炒前又要把水瀝乾，慢慢把糯米炒熟，途中要邊炒邊澆水，才不致米粒不熟或太軟，要炒上很長時間，所以一般餐廳因為生產成本時間和人工，也不願花上功夫生炒。現在餐廳的生炒糯米飯均用的是熟米炒製，與生炒口感是不一樣的。', '30分鐘', ''),
(752, '簡易火腿絲泡飯', '2012-08-14', '泡飯是江南一帶（尤其是上海）的一種常見的食物，多用來當早飯。與粥不同，非但全無粥的那種黏糊和纏綿，反而條理清晰。', '10分鐘', '2人'),
(753, '韓式炒粉絲', '2012-08-14', '', '10分鐘', ''),
(755, '醬爆雞丁', '2012-08-15', '醬爆雞丁', '30分鐘', '2人'),
(756, '芙蓉蛋', '2012-08-15', '芙蓉蛋是一道中國粵菜。相傳芙蓉蛋是清代翰林朱善祥在雲南任主考時吃到的地方菜， 因菜味鮮、甘香、軟滑，神似綻放的白芙蓉，故名「芙蓉蛋」。', '10分鐘', '2人'),
(757, '簡易素食食譜 - 腐皮卷', '2012-08-15', '腐皮卷在中餐中通常被作為點心和小吃食用。這道精美小食外表酥脆，內裏多汁，口感十足。', '30分鐘', '2人'),
(759, '簡易家常菜食譜 – 蜆蒸水蛋', '2012-08-15', '水蒸蛋是一道中餐家常菜，今天我們將為在這道菜裡加上一些新鮮的蜆，從而變得更加美味。讓它成為你餐桌上的秘密武器吧！', '30分鐘', '2人'),
(810, '桂花牛奶凍', '2012-08-21', '桂花具有疏肝通氣、醒脾開胃，治牙痛、喉乾、口燥、口臭之功效，同時也有益腎氣之功.這道桂花牛奶凍，既有桂花的清香撲鼻，又有牛奶的爽滑口感，同時又賣相十足，值得大家一試。', '30分鐘', '3人'),
(811, '杏仁糊', '2012-08-21', '杏的營養價值很高，而杏仁的營養價值更豐富。杏仁含有豐富的單不飽和脂肪酸，有益於心臟健康；含有維生素E等抗氧化物質，能預防疾病和早衰。杏仁中還富含蛋白質和微量元素，有益於保持身材和美容。南北杏就是南杏仁和北杏仁。杏仁分甜和苦兩種，甜的習稱南，苦的習稱北杏。北杏仁多用於入藥，有小毒，不能多吃，南杏仁則味道更為香甜。', '10分鐘', ''),
(815, '台灣水瓜黑木耳炒牛腱', '2012-08-21', '這裡我們將介紹另一道夏日佳餚，台灣水瓜黑木耳炒牛腱的清脆口感，特別適合於不喜在夏天食用重口味菜餚的人群。同時水瓜和木耳都是涼性食材，有利於夏天清熱解毒，消除肺熱，保持身體健康。', '30分鐘', '2人'),
(846, '炸芝士豬排 [簡易親子食譜]', '2012-08-28', '芝士和豬排都是小朋友們很喜歡的食物， 因為口感酥脆，内裏松軟，再加上芝士的香味，確實誘人。今天我們就為大家介紹一下芝士豬排的簡單做法。', '30分鐘', '2人'),
(849, '港式芒果布丁', '2012-08-28', '芒果肉含有豐富的維生素A、維生素C和維生素D，中醫學認為，具有清熱作用、味甘、酸，性涼，有益胃止嘔、生津解渴及止暈眩等功效，甚至可治胃熱煩渴。今日就同大家分享一個簡單美味的港式芒果布丁食譜，最適合近日的炎熱天氣。', '1.5小時', '2人'),
(850, '日式牛肉飯[超簡易食譜]', '2012-08-28', '日式牛肉飯是一道很受大家歡迎的日本料理， 這時因為它不僅味道鮮美，而且做法容易。今天我們和大家分享這一道簡單的日式牛肉飯菜譜。在繁忙的日子里，它將成為你不論午餐還是晚餐的絕好選擇。而且孩子們也非常喜歡牛肉飯哦！', '30分鐘', '1人'),
(861, '日式炒飯[超簡單親子食譜]', '2012-09-04', '有時我們很難去估計做一個便當需要多少材料，所以在做完那些可愛的午餐便當之後，往往會剩下一些，例如香腸，玉米，雞蛋等等。利用這些剩下的食材，我們同樣可以做出美味的菜式哦！下次為孩子們做完便當後試試吧！', '10分鐘', '2人'),
(874, '清香南瓜餅', '2012-09-04', '南瓜中含有多種維生素，不但營養豐富，而且熱量低，還具有抗癌的作用；其中的果膠可以清除體內的重金屬和部分農藥，常吃南瓜也有助於防治糖尿病。這道南瓜餅，也有解毒和幫助消化的功效。\n\n<十五分鐘懶人版｜金沙南瓜>\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\n立即落單：金沙南瓜', '30分鐘', '4人'),
(875, '鹹蛋黃煮南瓜[時令健康食譜]', '2012-09-04', '南瓜果肉可降低血糖水平此外，南瓜多醣可以有效地降血脂，南瓜中的果膠能有效地解毒，護肝腎以及保護胃腸道黏膜，適宜於胃病患者。南瓜也能加強胃腸蠕動，幫助食物消化，從而達到通便潤膚的美容功效。這道將鹹蛋黃和南瓜的味道完美組合，入口即化，十分美味。', '10分鐘', '2人'),
(877, '桂花栗子粥[時令健康食譜]', '2012-09-04', '栗子粥屬上海菜菜系，主料為稻米和香栗子，栗子酥爛香糯，粥甜可口。栗子粥有補虛養身、壯腰健腎，調養脾胃的功效。', '1.5小時', '2人'),
(885, '栗子燒大白菜[時令健康食譜]', '2012-09-05', '這道板栗燒白菜不僅營養價值豐富，還十分美味，嚼兩口甘甜的栗子再配上一口百菜，蔬菜的脆爽多汁加上栗子的綿軟濃香，真是令人久久回味!', '1小時', '2人'),
(889, '秋葵山藥冷豆腐[秋節時令健康食譜]', '2012-09-05', '這款菜式有效的保留了秋葵的營養，同時又加入了營養價值同樣很高的豆腐和山藥，營養價值豐富，並且製作簡單，容易上手。', '30分鐘', '2人'),
(891, '草莓奶油芝士鬆餅[簡易親子食譜]', '2012-09-05', '', '10分鐘', '2人'),
(894, '秋葵雞肉沙拉[秋節時令健康食譜]', '2012-09-06', '這道菜最大益處是保有了秋葵的營養，口感清爽，是美容養顏的不二選擇.', '10分鐘', '2人'),
(896, '桂花南瓜蒸百合[秋節時令健康食譜]', '2012-09-06', '这款南瓜蒸百合，应大受女性歡迎的菜之一。這道菜味道清淡不油腻、精致不媚俗、营养又美容。非常适合女性的口味。我們今天就把这道菜送给那些热爱生活、追求健康生活的新派女性。', '1小時', '2人'),
(906, '簡易洋蔥燜鴨[中式家常食譜]', '2012-09-09', '', '1小時', '3人'),
(907, '自家制糯米釀鮮魷[傳統中式食譜]', '2012-09-09', '自家制糯米釀鮮魷[傳統中式食譜]', '30分鐘', '2人'),
(914, '蜜瓜螺頭雞湯', '2012-09-11', '蜜瓜螺頭雞湯燒出來的正色是奶白色，很濃很白。女士們喝最好，具有美容，滋潤效果。', '1.5小時', '2人'),
(916, '秋葵牛肉卷[秋季時令健康食譜]', '2012-09-11', '秋葵營養極其豐富，蛋白質、維生素A、B、C，微量元素應有盡有，是當之無愧的新型保健蔬菜。秋葵可消除疲勞、迅速恢復體力。經常食用幫助消化、增強體力、保護肝臟、健胃整腸。能增強人體防癌抗癌。不僅對皮膚具有保健作用，且能使皮膚美白、細嫩。\n\n<十五分鐘懶人版｜燒汁秋葵豬肉卷>\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\n立即落單：燒汁秋葵豬肉卷', '30分鐘', '2人'),
(922, '鮮百合洋蔥炒雲耳', '2012-09-14', '', '30分鐘', '2人'),
(927, '小黃瓜涼拌海蜇頭[簡易前菜食譜]', '2012-09-17', '海蜇含有人體需要的多種營養成分，碘的含量豐富；且含有一種類似於乙酰膽鹼的物質，能擴張血管，降低血壓；所含的甘露多醣膠質對防止動脈粥樣硬化有一定功效。海蜇能軟堅散結、行淤化積、清熱化痰，對氣管炎、哮喘、胃潰瘍、風濕性關節炎等疾病有益。', '10分鐘', '2人'),
(928, '蛋沙侓三文治[超簡易親子食譜]', '2012-09-17', '雞蛋含有豐富的蛋白質、脂肪、維生素和鐵、鈣、鉀等人體所需要的礦物質，同時對神經系統和身體發育有利，能健腦益智，改善記憶力，並促進肝細胞再生，雞蛋中也含有較多的維生素B和其他微量元素，可以分解和氧化人體內的致癌物質，具有防癌作用。今天就和大家分享這個簡單而且健康的蛋沙侓三文治食譜。', '10分鐘', '1人'),
(932, '麻醬有機菠菜[簡易健康小食食譜]', '2012-09-18', '菠菜含有大量的植物粗纖維，具有促進腸道蠕動的作用，幫助消化。菠菜也能供給人體多種營養物質，從而可以維護正常視力和促進兒童生長發育，增加預防傳染病的能力。其所含鐵質，對缺鐵性貧血有較好的輔助治療作用；同時菠菜也被民間用於美容保養，對去皺潔膚也有很好的效果。', '30分鐘', '1人'),
(933, '秋葵炒鮮百合黑木耳[秋季時令健康食譜]', '2012-09-18', '秋葵可消除疲勞、迅速恢復體力。經常食用幫助消化、增強體力、保護肝臟、健胃整腸。同時百合有利於美容養顏，清熱涼血。油性皮膚的人多吃百合對皮膚特別好。這道健康食譜味道清淡，適合各種人群。', '30分鐘', '2人'),
(935, '桂花糕', '2012-09-20', '桂花中所含的芳香物質，具有化痰、止咳、平喘的作用。同時桂花也具有行氣之功，能夠緩急止痛、散血消淤，並促進腸道穢濁物質的排泄，桂花的馨香，能祛除口中異味，並有殺滅口中細菌的功效。', '1.5小時', '2人'),
(936, '芋頭椰汁西米露', '2012-09-20', '芋頭又稱芋艿，口感細軟，綿甜香糯，營養價值近似於土豆，又不含龍葵素，易於消化而不會引起中毒，是一種很好的鹼性食物。它既可作為主食蒸熟蘸糖食用，又可用來製作菜餚、點心、因此是人們喜愛的根莖類食品。在廣東等地方，中秋節吃芋頭是源遠流長的一項習俗。\n 芋頭中豐富的營養價值，能增強人體的免疫功能, 提高機體的抵抗力，並有美容養顏、烏黑頭髮的作用，還可用來防治胃酸過多症；同時能增進食慾，幫助消化，故中醫認為芋艿可補中益氣。', '1小時', '2人'),
(966, '家鄉蓮藕餅[秋季時令健康食譜]', '2012-09-24', '蓮藕味甘，富含澱粉、蛋白質、維生素C和B1，以及鈣、磷、鐵等無機鹽，藕肉易於消化，適宜老少滋補。生藕性寒，有清熱除煩、涼血止血散淤之功；熟藕性溫，有補心生血、滋養強壯及健脾胃之效。藕段間的藕節因含有2%左右的鞣質和天門冬酰胺，其止血收斂作用強於鮮藕，還能解蟹毒。蓮藕的花、葉、梗、須、蓬及蓮子、蓮子心各有功效，均可入藥治病。\n\n<十五分鐘懶人版｜家鄉煎藕餅>\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\n立即落單：家鄉煎藕餅', '30分鐘', '2人'),
(968, '四川麻辣肚絲[簡易中式小食食譜]', '2012-09-24', '豬肚是中國人喜歡食用的一種食材，豬肚含有蛋白質、脂肪、碳水化合物、維生素及鈣、磷、鐵等，具有補虛損、健脾胃的功效，適用於氣血虛損、身體瘦弱者食用。', '30分鐘', '2人'),
(969, '冰糖雪耳燉木瓜', '2012-09-24', '南北杏可退肝火、解熱毒之功效。木瓜有多種營養素和蘿蔔素，蛋白質、鐵、鈣、木瓜酵素及有機酸，有利於抗癌防老。將這些營養豐富功效超多的材料放在一起燉個甜湯，犒賞自己的身體真的是很必要的喔！', '1小時', '1人'),
(981, '紅豆沙自家製湯丸', '2012-09-26', '【傳統中式甜品食譜】紅豆含有較多的皂角甙和膳食纖維，可刺激腸道，因此它有良好的利尿作用，能解酒、解毒，對心髒病和腎病、水腫有益，夏天人體易水腫，喝紅豆湯不失為一種好的消腫食療方法。同時紅豆也具有良好的潤腸通便、降血壓、降血脂、調節血糖、解毒抗癌、預防結石、健美減肥的作用。', '1.5小時', '2人'),
(982, '蓮藕燜排骨[秋季時令健康食譜]', '2012-09-26', '', '1小時', '2人'),
(998, '蠔皇碗仔翅', '2012-09-27', '', '30分鐘', '2人'),
(1006, '香蕉花生醬多士[超簡易親子食譜]', '2012-10-03', '', '10分鐘', '2人'),
(1007, '羅漢果蓮藕湯', '2012-10-03', '【秋季時令健康食譜】羅漢果蓮藕甜湯味道甘甜可口，有清肺止咳，和保護嗓子的功效，羅漢果性涼味甘，有消炎清熱，利咽潤喉的作用。羅漢果的皮也可用來泡水或煲湯。', '1.5小時', '2人'),
(1010, '帶子蒸豆腐', '2012-10-03', '帶子不僅味道鮮美，還富含蛋白質、碳水化合物、核黃素和鈣、磷、鐵等多種營養成分，礦物質的含量遠在魚翅、燕窩之上。帶子具有滋陰補腎、和胃調中功能，能治療頭暈目眩、咽乾口渴、虛癆咳血、脾胃虛弱等症，常食有助於降血壓、降膽固醇、補益健身。據記載，帶子還具有抗癌、軟化血管、防止動脈硬化等功效。', '30分鐘', '2人'),
(1011, '九層塔炒蜆[簡易海鮮食譜]', '2012-10-03', '九層塔是西餐中常見的食材，和番茄特別搭；潮菜中又名“金不換”。其花呈多層塔狀，故稱為“九層塔”，來自龐大羅勒家族，由於其葉與莖及花均有濃烈的八角茴香味，也叫蘭香羅勒，全草具疏風解表，化濕和中，行氣活血，解毒消腫之效。', '30分鐘', '2人'),
(1012, '可愛章魚便當[超簡易親子食譜]', '2012-10-03', '媽媽們是不是還在為孩子們在學校的午餐發愁呢？這款小章魚便當不僅賣相可愛，更加富有營養。小朋友們看到如此可愛的便當，怎麼能不願意把它吃光光呢？', '30分鐘', '1人'),
(1014, '鮮百合綠豆糖水', '2012-10-08', '炎炎夏日，在沒有胃口吃飯的時候能來一碗清爽的涼湯，那豈不是很美？綠豆薏米百合湯具有清熱解毒，美容降壓的功效。好吃又容易製作。下面我們就自己動手來做吧!', '1.5小時', '2人'),
(1016, '叉燒豆角炒蛋', '2012-10-08', '', '10分鐘', '2人'),
(1017, '雞蛋蔬菜捲[簡易親子食譜]', '2012-10-08', '', '30分鐘', '1人'),
(1021, '南瓜燜肉丸[秋季時令健康食譜]', '2012-10-09', '南瓜中含有多種維生素，不但營養豐富，而且熱量低，還具有抗癌的作用；其中的果膠可以清除體內的重金屬和部分農藥，同時也有解毒和幫助消化的功效。', '30分鐘', '2人'),
(1022, '鮮百合海鮮豆腐羹', '2012-10-09', '', '30分鐘', '2人'),
(1023, '涼瓜炒蛋[簡易家常食譜]', '2012-10-09', '苦瓜氣味苦、無毒、性寒，入心、肝、脾、肺經；具有清熱祛暑、明目解毒、利尿涼血、解勞清心、益氣壯陽之功效。', '30分鐘', '2人'),
(1024, '西芹百合炒蝦仁', '2012-10-11', '', '30分鐘', '2人'),
(1026, '小紅椒油爆牛肉[簡易家常菜食譜]', '2012-10-15', '', '30分鐘', '2人'),
(1027, '肉碎蛋角[傳統家常菜食譜]', '2012-10-15', '', '10分鐘', '2人'),
(1028, '海膽冷豆腐[美顏與健康食譜]', '2012-10-15', '', '10分鐘', '2人'),
(1030, '椰汁馬蹄糕', '2012-10-16', '馬蹄既可作為水果，又可算作蔬菜，是大眾喜愛的時令之品。馬蹄中含的磷是根莖類蔬菜中較高的，能促進人體生長發育和維持生理功能的需要，對牙齒骨骼的發育有很大好處，同時可促進體內的糖、脂肪、蛋白質三大物質的代謝，調節酸鹼平衡，因此馬蹄適於兒童食用。同時馬蹄對降低血壓也有一定效果。這種物質還對癌腫有防治作用。', '1小時', '2人'),
(1031, '馬蹄三色素', '2012-10-16', '馬蹄既可作為水果，又可算作蔬菜，是大眾喜愛的時令之品。馬蹄中含的磷是根莖類蔬菜中較高的，能促進人體生長發育和維持生理功能的需要，對牙齒骨骼的發育有很大好處，同時可促進體內的糖、脂肪、蛋白質三大物質的代謝，調節酸鹼平衡，因此馬蹄適於兒童食用。同時馬蹄對降低血壓也有一定效果。這種物質還對癌腫有防治作用。這道菜健康清淡， 適合口味清淡的人群。', '10分鐘', '1人'),
(1032, '番茄釀馬蹄牛肉', '2012-10-16', '【秋季時令健康食譜】馬蹄既可作為水果，又可算作蔬菜，是大眾喜愛的時令之品。番茄性甘、酸、微寒，歸肝、胃、肺經；具有生津止渴，健胃消食，清熱解毒，涼血平肝，補血養血和增進食慾的功效。', '30分鐘', '2人'),
(1035, '桂花馬蹄糕', '2012-10-18', '馬蹄既可作為水果，又可算作蔬菜，是大眾喜愛的時令之品。桂花具有疏肝通氣、醒脾開胃，治牙痛、喉乾、口燥、口臭之功效，同時也有益腎氣之功。', '1.5小時', '2人'),
(1036, '楊桃燉瘦肉湯', '2012-10-18', '【秋季時令健康食譜】楊桃不僅是水果，它的藥用價值也很大，具有清熱解毒、消滯利咽、通便等功效，它含有多種營養成分，並有大量揮發性成分，可消除咽喉炎症和口腔潰瘍，防治風火牙痛。', '1.5小時', '2人'),
(1037, '粟米馬蹄珍珠丸子[秋季時令食譜]', '2012-10-18', '玉米中的維生素B6、菸酸等成分，具有刺激胃腸蠕動、加速排便代謝的特性，可防治便秘、腸炎、腸癌等。玉米富含維生素C等，有長壽、美容作用。玉米胚芽所含的營養物質有增強人體新陳代謝、調整神經系統功能。能起到使皮膚細嫩光滑，抑制、延緩皺紋產生作用。玉米有補中益氣、開胃及降血脂、降血清、膽固醇的功效。', '1小時', '2人'),
(1038, '楊桃拌三絲[秋季時令健康食譜]', '2012-10-18', '楊桃也是好東西，楊桃不僅是水果，它的藥用價值也很大，具有清熱解毒、消滯利咽、通便等功效，它含有多種營養成分，並有大量揮發性成分，可消除咽喉炎症和口腔潰瘍，防治風火牙痛。', '30分鐘', '3人'),
(1050, '邪惡蜘蛛蛋[萬聖節食譜]', '2012-10-22', '', '30分鐘', '3人'),
(1053, '鬼馬釀青椒', '2012-10-22', '', '30分鐘', '3人'),
(1059, '蘆筍炒牛肉[簡易家常菜食譜]', '2012-10-24', '蘆筍是一種營養豐富的蔬菜，在國際市場上有“蔬菜之王”的美稱。蘆筍具有暖胃、寬腸、潤肺、止咳、利尿諸功能，對高血壓、血管硬化、心髒病、糖尿病、膀胱炎、急慢性肝炎及肝硬化有一定的輔助治療效果。\n\n<十五分鐘懶人版｜蘆筍炒牛肉>\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\n立即落單：蘆筍炒牛肉', '30分鐘', '2人'),
(1060, '葡國雞飯[簡易港式食譜]', '2012-10-24', '葡國菜的傳統風格偏濃郁，而經典菜式澳門葡國雞飯，正秉承了這一特點。黃薑是葡式料理中不可或缺的調味料，與咖哩一同做菜，味道格外香濃馥郁，令人無法抗拒。', '1小時', '1人'),
(1061, '楊桃燉牛腩', '2012-10-24', '楊桃不僅是水果，它的藥用價值也很大，具有清熱解毒、消滯利咽、通便等功效，它含有多種營養成分，並有大量揮發性成分，可消除咽喉炎症和口腔潰瘍，防治風火牙痛。', '1.5小時', '2人'),
(1080, '菊花雞絲', '2012-10-29', '菊花內含菊甙、胺基酸、黃酮類及多種維生素和微量元素。傳統醫學認為，菊花具有養肝明目、清心、補腎、健脾和胃、潤喉、生津，以及調整血脂等功效。常飲菊花茶，可以春暖去濕、夏暑解渴、秋日解燥、冬季清火。', '30分鐘', '2人'),
(1081, '枸杞菊花煲排骨[秋季時令健康食譜]', '2012-10-29', '菊花內含菊甙、胺基酸、黃酮類及多種維生素和微量元素。傳統醫學認為，菊花具有養肝明目、清心、補腎、健脾和胃、潤喉、生津，以及調整血脂等功效。常飲菊花茶，可以春暖去濕、夏暑解渴、秋日解燥、冬季清火。', '1.5小時', '2人'),
(1089, '菊花冰糖蓮子雪耳羹', '2012-10-30', '【秋季時令健康食譜】菊花內含菊甙、胺基酸、黃酮類及多種維生素和微量元素。傳統醫學認為，菊花具有養肝明目、清心、補腎、健脾和胃、潤喉、生津，以及調整血脂等功效。秋季常飲菊花茶，具有去燥明目的功效。', '1.5小時', '2人'),
(1094, 'XO醬炒雙鮮', '2012-10-31', '', '30分鐘', '2人'),
