(1164, '小青瓜三文魚忌廉杯[簡易派對食譜]', '2012-12-10', '', '10分鐘', '2人'),
(1165, '培根菠蘿鮮蝦卷[簡易派對食譜]', '2012-12-10', '年底的聚會一個接一個，是否已經外出party到腳軟？其實只要準備得當，在家里辦個健康美味的聚會並非難事哦！像這道培根菠蘿鮮蝦卷，味道脆甜可口，外型又至Q，實在是端出宴客的不二選擇！', '30分鐘', '2人'),
(1166, '節日三文治蛋糕', '2012-12-10', '', '30分鐘', '3人'),
(1172, '香桃豬肉捲【簡易家常食譜】', '2012-12-14', '', '30分鐘', '2人'),
(1179, '銀魚仔蝦米蒸茄子 [簡易家常食譜]', '2012-12-19', '', '30分鐘', '2人'),
(1181, '龍蝦牛油果杯 [簡易派對精選食譜]', '2012-12-21', '', '1.5小時', '2人'),
(1195, '素福袋', '2013-01-02', '', '30分鐘', '1人'),
(1199, '鮮菇繪牛肉飯', '2013-01-04', '', '30分鐘', '2人'),
(1200, '三杯鴨胸', '2013-01-04', '', '30分鐘', '2人'),
(1201, '鴨肉鬆生菜包', '2013-01-05', '', '30分鐘', '3人'),
(1202, '蔬菜牛肉捲', '2013-01-05', '', '30分鐘', '2人'),
(1204, '咖喱魚蛋豬皮蘿蔔', '2013-01-07', '咖喱魚蛋是在東南亞很常見的美食，今天我們將它帶進日日煮的廚房，教給大家如何輕鬆做好吃的咖喱魚蛋豬皮蘿蔔！', '1小時', '2人'),
(1205, '中式牛柳', '2013-01-07', '中式牛柳是非常普遍的中餐，它味道美，步驟少，容易做，是烹飪初學者可以嘗試的菜式之一。', '30分鐘', '2人'),
(1206, '上海小籠包', '2013-01-08', '', '30分鐘', '2人'),
(1207, '蘿蔔燜牛尾[簡易家常食譜]', '2013-01-08', '', '1.5小時', '3人'),
(1208, '鹵水牛展', '2013-01-08', '滷水牛展是晚宴上的絕佳開胃菜，而且你可以事先將它準備好，不用擔心涼掉。牛展很適合用來做涼切片，只需要簡單的去骨，低火燜2小時，你就可以品嘗到這道鮮嫩美味，入口即溶的滷水牛展。', '1.5小時', ''),
(1212, '黑椒蝦球炸茄子', '2013-01-09', '', '30分鐘', '2人'),
(1215, '上湯年糕', '2013-01-10', '年糕是東亞過年的一種傳統食品，中文裡年糕與「年高」諧音，有年年高的意思，象徵收入、職位或小孩子都一年比一年高。年糕早期是在年夜用來祭神及供奉祖先，其後漸漸成為一種春節食品。', '1小時', '3人'),
(1219, '土魷蒸肉餅[簡易家常食譜]', '2013-01-11', '送飯之選！簡單又方便，今晚就試試跟著以下步驟來做吧！\n\n<十五分鐘懶人版｜土魷肉餅 >\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\n立即落單：土魷肉餅', '30分鐘', '2人'),
(1223, '素菜肉丝炒年糕 [简易素菜食谱]', '2013-01-14', '', '30分鐘', '2人'),
(1224, '瑤柱蒸蛋白[健康家常食譜]', '2013-01-14', '', '30分鐘', '1人'),
(1235, '魚湯浸西洋菜 [健康家常食譜]', '2013-01-16', '', '30分鐘', '2人'),
(1236, '醬爆鴨胸', '2013-01-16', '', '30分鐘', '2人'),
(1240, '簡單素菜湯[簡易健康食譜]', '2013-01-17', '', '30分鐘', '2人'),
(1241, '馬拉盞炒芥蘭', '2013-01-17', '加入了蒜蓉和馬拉盞，整碟菜鹹香惹味香噴噴！\n\n<十五分鐘懶人版｜馬拉盞炒時菜>\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\n立即落單：馬拉盞炒時菜', '30分鐘', '2人'),
(1248, '千葉豆腐', '2013-01-18', '', '30分鐘', '2人'),
(1251, '三色蒸蛋[簡易家常食譜]', '2013-01-21', '', '30分鐘', '2人'),
(1254, '紅燒冬菇 [農曆新年食譜]', '2013-01-21', '', '30分鐘', '3人'),
(1255, '紅豆湯圓 - 合家團圓 [農曆新年食譜]', '2013-01-21', '', '30分鐘', '1人'),
(1256, '紅糖年糕 [農曆新年食譜]', '2013-01-21', '', '1小時', '5人'),
(1260, '白菜炒魚餅', '2013-01-22', '', '30分鐘', '3人'),
(1264, '糯米糖藕[農曆新年食譜]', '2013-01-23', '', '30分鐘', '3人'),
(1266, '巧克力蘸草莓 [情人節特別食譜]', '2013-01-23', '有什麽比在情人節收到愛人親手製作的巧克力更令人開心的事呢?如果你對自己既廚藝不係好自信，可以試一試這道簡單的食譜，一樣感動ta哦~', '10分鐘', '2人'),
(1267, '自家製心太軟[情人節特別食譜]', '2013-01-23', '心太軟是一道很受歡迎的法式甜點，其實它的做法也非常簡單，重點在於控制烤製的時間，保證内裏依然是流動的液體。由於大家使用的模具不同，烤制的時間也會需要相應調整，不過其實呢，就算烤至全部都成型也不用太過在意，因為它依然會是非常好吃的巧克力蛋糕！', '1小時', '2人'),
(1269, '涼拌蟲草花[健康前菜食譜]', '2013-01-24', '', '1.5小時', '1人'),
(1270, '愛心南瓜餅 [情人節特別食譜]', '2013-01-24', '大家有沒有試過中式的情人節甜點呢？像小編就好鍾意中式的傳統甜點...>~<其實只要花小小心思，看似很傳統的甜點也可以變得非常可愛呢~像這道愛心南瓜餅，配方同普通南瓜餅似乎沒什麽太大改變，但是如果是在情人節看到它的話，是不是會有想要試一試的衝動呢？', '30分鐘', '2人'),
(1271, '五香芋頭糕[農曆新年食譜]', '2013-01-24', '新年大家似乎都較鍾意做蘿蔔糕，但其實芋頭糕也是一個不錯的選擇。因為芋頭不僅口感更加柔軟幼滑，更可以使用較少的油，從而比較健康不油膩。特別是擔心新年期間食物太過油，但又不願意放棄口福的愛吃族，我們會大力推薦這道五香芋頭糕！', '1.5小時', '3人'),
(1272, '自製烘焙藍莓芝士蛋糕 [情人節特別食譜]', '2013-01-24', '芝士蛋糕好多人都鍾意食，但好多人都不知其實芝士蛋糕是相當容易製作的甜點，因為它的樣子看起來很專業呢！如果想要在情人節讓他大吃一驚的話，何不試試這款自製烘焙藍莓芝士蛋糕呢？', '1.5小時', '2人'),
(1278, '蝦仁蒸蛋', '2013-01-25', '', '10分鐘', '1人'),
(1279, '玫瑰情人露 [情人節飲品]', '2013-01-25', '美好的情人節之夜怎能少去一杯應景的飲品？如果你不想在情人節喝太多的話，可以試試這款無酒精的玫瑰情人露，由花朵們來為你的情人節之夜加持吧~', '30分鐘', '2人'),
(1280, '愛心迷你午餐肉壽司 [情人節特別食譜]', '2013-01-25', '本次情人節推薦中小編們最鍾意的食譜終於推出啦！這道愛心迷你午餐肉壽司有飯有肉，相對於甜食來說，更容易被男生接受，更得意的是，這款壽司外型可愛到爆，讓人覺得至專業。同時它也味道絕佳，小編們都贊不絕口，在影完像之後馬上被搶光光╮(╯▽╰)╭！大家有沒有心動呢？一起來試試吧！', '30分鐘', '2人'),
(1281, '海螺雞湯 [健康中式湯水食譜]', '2013-01-26', '', '1.5小時', '3-4人'),
(1283, '黑椒火腿風琴薯[情人節特別食譜]', '2013-01-26', '情人節想要做愛心晚餐的人，可以嘗試挑戰一下這道黑椒火腿風琴薯。馬鈴薯和火腿都是廣受歡迎的食材，烤制過後，火腿的香味會滲入馬鈴薯中，遠遠就能聞到香味！同時它的外表也比較特別，屬於好看又好吃的情人節推薦！', '1小時', '2人'),
(1284, '甜蜜燕麥香蕉[情人節特別食譜]', '2013-01-26', '', '10分鐘', '2人'),
(1285, '冬瓜草菇羮', '2013-01-28', '', '1小時', '3人'),
(1286, '酸梅蒸雞腿肉', '2013-01-28', '', '30分鐘', '3人'),
(1287, '法式紅燴牛腩 [情人節食譜]', '2013-01-28', '紅燴牛腩是最受歡迎的法國菜之一，加入紅酒后的牛腩顏色誘人，口感鮮嫩，還透著紅酒的酒香以及淡淡的果香，還未佐酒便已醉人。牛腩的醬汁也可以佐以法式麵包，又是另一種風味。單單這一道菜，幾乎就可成為豐盛的一餐了！', '1小時', '2人'),
(1288, '火鴨絲燜米粉[簡易粉麺食譜]', '2013-01-29', '', '30分鐘', '3人'),
(1289, '豆豉炒蜆', '2013-01-29', '簡易家常食譜', '30分鐘', '2人'),
(1292, '肉絲炒麵[簡易粉麺食譜]', '2013-01-30', '', '30分鐘', '1人'),
(1293, '魚香豆腐', '2013-01-30', '', '30分鐘', '2人'),
(1295, '鹽焗雞[簡易家常食譜]', '2013-01-31', '鹽焗雞是中國廣東特色客家菜餚。是在早年間客家人遷徙中流傳下來的醃製雞的方法，醃製過後的雞可在常溫下保持數日不壞。鹽焗雞皮軟肉嫩，香濃美味而不油膩，並有溫補功能，是適合在家自己製作的養生食材。', '1小時', '3人'),
(1296, '鹵水雙菇', '2013-01-31', '滷味常常令人大流口水，但如何製作好吃的素食滷味呢？今天我們就先來為大家介紹如何製作鹵水雙菇吧！', '1小時', '3人'),
(1298, '肉碎炒芽菜', '2013-02-01', '芽菜由於質嫩脆，味甜香，除作燒白底子外，多用於調味，如熬湯提味，做面肉餡。燒肉和炒肉絲中放些芽菜，都可增加鮮味，這道肉碎炒芽菜口感非常豐富，集合了米粉的酥脆，豬肉的鬆軟以及芽菜的鮮甜。', '30分鐘', '3人'),
(1299, '素擔擔面[健康素食食譜]', '2013-02-01', '擔擔麵是川味美食，受到大家的喜愛，今天介紹的這道素擔擔麵，讓素食者也能夠品嘗到這道美味。', '30分鐘', '1人'),
(1300, '柱侯魚蛋豬皮', '2013-02-02', '', '30分鐘', '3人'),
(1301, '拔絲香蕉[健康素食食譜]', '2013-02-02', '很多人都喜歡拔絲土豆或紅薯，其實很多其他的食材也可以用來做拔絲！今天我們很大家分享一道拔絲香蕉，一起來試試看吧！', '10分鐘', '1人'),
(1303, '簡易南瓜湯[熱門家常食譜]', '2013-02-04', '', '30分鐘', '3人'),
(1304, '翡翠玉卷', '2013-02-04', '這道翡翠玉卷可以由此延伸出很多種變化，其中的蔬菜可以根據個人喜好進行調整，也可以在此基礎上多一些創新，像最近小編的朋友就試著在裏面包上薄荷葉，清清涼涼也很好吃呢!', '30分鐘', '1人'),
(1305, '枸杞魚片湯', '2013-02-05', '枸杞葉具有養肝 滋腎 潤肺作用 同時對於頭暈目眩 目視不清 腰膝酸軟等也有好處', '30分鐘', '2人'),
(1306, '糖醋蓮藕[健康素食食谱]', '2013-02-05', '', '30分鐘', '2人'),
(1307, '雞蛋絲瓜滾豬肚菇湯', '2013-02-05', '', '30分鐘', '2人'),
(1308, '蘿蔔腐竹煲', '2013-02-05', '', '30分鐘', '3人'),
(1310, '芥菜豆腐湯', '2013-02-06', '芥萊是中國特有的蔬菜，中醫認為，芥菜性味辛、溫。入肺、胃、腎。功效宣肺化痰、溫中利氣。芥菜含有豐富的營養成分，具有維持人體機能新陳代謝的重要保健作用。', '30分鐘', '2人'),
(1311, '苦瓜的甜蜜吃法', '2013-02-06', '苦瓜与南瓜的完美结合，让不爱吃苦瓜的人，也会爱上苦瓜。苦味与甜味的结合，吃在嘴里也不觉得苦瓜有那么苦了，淡淡的苦瓜清香加上清甜软糯的南瓜，越吃越上瘾。性寒的苦瓜加上性温的南瓜，从搭配上来说比较合理，适合各个体质的人食用。', '30分鐘', '1人'),
(1313, '西蘭花海鮮羹[健康湯水食譜]', '2013-02-07', '西蘭花富含維生素C，在防治胃癌、乳腺癌方面效果尤佳。另外西蘭花還有增強機體免疫功能，它不但有利於人的生長發育，更重要的是能提高人體免疫功能，促進肝臟解毒，增強人的體質，增加抗病能力。', '30分鐘', '2人'),
(1316, '豆腐湯丸[健康食譜]', '2013-02-14', '這是一道小朋友很喜歡的菜，它不僅味道鮮美，而且營養豐富。', '30分鐘', '2人'),
(1317, '小豆腐[健康素食譜]', '2013-02-14', '現在很多家庭都會自己在家中製作豆漿，其實製作豆漿後留下來的豆渣也是很有營養價值的哦！今天我們就用這些豆渣來製作一款美味的小豆腐吧！', '30分鐘', '2人'),
(1318, '簡易韓式拌飯', '2013-02-14', '簡易韓式拌飯', '30分鐘', '1人'),
(1319, '自製無油健康薯片[健康素食譜]', '2013-02-14', '薯片似乎是人人都愛的零食，但日日吃商場買回的薯片，熱量高，鹽分也高，何不試著在家做一款為家人量身定制的無油自製薯片呢？', '30分鐘', '1人'),
(1323, '大蔥炒牛肉[簡易家常食譜]', '2013-02-17', '', '30分鐘', '2人'),
(1324, '薯仔煎蛋餅[簡易小食食譜]', '2013-02-17', '', '30分鐘', '1人'),
(1325, '雜菇燜伊麺[簡易粉麺食譜]', '2013-02-17', '', '30分鐘', '1人'),
(1335, '白蘿蔔燜火腩[簡易家常食譜]', '2013-02-25', '', '30分鐘', '2人'),
(1336, '梅子蒸排骨', '2013-02-25', '', '10分鐘', '3人'),
(1337, '番茄薯仔燜排骨', '2013-02-25', '', '1小時', '3人'),
(1338, '蒜子回鍋排骨', '2013-02-25', '「回鍋」做法一點都不難，做出來卻讓排骨酥軟可口！\n\n<十五分鐘懶人版｜回鍋肉>\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\n立即落單：回鍋肉', '30分鐘', '2人'),
(1339, '乾蒜香煎豬排', '2013-02-25', '', '30分鐘', '1人'),
(1340, '乾蒜豆豉燜排骨', '2013-02-25', '', '1小時', '2人'),
(1341, '苦瓜燜排骨', '2013-02-25', '', '30分鐘', '3人'),
(1345, '山藥薏米芡實粥', '2013-02-26', '通常的食物，即使是那些可以增長氣血的食物，我們想要獲取它的營養，也要先投入一些氣血來消化吸收它，可對於氣血太弱的人，這點氣血也拿不出來，而山藥、薏米、芡實，卻是不需要我們額外的支出，而卻能直接供給我們氣血的良藥美食。', '1小時', '2人'),
(1346, '香菇玉米粥', '2013-02-26', '', '1小時', '2人'),
(1349, '薏仁紫米燕麥粥 [健康初春食譜]', '2013-02-26', '薏米的營養價值很高,所含蛋白質遠比普通的大米、白面高。薏米美容大家都知道，常吃的話可以保持皮膚光澤細膩。薏米還有化濕利尿作用，是去濕消腫的法寶。燕麥所含的多種酶類有較強的活力，能夠幫助延緩細胞的衰老。', '1.5小時', '2人'),
(1350, '瘦身南瓜小米粥[健康初春食譜]', '2013-02-26', '', '1小時', '1人'),
(1351, '台式咸粥 [健康初春食譜]', '2013-02-26', '', '30分鐘', '2人'),
(1352, '清甜蛤蜊粥 健康初春食譜]', '2013-02-26', '', '1.5小時', '2人'),
(1353, '芋頭排骨粥[健康初春食譜]', '2013-02-26', '', '30分鐘', '2人'),
(1354, '皮蛋瘦肉粥 [健康初春食譜]', '2013-02-27', '', '1小時', '2人'),
(1355, '菠菜肉香米粥', '2013-02-27', '', '1.5小時', '1人'),
(1356, '薏仁牛奶粥', '2013-02-27', '薏仁具有排水和美白的功效，牛奶能滋潤肌膚，一舉兩得。', '10分鐘', ''),
(1357, '藍莓燕麥粥', '2013-02-27', '作為每日的第一餐，早餐一定要吃！這款是小編個人早餐的最愛，營養素搭配全面且暖胃。濃郁的麥香加上牛奶的綢滑配上藍莓的清甜，能量的持續釋放保證一個上午的充沛精力~', '10分鐘', '1人'),
(1358, '魚肉腐皮卷', '2013-03-01', '', '30分鐘', '1人'),
(1359, '豆豉釀茄子', '2013-03-01', '', '30分鐘', '2人'),
(1360, '白菜炒茄子[簡易家常食譜]', '2013-03-02', '', '30分鐘', '2人'),
(1361, '桂花炒粉絲', '2013-03-04', '', '30分鐘', '2人'),
(1363, '草菇三色蔬', '2013-03-04', '草菇富含蛋白質、氨基酸、脂肪、碳水化合物和維生素c等營養成分，草菇的維生素C含量高，能促進人體新陳代謝，提高機體免疫力，增強抗病能力。', '1小時', '3人'),
(1364, '番瓜雜菌盅', '2013-03-04', '這道雜菌盅造型小巧可愛，且在吃雜菌的時候還有絲絲番瓜香味，等菌類吃完，還可以享用香甜的番瓜，一舉兩得。', '30分鐘', '2人'),
(1365, '雜菌湯', '2013-03-04', '菌類是大家很喜歡食用的食材，今天為大家介紹一款雜菌湯，這款湯品味道清淡，盡顯菌菇原味。', '30分鐘', '3人'),
(1367, '乾鍋茶山菌', '2013-03-04', '', '30分鐘', '3人'),
(1371, '奶油蘑菇濃湯', '2013-03-05', '有一碗這樣的濃湯， 白天工作再苦再累， 也能化解； 有這樣的一碗濃湯， 生活再美不過如此了。', '30分鐘', '1人'),
(1372, '香菇燒栗子', '2013-03-05', '', '1小時', '2人'),
(1374, '辣油炒雞柳', '2013-03-06', '', '30分鐘', '2人'),
(1376, '臘肉炒豆角', '2013-03-07', '', '30分鐘', '3人'),
(1378, '水瓜浸蜆[簡易家常食譜]', '2013-03-11', '', '30分鐘', '3人'),
(1381, '芥菜豆豉燜排骨', '2013-03-11', '', '30分鐘', '3人'),
(1382, '奇異果乳酪煎餅', '2013-03-12', '奇異果乳酪煎餅', '30分鐘', '1人'),
(1384, '乳酪水果杯', '2013-03-12', '健康親子食譜', '10分鐘', '1人'),
(1386, '冰糖水果串串', '2013-03-12', '', '30分鐘', '1人'),
(1387, '奶味香蕉蛋羹', '2013-03-12', '奶味香蕉蛋羹是一款美味又營養的簡單輔食，它香味濃郁、嫩滑可口，是最常見的嬰幼兒營養食譜。', '30分鐘', '1人'),
(1388, '玫瑰櫻桃雙皮奶', '2013-03-12', '', '30分鐘', '1人'),
(1389, '香蕉士多啤梨奶昔', '2013-03-13', '這是另一道我們在春日里喜歡飲用的健康飲品。用香蕉、士多啤梨、乳酪和蜂蜜調製的可口甜蜜奶昔，既健康又大飽口福！', '10分鐘', '2人'),
(1390, '草莓煉乳布丁[健康親子食譜]', '2013-03-13', '', '1小時', '2人'),
(1391, '糖漬金桔', '2013-03-13', '', '1.5小時', '2人'),
(1392, '水晶橙子凍', '2013-03-13', '', '1.5小時', '2人'),
(1393, '秋梨蜜糖水', '2013-03-13', '秋梨蜜糖水是北京傳統特產，梨香芬芳、甜潤可口。讓家中老人和孩子經常飲用，可以起到很好的潤肺、化痰、止咳、安神的作用。', '1.5小時', '2人'),
(1394, '銀耳雪梨糖水', '2013-03-13', '', '1小時', '2人'),
(1395, '鯪魚球豆腐湯', '2013-03-13', '', '30分鐘', '2人'),
(1396, '健康紅菜頭湯', '2013-03-13', '', '30分鐘', '2人'),
(1397, '葡萄牛奶果凍', '2013-03-14', '', '1.5小時', '1人'),
(1399, '檸檬果凍蛋糕', '2013-03-15', '', '1.5小時', '2人'),
(1400, '香菇薏米燜飯 [健康粗粮食谱]', '2013-03-18', '', '1小時', '2人'),
(1401, '皮蛋瘦肉薏米粥 [健康粗糧食譜]', '2013-03-18', '薏米含有大量的維生素B1，可以改善粉刺，黑斑，雀斑和皮膚粗糙等等現象。薏米含澱粉非常豐富，易溶於水而易被消化吸收。薏米還有利水消腫、健脾去濕、 舒筋除痺、清熱排膿等功效，為常用的利水滲濕藥。常吃薏米可祛濕、健脾，現在醫學認為，薏米還具有很好的抗癌作用。加點薏米下去，還有美容的功效，營養也更加齊全了。', '1.5小時', '2人'),
(1405, '薏米排骨冬瓜湯 [健康粗糧食譜]', '2013-03-18', '薏米是這幾年突然廣泛流行起來的食物。山藥薏米芡實粥、薏米排骨冬瓜湯，這兩個估計是最常見的薏米做法吧。營養學說，薏米有消除水腫和預防腫瘤的作用，對腸胃很好，而且據說還可以美白。冬瓜和排骨常常被用來煮湯，雖然只是增加了一點點薏米，功效卻和之前已經不大一樣了。', '1.5小時', '3人'),
(1406, '黑米薏仁飯 [健康粗糧食譜]', '2013-03-18', '', '1小時', '2人'),
(1407, '花生薏仁芋圓糖水 [健康粗糧食譜]', '2013-03-18', '', '1小時', ''),
(1408, '紫糯小米豆漿[健康粗糧食譜]', '2013-03-19', '紫米滋陰補腎、明目補血。這道豆漿飲品富含B族維生素，有滋陰補腎、健脾暖肝、明目活血的功效，尤其對家中病後體虛者和孕婦的氣血恢復特別有益。', '1小時', ''),
(1409, '松仁玉米 [健康粗糧食譜]', '2013-03-19', '', '10分鐘', ''),
(1410, '鹹蛋黃烘玉米[健康粗糧食譜]', '2013-03-19', '', '30分鐘', ''),
(1411, '玫瑰冰糖小米粥 [健康粗糧食譜]', '2013-03-19', '', '1小時', ''),
(1412, '香糯窩窩頭', '2013-03-19', '', '30分鐘', ''),
(1413, '香茅雞扒', '2013-03-20', '香噴噴，啖啖肉的好滋味！香茅雞扒食譜，做法！\n\n<十五分鐘懶人版｜藜麥芝麻烤雞扒>\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\n立即落單：藜麥芝麻烤雞扒', '30分鐘', ''),
(1414, '帶子炒有機雪豆', '2013-03-20', '', '30分鐘', ''),
(1416, '可愛兔子饅頭', '2013-03-20', '', '1.5小時', ''),
(1417, '三色椒煎蛋', '2013-03-21', '', '10分鐘', ''),
