(1689, '香茅雞翼', '2013-05-14', '加入了香茅，只要用普通的醃製調料醃製雞翼，也能增添它的風味層次！\r\n\r\n<十五分鐘懶人版｜泰香茅魚露雞翼>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：泰香茅魚露雞翼\r\n\r\n\r\n<十五分鐘懶人版｜泰香茅魚露雞翼>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：泰香茅魚露雞翼', '30分鐘', ''),
