(25801, '扭扭車厘批', '2014-08-04', '車厘子是夏日受歡迎的水果之一。車厘子批是其中一種方法去品嚐車厘子的味道。利用這製作批皮的特別技巧，為這經典甜品增加趣味及時尚感。', '1.5小時', ''),
(25811, '字母牛油曲奇', '2014-08-04', '在小朋友的生日會中，送牛油曲奇是十分受歡迎的。不如為小朋友的生日派對，自製獨有的字母曲奇。再利用同一個曲奇模製作翻糖裝飾，就又容易、又萬無一失！', '1小時', ''),
(25821, '免焗花生燕麥曲奇', '2014-08-04', '這簡易又美味的食譜適合沒有焗爐的人。因使用即食燕麥，所以增加額外的纖維及質感，令曲奇更有口感。', '30分鐘', ''),
(25871, 'Oreo 雪糕', '2014-08-07', '這雪糕美味非常！當試在家中炮製此雪糕，可能很難再回超級市場，由街外買Oreo 雪糕了！', '1.5小時', ''),
(25881, '香橙雪糕', '2014-08-07', '這食譜做法簡單，亦不需要任何烹調或使用雪糕機。這種雪糕質地輕盈又綿滑，充滿果酸的清新味道，最適合夏天享用。', '1.5小時', ''),
(25891, '士多啤梨雪葩', '2014-08-07', '這雪葩食譜沒有加入牛奶，適合患有乳糖不耐症的人食用。食譜亦沒有使用蛋黃，即使加入糖，它的口感仍是十分輕盈及健康。清新的雪葩最適合豐富的晚餐後享受。', '1.5小時', ''),
(25951, '紅燒冬瓜火腩', '2014-08-11', '', '30分鐘', ''),
(25961, '南乳粉絲豆卜炆冬瓜煲', '2014-08-11', '', '30分鐘', ''),
(25971, '冬瓜燜排骨', '2014-08-11', '', '30分鐘', ''),
(25981, '冬瓜炒三絲', '2014-08-11', '', '30分鐘', ''),
(25991, '魚香冬瓜', '2014-08-11', '', '30分鐘', ''),
(26001, '咸魚雞粒冬瓜煲', '2014-08-11', '來試試這個咸魚雞粒冬瓜煲食譜，鹹香滋味，令人回味無窮！\r\n\r\n<十五分鐘懶人版｜咸魚雞粒豆腐煲>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：咸魚雞粒豆腐煲', '30分鐘', ''),
(26011, '蛋白海鮮冬瓜羹', '2014-08-11', '', '30分鐘', ''),
(26041, '煙三文魚刁草忌廉芝士貝果', '2014-08-15', '', '20分鐘', ''),
(26051, '煙肉生菜番茄三文治', '2014-08-15', '', '30分鐘', ''),
(26061, '呑拿魚沙律三文治', '2014-08-15', '', '20分鐘', ''),
(26071, '小紅莓雞沙律卷', '2014-08-15', '吃厭了麵包三文治的話，不如用粟米卷搭配喜歡的沙律來做一個健康小食吧！', '1小時', ''),
(26081, '雞肉米漢堡', '2014-08-15', '這款健康的米漢堡也是野餐的好選擇呀！你也試一試吧！', '1小時', ''),
(26101, '意式香草麵包', '2014-08-15', '誰說素食者選擇單調了？試一試自製香脆意式香草包配開胃的牛油果沙律吧！你那些食葷的朋友一定會嫉妒的！', '1.5小時', ''),
(26111, '白飯魚三色椒奄列', '2017-06-21', '鈣質吸收除佐奶類製品之外，仲可以從小魚之中既魚骨吸收到, 其實有好多吾同種類既小魚乾都係一D非常好既選擇，我今次為大家介紹既係白飯魚三色椒奄列', '10分鐘', ''),
(26131, '大蒜洋蔥炒雞柳', '2017-06-28', '準媽咪好多時會覺得吃藥會影響胎兒發展，但若果碰上流感高峰期，又確實好容易被傳染到，增強抵抗力，先至係最聰明既做法，而植物中既蒜素就係其中一種可以提升免疫系統既營養素。', '20分鐘', ''),
(26151, '小芋頭燜鴨', '2014-08-25', '小芋頭是中秋聚餐的傳統食材，物美價廉又健康，非常適合用來準備家庭聚餐！', '1小時', ''),
(26161, '栗子冬筍燜雞', '2014-08-25', '燜雞總能將一頓平常飯菜變得豐盛起來，更別說還加入了栗子和冬筍呢！下次你也試一試吧！告訴我們你喜不喜歡啊~', '1小時', ''),
(26171, '薑蔥海鮮粉絲煲', '2014-08-25', '美味而營養的煲仔菜令人垂涎欲滴，向來是廣受喜愛的中菜之一。最驚喜的是！做法居然這麼簡單啊。', '30分鐘', ''),
(26181, '子薑三色椒炒牛肉', '2014-08-25', '你喜歡顏色繽紛的食物嗎？那麼這道菜絕對適合你，三色椒令整道菜變得味道豐富而口感獨特。\r\n\r\n<十五分鐘懶人版｜三色椒炒牛柳片>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：三色椒炒牛柳片', '30分鐘', ''),
(26191, '金沙奶黃迷你月餅', '2014-08-25', '沒有什麼比健康而美味的金沙奶黃迷你月餅更適合歡度中秋啦！', '1.5小時', ''),
(26221, '砂窩雲吞雞', '2014-08-25', '這是一道簡單傳統而色味俱全的上海菜，而訣竅便是......太簡單了，沒有訣竅！', '1.5小時', ''),
(26231, '韓國牛骨奶湯', '2014-08-27', '有濃郁奶香的韓國牛骨奶湯是一道很受歡迎的韓國菜，步驟之簡易，你也會因此而享受在家自製的樂趣。', '1小時', ''),
(26241, '木瓜鮮奶燉杏仁露', '2014-08-27', '木瓜鮮奶燉杏仁露是一道傳統的中式甜點，為何不在家試著做個簡易版呢？', '30分鐘', ''),
(26251, '鮮奶魚湯', '2014-08-27', '奶白色的鮮味中式魚湯總是讓人難以抗拒。炮製美味魚湯是不可能的任務嗎？試一試這個建議食譜再說吧！', '30分鐘', ''),
(26261, '特濃牛乳奶凍', '2014-08-27', '奶凍是有名的意大利甜品之一，試一試這道呍呢拿味的簡易奶凍食譜吧！', '1.5小時', ''),
(26271, '脆皮炸鮮奶', '2014-08-27', '這道菜是一家老少的最愛。外脆內嫩的相互映襯，絕對不容錯過。', '1.5小時', ''),
(26291, '燉雙皮奶', '2014-08-27', '有誰不愛幼滑的雙皮奶嗎？快來看看在家自製的訣竅吧！', '30分鐘', ''),
(26341, '辣辣咖喱魚蛋', '2014-09-01', '', '1小時', ''),
(26351, '滷水鴨腎', '2014-09-01', '', '1小時', ''),
(26361, '酥炸雲吞', '2014-09-01', '', '1小時', ''),
(26371, '煎釀三寶', '2014-09-01', '', '1小時', ''),
(26381, '生菜魚肉湯', '2014-09-01', '', '30分鐘', ''),
(26451, '韓式牛肉拌麵', '2017-09-17', '星星熱之後，我以為韓國美食會慢慢冷卻，但反而韓國食店越開越多，咁等我都湊下熱鬧，教大家做一道快靚正既牛肉辣拌麵，尤其是牛肉含豐富鐵質同維他命B雜，非常適合女士，面色又會靚d，個人又會精神d，要做都要做個最靚既準媽咪！', '30分鐘', ''),
(26471, '鹹檸陳皮蒸烏頭', '2014-09-11', '', '30分鐘', ''),
(26481, '菜脯蒜芯炒牛肉', '2014-09-11', '', '30分鐘', ''),
(26491, '香辣蝦乾鴛鴦茄子煲', '2014-09-11', '', '30分鐘', ''),
(26511, '欖菜蒸排骨', '2014-09-11', '', '30分鐘', ''),
(26521, '蒜香銀魚花生', '2014-09-11', '', '30分鐘', ''),
(26531, '味菜炒三鮮', '2014-09-11', '', '30分鐘', ''),
(26571, '早餐Pizza', '2014-09-17', '在早餐是吃pizza的好處是你可以隨手抓起一塊就衝出家門！看一看我們的食譜，再打造你自己心水的專屬版本吧！', '1.5小時', ''),
(26581, '公司奄列', '2014-09-17', '無論是早餐或其他時間，想吃得健康而便捷的話，公司奄列總是一個不錯的選擇。材料方面沒有絕對限制，任君選擇！', '1小時', ''),
(26601, '花生果醬西多士', '2014-09-17', '你鍾意吃西多士嗎？試著跟這個食譜用新鮮果醬來做吧！新的一天從獨特有趣的食物混搭開始！', '30分鐘', ''),
(26611, '滑蛋番茄通粉', '2014-09-17', '這個快捷簡易的食譜包含滑蛋、通粉及香甜的番茄湯，作為傳統早餐非常受歡迎！', '1小時', ''),
(26621, '上海粢飯', '2014-09-17', '上海粢飯是一道有名的早餐食譜，一般以豆奶搭配伴食。最妙的不只是彈牙口感，餡料也非常特別。做給你關心的人們，為新的一天打造美好開端吧！', '30分鐘', ''),
(26631, '菜乾火鴨粥', '2014-09-17', '買回來吃剩的烤鴨你都怎麼處理呢？不妨試一試我們的菜乾火鴨粥食譜。記得要煮多一些，否則不夠吃呢！', '1小時', ''),
(26711, 'XO醬京蔥牛肉', '2014-09-23', '', '30分鐘', ''),
(26721, '日式咖喱漢堡扒', '2014-09-23', '', '1小時', ''),
(26751, '俄羅斯酸奶牛肉', '2014-09-23', '', '1小時', ''),
(26771, '威靈頓牛柳', '2014-09-23', '', '1小時', ''),
(26781, '啤酒炆牛腩', '2014-09-23', '', '1.5小時', ''),
(26791, '咕嚕雞球', '2017-10-15', '孕婦特別喜歡吃甜甜酸酸的餸菜，像咕嚕肉，但原來一碟咕嚕肉已經有1,100卡路里，所以我想用一個簡單的煮法去做這道低卡甜酸雞球，味道醒胃惹味，更能提供蛋白質及維他命B雜，對胎兒發展非常有幫助！', '30分鐘', ''),
(26831, '椰香南瓜湯', '2014-09-23', '', '1小時', ''),
(26841, '南瓜豆腐慕絲蛋糕', '2014-09-23', '', '1.5小時', ''),
(26861, '迷你南瓜杏仁茶', '2014-09-24', '', '30分鐘', ''),
(26881, '日式南瓜藜麥沙律', '2014-09-24', '', '30分鐘', ''),
(26931, '洋蔥南瓜燴雞柳', '2014-10-06', '', '30分鐘', ''),
(26941, '籠仔膏蟹糯米飯', '2014-10-08', '', '1小時', ''),
(26951, '蟹粉炒豆苗', '2014-10-08', '', '30分鐘', ''),
(26971, '薑茶湯圓', '2014-10-08', '', '30分鐘', ''),
(27011, '蟹粉燴伊麵', '2014-10-08', '', '30分鐘', ''),
