(27051, '香芋芥菜臘味飯', '2014-10-16', '', '30分鐘', ''),
(27071, '芥菜粉絲煮蜆', '2014-10-16', '', '30分鐘', ''),
(27081, '酸辣芥菜', '2014-10-16', '', '1.5小時', ''),
(27101, '金華火腿雞粒扒芥菜膽', '2014-10-16', '', '30分鐘', ''),
(27121, '辣辣手撕雞撈麵', '2014-10-18', '', '30分鐘', ''),
(27131, '韓式炒薯絲', '2014-10-18', '', '30分鐘', ''),
(27141, '炸芝士飯團', '2014-10-18', '', '30分鐘', ''),
(27171, '煙三文魚天使麵配芝麻醬', '2014-10-18', '', '30分鐘', ''),
(27181, '蚵仔麵線', '2014-10-18', '', '1小時', ''),
(27281, '蝦醬露筍炒牛肉', '2017-10-22', '煮牛肉的方法其實很多，這次用上蝦醬，希望為大家帶來新鮮感，牛肉方面我用了牛冧肉，比起普通瘦牛肉更軟腍，而且脂肪含量低，非常健康，再配合低卡高纖的露筍，有助孕婦預防便秘！', '30分鐘', ''),
(27461, '核桃糙米飯', '2014-10-24', '', '30分鐘', ''),
(27481, '紫糯米釀魷魚', '2014-10-27', '', '1小時', ''),
(27491, '香菇黑木耳糯米飯', '2014-10-27', '', '1小時', ''),
(27511, '迷你蛋包飯', '2014-10-27', '日式蛋包飯有很多款式，如以茄汁或咖哩煮成的飯。這次我們將會教大家炮製蛋包飯的迷你版本，而這個可愛的蛋包飯必定能夠滿足飯桌上的每一位。', '30分鐘', ''),
(27521, '牛肝菌海鮮燉飯', '2014-10-27', '這道海鮮燉飯完全能夠豐富一頓晚餐，令你得到滿足。烹調這美味的海鮮燉飯，最重要的秘訣是使用新鮮的海鮮，以及優質的牛油。為了令這道菜式更豐富多彩，本菜譜採用了很多香料，有助刺激大家的味蕾。', '1小時', ''),
(27531, '薑米蛋炒飯', '2014-10-27', '', '30分鐘', ''),
(27541, '臘味煲仔飯', '2014-10-27', '', '1小時', ''),
(27611, '海鮮香茜皮蛋鍋', '2014-10-31', '', '30分鐘', ''),
(27631, '麻辣魚片豆腐', '2014-10-31', '', '1小時', ''),
(27641, '蕃茄牛肉鍋', '2014-10-31', '', '30分鐘', ''),
(27651, '泰式酸辣鍋', '2014-10-31', '', '1小時', ''),
(27661, '五色豆漿素鍋', '2014-10-31', '', '1小時', ''),
(27671, '板栗燜排骨', '2014-10-31', '', '10分鐘', ''),
(27681, '臘肉雪菜炒毛豆', '2014-10-31', '', '30分鐘', ''),
(27691, '冰糖百合綠豆沙', '2014-10-31', '', '1小時', ''),
(27701, '日日煮燜鴨', '2014-10-31', '', '1小時', ''),
(27731, '蔥爆豬潤', '2014-10-31', '', '30分鐘', ''),
(27741, '紫番薯奶皇糯米糍', '2014-10-31', '', '30分鐘', ''),
(27761, '羊扒伴炒雜菜', '2017-11-26', '有好多人吾鐘意食牛肉，大部分係因為宗教既原因，但若果吾食牛肉，就吾能夠吸收足夠既鐡質，除佐孕婦本身會容易貧血，更會影響胎兒發展，而含豐富鐵質既羊肉，就絕對係代替牛肉既最佳選擇，只要配以香料烹調，就會成為一道美味佳餚！', '30分鐘', ''),
(27771, '香蒜大蜆意粉', '2017-10-29', '蜆含有豐富既維他命B12，可以幫助製做紅血球同埋維持神經系統健康，今次我用佐兩種香草黎烹調，除佐可以辟走貝殼類既海洋腥味，更可以增強鮮甜味，而香草熱量好低，就算落多D都吾會影響呢度菜式既熱量！', '30分鐘', ''),
(27891, '珍珠肉丸蒸豆腐', '2014-11-04', '', '30分鐘', ''),
(27901, '當歸紅棗豬肚湯', '2014-11-04', '', '1.5小時', ''),
(27911, '龍眼白蓮子白果露', '2014-11-04', '', '烹飪時間', ''),
(27921, '紅參大蒜連皮排骨湯', '2014-11-04', '', '1小時', ''),
(27931, '桂圓蜜棗紅參湯', '2014-11-04', '', '30分鐘', ''),
(27941, '肉桂紅酒炆牛肋骨', '2014-11-04', '', '1小時', ''),
(27951, '肉桂米酒粥', '2014-11-04', '', '1小時', ''),
(28041, '煙三文魚白汁意粉', '2017-11-05', '我好鍾意食三文魚，除咗有豐富的奧米加三脂肪酸可以保護心臟健康之外,它獨特的煙燻味可以令我增加食慾。但要留意不同牌子的三文魚所含的鈉質多少都有不同，只要以100克比較，就可以選出教低鹽份的牌子。', '30分鐘', ''),
(28051, '芝士焗薯蓉', '2017-11-12', '芝士是牛奶以外最佳的鈣質來源，而且它有獨特香味，令各類菜色增加不同口味，但原來芝士脂肪含量好高以最受歡迎的車打芝士為例，每1安士含9.5克脂肪，相等於兩茶匙油，大概佔總熱量的三成，都算致肥。', '30分鐘', '2人'),
(28061, '墨西哥火雞卷', '2017-12-09', '自己準備早餐，來來去去都是雞蛋、火腿、芝士等等，都有點悶。其實可以去大型西式超市的切肉專櫃，買燒牛肉、雞胸肉或者火雞胸肉來做份特色三文治，那就美味又有新意，今次教大家做這款墨西哥火雞卷，希望大家能夠星期日都可以係屋企食到一份精彩的早餐。', '30分鐘', ''),
(28071, '泡菜炒年糕', '2017-11-19', '泡菜其實是一樣百搭的食材，本身是韓國料理的前菜，但又可以作爲不同菜色的材料。例如炒肉片、放湯、煎蛋、炒飯等等。而泡菜本身都算是一種健康食材，因為大白菜本身已經是抗氧化蔬菜，發酵後會增加維他命B12同乳酸菌，非常健康，今次會用來炒韓式年糕，成為一道均衡健康的韓國佳餚。', '30分鐘', ''),
