(28221, '椰子紅棗雞湯', '2014-11-24', '椰子紅棗雞湯食譜做法，既鮮甜又滋潤，是個十分有益的湯水！\r\n\r\n<十五分鐘懶人版｜椰子雞湯>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：椰子雞湯', '1小時', ''),
