(28241, '紅棗杞子蒸排骨', '2014-11-24', '人見人愛的蒸排骨食譜做法，簡單容易。\r\n\r\n<十五分鐘懶人版｜紅棗杞子蒸雞>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：紅棗杞子蒸雞', '30分鐘', ''),
