(29001, '銀鱈魚煎蛋角', '2017-06-23', '銀鱈魚含豐富奧米加三脂肪酸，每100克魚肉含120-220毫克，建議每星期可吃二次這類深海魚，每次吃兩至三兩，若100克，既安全，又有益胎兒腦部發展。', '30分鐘', ''),
(29011, '番茄咖哩牛肉', '2017-12-17', '煮咖哩聽落好複雜好花時，但呢道番茄咖喱牛肉不單止開胃惹味，亦很快捷方便，20分鐘就可以煮好，用餸連汁送飯非常一流，牛肉又含豐富鐵質，適合無胃口的準媽媽。', '30分鐘', ''),
(29021, '北菇雲耳滑雞飯', '2017-12-24', '冬天躲懶但想吃惹味煲仔飯，吃完又怕洗煲好辛苦，不如試做我今日示範的北菇雲耳滑雞飯，只需一個普通電飯煲，配上已調味的配料，電飯煲一熄燈，一煲香噴噴的有味飯就大功告成了！', '30分鐘', ''),
