(29601, '粟米南瓜露', '2015-01-21', '這個甜品用上的是全天然的甜味調節劑，粟米和南瓜的糖份不少，而且為了提升甜品的飽肚感，有部分粟米會原粒烹煮，這樣就能延長咀嚼時間大大增加飽肚感，以免吃過一碗後，想再添食呢！\r\n\r\n一人份量 = 85 kcal', '30分鐘', ''),
