(29891, '[補而不燥篇] - 洛神花陳皮綠茶', '2015-01-24', '洛神花陳皮綠茶有涼血清熱滋潤腸道的功效，茶色漂亮又好味，係襯晒過年氣氛的保健茶。\r\n\r\n每周2-3次。月經量多者行經時不服。', '30分鐘', ''),
(29911, '[新年進補篇] - 馬蹄淮山黨蔘黃豆羊肉湯', '2015-01-24', '冬天天冷時，怕凍或陽虛者可每周服1-2次。一般一周服一次，也可起到暖身、助陽氣及禦寒的功效。因為加左成斤馬蹄，所以這煲湯不會太燥熱，馬蹄是涼的，中和左羊肉的燥熱。\r\n適合手冰腳凍，成日都怕冷又易病人士。', '1小時', ''),
(29921, '[新年進補篇] - 如意栗子紅豆年糕湯', '2015-01-24', '如意栗子紅豆年糕湯是一家大細都能食的甜品，食材性質平和，但年糕是糯米做的，較難消化，胃弱者勿多吃。最適合新春佳節時用來款待來拜年的親朋戚友。過一個吉祥如意的羊年。', '30分鐘', ''),
