(31391, '香草飯焗釀番茄', '2015-03-24', '', '1小時', ''),
(31401, '粟米煎餅配番茄莎莎', '2015-03-24', '', '1小時', ''),
(31411, '烤焗番茄意大利飯', '2015-03-24', '', '1小時', ''),
(31441, '番茄菠菜千層麵', '2015-03-24', '', '1小時', ''),
(31451, '手工艾草青團', '2015-03-30', '清明至，青團香。清明節吃青團這個說法一直流傳于江浙滬皖一帶。外婆的手工青團，將新鮮的艾草攪拌成汁加入糯米當中，包上紅豆沙餡。蒸出的一個個披著鮮亮綠色外衣的可愛團子，清甜甘香，軟糯可口，是最可愛的清明小食。', '20分鐘', ''),
(31461, '秘制外婆紅燒肉', '2015-03-30', '紅燒肉總是餐桌上最讓人垂涎欲滴的菜式，肥瘦相間的五花肉，香甜鬆軟，入口即化，肥而不膩。外婆們也最愛用這道菜牢牢地抓住著一代又一代人的胃。', '1.5小時', ''),
(31471, '青菜雞蛋面', '2015-03-30', '總覺得面是最溫暖的一種食物。無論是早餐或晚飯，開心或難過，一碗簡單卻用心，蒸騰著熱氣的青菜雞蛋面，總能給你一種暖暖的力量。', '10分鐘', ''),
(31481, '多汁番茄炒蛋', '2015-03-30', '番茄炒蛋大概是新手學菜的首選，烹調方法簡單易學，營養搭配合理，符合大眾口味。鮮嫩的雞蛋包裹著酸甜的茄汁，不僅口味極佳，豐富搭配的營養元素還有健美抗衰老的作用哦~\r\n\r\n 幫你買埋餸，即開即煮！\r\n 馬上選購： https://bit.ly/2X6C5QY', '10分鐘', ''),
(31491, '酸辣土豆絲', '2015-03-30', '酸辣土豆絲，一道人人都會愛吃人人都會做的家常菜。它就像鹽，就像水，似乎看似很簡單很平凡，但少了它一切又都不對勁。菜肴色澤光亮，酸辣可口極易下飯，當心吃太多米飯哦~', '10分鐘', ''),
(31501, '農家小炒肉', '2015-03-30', '有特色的菜式，哪怕是用最簡單的食材也能成就經典。其實農家小炒肉做法和用料都很簡單，沒有過於繁雜的調味，勝在原汁原味，突出乾脆俐落的肉香和辣椒香，充滿了濃濃的鄉土味。', '20分鐘', ''),
(31511, '土豆燉豆角', '2015-03-30', '土豆燉豆角是地道的東北家常菜，老少皆宜。土豆綿軟，芸豆脆爽，豬肉香濃，無論是搭配米飯或者是吃饅頭，它都是很適宜的一款家常美味。', '20分鐘', ''),
(31521, '平菇青筍炒肉片', '2015-04-02', '春天應多吃補充維生素和蛋白質的菜式，青筍，也叫萵筍，是春季時令蔬菜。含有大量的植物纖維素，能促進腸壁蠕動，促進消化。平菇富含多種維生素、礦物質，特別是蛋白質含量是雞蛋的兩倍。', '20分鐘', ''),
(31531, '泰式魷魚沙拉', '2015-04-02', '經典泰式涼菜。泰式涼菜和中式涼菜口味不一樣，泰式涼菜清淡、鮮美，常用水果入菜，料汁也多以青檸汁為主。清爽簡便的料理，酸酸甜甜搭上新鮮魷魚，口感豐富！', '10分鐘', ''),
(31541, '蛤蜊海帶豆腐湯', '2015-04-02', '經典家常菜，製作簡單，味道鮮美，營養豐富。蛤蜊富含蛋白質、鐵、碘等多種營養物質；豆腐藥食兼備，常吃可以促進機體代謝；海帶含有多種微量元素和膳食纖維。這三種價廉物美的食材結合在一起，成就了一道美味營養湯。', '20分鐘', ''),
(31551, '青椒炒豬潤', '2015-04-02', '青椒炒豬潤，口感鮮嫩，味道濃郁。豬潤的營養含量是豬肉的10多倍，豬潤中維生素的含量超過奶、蛋、肉等，豬潤含有的豐富的蛋白質可以增強體質，且富含可使大腦清醒和警覺的酪氨基酸。', '10分鐘', ''),
(31561, '檸檬煮青口', '2015-04-02', '青口鮮美肉嫩,再加上檸檬更突出青口的美味。青口具有很高的營養價值，含有豐富的蛋白質、以及各種維生素、碘、鈣、磷、鐵等微量元素和多種氨基酸，被稱為“海中雞蛋”。', '10分鐘', ''),
(31571, '香煎豬排佐蘋果', '2015-04-02', '選用豬脊肉，含有人體生長的發育所需的豐富的優質蛋白、脂肪、維生素等，而且肉質較嫩，易消化。蘋果除了讓豬排增添果香芬芳以外，還使得肉質鮮嫩的豬排絲毫不膩，酸甜適口。', '20分鐘', ''),
(31581, '照燒三文魚配時蔬', '2015-04-02', '簡約照燒三文魚配時蔬，營養美味，老少鹹宜。三文魚肉質緊密鮮美，含有豐富的不飽和脂肪酸，能有效降低血脂和血膽固醇，促進消化。搭配時蔬，更加營養美味', '20分鐘', ''),
(31591, '英式鬆餅配忌廉果醬', '2015-04-02', '', '1小時', ''),
(31601, '香茅單骨雞翼', '2015-04-03', '單骨雞翼吃起來就是爽，更易入口更入味！實際上就是簡單地利用剪刀，把雞翼從中間剪開即成，快來試試吧！', '1小時', ''),
(31621, '煎咖央西多士', '2015-04-03', '', '30分鐘', ''),
(31651, '焗棉花糖多士配水果茶', '2015-04-03', '', '30分鐘', ''),
(31721, '玫瑰紅豆蓉湯丸', '2015-04-12', '', '1小時', ''),
(31741, '洛神花果醬', '2015-04-12', '', '1小時', '');
INSERT INTO recipes (id, title, date, description, cooking_time, serving_size) VALUES
(31751, '薰衣草半熟蛋糕', '2015-04-12', '', '30分鐘', ''),
(31781, '桂花玻璃蝦球', '2015-04-12', '', '30分鐘', ''),
(31801, '椰奶酒香草莓芝士杯', '2015-04-13', '人氣簡易甜品，當新鮮的草莓遇上微甜的朗姆酒，當醉人的果汁裹入濃香的椰奶芝士，那種美妙的口感簡直讓人回味無窮。趕緊挑個陽光晴好的下午，與閨蜜們一同分享吧！', '10分鐘', ''),
(31811, '草莓果醬', '2015-04-13', '想更長久保存草莓的美味？那就趁著草莓季親手熬制一款草莓果醬吧，無添加無防腐劑打造自己的健康美味，可以搭配麵包和優酪乳，讓草莓的誘人果香一直環繞著你！', '20分鐘', ''),
(31821, '草莓大福', '2015-04-13', '超人氣草莓甜品，每個草莓大福裡面有一整個新鮮水靈的草莓。外面軟軟的年糕很治癒，裡面酸甜多汁的草莓很小清新。絕對是文藝女青年必學的可愛甜品！', '20分鐘', ''),
(31831, '草莓紙杯蛋糕', '2015-04-13', '草莓紙杯蛋糕，新鮮的草莓，酸甜的口感，無論是作為早餐或者下午茶點心都是不錯的選擇哦。紙杯蛋糕做起來也很簡單上手，整個蛋糕的造型可愛華麗，喜歡吃草莓味道的做起來吧。', '20分鐘', ''),
(31841, '草莓配洋甘菊奶油', '2015-04-13', '健康休閒甜品。洋甘菊茶有鎮靜作用，讓人變得溫柔和善，對於睡眠、穩定情緒也很有幫助，使人精神放鬆，搭配新鮮草莓和濃濃的奶油，健康營養又美味', '1.5小時', ''),
(31851, '義大利草莓蛋撻', '2015-04-13', '草莓+蛋撻，好吃到不能忍！草莓鮮美紅嫩，內含豐富維生素C，胡蘿蔔素和天冬氨酸，屬於水果中的尚品。經過蛋撻皮的完美呵護，讓整個草莓蛋撻散發出更加迷人誘惑的風味！', '20分鐘', ''),
(31881, '酥皮香橙杏仁條', '2015-04-16', '', '1小時', ''),
(31891, '眉豆土魷蒸肉餅', '2015-04-16', '眉豆含維他命B雜，配上肉嫩多汁的土魷肉餅，這樣的一道菜能夠令人不愛上嗎？\r\n\r\n<十五分鐘懶人版｜土魷肉餅 >\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：土魷肉餅', '30分鐘', ''),
(31901, '粟米鬚響螺豬腱湯', '2015-04-16', '', '1.5小時', ''),
(31911, '薏米海鮮周打湯', '2015-04-16', '', '1小時', ''),
(31921, '冬瓜蝦米煮粉絲', '2015-04-16', '粉絲把蝦米的鹹香和冬瓜的精華通通吸收了，組成了最完美的組合！\r\n\r\n<十五分鐘懶人版｜粉絲蝦米煮節瓜 >\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：粉絲蝦米煮節瓜', '30分鐘', ''),
(31931, '焗紅豆蓉西米布甸', '2015-04-16', '', '1小時', ''),
(31951, '三色豆桂花啫喱', '2015-04-16', '', '1.5小時', ''),
(31981, '茄汁大蝦', '2015-04-20', '茄汁大蝦是廣東漢族名菜，屬於粵菜系。主要原料是蝦，口味是酸甜，工藝是炒，烹飪難度屬於中級。蝦營養豐富，且其肉質鬆軟，易消化，對身體虛弱以及病後需要調養的人是極好的食物。蝦中含有豐富的鎂，鎂對心臟活動具有重要的調節作用，能很好的保護心血管系統。', '10分鐘', ''),
(31991, '鮮蝦天婦羅', '2015-04-20', '天婦羅是日式料理中的油炸食品，用麵粉、雞蛋與水和成漿，將新鮮的魚蝦和時令蔬菜裹上漿放入油鍋炸成金黃色，吃時蘸醬油和蘿蔔泥調成的汁，鮮嫩美味，香而不 膩。 天婦羅不是某個具體菜肴的名稱，而是對油炸食品的總稱。 而具體的種類則有蔬菜天婦羅、海鮮天婦羅，什錦天婦羅等等。 自己之前也沒做過，所以就在做蝦肉餛飩的時候順便留了六隻小蝦出來做這道天婦羅，味道很鮮美的，外香脆，裡嫩甜，蘸點醬油香醋，或者搭配水果吃也是很不錯的選擇哦。', '20分鐘', ''),
(32001, '蒜蓉粉絲蒸蝦', '2015-04-20', '蒜蓉粉絲蒸蝦是一道清淡鮮香的菜，粉絲吸收了蝦的鮮，更加美味。其中的蒜具有殺菌和治傷寒的作用,特別是其中的蝦的擺盤整形好的話,也是一道很適合用來招待親朋好友的宴客菜。', '10分鐘', ''),
(32011, '醉蝦', '2015-04-20', '醉蝦是南通，上海以及寧波一帶的一道漢族傳統名菜。顧名思義，就是把活蝦放入酒中，沒一會兒蝦就醉了。把冰塊放入玻璃器皿中，然後放入活蝦，最後將黃酒倒入完全浸泡住蝦並蓋上蓋子。食用者即可以嘗到蝦的鮮香，同時也可以嘗到酒的洌香。醉蝦肉質鮮美口感飽滿、回味悠長、軟嫩滑爽。', '20分鐘', ''),
(32021, '黃金鳳尾蝦', '2015-04-20', '鳳尾蝦，江蘇南京市漢族傳統名菜，屬金陵菜，蝦肉潔白，尾殼鮮紅，形似鳳尾，襯以綠色青豆，色彩豔麗，蝦味鮮嫩。其主料為河蝦，並以雞蛋清和豌豆做輔。不僅營養豐富，養血固精，而且能夠延緩衰老，提高機體的抗病能力和免疫功能。', '20分鐘', ''),
(32031, '香煎玉米蝦餅', '2015-04-20', '把玉米跟蝦完美的結合在了一起，外酥裡嫩，外面的一層殼又牢牢的把玉米和蝦的營養包裹了起來，不讓它們有任何的流失。\r\n\r\n<十五分鐘懶人版｜蝦膠粟米餅>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：蝦膠粟米餅', '20分鐘', ''),
(32041, '荷蘭豆炒蝦球', '2015-04-20', '荷蘭豆脆爽，蝦仁鮮嫩，搭配在一起，不僅色澤靚眼，而且口感豐富，是道簡單易做的好菜哦！\r\n\r\n<十五分鐘懶人版｜蜜糖豆桂花蝦球>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：蜜糖豆桂花蝦球', '10分鐘', ''),
(32051, '椰皇雪耳燉蛋白', '2015-04-21', '', '1.5小時', ''),
(32081, '木耳蟲草花紅棗雞卷', '2015-04-21', '【木耳蟲草花紅棗雞卷食譜】需要花點心思，但難道不高，快來試試！\r\n\r\n<十五分鐘懶人版｜黃金雞卷>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：黃金雞卷', '1小時', ''),
(32091, '雲耳百合杞子炒絲瓜', '2015-04-21', '', '30分鐘', ''),
(32101, '無花果蘋果燉豬腱湯', '2015-04-21', '', '1.5小時', ''),
(32111, '黑芝麻豆漿布甸配芝麻薄脆', '2015-04-21', '', '1小時', ''),
(32161, '芝味通粉', '2015-04-22', '', '1小時', ''),
(32171, '滑滑蛋蝦仁', '2015-04-22', '', '30分鐘', ''),
(32201, '法式洋蔥湯', '2015-04-25', '', '1.5小時', ''),
(32261, '法式蘋果批', '2015-04-25', '法式蘋果批', '1.5小時', ''),
(32271, '浪漫櫻花慕斯', '2015-04-27', '慕斯是人氣甜品之一，柔軟香甜，入口即化。白色慕斯底搭配粉色的鹽漬櫻花，就成了粉色系唯美風的櫻花慕斯，瞬間俘獲了眾多少女的心。不單單是舌尖上的美味，更具視覺上的衝擊，這款甜品，無論是送給愛人，或是親密的朋友，想來都是一款讓對方倍感驚喜的禮物。', '1小時', ''),
(32281, '櫻花壽司', '2015-04-27', '壽司是日本的傳統美食，口味眾多，在櫻花季節不可錯過的便是櫻花壽司，淡淡的花香留於唇齒，清淡不油膩。粉色的花瓣造型，每一個被吃的花瓣，都把春天留在你的身體裡。', '20分鐘', ''),
(32291, '抹茶櫻花費南雪', '2015-04-27', '費南雪是一款法國糕點，最初的費南雪做得很像縮小版的金條，是巴黎證券交易所附近的蛋糕師傅發明的茶點,據說是為了讓那些在證券交易所的金融家們能快速食完並不弄髒他們的西裝。而糕點本身也做成金條狀，頗有寓意。費南雪可以加入各種食材變換不同口味，抹茶櫻花費南雪，濃郁的茶香搭配櫻花的清雅淡香，讓每一口都充滿春日生機。', '30分鐘', ''),
(32301, '櫻花梅子飯糰', '2015-04-27', '在追求健康的今天，相比於一般熱量很高的速食食品，飯糰開始愈發得到人們的青睞。主要成分為大米，大小適中，不易發胖。軟糯的米飯，搭配清新的櫻花和酸爽的梅子，再加上親手手工製作的感覺，吃飯糰便成為了一件迷人的事情。', '20分鐘', ''),
(32311, '櫻花黃油餅乾', '2015-04-27', '櫻花黃油餅乾是最適合新手的簡單點心，黃油賦予了它十分酥鬆的口感，加入蛋黃更有濃郁風味，點綴的櫻花讓餅乾看起來可愛誘人。在週末慵懶的午後，和朋友一起享用親手烘焙的可愛櫻花黃油餅乾，享受愜意時光。', '30分鐘', ''),
(32321, '手擀櫻花素面', '2015-04-27', '櫻花素面是傳統櫻花料理之一，將櫻花粉一起和麵，做出的麵條透著淡淡的紅暈晶瑩透亮。麵條在盤中卷著，就等一雙筷子啟動出生氣，在口裡跳躍出花的芳香來。', '1.5小時', ''),
(32331, '櫻花和果子', '2015-04-27', '櫻花和果子，是日本特色點心。粉嫩的粉紅顏色、花瓣的形狀，甚至是材料上也取用櫻花花瓣或是鹽漬的櫻花葉。在日本，和果子基本上是依附在茶道中副產品，也就是佐茶的茶食，茶道老師蘇信義表示，日本人喝抹茶配食甜膩的和果子，多少有養生的意義在，因為糖份可以抵消生茶刮胃去油的功效。', '30分鐘', ''),
(32341, '香菇蛋撻', '2015-05-04', '香菇蛋撻是一道造型新穎又簡單好味的菜。香菇在民間素有“山珍”之稱，是高蛋白低脂肪的營養食材。搭配鵪鶉蛋和雞肉，口感新鮮醇厚，色香味俱佳。', '20分鐘', ''),
(32351, '乾鍋茶樹菇', '2015-05-04', '乾鍋茶樹菇是一道湖南家常菜，菜品口味濃郁鮮香，酸辣適口。在眾多的蘑菇中，茶樹菇被譽為“中華神菇”，營養豐富，菇柄脆嫩爽口。臘肉的香味和茶樹菇的香味完美地融合，是一道越煮越好吃的下飯菜。', '20分鐘', ''),
(32361, '金針菇豉油蒸豆腐', '2015-05-04', '春季多吃一些菌菇和豆製品有益身體健康。那麼這兩樣素食如何做出美味呢？我們不需要用大油、用增味劑，只要加一些肉末，再澆上蒸魚豉油就可以做出健康又美味的家常菜。', '10分鐘', ''),
(32371, '香煎肥牛金針菇卷', '2015-05-04', '金針菇肥牛卷向來廣受食客們的推崇，兩種看似毫不相干的食物，竟能如此巧妙地融合在一起，不得不說是中西式食物結合的又一完美體現。嗜油的金針菇能充分地吸收肥牛的油膩，配上與肥牛堪稱為絕配的蠔油，牛肉鮮美，金針菇滑溜，經過烤制後又有點脆的口感，異常鮮美。', '20分鐘', ''),
(32381, '奶油蘑菇湯', '2015-05-04', '湯類在西餐中佔有重要的地位。西方人的飲食習慣是在熱菜之前先喝湯。奶油蘑菇湯是法國菜譜之一，以蘑菇為制作主料，奶油蘑菇湯的烹飪技巧以白燒為主，口味屬於奶湯鹹鮮。', '1.5小時', ''),
(32391, '菌菇雞肉焗飯', '2015-05-04', '有一種飯怎麼做都好吃，那就是焗飯。袁枚在《隨園食單》中說菌菇是一種“可葷不可素”的食材，和雞肉的搭配更能相得益彰。用來焗飯，真的是好吃到打嘴都不放！', '10分鐘', ''),
(32401, '義大利菌菇水餃', '2015-05-04', '義大利餃是一種傳統的義大利麵食，以面皮做成袋狀，放入沸水中煮熟。因為面皮中沒有加水，使得口感更佳特別。有傳言，義大利水餃是由馬可波羅從中國帶到義大利的。用菌菇作為水餃的餡兒，使得水餃的口感更佳豐富。', '20分鐘', ''),
(32411, '奶油培根意大利面', '2015-05-04', '奶油培根意大利面', '10分鐘', ''),
(32421, '自製糖葫蘆', '2015-05-06', '糖葫蘆這種零食從古至今都是孩子們的最愛，成人也會偶爾回憶一下童年。如果不放心“路邊攤”的食品安全，不如自己在家動手做吧，既方便又衛生。', '10分鐘', ''),
(32431, '三色蒸雞蛋', '2015-05-06', '三色蒸雞蛋', '10分鐘', ''),
(32471, '香煎芋蓉腐皮卷', '2015-05-07', '', '1小時', ''),
(32481, '忌廉雙花湯', '2015-05-07', '', '1小時', ''),
(32551, '糖醋紫菜素雞卷', '2015-05-07', '', '30分鐘', ''),
(32601, '冬菇燜五花肉', '2015-05-07', '冬菇燜五花肉', '1小時', ''),
(32621, '蜜瓜果凍', '2015-05-10', '不管什麼季節，QQ順滑的果凍一直是受大家鍾愛的一類甜品，男女老少都愛吃。果凍不含脂肪，可以算是減肥的佳品。自己在家動手製作蜜瓜果凍，除了能夠保證果凍中食材的新鮮，又能減少防腐劑、糖和香料的吸收，更加有益健康！', '1小時', ''),
(32631, '櫻桃克拉芙提', '2015-05-10', '克拉芙緹作為一道傳統的法國甜點，在法國幾乎家家都會做。它比松餅更能吃出奶香，比布丁口感更實在。一般的克拉芙緹都是櫻桃的，而且還不去核，據說不去核的櫻桃烤出來的克拉芙提有杏仁兒的香味兒，而且能更好地鎖住櫻桃的水分。而且冷藏後風味更佳哦！', '30分鐘', ''),
(32641, '香蕉核桃戚風蛋糕', '2015-05-10', '入口即化的戚風蛋糕很受熱愛甜點的食客們的歡迎。它口感細膩，配料很少，操作簡單。很適合在家自己做。香蕉和核桃的加入，更佳豐富了戚風蛋糕的口感，使得味蕾的感覺更佳豐盈，香味的層次的更佳明顯。', '1小時', ''),
(32651, '芒果優酪乳布丁', '2015-05-10', '布丁和魚薯一樣，是極具代表性的英國料理。相比果凍，布丁有更多的奶味和雞蛋的味道，所以營養更佳豐富，但熱量也很低。當優雅英倫范兒的布丁邂逅香甜的芒果和酸甜的優酪乳，就會碰撞出無與倫比的肆意果香和酸甜爽口，絕對是低熱量下午茶甜點的好選擇！', '30分鐘', ''),
(32661, '藍莓軟曲奇', '2015-05-10', '軟曲奇在各種烘焙品中，應該算是獨樹一幟的存在。它的口感介於餅乾和蛋糕之間，既不想蛋糕這般濕軟，又不像餅乾那般幹硬。混合入藍莓的清香，外酥內軟，又不過分甜膩。做起來簡單又省時，可算是入門級甜品哦！', '30分鐘', ''),
(32671, '西瓜芒果冰沙', '2015-05-10', '有什麼能比水果味的冰沙更能緩解燥熱的味蕾呢？熱情的芒果、鮮豔的西瓜和冰塊交融在一起，碰撞出色澤鮮美、味道涼爽甘甜、果味純厚、口感細膩、冰涼透心的清爽感覺。', '1.5小時', ''),
(32681, '哈密瓜慕斯', '2015-05-10', '慕斯蛋糕最早出現在美食之都法國巴黎，是最令人驚豔的冷點，輕輕的咬一口，涼涼的感覺，那固體在嘴裡倏的變成又香又甜的汁水，如同遊戲一般讓人無法拒絕。又由於其中鎖水成分的存在，所以，加入了哈密瓜的慕斯，更加的香甜可口。', '20分鐘', ''),
(32751, '泡菜午餐肉炒飯', '2015-05-11', '泡菜午餐肉炒飯', '10分鐘', ''),
(32811, '忌廉薯仔千層批', '2015-05-12', '', '1小時', ''),
(32821, '日式薯仔燉肉', '2015-05-12', '', '1.5小時', ''),
(32841, '雞肉洋蔥煎薯餅', '2015-05-12', '', '1小時', ''),
(32851, '金黃薯餅全日早餐', '2015-05-12', '', '1小時', ''),
(32941, '珊瑚水晶卷', '2015-05-15', '家宴上的堪稱人氣王的開胃菜。雖是小菜一碟，可是既好看又好吃。味道清新，色澤鮮豔，脆脆爽爽、酸酸甜甜的，可以刺激你的味蕾，以達到食欲大開的目的。山楂本身具有消食健胃的功效，而蘿蔔同樣可以促進胃液分泌，調整胃腸功能。而且，做法非常非常簡單。', '10分鐘', ''),
(32951, '糖醋櫻桃小蘿蔔', '2015-05-15', '這據對是一道讓你眼前一亮的開胃解膩的家常菜。櫻桃蘿蔔口感甜甜脆脆，微微辣，很適合生吃。而且超Q超可愛。只要看上一眼就會心情大好可以算得上是治癒系蔬菜。酸酸甜甜，冰涼脆爽，不管你是吃素還是吃肉，餐間端出這麼一盤小蘿蔔，絕對的開胃解膩哦，還很養眼。', '10分鐘', ''),
(32961, '花生拌菠菜', '2015-05-15', '菠菜配合醋的酸爽，花生的香味會變得很清新。菠菜性涼，有滋陰潤燥、養血止血、刺激腺液分泌的功效。菠菜烹熟後軟滑易消化，特別適合老、幼、病、弱者食用。絕對是一道開胃又健康的涼拌菜。', '10分鐘', ''),
(32971, '韓式拌芽菜', '2015-05-15', '這是一道清熱去火的夏季涼菜，這道菜菜做法簡單，用料簡單，但卻是清熱、去火、降燥、解毒、除濕的好菜。在很多韓式的飯店，它都會作為小菜贈送給客人開胃。而它清爽的口感，在夏天一上桌就會遭到哄搶。大家不妨經常做來吃吃。', '10分鐘', ''),
(32991, '涼拌藕丁', '2015-05-15', '湖北的特色菜中，藕占了相當重要的席位，涼拌藕丁是一道湖北菜。它不僅是夏秋季最清熱去火的養生菜，而且它還是湖北酒店裡的一道招牌菜！與此同時，這道菜的做法非常簡單，相信也可以算得上是入門級的菜肴了。', '10分鐘', ''),
(33001, '蒜泥白肉', '2017-01-26', '成都“竹林小餐”名菜之一，曾風靡一時，為人們稱道，此菜要求選料精，火候適宜，刀工好，佐料香，熱片冷吃。吃的時候用筷子拌一下，一股醬油、辣椒油和大蒜組合的香味直撲鼻端，使人食欲大振，肥而不膩。', '10分鐘', ''),
(33041, '花雕雞麵', '2015-05-21', '雞肉吸收了花雕的酒香味，加上用麵條把湯汁精華完全吸收，這道花雕雞麵會讓人一口接一口，把湯料也喝得一滴不留。', '1小時', ''),
(33051, '整個番茄大蝦飯', '2015-05-21', '熱爆互聯網的整個番茄飯，加點心思加入不同材料就可以千變萬化，這次加入蒜頭、橄欖油、巴馬臣芝士，增添意大利飯的風味。', '30分鐘', ''),
(33061, '啤酒雞肉蘑菇飯', '2015-05-21', '一個電飯煲也可以輕鬆煮出豐富晚餐，煮飯時用黑啤取代水，煮出來的飯就帶有麥香，加上雞肉、蘑菇、洋蔥等配料，味道就更豐富。', '1小時', ''),
(33071, '簡易日式烏冬', '2015-05-21', '不想吃飯的日子，簡單煮個烏冬就方便不過，雪櫃裡找到任何材料也可以加進去，自創新口味。', '1小時', ''),
(33081, '三文魚魚籽飯', '2015-05-21', '煎至金黃色的三文魚，內裡仍保留嫩滑的質感，將三文魚搗碎與米飯混在一起，是簡單又美味的Comfort food。', '1小時', ''),
(33091, '一鑊熟番茄羅勒意粉', '2015-05-21', '煮意粉例必先把意粉灼熟，再用煎鍋加其他材料一起烹煮，這次教大家用一個鍋就完成這道意粉，味道不比平日的意粉差啊！', '1小時', ''),
(33101, '西班牙海鮮飯', '2015-05-21', '到西班牙餐廳最愛點連巨型鍋上枱的海鮮飯Paella，在家沒有大鍋怎麼辦？普通煎鍋也一樣做到。', '1小時', ''),
(33111, '薑檸可樂雞翼', '2015-05-21', '檸樂煲薑是醫治初起感冒的民間偏方，將它與小時候常吃的可樂雞翼結合，成為既酸又帶少許辣的版本，派對必備。', '1小時', ''),
(33121, '特濃咖啡骨', '2015-05-21', '一杯特濃咖啡是意式咖啡的根本，有了它就可變出Cappuccino、Mocha等飲品，用來下廚又如何？配搭排骨原來非常可口，濃香味道一吃難忘。', '1小時', ''),
(33131, '黑啤燴牛仔骨', '2015-05-21', '外國人很喜歡用黑啤入饌，尤其炆煮肉類菜式，甚至用來做蛋糕！今次先來入門版黑啤燴牛仔骨，加入喜歡的蔬菜一起燴，做法簡單但成品非常有成功感。\r\n \r\n<十五分鐘懶人版｜惹味黑椒牛仔骨>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：惹味黑椒牛仔骨', '1小時', ''),
(33141, '三文魚茶漬飯', '2015-05-21', '初次遇上茶漬飯，很好奇茶怎麼混飯一起吃？試過後竟然愛上那清香的味道，配搭油潤的三文魚，美味飽肚又健康。', '30分鐘', ''),
(33171, '韓式牛肉水冷麵', '2015-05-21', '夏天光顧韓國菜餐廳，少不了吃清涼的水冷麵，韓國人喜歡用梨入饌，水冷麵必定伴有清甜爽口的梨片，多吃也不膩。', '1.5小時', '1人'),
(33181, '菠菜松子意大利面', '2015-05-22', '菠菜松子意大利面', '10分鐘', '2人'),
(33221, '穀麥炒滑蛋配多士', '2015-05-26', '', '10分鐘', '2人'),
(33261, '有營香蜜脆雞條配卜卜米芝茄串', '2015-05-26', '', '30分鐘', '1人'),
(33271, '黃瓜細卷', '2015-05-27', '細卷的直徑為3cm左右，吃起來十分方便。做起來也可以算是壽司中最簡單的一種。在上面只放一種配料，將其卷起，還有一種說法就是因為它的樣子細長，又被稱為“槍卷”。', '10分鐘', '1人'),
(33281, '太卷', '2015-05-27', '太卷壽司是日本壽司中的一種，通常卷上好幾種食材卷成的壽司卷較粗，主婦們為了好看，常常特意做出橫切面呈現有趣圖案的太卷，有個特別的名稱叫裝飾壽司。', '10分鐘', '1人'),
(33301, '三文魚壽司', '2015-05-27', '三文魚中的歐米伽3脂肪酸含量極高，有助於老年黃斑變性患者保護視力、預防皺紋，同時還能控制體重。維生素D有助於保持皮膚細胞的鮮活。B族維生素還能讓你的頭髮更亮澤。將它做成壽司，可以保持食材的新鮮，對於不太喜歡西餐口味的人來說，是最容易接受的異國美食。', '10分鐘', '2人'),
(33311, '辣味金槍魚', '2015-05-27', '味美新鮮的金槍魚向來是日本人最愛的海鮮料理之一，尤其是金槍魚生魚片，堪稱生魚片之中的極品。金槍魚屬於一種比較有“肉感”的菜肴，營養也價值很高，蛋白質含量在20%以上，各種礦物質和微量元素豐富，B族維生素較高。從營養上說，它遠遠優於肉類，而且口感細膩，味道鮮美。', '10分鐘', '2人'),
(33321, '鰻魚手卷', '2015-05-27', '手卷是很簡單，但純粹，可以隨便添加你想要的吃食，深受日本民眾的喜愛。它做起來非常的方便，不太會用壽司捲簾的人可以用這樣的方法。鰻魚富含多種營養成分，具有補虛養血、祛濕、抗癆等功效。', '10分鐘', ''),
(33331, '鯛魚壽司', '2015-05-27', '鯛魚是一種上等食用魚類，肉質細嫩、味道鮮美，營養豐富，富含蛋白質、鈣、鉀、硒等營養元素，為人體補充豐富蛋白質及礦物質。中醫認為，鯛魚具有補胃養脾、祛風、運食的功效。配上壽司飯，營養又美味！', '10分鐘', ''),
(33351, '清涼水果特飲', '2015-05-29', '想让春夏的饮料多一些口味和清凉？不如加一些小料进去，味道也是很赞的。', '10分鐘', '2人'),
(33361, '秘制糖醋排骨便當', '2015-06-01', '糖醋排骨是糖醋菜中具有代表性的一道大眾喜愛的傳統菜，不分年齡與各人口味，大小通吃。選用新鮮豬子排作料，肉質鮮嫩，成菜色澤紅亮油潤，口味香脆酸甜下酒配飯都很不錯，一定會讓你的便當變得十分可口。', '20分鐘', '1人'),
(33371, '香辣魚香茄條便當', '2015-06-01', '魚香茄子是中國八大菜系中川菜的著名菜肴。味道鮮美，柔軟潤香，鮮鹹適口。不僅國人喜歡吃，也是很多外國人的心頭好。很多時候都會將它作為蓋澆飯或者麵條的澆頭來食用。加入了辣椒的魚香茄子香味更加濃郁，配米飯吃的時候更能激發食客的食欲。', '20分鐘', '1人'),
(33381, '麻辣雞絲粉皮', '2015-06-02', '麻辣雞絲粉皮', '10分鐘', '1人'),
(33391, '紅燒牛腩蛋包飯便當', '2015-06-02', '蛋包飯是日本一種比較普通且很受青睞的主食，由蛋皮包裡炒飯而成的菜肴，不論是在韓國，日本或臺灣，都是相當受到歡迎的料理。配上川菜代表之一的紅燒牛腩，增添了整個便當豐富的口感。', '20分鐘', '1人'),
(33401, '懶人香菇雞肉燜飯便當', '2015-06-02', '香菇雞肉燜飯，做法簡單，將菜與飯合二為一燜在一個鍋裡，小火慢燉讓每粒米飯吸收了大量的菜汁和肉湯。所以，味道也會濃郁鮮美。口感香糯Q彈，粒而不散，粘而有形，吃起來有一種滿足感。香米的香氣加上雞肉的濃郁，氣味香濃，滿屋香飄。', '10分鐘', '1人'),
(33411, '豉油皇煎蝦碌', '2015-06-02', '豉油皇煎蝦碌是一道簡單易做的家常菜，大蝦新鮮，調味得宜，就成為一道下飯的好菜式。今次示範做的是蝦去殼版本，讓爸爸可以啖啖肉品嚐。', '30分鐘', '1人'),
(33421, '蒜子火腩薑蔥煀蠔', '2015-06-02', '火腩其實是燒肉，燒肉成為再度烹調的食材就稱為火腩，是炆煮菜式的最佳配搭，這次以大生蠔做主角，鮮味無窮。', '1小時', '2人'),
(33431, '美式海鮮拼盤', '2015-06-02', '用啤酒做炸漿可以令炸物更脆口，這個有齊多種海鮮的美式海鮮拼盤，最適合配冰凍啤酒享用。', '1小時', '2人'),
(33441, '避風塘炒蟹', '2015-06-02', '避風塘炒蟹是香港的著名菜式，以香、辣、惹味見稱，特別之處在於大量炸蒜和辣椒融和的味道，讓人吃完蟹之後仍啜指回味。', '1小時', '1人'),
(33451, '椒鹽鮮魷', '2015-06-02', '椒鹽鮮魷是大牌檔常見的菜式，炸至酥香的魷魚配合蒜頭、乾蔥、指天椒的香辣味道，令人食指大動。', '1小時', '2人'),
(33461, '忌廉蟹肉意粉', '2015-06-02', '如果時間或地點限制未能買到靚海鮮，超市買到的罐頭蟹肉就派上用場，同樣可以煮出充滿海鮮滋味的意粉。', '1小時', '1人'),
(33471, '雞蛋焗魚腸', '2015-06-02', '雞蛋焗魚腸是一道順德菜，亦是不少老香港愛吃的菜式，工序繁複，但吃起來的甘香滋味叫人難忘。', '1小時', '1人'),
(33481, '西瓜凍湯', '2015-06-02', '西瓜又稱寒瓜，具清熱生津之效，是夏天大熱的水果之選，用來做凍湯一樣清涼開胃。', '30分鐘', '1人'),
(33501, '馬蹄西米綠豆爽', '2015-06-02', '綠豆爽為潮汕小吃，綠豆能驅除暑熱，加上口感煙韌的西米，讓人一到夏天就想起這款甜品。', '1.5小時', ''),
(33531, '冰糖雪耳蓮子百合羮', '2015-06-02', '夏天到就宜吃一些苦味食材，因為此類食材有清泄暑熱的功效，蓮子就是其中之一，它同時具清涼滋補功效，用來做甜品最適合。', '1.5小時', '1人'),
(33541, '麻辣肉碎拌麵', '2015-06-02', '「冬至餃子夏至麵」，夏天炎熱沒有胃口吃飯，涼麵或拌麵就是最佳選擇', '1小時', '1人'),
(33551, '鮮香蝦仁菠蘿炒飯便當', '2015-06-02', '鮮蝦菠蘿炒飯是很多喜歡酸甜口感的人的最愛。鮮蝦很惹味，搭配上菠蘿更是錦上添花。於是菠蘿的清爽香甜，蝦的鮮味完全融於米飯當中，就會讓人胃口大開。金黃的菠蘿和紅白相間的鮮蝦搭配起來，顏色鮮豔，吃飯的時候心情也會很好。', '20分鐘', '1人'),
(33561, '開胃酸豆角肉沫便當', '2015-06-02', '酸豆角雖然平凡，但是味道卻一點也不單調。酸而鹹的味道，最適合搭配辣椒一起炒，再搭些肉末，酸、辣、咸，適合下飯，也能搭配清粥小菜，味道總是相宜。僅僅是想想，已經止不住要咽口水了。', '20分鐘', '1人'),
(33571, '甜酸菠蘿咕嚕肉便當', '2015-06-03', '菠蘿咕嚕肉這道菜始於清代。當時在廣州市的許多外國人都非常喜歡食用中國菜，尤其喜歡吃糖醋排骨，但吃時不習慣吐骨。廣東廚師就發明了這道沒有骨頭的菜。它口感清新解膩，酸甜的味道又能增進食欲，無論作為水果還是菜肴，都非常美味。\r\n\r\n<十五分鐘懶人版｜三色椒菠蘿牛肉>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：三色椒菠蘿牛肉', '10分鐘', '1人'),
(33591, '楊枝甘露', '2015-06-05', '楊枝甘露', '20分鐘', '1人'),
(33601, '油炸臭豆腐', '2015-06-08', '炸臭豆腐，為湖南有名的漢族傳統小吃，具有遠處聞起來臭，吃起來香的特點。許多人卻為了吃它排上好長的隊才能買到。隨著人們生活水準的提高，大家都追求食物的新、奇、特，臭豆腐以不是個別地域的風味小吃了，全國各地乃至世界各地都有名氣。', '30分鐘', '2人'),
(33611, '簡易煎餅果子', '2015-06-08', '煎餅果子是天津著名的小吃。天津人把它作為早點，在東北和山東地區也是頗有特色的地域美食。煎餅果子作為早餐比較方便、熱乎，近年來開始在全國各地流行，受到很多上班族和學生的喜愛。', '10分鐘', '1人'),
(33621, '爽口涼皮', '2015-06-08', '涼皮是陝西省漢族特色小吃之一，被許多人認為是陝西小吃中最受歡迎的品種。是一種涼拌著吃、口感絕佳的西北麵食小吃。調好的涼皮,皮子白裡透亮、麵筋因為吸附醬油而泛黃、黃瓜絲現著綠、辣椒油敞著紅，好吃又好看。是很不錯的消暑食品。', '10分鐘', '1人'),
(33631, '香辣烤冷面', '2015-06-08', '烤冷面，東北一帶地方特色小吃。有碳烤、鐵板烤和油炸三種，味道各有差異。主要流行鐵板和油炸。烤冷面的成本低，味道極棒。早期所用冷面為普通冷面，製作工藝成熟後使用特製冷面，柔軟，可以直接食用。', '10分鐘', '1人'),
(33641, '武漢熱乾麵', '2015-06-08', '熱乾麵是湖北省武漢市的漢族特色小吃，是中國五大面之一。熱乾麵的麵條纖細根根有筋力，色澤黃而油潤，滋味鮮美。拌以香油、芝麻醬、富清鮮辣味粉、五香醬菜等配料，色香味俱全。', '10分鐘', '1人'),
(33651, '公司三明治', '2015-06-08', '簡單營養的早餐對於忙碌的上班族來說再好不過，今天就為大家帶來一個可以在10分鐘內搞定的公司三明治，讓你每天精神滿滿哦！', '10分鐘', '1人'),
(33661, '川味酸辣粉', '2015-06-08', '酸辣粉是四川省、重慶市等地的漢族傳統特色小吃，屬於川菜。由於價廉物美，長期以來一直深受人們的喜愛，它的特點是麻、辣、鮮、香、酸且油而不膩，口感筋道。素有“天下第一粉”的美名。', '10分鐘', '1人'),
(33671, '蘿蔔絲油墩子', '2015-06-08', '油墩子是江浙滬地區的街頭小吃，又稱蘿蔔絲餅。屬油炸食品，略帶鹹味的麵糊加上提鮮的蘿蔔絲、蔥花使得油墩子的口感十分具有層次感，外表呈黃褐色，吃起來香脆有味，外焦裡嫩。由於價廉物美，是很多江浙滬地區長大的人們，早餐或下午茶的最愛。', '10分鐘', '2人'),
(33681, '薄荷藍莓布朗尼奶昔', '2015-06-10', '大部分女生會喜歡吃布朗尼。不過，夏天吃會有些膩。我們加一些清涼的薄荷葉、冰爽的霜淇淋，搭配酸甜的藍莓，改善它的口感就會更好吃啦！在夏日的午後，簡單地做上兩杯薄荷藍莓布朗尼奶昔，和閨蜜來一個甜蜜清爽的下午茶約會吧！', '10分鐘', '1人'),
(33691, '海帶豆腐湯', '2015-06-12', '夏天是減肥的好季節，今天就給大家帶來一道清爽可口又能夠清熱減脂的海帶豆腐湯。', '10分鐘', '1人'),
(33701, '蒜泥手撕茄子', '2015-06-12', '茄子性涼，很適合在夏季食用清熱降火。這道菜就很適合夏天的感覺。而且高溫油炸會使得茄子的營養損失很大，這種蒜泥涼拌的方式是最能保存營養的了。', '20分鐘', '1人'),
(33711, '紅燒茄子', '2015-06-12', '紅燒茄子是一道非常受歡迎的家常菜，在北魏時期的著作中就記載了它的做法，可見它的受歡迎程度。它做法很精細，吃起來鮮香適口，外酥裡嫩，味美多汁，看起來色澤油亮，讓人食欲大開。是很多人家常菜譜中的常客。\r\n\r\n<十五分鐘懶人版｜健康版紅燒茄子>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：健康版紅燒茄子', '20分鐘', '2人'),
(33721, '肉末茄子', '2015-06-12', '肉末茄子的歷史非常久遠，最早可以追溯到西漢時期。茄子在煮的過程中很好地吸收了肉中的油脂，所以更加入味，搭配麵條或者是米飯口味更加。而且它營養豐富，操作起來也十分簡單，是一道新手入門級的菜肴。', '10分鐘', '2人'),
(33731, '地三鮮', '2015-06-12', '地三鮮是一道典型的東北菜，選擇了地裡頭時鮮的三種蔬菜：土豆、茄子和青椒。它味道鮮濃，食材也是天然綠色的。而且一道菜就涵蓋了多種食材的營養。真的是百吃不厭，令人回味。', '20分鐘', '2人'),
(33741, '東坡茄子', '2015-06-12', '東坡茄子借鑒的是“東坡肉”的做法。口感微甜，色澤油亮，這道菜很適合在夏天食用。茄子能很好地吸收醬汁中的味道，所以它或許比肉更好吃。', '20分鐘', '2人'),
(33751, '尖椒茄子餡餅', '2015-06-12', '餡餅是很多習慣吃麵食的地區常見的做法，餡料可以是各種食材。用尖椒茄子來做餡料的餅既沒有肉末餡的油膩，吃起來也非常的鮮香爽口。茄子和尖椒都是富含維生素的食物，所以這道菜可以說是補充維生素的佳品。', '30分鐘', '3人'),
(33761, '炸茄盒', '2015-06-12', '炸茄盒的做法適用於很多食材，但用茄子做是最入味的。因為茄子的烹飪特性使它能更好地吸收肉末的鮮香，所以更加好吃。茄子在高溫油炸的過程中會損失掉不少營養，但裹上麵粉之後的營養就能很好的保存下來。', '30分鐘', '2人'),
(33771, '肉鬆芝麻飯糰', '2015-06-16', '如果夏天你不想開火煮菜，那不如嘗試一下今天我帶來的這道簡單美味的肉鬆芝麻飯糰吧~', '10分鐘', '2人'),
(33791, '蟹柳蕎麥麵', '2015-06-16', '', '30分鐘', '1人'),
(33821, '多彩冰飲', '2015-06-16', '只需要簡單幾個步驟就可以讓你的果汁更加富有創意。這一杯多彩冰飲完全可以讓夏季的飲品充滿色彩，是聚會或者家庭飲用的好選擇。', '20分鐘', '1人'),
(33841, '薑檸蜜焗雞翼', '2015-06-16', '', '1小時', '1人'),
(33851, '百里香醬汁焗肉眼扒', '2015-06-16', '節慶日子不能缺少這件份量十足的肉眼扒，將整件肉眼扒端上枱，按個人需要切出不同厚度的牛扒，配以百里香醬汁，單是想像畫面都叫人流口水了。', '1.5小時', '3人'),
(33861, '香橙蜜糖燒無骨火腿', '2015-06-16', '美國人吃的無骨火腿，當然不是香港人在茶記吃到腿蛋治的火腿，著名的金門火腿是豬後腿的整塊肉，加上多種糖和橙汁裏著反覆焗製，是聖誕和派對美食的首選。', '1.5小時', '3人'),
(33871, '魔鬼蛋配風乾火腿', '2015-06-16', '魔鬼蛋是外國人派對上經常出現的頭盤小食，做法簡單，變化多樣，可按個人喜好加入不同材料和調味料調整味道和賣相。', '1小時', '2人'),
(33881, '烤燈籠椒羊奶芝士沙律', '2015-06-16', '中式煮法炮製燈籠椒不外乎炒或者釀，其實清甜的燈籠椒用來做沙律亦非常適合，配合一個自己調校的黑醋汁，更加健康有益。', '1.5小時', '2人'),
(33891, '經典薯仔沙律', '2015-06-16', '薯仔沙律既可做沙律、伴菜甚至主菜，不同國家更有不同做法，今次介紹美式做法，加入蘋果醋、法式芥辣和蜜糖等調味料，令沙律味道更豐富。', '1.5小時', '2人'),
(33901, '紐約芝士蛋糕', '2015-06-16', '紐約芝士蛋糕是一款經典又百吃不厭的美式甜品，不少酒店及高級餅店都以獨家配方炮製自居，自己做也不難啊，加入水盤蒸焗可以令芝士蛋糕質感更軟滑。', '1.5小時', '3人'),
(33911, '雙重朱古力布朗尼', '2015-06-16', '相比起裝飾設計花俏的甜品，布朗尼Brownies外表相對平凡，卻是很多愛甜人士的心頭好，工作到累的時候，吃一件口感紮實又濕潤的Brownies真是樂事。', '1.5小時', '3人'),
(33941, '椰汁火龍果凍', '2015-06-17', '椰汁果凍加上黑芝麻裝飾，像真度非常高，與火龍果肉分不清孰真孰假，做這款甜品送給朋友，讓他們猜猜哪個才是真正果肉吧。', '1.5小時', '2人'),
(33961, '檸檬造型蛋糕', '2015-06-17', '是檸檬？是蛋糕？一口咬下去沒有酸澀的檸檬汁，卻是香甜軟綿的美味蛋糕，這款酸中帶 甜、造型可愛的小蛋糕，伴以紅茶一杯，就成了很圓滿的下午茶。', '1小時', '2人'),
(33991, '曲奇牛奶杯', '2015-06-17', '這款曲奇牛奶杯最適合懶洗碗的朋友，因為喝完牛奶連杯都能吃掉。', '1.5小時', '2人'),
(34031, '豇豆釀肉', '2015-06-21', '這是一道好吃又好看的菜。豆角與肉末的融合，使肉汁進入到豆角中，又讓豆角散發的清香融合到肉裡。很適合在招待的時候端上桌一起享用。', '20分鐘', '2人'),
(34041, '豆角燜面', '2015-06-22', '豆角燜面是中國北方地區常見的家常麵食，南方則很少見。燜面是利用水蒸氣將麵條、豆角燜熟，這樣做可以將豆角和麵的味道像融合，而且省時省力，口味也很不錯。', '10分鐘', '1人'),
(34051, '麻醬豆角', '2015-06-22', '麻醬豆角是夏季人們非常喜愛的菜品。豆角的口味比較清淡，麻醬能更好提升豆角的味道。這道菜清涼可口，消熱解暑。做起來很簡單，短時間即可完成。在夏天燥熱的氣溫下提振食欲。', '10分鐘', '2人'),
(34061, '排骨燉豆角', '2015-06-22', '排骨燉豆角是一道非常美味的家常菜，排骨經過煎炒再加入燉，鹹香可口。排骨提供人體生理活動必需的優質蛋白質、脂肪，尤其是豐富的鈣質可維護骨骼健康。四季豆富含蛋白質和多種氨基酸，常食可健脾胃，增進食欲。夏天多吃一些豆角有消暑，清口的作用。', '30分鐘', '2人'),
(34071, '茄汁肉末燒豆角', '2015-06-22', '茄汁肉末燒豆角，很家常的一個菜，配粥、麵條、大米飯，都很下飯的。與此同時，豆角和番茄的熱量都很低，這道菜用清炒的方式，熱量不高，很適合需要瘦身的人們。', '20分鐘', '2人'),
(34081, '涼拌豇豆', '2015-06-22', '豇豆是浙江一帶的風味名菜，屬於浙菜系。此道菜口感清爽、脆嫩，鹹中有辣，辣中帶酸，很是開胃。如果在吃之前放入冰櫃中稍稍冰鎮一下，在這炎炎夏日裡吃起來感覺更是爽。', '10分鐘', ''),
(34091, '豆角炒牛肉', '2015-06-22', '豆角炒牛肉是一道廣東常見的經典中式小炒菜，它有一個很有意思的名字叫做：“亂棍打死牛魔王”。豆角可用作調和牛肉的濃味，加入蒜頭爆炒，香氣四溢，好吃極了。', '20分鐘', '2人'),
(34111, '左宗棠雞', '2015-06-23', '聽到左宗棠雞的名字，會以為是歷史悠久的中菜，其實此菜式創於1970年代，台灣廚師隨意創作和命名的一道菜，結果在美國很受歡迎，成為一道在美國家傳戶曉的中菜，然後反傳入中國。', '1小時', '3人'),
(34121, '白兔棉花糖', '2015-06-23', '小時候上茶樓，最期待是吃到白兔棉花糖，樣子可愛，咬下去軟綿綿又甜絲絲，原來這種甜品用材料簡單做法不難，不過做得像不像小白兔就考你手藝了。', '1.5小時', '2人'),
(34151, '香蕉鬆餅', '2015-06-25', '輕鬆就能搞定的香蕉鬆餅，很適合作為工作日的早點哦！號稱「超級能量塊」的香蕉為你補充能量，馬上學起來吧~', '10分鐘', '2人份人'),
(34181, '檸檬撻', '2015-06-27', '第一啖吃下去那股強烈的酸香，給味蕾一剎那的刺激，多咀嚼幾下就會愛上這種叫人難忘的酸甜味道。', '1.5小時', '2人'),
(34191, '焗泰式檸檬魚', '2015-06-27', '泰國菜式的酸辣味道在夏天令人很開胃，這款泰式檸檬魚不用鱸魚的話，選用烏頭或鰂魚亦可，在家也能感受泰式酸辣香。', '1小時', '3人'),
(34201, '蜜糖黑醋雞', '2015-06-27', '外表看來黑沉沉的雞肉，一咬下去黑醋和蜜糖交織出的酸甜味道，令你精神為之一振。', '30分鐘', '2人'),
(34211, '毛豆酸菜炒蠔仔', '2015-06-27', '鹹酸菜是潮州的特產，味道開胃得很，配以毛豆及蠔仔同炒，成為一道醒胃又下飯的菜式。', '1小時', '2人'),
(34221, '蕎頭炒火鴨絲', '2015-06-27', '酸脆可口的蕎頭不少人會用來作餐前小吃，用來入饌亦非常可口，配以火鴨絲、青紅椒及洋蔥，炒起來香氣四溢。', '30分鐘', '2人'),
(34231, '涼拌酸辣螺肉', '2015-06-27', '響螺肉常見用來煲湯和炒菜，這次就用來做涼拌前菜，拌以酸甜開胃的特色醬汁，味道清新滋味。', '1.5小時', '2人'),
(34241, '青檸芫茜大蝦串', '2015-06-27', '大蝦串最適合做派對小食，配以醒胃的青檸蒜蓉醬汁，最後灑上的芫茜更有提味作用。', '30分鐘', '2人'),
(34251, '醒胃酸辣湯', '2015-06-27', '酸辣湯是四川名菜，用料雖多，但全部材料都很容易買到，包括冬菇、豆腐、筍、雞蛋等等，半小時就可以完成，是非常快靚正的一款湯水。', '1小時', '2人'),
(34261, '苦瓜黃豆排骨湯', '2015-06-27', '這款是夏天必喝的湯水之一，因為它有清潤消暑的作用，據說苦瓜有排毒功效，此湯有助治療惱人的痘痘暗瘡。', '1.5小時', '2人'),
(34271, '果仁金寶咖啡蛋糕', '2015-06-27', '部份人會因為嫌咖啡味太苦不愛喝，但當加入雞蛋、牛奶、牛油等材料造成蛋糕後，咖啡提升至另一種味道層次，餘下的只有咖啡香而沒有咖啡之苦了。', '1.5小時', '2人'),
(34291, '薄荷西柚雪葩', '2015-06-27', '橘子類生果中，西柚的受歡迎程度給橙、檸檬比下去，因為好多時西柚都帶有苦味，但西柚用來做甜品味道就清新可口了。', '1.5小時', '2人'),
(34301, '火箭菜烤鴨薄餅', '2015-06-27', '第一次吃火箭菜沙律，心想為何天下間有這麽苦的菜呢？多吃幾次後找到竅門，只要食材配搭得宜，火箭菜的苦味亦是很好的配搭。', '1.5小時', '2人'),
(34311, '海底椰雪耳南北杏豬骨湯', '2015-06-27', '南杏甜，北杏苦，煲湯少不了南北杏這種食材配搭，因為它們走在一起甚具食療作用，而且南杏的甜和北杏的香互相補足，令湯的味道更可口。\r\n\r\n<十五分鐘懶人版｜蘋果海底椰蜜棗瘦肉湯>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：蘋果海底椰蜜棗瘦肉湯', '1.5小時', '2人'),
(34321, '合桃蓮子露', '2015-06-27', '啞巴吃黃蓮，有苦說不出，蓮子最苦的地方是芯，去掉蓮子芯，加上合桃打成糊狀，就成為可口滋潤的糖水了。', '1.5小時', '2人'),
(34331, '苦瓜炒牛肉', '2015-06-27', '苦瓜炒牛肉是一道家常菜，其它瓜類都是吃其清甜味，偏偏苦瓜吃的卻是甘苦味，它有清脂消暑的作用，最適合夏天食用。', '1小時', '2人'),
(34361, '紅酒瓜球', '2015-06-28', '如果在一個浪漫的場合，需要一道有情調的菜，你一定要試試“紅酒瓜球”這道菜。這道菜做起來很簡單，但是看上去卻是很有格調的而且在減肥界，紅酒和冬瓜這兩種減肥佳品搭配起來再合適不過哦。', '20分鐘', '2人'),
(34371, '瘦身養顏黃瓜粥', '2015-06-28', '上班族的女性或許一直在煩惱，如何吃的健康又瘦身，而且還能適應忙碌的工作節奏。現在向你推薦：瘦身養顏黃瓜粥。它的熱量非常低，口味清爽。在下班後的空閒時間煮上一鍋，無論是作為晚飯還是第二天的早餐都是非常美妙的。', '10分鐘', '2人'),
(34381, '葫蘆瓜鮮蝦蛋糕', '2015-06-28', '在很多時候，蛋糕都是甜的，這讓很多想減肥的人望而卻步。如果你把葫蘆瓜和鮮蝦放進蛋糕，就可以放心得多吃兩口了。向您推薦這道：葫蘆瓜鮮蝦蛋糕。當然，如果你家的小孩子不是很喜歡吃蔬菜，可以試試將葫蘆瓜藏在蛋糕裡頭，讓ta悄悄地吃下去哦。', '30分鐘', '2人'),
(34391, '苦瓜釀肉', '2015-06-28', '苦瓜是一道健康的食材，可以說是夏季瓜類的第一佳品，但是很多人都不喜歡它的味道。我們現在就用肉糜淡化掉苦瓜的味道，做一道苦瓜釀肉，讓不愛吃苦瓜的人在享受美味的同時也能吃的健康。', '20分鐘', '2人'),
(34401, '蠔油燜冬瓜', '2015-06-28', '面對複雜的料理，入廚新手經常不知道如何操作。你可以選擇簡單的食材和簡單的方式作為入門。比如這道蠔油燜冬瓜。食材和醬料都可以很輕鬆地購買到。冬瓜的口感比較淡，就需要像蠔油這樣的“小夥伴”來搭配，料理出新的滋味。', '10分鐘', '2人'),
(34411, '酥糯南瓜餅', '2015-06-28', '家裡有老人和小孩的朋友千萬不要錯過這道酥糯南瓜餅。南瓜作為健康食品的主力軍，很容易消化。甜甜的紅豆沙搭配香糯的南瓜，無論是作為下午茶點心還是在早上配上一碗清新靚麗的小粥都是很棒的選擇。', '20分鐘', '3人'),
(34421, '爽口醬醃瓜條', '2015-06-28', '很多朋友的胃口會因為夏季炎熱的天氣而不好，這也是主婦們在料理時常常煩惱的問題。你需要這道爽口醬醃瓜條。它酸酸的口味非常適合提振食欲，搭配一些清爽的粥或者是饅頭，是再合適不過了。', '1.5小時', '2人'),
(34431, '微波爐薯片', '2015-06-30', '薯片是很多孩子喜歡的小零食，可怎樣才能讓它更加健康呢？我們來教你用微波爐做吧！它操作簡單，而且比買的更便宜，更低脂哦！', '20分鐘', '2人'),
(34441, '西瓜牛奶西米糖水', '2015-07-03', '西瓜牛奶西米糖水應該是最適合夏天的西米糖水之一了。西瓜清熱解暑的功效和牛奶的美白效果讓你整個夏天都會美美噠。這道甜品的食材都是常見的，在夏天的時候作為家庭常備飲料放在冰箱裡也很好啊！', '10分鐘', '2人'),
(34451, '紫薯西米', '2015-07-03', '紫薯的顏色很好看，做起甜品來會很美觀，可以說是色香味俱全了。不僅如此，紫薯也是非常好消化的粗糧，適合全家老小一起食用。用紫薯和西米搭配，是很好的夏季飲品，不僅口味很棒，也非常的健康。', '10分鐘', '2人'),
(34461, '木瓜雪耳西米', '2015-07-03', '這是一份極致美容佳品。每一種食材對女士來說都是極好的。木瓜可以抗氧化，雪耳有滋陰嫩膚的功效，而西米有使皮膚恢復天然潤澤的功能。你可以在家做一些分享給自己的閨蜜，一定是一份貼心的小禮物。', '30分鐘', '2人'),
(34471, '椰汁西米芝麻糊', '2015-07-03', '芝麻糊是一種對頭髮很好的食材，可是讓人的頭髮烏黑光澤。同時，芝麻糊醇香的口感也可以使食物更馥芳香。這道椰汁西米芝麻糊在港式甜品中有很高的人氣，充滿了小時候喝芝麻糊的味道，但更多了水果的香甜。是一道不可錯過的甜品。', '10分鐘', '1人'),
(34481, '椰汁西米龜苓膏', '2015-07-03', '吃龜苓膏的好處很多。它由多味中草藥熬制而成，很早以前就被人們當作藥膳來食用，能夠起到清火的作用，特別適合夏天。有些人不喜歡龜苓膏的藥味，用椰汁和西米能沖淡龜苓膏的藥味，入口更加容易。', '10分鐘', '2人'),
(34491, '薏仁西米紅棗粥', '2015-07-03', '如果你在減肥，又不想讓自己的皮膚失去彈性和光澤，你一定不能錯過這道薏仁西米紅棗粥。薏仁，西米都屬於粗糧雜糧類，紅棗也具有養顏的功效。熬煮一鍋放在冰箱中，早上起來後熱著吃，會讓你一天的氣色都很好。', '20分鐘', '2人'),
(34501, '西柚西米撈', '2015-07-03', '如果能在夏日的日常生活中加一些好味道，那絕對是非常美妙的體驗。西柚西米撈可以幫你做到。你可以將它裝在隨身杯中，帶去工作或者上學。隨時隨地給自己增加各種元氣能量。而作為小朋友的下午茶糖水也是一種增加維生素的好方法。', '10分鐘', '1人'),
(34531, '西瓜蛋糕', '2015-07-07', '夏天最受歡迎的水果當然就是西瓜啦！怎麼把西瓜吃得更有創意呢？你可以試試這個西瓜蛋糕！既美味，又有無限地驚喜。', '10分鐘', '2人'),
(34541, '辣酒煮花螺', '2015-07-08', '花螺體積小小的，肉質鮮甜爽脆，最受歡迎的做法是用辣酒煮，每粒花螺浸滿辣汁，用竹簽挑出來一啖一粒，下酒一流。', '1小時', '1人'),
(34591, '一樂拉麵（《火影忍者》）', '2015-07-10', '《火影忍者》中讓鳴人毫無抵抗力的一樂拉麵一直是“火影迷”最期待的日式拉麵。鮮美的湯頭，Q彈的麵條，加上肉片和海帶作為陪襯，充滿了日式拉麵的風情。無論你是不是火影忍者迷，都應該嘗試一下。', '20分鐘', '1人'),
(34601, '炒烏冬（《灌籃高手》）', '2015-07-10', '烏冬面在日本是非常普通的吃食，但如果是你暗戀的人做給你吃的話，就會增添美味。《灌籃高中》中櫻木花道暗戀的晴子就用這道菜讓花道淚流滿面。充滿感情的食物總能引起人們的共鳴。不如你也做給心愛的人吃吧。', '20分鐘', '1人'),
(34611, '山治炒飯（《海賊王》）', '2015-07-10', '簡單的食物有時候也充滿了偉大的力量。就像是《海賊王》裡面的山治用一份簡單的海鮮炒飯，打動了饑腸轆轆的“鬼人”阿金。沒有什麼珍貴的食材也沒有繁複的製作，這在家平常就能做的簡單料理，是海賊迷們津津樂道的經典。', '20分鐘', '1人'),
(34621, '培根土豆卷（《食戟之靈》）', '2015-07-13', '人們常說，失敗是成功之母。這句話成就了很多美食界的經典。比如這道“培根土豆卷”就是《食戟之靈》的男主角從以前失敗的料理中吸取經驗得來的。土豆吸取了培根的油脂，加入了蘑菇和洋蔥烤制，好吃得能讓人飛起來！', '1.5小時', '2人'),
(34631, '炒麵麵包（《烘焙王》）', '2015-07-13', '很多動漫迷熱衷於打開二次元和三次元的結界，將動漫中的經典還原到現實中。“炒麵麵包”就是很好的代表。它在日本漫畫《烘焙王》中被發揚光大，變成了日本、韓國和臺灣地區的人氣美食。不管你是不是動漫迷，這道改良為亞洲口味的熱狗是外出野餐、工作便當的理想之選！', '20分鐘', '1人'),
(34641, '章魚燒（《百變小櫻Magic咭》）', '2015-07-13', '章魚燒是日本家喻戶曉的國粹小吃，也同時成為很多動漫中的常客。比如《百變小櫻Magic咭》的故事就是以章魚燒開始的。現實中，很多女生也喜歡將章魚燒作為逛街時的零食，Q彈的章魚外面裹上麵糊，澆上照燒醬撒上海苔碎，口味很棒。', '20分鐘', '1人'),
(34651, '蛋黃醬蓋澆飯（《銀魂》）', '2015-07-13', '《銀魂》中的土方十四郎最愛吃蛋黃醬，他會在食物上加入很多。這種吃法往往不容易被平常人接受。我們還原的這道土方蛋黃醬蓋澆飯，將土豆和蛋黃醬融合，讓土豆吸收蛋黃醬的鹹味，使得入口更加好吃。不僅外形還原了動漫中的場景，口味也非常的好吃。', '20分鐘', '1人'),
(34661, '杯子牛奶布丁', '2015-07-13', '今天推薦一道冰涼又營養的杯子牛奶布丁，不用烤箱就可以做，很適合夏天在家DIY哦！', '1.5小時', '4人'),
(34681, '絲瓜雲耳粉絲湯', '2015-07-14', '夏天經常流汗，可以多喝湯補充水份，滾湯就快靚正了，今次選用可以清熱解暑的絲瓜，兼有美顏潤膚功效呢！加上雲耳及粉絲，半小時就完成了。', '30分鐘', '2人'),
(34711, '木瓜魚尾湯', '2015-07-14', '木瓜和魚尾含豐富膠質和蛋白質，所以這款湯水有潤膚養顏的作用，尤其適合女生飲用。\r\n\r\n<十五分鐘懶人版｜木瓜花生魚尾湯>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：木瓜花生魚尾湯', '30分鐘', '2人'),
(34721, '番茄莧菜肉片湯', '2015-07-14', '莧菜有清熱潤腸胃功效，配搭酸酸甜甜的番茄，加上肉片的鮮味，令湯的味道更調和。', '30分鐘', '1人'),
(34731, '冬瓜瑤柱豬潤瘦肉湯', '2015-07-14', '冬瓜是夏天無論煲湯或是滾湯的好材料，加上豬潤、瘦肉以及瑤柱調味，全部材料都很快熟透，轉眼間就煮好一鍋美味湯水了。\r\n\r\n<十五分鐘懶人版｜瑤柱香菇冬瓜肉粒湯>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：瑤柱香菇冬瓜肉粒湯', '30分鐘', '2人'),
(34751, '香辣雞肉牛油果漢堡', '2015-07-14', '提到辣味菜式，不能缺少來自美國南部的Cajun菜，這種以洋蔥及辣椒等調味的菜式令人一辣難忘，除了常見用來烹調海鮮，用來配肉做漢堡也很夾呢！', '1小時', '2人'),
(34761, '泰式無骨鳳爪', '2015-07-14', '在泰國菜館常吃到的無骨鳳爪，混合酸、甜、辣的味道令人非常開胃，自己做會很困難嗎？到凍肉店買急凍無骨鳳爪，自己做調味就可以了，今晚就試試吧！', '1.5小時', '1人'),
(34771, '辣炒雞塊', '2015-07-14', '想做一些快捷方便的菜式，但又不想重覆又重覆煮常做的家常菜？不妨從調味方面著手，加一點四川風味的花椒，再加點醒胃的白醋和辣椒，15分鐘就炒好一碟惹味的雞塊菜式了。', '1小時', '2人'),
(34781, '韓式泡菜炒豬腩肉', '2015-07-14', '自從韓國文化席捲全球後，泡菜成為了很常用的食材，凍食熱食皆宜，用來炒菜調味亦簡易方便，好像這道泡菜炒豬腩肉，除了加入大豆芽，加入你喜歡的蔬菜亦可。', '30分鐘', '2人'),
(34801, '粟米蝦仁炒鮮百合', '2015-07-14', '粟米本身多汁清甜，既可以單獨吃，亦可以用來入饌令菜式賣相變得更吸引，這道粟米蝦仁炒鮮百合，味道和口感的配搭清新爽脆，很下飯。', '30分鐘', '2人'),
(34811, '雙菇豆漿浸時蔬', '2015-07-14', '豆漿營養豐富，有些不喝牛奶的朋友會飲豆漿去代替補充營養，用豆漿去浸菜，有營養之餘亦可以令蔬菜口感更滑溜。', '30分鐘', '2人'),
(34821, '三杯炒蜆', '2015-07-14', '三杯煮法在台灣很受歡迎，三杯是指麻油、米酒、醬油各一杯，除了著名的三杯雞，用這個煮法蜆一樣惹味。\r\n\r\n <十五分鐘懶人版｜金不換豉椒炒蜆>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：金不換豉椒炒蜆', '1小時', '2人'),
(34831, '米飯披薩', '2015-07-14', '想讓你的披薩更有創意？用米飯代替傳統的餅底吧。再加點自己喜歡的食材，這絕對是最棒的自製披薩！', '20分鐘', '2人'),
(34871, '麻辣雙色炒豆乾', '2015-07-16', '五香豆腐乾經過脫水、壓縮及調味而成，內軟外硬，用來炒和炆就最適合，這次配以芹菜、木耳加上麻辣香，更為惹味。', '30分鐘', '2人'),
(34881, '大豆芽西芹炒雞柳', '2015-07-16', '大豆芽是大豆種子浸水後萌發的產品，幼嫩爽脆，這道菜可按個人喜好控制大豆芽的軟腍度，喜歡爽口一點的快炒一會就要上碟了。', '30分鐘', '2人'),
(34891, '腐竹節瓜魚湯', '2015-07-16', '節瓜是夏天當造的蔬菜，配上煎香的魚尾以及軟滑的腐竹，湯色奶白清甜可口。', '1小時', '2人'),
(34901, '酥炸腐乳雞球', '2015-07-16', '腐乳有中國芝士之稱，它獨有的鹹香味道非常特別，用來醃雞肉後炸脆，成為送酒一流的香口小吃。', '1.5小時', '2人'),
(34911, '雞蓉豆腐薺菜羹', '2015-07-16', '豆腐分軟豆腐和硬豆腐，軟豆腐比較適合做湯羮，因為口感軟嫩，可以滑進喉嚨去，所以做這款湯時材料不妨切細一點，令口感更滑溜。', '1小時', '2人'),
(34951, '粟米雪耳紅蘿蔔豬骨湯', '2015-07-16', '這款湯水選用多款長年供應的食材炮製，無論冬夏天都適合飲用，加入新鮮粟米一起煲，令湯水更加鮮甜好喝。', '1.5小時', '2人'),
(34961, '粟米炒豬腩片', '2015-07-16', '粟米是很百搭的食材，在雪櫃裡找找看有甚麼食材拼配，今次找來火鍋用的豬腩片，加上西芹、紅蘿蔔，很快便炒好一道色彩豐富的下飯好菜式。', '30分鐘', '2人'),
(34971, '法式紅酒牛排', '2015-07-17', '如果要招待獅子座的朋友，一定要選擇非常貴氣的菜肴。法式紅酒牛排就是非常好的選擇。紅酒、牛排和法式烹飪方法非常符合獅子座的氣質。千萬不要忘記用一個漂亮的盤子裝盤，更加會有畫龍點睛的作用。', '1.5小時', '2人'),
(34981, '熔岩巧克力布丁', '2015-07-17', '如果用一道甜品來形容獅子座，那一定是這道熔岩巧克力布丁。它就像是獅子座，冷冷的外表下包含了火熱甜蜜的熔岩巧克力。甜蜜的味道加上香滑的口感，非常適合在獅子座的朋友過生日的時候烤出來，增加一種浪漫的情懷。', '20分鐘', '2人'),
(34991, '獅子座曲奇', '2015-07-17', '要做代表獅子座的食物當然不能忘記獅子造型的曲奇餅乾啦。這道獅子座曲奇餅造型很可愛，而且裡面有濃濃的可哥味，很適合烘焙給小朋友吃。當然，如果你有獅子座的朋友過生日，作為生日禮物也是非常不錯的！', '1小時', '2人'),
(35001, '紅酒煮梨', '2015-07-17', '什麼是獅子座最愛的菜肴？網上曾經做過一次投票，結果紅酒煮梨拔得頭籌。究其原因，或許是因為它顏色火熱鮮豔，口感香甜，同時也具有清熱減脂的功效吧。如果你是入廚新手，想要做一道菜款待獅子座的ta，一定不要忘記這款紅酒煮梨哦。', '20分鐘', '2人'),
(35011, '鍋包肉', '2015-07-17', '叢林之王的獅子一直都是食肉動物。獅子座的朋友也是愛吃肉的一群人。遇到這道東北名產鍋包肉一定會喜笑顏開。它顏色就像獅子的頸圈一般金黃，而包裹的豬肉一定能打動TA的內心。', '20分鐘', '2人'),
(35021, '油炸冰淇淋', '2015-07-17', '獅子座愛甜品，最愛的還是霜淇淋。油炸霜淇淋的外表就像是、金光閃閃顏值很高的獅子座，而內心卻相當地柔軟和細膩，可以算是獅子座的代表性食物。而霜淇淋用油炸的方式，可以讓人同時體驗冰火兩重天的暢快感覺。', '20分鐘', '2人'),
(35031, '叉燒霸王雞翅', '2015-07-17', '獅子座非常喜歡大氣的東西，連料理都不例外。叉燒霸王翅就很符合他們動物之王的特性。張狂的外表，烤的金黃酥脆的雞翅和叉燒醬搭配，不管是誰看見了都會垂涎三尺的。它一定是獅子座生日宴上不可缺少的菜肴。', '20分鐘', '2人'),
(35061, '水晶藕圓子', '2015-07-24', '在節慶期間，很多人家裡會做藕圓子，象徵著圓滿。晶瑩剔透的糯米包裹著香脆的藕還有鮮香的豬肉，看上去也很漂亮，招待親朋好友也很有面子。', '1小時', ''),
(35071, '乾煸藕條', '2015-07-26', '藕是很多朋友選擇麻辣香鍋時的必點食物，因為它配合花椒、紅尖椒一起來炒，大大提升了口感。這道幹煸藕條是一道快手小菜，非常適合工作忙碌的朋友迅速做來吃。', '20分鐘', '2人'),
(35081, '素藕合', '2015-07-26', '藕合應該算是一道家常菜了，可是，想要減肥的朋友卻有些望而卻步。我們不妨把傳統的肉餡兒換成根莖類的素食，加上富含膳食纖維的蓮藕，不但不易長肉，還能減肥瘦身。', '20分鐘', '3人'),
(35091, '荷塘小炒', '2015-07-26', '如果想給家人做一道營養豐富的素材，我們向您推薦這道：荷塘小炒。胡蘿蔔、木耳、荷蘭豆和山藥都是營養豐富的食材，藕中含有的大量膳食纖維非常有利於消化。而且它色彩豐富，可以說是色香味俱全。', '20分鐘', '2人'),
(35101, '藕面窩', '2015-07-26', '藕面窩有點像油端子，但裡面是用藕作為主要的食材。它是武漢人的早點，也非常適合大家作為下午茶點來食用。如果出門野餐，也可以做來和家人一起分享。', '20分鐘', '2人'),
(35111, '和風蓮藕沙拉', '2015-07-26', '蓮藕的營養豐富，在《本草綱目》中被稱作“靈根”，藥用價值也不錯。簡單地搭配上番茄、生菜、黃瓜，再用日式醬料做成沙拉，低脂低卡，非常適合用來作為減肥餐。', '10分鐘', '2人'),
(35121, '湄南河泡藕梢', '2015-07-26', '藕梢是幼年時的蓮藕，口感比藕嫩很多。它可以幫助消化，提振食欲。搭配上泰式的醬料，可以在夏天提振全家大小的食欲。酸甜的口味也非常的棒！', '10分鐘', '2人'),
(35131, '巧味棉花糖', '2015-07-28', '只要多一點想像，就可以讓常見的零食變得更加有趣。就像這巧味棉花糖。多一點巧克力，就可以化身成為派對零食的顏值擔當！', '10分鐘', '2人'),
(35141, '香芒水果撻', '2015-08-03', '早餐來一份亮黃色的香芒水果撻，足以點亮一天的好心情。香甜的芒果中混雜著豐富的水果香氣，這一份惹人心醉的甜蜜情誼是對愛人最好的表達。和你愛的人一起，用這一份甜品，開啟一天的滋味生活吧！', '1小時', '2人'),
(35151, '芒果慕斯', '2015-08-03', '濃郁的芒果，爽口的優酪乳和絲滑的慕斯搭配在一起，組合成人見人愛的芒果優酪乳慕斯。再加上一杯香醇的咖啡，足以驅趕假日午後的慵懶，讓兩個人的時光也變得鮮活明亮光彩。', '1.5小時', '2人'),
(35161, '芒果糯米糍', '2015-08-03', '小巧的芒果糯米糍很適合作為小夫妻在家時的暖心夜宵。它混合著濃郁的芒果香味，加上糯米和椰蓉，頂飽又不會增加太多的熱量。搭配上一杯牛奶，無論是在家上網休閒還是工作熬夜，都是營養好滋味的。', '30分鐘', '2人'),
(35171, '芒果椰汁千層糕', '2015-08-03', '炎熱的夏天讓人心情煩躁？做一份清涼的點心如何？這款芒果椰汁千層糕融合了芒果和椰子的雙重口感，再加上這份凍出來的沁涼，簡直無法用語言形容。不妨試試看，給你的ta做一份帶去招待朋友，順便炫耀一下家裡的這雙巧手吧！', '1.5小時', '3人'),
(35181, '芒果馬卡龍', '2015-08-03', '需要在紀念日送一份點亮心情的禮物？向你推薦：芒果馬卡龍。鮮亮、甜蜜，一定要將這一份好心情一併送給ta！', '1.5小時', '2人'),
(35191, '鹽焗蟶子', '2015-08-04', '鹽焗這種煮法溫度均勻，令食物受熱程度一致，又能保存食物鮮味，這次先在粗鹽裡加入花椒、胡椒粒等調味料，令蟶子更添香味。', '30分鐘', '3人'),
(35201, '香茅椰青水煮蜆', '2015-08-04', '加入香茅和椰青水煮蜆，是充滿越南風味的做法，既可吃到蜆肉鮮味，又帶點香茅椰子清香，用來做宴客菜都不失禮。', '30分鐘', '2人'),
(35211, '蛋黃醬焗青口', '2015-08-04', '眾多急凍海鮮中，青口最容易處理，因為青口本身已經煮熟，加上喜歡的配料和調味即可，快捷方便。', '30分鐘', '2人'),
(35221, '冰鎮鮮鮑魚', '2015-08-04', '乾鮑是名貴海產，新鮮鮑魚的價錢則平民化得多，用來做冰鎮的冷盤既消暑，又能品嚐其爽滑彈牙的口感。', '1.5小時', '3人'),
(35231, 'XO醬涼拌象拔蚌', '2015-08-04', '相對其它貝類海鮮，象拔蚌的外型就有點與別不同，不過同樣鮮甜可口，長長的象拔可以切成薄片生吃、灼熟或快炒，這次加入XO醬就更惹味。', '1小時', '2人'),
(35251, '餃子大阪燒', '2015-08-04', '', '30分鐘', '2人'),
(35261, '抹茶海綿蛋糕', '2015-08-04', '現在很多朋友都喜歡在家烘焙，今天就推薦一款做法非常簡單，不用烤箱就可以完成的抹茶海綿蛋糕，快點學起來吧~', '1小時', ''),
(35271, '蘋果千層酥', '2015-08-04', '如果你想在家辦一個小派對，試試看這個玫瑰形狀的小甜點吧。濃郁的蘋果味道和柔軟的口感一定會讓你的客人留下深刻的印象。雖然它看上去很複雜，但是操作起來卻很簡單。絕對是點心中的“顏值擔當”。', '30分鐘', ''),
(35282, '台灣瓜仔肉', '2015-08-06', '鳳凰衛視主持Ivy竹幼婷，工作忙碌的她原來熱愛下廚，把廚房裝飾得猶如遊樂場一樣，再忙的日子她也不忙下廚，因為唯有自己煮的菜，才有那種叫她忘不了的台灣味。\r\n\r\n按此了解更多Ivy廚房的故事', '30分鐘', '2人'),
(35286, '補身汽鍋雞 [3-4人份]', '2015-08-07', '雲南的中南部聚集著很多的少數民族，也形成了自己的飲食特色，比如：汽鍋雞。這可是古代建水的官員招待皇帝的吃食。用蒸的原理讓雞肉和其他食材相互吸收精華。是一道絕對的養生菜肴。很適合年輕夫婦一起品嘗。', '1.5小時', '2人'),
(35288, '傳統紅三剁 [2-3人份]', '2015-08-07', '帶雲南的土產回去倒不如學一道雲南的傳統料理。讓每次在餐桌上吃到的時候，都能回憶起旅行的甜蜜感覺。向您推薦：紅三剁。選料簡單、製作也非常簡單。是地地道道的雲南傳統家常菜肴。很適合新婚夫婦的日常食譜。就讓一道菜，留下你們對雲南的最美好的想念吧！', '20分鐘', ''),
(35289, '騰沖大救駕[1人份]', '2015-08-07', '騰沖因為它豐富的地熱資源和翡翠吸引著很多年輕夫婦前往度蜜月。到了騰沖，當然要吃當地的特色：大救駕。Q彈的餌塊和酸菜一起炒，增加了口感。所以，在欣賞騰沖地貌的時候，不妨找個路邊食肆，點一份大救駕，再聽店家講一講它名字的由來。', '20分鐘', '1人'),
(35290, '雞樅菌豆腐湯', '2015-08-07', '每年的七八月是雲南的雨季，如果這個時候你正和你的另一半在雲南旅行，倒不如躲進一個地道的雲南菜館，點一份雞樅菌湯。雞樅菌多產於雲南南部，迄今為止還沒實現人工培育，所以是一道地道“野味”。清淡的湯品和傳統的雲南景色相輝映，即使是雨季，也會多一份詩意吧。', '1.5小時', '1人'),
(35311, '鹽燒三文魚骨', '2015-08-11', '到居酒屋總愛點燒三文魚骨來送酒，其實自己做也很簡單，三文魚骨於超市或凍肉店有售，有時壽司店亦有切刺身剩下的三文魚骨出售，簡單調味即可變成美食。', '1小時', '1人'),
(35321, '煙三文魚磨菇意大利飯', '2015-08-11', '煙三文魚經過燻熟，帶有鹹味和煙燻香味，當意大利飯煮至軟硬適中後，加入煙三文魚拌勻即成，簡單快捷就煮好一道意大利菜。', '1.5小時', '2人'),
(35351, '香煎三文魚薯餅', '2015-08-11', '煎薯餅是一款老少咸宜又百變的菜式，今次選了三文魚做主角，配以蔥和芫茜的味道令它口味中式一點，如果加入羅勒，變成西菜口味亦得。', '1小時', '2人'),
(35361, '焗芝士三文魚通心粉', '2015-08-11', '你喜歡吃Mac and cheese嗎？這款焗通粉無論做主菜或小吃都可以，今次分享的是變奏版食譜，加入三文魚及洋蔥等材料，口感沒有Mac and cheese那麼膩，味道亦更加豐富。', '1小時', '2人'),
(35371, '栗子紅棗炆雞翼', '2015-08-11', '栗子炆雞是經典家常菜，比較多骨的雞件小朋友未必喜歡，如果換做雞翼呢？相信受歡迎程度一定大增！今次加入具補血功效的紅棗，更加有益。\r\n\r\n 幫你買埋餸，即開即煮！\r\n 馬上選購： https://bit.ly/2Xcyeab\r\n依加上網都有得賣啦！\r\n<十五分鐘懶人版｜栗子炆雞>\r\n立即落單：栗子炆雞', '1小時', '2人'),
(35381, '中式和牛柳', '2015-08-11', '中式牛柳是幾乎每間酒樓餐牌上都有的菜式，味道酸酸甜甜最宜配白飯同吃，這次換上和牛肉炮製，味道更有驚喜。', '30分鐘', '2人'),
(35391, '黑松露蝦仁炒蛋', '2015-08-11', '蝦仁炒蛋是很受歡迎的家常菜式，如何可以加點新意呢？1湯匙的黑松露醬就可以變化出新口味，亦可立即提升餸菜矜貴度。', '20分鐘', '1人'),
(35401, '鮮芒老虎蝦', '2015-08-11', '夏天的尾聲，芒果仍然當造的時候，走過生果店傳來陣陣芒果香，用來下廚的話配蝦就感覺清爽，顏色和味道都有非常夏天的感覺。', '30分鐘', '2人'),
(35441, '香蕉蛋糕卷', '2015-08-12', '香蕉蛋糕卷是一個適合任何時刻的可口小食。同時，也是非常適合孩子的小點心。它製作簡單，香甜可口。讓我們一起用這個小食給自己充充電吧。', '10分鐘', '3人'),
(35451, '朱古力三重奏', '2015-08-14', '這是一款非常養眼的朱古力甜品。從顏色到味道都是三重對比，視覺和味覺都得到了非常美好的享受。它就像是愛情，擁有多重滋味和感受。你可以搭配上紅酒、蠟燭，在情人節營造出一個溫馨而浪漫的夜晚。', '1.5小時', '3-4人'),
(35471, '維也納沙架蛋糕[3-4人份]', '2015-08-14', '沙架蛋糕可以算得上是巧克力蛋糕中的極品，也是奧地利的國寶級蛋糕了。咬下一口，濃郁的巧克力味道縈繞唇齒之間，簡直就是情調晚餐的必備甜品。', '1.5小時', '3-4人人'),
(35481, '朱古力撻', '2015-08-14', '還有什麼比巧克力更能表達浪漫甜蜜的心意呢？我們向你推薦：巧克力撻。巧克力撻皮和巧克力撻心，讓食用它的人每一秒都感受香濃的浪漫情調。趕緊給你的愛人在浪漫的日子準備這個甜蜜的禮物吧！\r\n【10-15個】', '1.5小時', '10人'),
(35491, '巧克力泡芙[10-15個]', '2015-08-14', '吃泡芙的時候很害怕一口下去，奶油會沾在嘴上。如果在情人面前就會很尷尬。你可以選擇手指泡芙，這種法式浪漫小點心可以讓你吃得很優雅。充盈著香濃巧克力的柔軟內芯和香脆的外殼，都會讓你覺得吃它的每一刻都是一種享受。', '1小時', '7人'),
(35511, '日式牛肉咖喱', '2016-09-02', '著名時裝設計師Johanna Ho何志恩，亮麗的成績表上全都是與時裝有關的項目，原來這位工作極度忙碌設計師，心底裡一直埋藏著下廚的夢。\r\n\r\n按此了解更多Johanna廚房的故事', '1小時', ''),
(35521, '韓式麻辣雞棒槌', '2015-08-18', '今天推薦一道大人和小朋友都很喜歡的韓式麻辣雞棒槌，這道菜造型可愛又方便食用，是家庭必備私房菜哦~', '30分鐘', '2人'),
(35531, '栗子雞肉南瓜盅', '2015-08-18', '栗子與南瓜是秋冬天的情侶，無論是煮湯、做菜或者甜品，總是有影皆雙，這是南瓜盅，南瓜香氣完全滲透入栗子中，熟透的南瓜又吸收到內裡材料的精華。', '1小時', ''),
(35551, '冬菇栗子炆五花腩', '2015-08-18', '炆冬菇是秋冬最令人想念的菜式之一，因為可以配搭不同材料一起炆煮，這次配搭栗子和五花腩，炆煮期間廚房飄出來的香味真是令人銷魂。', '1.5小時', '2人'),
(35561, '栗子蘋果煙肉湯', '2015-08-18', '這道栗子湯是不少外國人秋冬天最愛的Comfort Food，栗子加上蘋果、洋蔥打碎成軟滑口感，遇上香脆的煙肉，讓秋冬天充滿溫暖的感覺。', '1小時', '2人'),
(35571, '栗子忌廉撻', '2015-08-18', '據非正式統計顯示，栗子是不少人喜歡的蛋糕或甜品口味，本為硬身的栗子製成栗子蓉後變得軟滑且更易親近，啖啖都充滿栗子香，法國著名甜點Mont blanc(白朗峰)就是栗子撻，自己試做做看，像不像山形也一樣好吃吧！', '1.5小時', '2人'),
(35581, '赤豆冰棒', '2015-08-19', '很多的70後、80後都對兒時一毛錢一根的冰棍記憶猶新，當哈根達斯和夢龍霸佔雪糕界王牌的今天，想吃到和童年味道一樣的冰棍兒最方便的就是自己動手，來試試這款簡單美味的夏日消暑必備——赤豆冰棒吧！', '10分鐘', '2人'),
(35621, '普羅旺斯燴雞', '2015-08-21', '精緻的法國大餐一直是浪漫情調的催化劑。想要給你的另一半最好的料理，不妨從這道普羅旺斯燴雞開始吧！濃郁的香料和雞肉的搭配堪稱完美，讓你即使不在法國，也能有身臨其境的感覺。', '30分鐘', '3人'),
(35641, '骰子牛肉', '2015-08-21', '每個身處愛情中的人都想把最好的給對方。就像是精緻的骰子牛肉：精選的食材、精選的烹飪方式，搭配出最棒的營養組合。用心對待你的愛，或許正是這道菜傳達出的資訊。', '1小時', '2人'),
(35651, '西班牙番茄冷湯', '2015-08-21', '熱情不減，愛情不滅，相信是很多愛人心中的希望。這道西班牙番茄冷湯擁有火紅的顏色，酸甜的口感帶來的是西班牙式的熱情。', '30分鐘', '2人'),
(35661, '日式土瓶蒸', '2015-08-21', '如果你剛結婚，一定希望你的家庭菜單上的食譜都很健康。向你推薦這道日式土瓶蒸。海鮮、蔬菜、肉類......涵蓋各種營養。加上精巧的瓶子，讓你的ta吃得健康，吃得美味。', '1小時', '2人'),
(35671, '瑪格麗特冰棒', '2015-08-27', '眾所周知，龍舌蘭是調製雞尾酒的一種很重要的基酒，瑪格麗特被稱作“雞尾酒之後” ，神奇的冰棒雪糕機讓你體驗固體瑪格麗特融化於舌尖的清爽與銷魂！夏日解暑必備之清甜西瓜汁混搭熱烈龍舌蘭，高顏值自製冰棒分分鐘俘獲Ta的心！', '10分鐘', '2人'),
(35681, '和牛扒飯', '2015-08-28', '日式牛肉飯(牛丼)是日本速食文化之一，在碗內盛載米飯然後放上煮熟的牛肉。為另一半煮的話不如將它升級，用上更名貴好吃的和牛扒，配以日式酸醋汁，和牛的脂香混著飯非常好吃。', '30分鐘', '2人'),
(35691, '和牛扒煎蛋', '2015-08-28', '牛扒煎蛋是外國很流行的早餐甚至早午餐菜式，周末早上為他煮這個早餐，更用上油花均勻分佈的和牛扒，應該會讓他樂上一天。', '30分鐘', '1人'),
(35711, '日式和牛沙律', '2015-08-28', '沙律一直被視為餐桌上的配角，但如果你炮製這道日式和牛沙律，保證你一將沙律上枱，就立即成為該餐的主角。', '30分鐘', '1人'),
(35721, '和牛炒飯', '2015-08-28', '炒飯要炒得好，除了要炒得乾身爽口，油份也要適中，用上和牛肉炒飯，先把和牛煎香，讓油份滲出來，然後用來炒飯，定必香氣四溢。', '30分鐘', '1人'),
(35731, '松露磨菇忌廉湯', '2015-08-28', '香港有不少西餐廳都以雜菜湯和忌廉磨菇湯為常設例湯，大家都習慣喝那種只有幾片磨菇白色忌廉湯，其實磨菇湯可以足料好喝的，再加上白松露醬的香味，濃郁菇菌味倍增。', '1小時', '1人'),
(35741, '松露溫泉蛋意粉', '2015-08-28', '雞蛋和松露可謂是最完美的配搭，淡淡的蛋香加上濃濃的松露香氣，加上意粉一起煮，意粉吸收兩者的味道，質感滑溜可口，吃到停不了口。', '1小時', '1人'),
(35751, '松露醬配麵包條', '2015-08-28', '松露這種感覺高級的食材，最適宜在開派對時招呼朋友，不用擔心成本很貴，因為松露醬價錢大眾化，用來做成沾醬點麵包條吃，一定很受朋友歡迎。', '30分鐘', '1人'),
(35781, '香料鹽焗虎蝦', '2015-08-28', '這道可謂是不失敗的美味宴客菜，鹽焗的方法鎖著蝦的鮮甜味，而且賣相得體，焗熱的粗鹽還可以為這道菜保溫，加上各種香料味道，令蝦更為惹味。', '30分鐘', '3人'),
(35791, '金香炒虎蝦', '2015-08-28', '如果你到過馬來西亞，應該會嚐過著名的金香蟹或金香炒啦啦(蜆的馬來話)，自己煮可以嗎？想煮這道香口惹味菜式，要準備多種調味料，令虎蝦平均沾上醬汁就大功告功了。', '1小時', '3人'),
(35801, '醉虎蝦', '2015-08-28', '有人喜歡用生蝦來做醉蝦，但亦有人擔心衛生問題，或是腸胃較弱不宜吃生醉蝦，怎麼辦呢？把蝦煮熟用來做醉蝦別有一番風味，今次選用虎蝦來做，吃起來啖啖肉呢！', '30分鐘', '2人'),
(35811, '虎蝦濃湯', '2015-08-28', '西式湯品大致可分為清湯、濃湯和水果湯，當中以濃湯最受大眾歡迎，因為做法會將主要材料和配料用攪拌機打至細滑，啖啖都是豐富材料，這款用虎蝦煮的濃湯，味道比得上龍蝦湯呢。', '1.5小時', '1人'),
(35821, '椒鹽虎蝦', '2015-08-28', '吃蝦蟹等有殼類海鮮，除了喜歡吃蝦肉蟹肉之外，有不少人也鍾情沾滿調味料的外殼，炮製一道椒鹽虎蝦，就可以享受啜指的美味了。', '1小時', ''),
(35831, '美式晨之味', '2015-08-28', '說起美式早餐，最經典、最傳統的就是松餅了，再搭配上可口的醬料和小食，簡單美味而又營養豐富，是最流行的歐陸簡式早餐的一種。提前一天準備好一些食材，早上起來就能快速完成。早晨醒來，陽光正好，兩份美式早餐，兩個人的甜蜜世界，就用這一份美好，一起點亮新的一天吧！', '20分鐘', '2人'),
(35841, '英倫風情早餐', '2015-08-28', '英國人很重視早餐，認為早餐是一天中最重要的一頓飯。傳統英式早餐因其菜點豐富而享負盛名，為英國人所驕傲。而各種英式早餐中，焗豆、番茄、薯仔、香腸、雞蛋和英式紅茶是最必不可少的。假日的早晨，和你的另一半一起享受一個豐富而完美的早晨，給早餐來點花樣，做個英式早餐吧！', '30分鐘', ''),
(35851, '瑞典班戟薄餅', '2015-08-28', '北歐國家瑞典的早餐相對簡單。最主要就是他們的Pannkakor薄餅了，是北歐最古老的薄餅美食。配上果汁和果醬就構成了一道傳統的北歐風味。薄餅做起來特別簡單，所以，你可以多睡一會兒，再和另一半領略一個北歐風情的早晨！', '30分鐘', '2人'),
(35861, '西班牙小油條', '2015-08-28', '西班牙的小油條是西班牙美食的精髓之一，也是西班牙人經常吃的早餐之一。搭配上巧克力，感覺整個早晨都會很溫暖。它很適合夫妻共同完成：一個人將麵糊擠到鍋裏，一個人剪斷它。一起享受烹飪的樂趣。', '30分鐘', '2人'),
(35871, '芬蘭燕麥粥', '2015-08-28', '在高科技最發達國家生活的芬蘭人，吃東西卻很“原始”！早晨的芬蘭人喜歡燕麥、牛奶、新鮮講過，滿滿的回歸自然的感覺，卻很健康。這樣的早餐很適合一個清新的早晨，和心愛的人一起感受大自然饋贈的最“純淨”的味道了。', '20分鐘', ''),
(35881, '釀番茄', '2016-09-03', 'Cecile和丈夫及6歲大的女兒本住在法國巴黎，一年前因丈夫工作關係，全家來到香港定居。為了更妥善照顧女兒，Cecile找了一份法文教師的兼職，閒暇時，熱愛下廚的她就在自己的廚房小舞台實踐靈感。', '30分鐘', '2人'),
(35891, '香蕉藍莓沙冰', '2015-09-02', '藍莓富含花青素，是天然的抗氧化物，對於延緩衰老和增強記憶力有良好的效果。香蕉含有的某種特殊元素可以使人心情愉悅，是名副其實的“開心果”喔！ 抓住盛夏的尾巴，讓這款酸酸甜甜，清爽濃稠的魅紫色香蕉藍莓沙冰喚醒你沉寂已久的活力！', '10分鐘', ''),
(35901, '焗流心芝士撻', '2015-09-04', '最近從日本而來的流心芝士撻成為了人氣商品，但往往要排隊一小時才能購買限定數目，不如自己試做做看，用上在一般超市買到的三款芝士，芝士味非常濃郁呢！', '1小時', '3人'),
(35921, '鮮蝦牛油果沙拉', '2015-09-06', '有“油”的一定熱量高？我確定你是在搞笑！牛油果能將你的“森破”駁斥得體無完膚。其中含有不飽和脂肪酸，熱量是非常的燒少。牛油果很難吃？那一定是你打開的方式不對！用來做沙拉的牛油果，與其他豐富的食材混合在一起，吃到口中會有一種奇妙的口感：香、滑，是各種味道的催化劑。就讓一盤沙拉“秒殺”你的大肚腩和游泳圈，和愛的人開啟“輕食生活”吧！', '1.5小時', '2人'),
(35931, '咖喱雜蔬烏冬面', '2015-09-06', '懶和美味並沒有天然的關係，用對方法才是關鍵！咖喱就是愛美食又不太願意花費太多精力人的必殺技，是新手煮夫（煮婦）常備的快手醬料。這道咖喱雜蔬烏冬面，每一種食材中都糅雜著咖喱的芳香，還加入了椰醬來減低辣味和增強香味，配以香茅，更加增強咖喱的濃郁。容易消化的烏冬面和卡路里不高的蔬菜搭配，最適合作為晚餐食用。晚餐後與愛人手牽手散個步，消化了不少的熱量又收穫了浪漫的情調。', '30分鐘', '1人'),
(35941, '通心粉沙拉配香煎鴨胸', '2015-09-06', '忙碌的年輕夫婦當然希望擁有一個可口健康又快速的晚餐啦！所以，主食、蔬菜、肉類......集齊這些就能召喚一頓健康的晚餐呢！向您推薦“通心粉沙拉配香煎鴨胸”。20分鐘就能做完的料理，融合了健康、情調和迅速的特點。微酸的黑醋汁激發胃口，黑胡椒讓肉類食材更添滋味，彩色的通心粉也頓時讓這道菜顏值滿滿，立刻激發你的食欲。', '30分鐘', '1人'),
(35951, '蔬菜豆腐餅', '2015-09-06', '蔬菜和豆腐看似有些寡淡，不過合理的搭配和巧妙地烹飪就可以玩出不同的花樣。就像是這個蔬菜豆腐餅。菠菜和豆腐的搭配，補鈣健骨，放入提鮮的香菇，激發出豆腐的香氣來。又有燕麥的配合，增強了飽腹感。有時候，可以在家改變一下口味的哦。', '20分鐘', '2人'),
(35961, '雞肉素菇炒飯', '2015-09-06', '一份惹味的醬料絕對敵過N種食材的混搭。也是年輕上班族的廚房必備。如果你沒時間去市場買食材的話，就用冰箱裏的常備品做一份“雞肉素菇炒飯”吧。用含有不飽和脂肪酸的橄欖油和健康低卡的糙米，大大降低了攝入熱量的可能性。好吃的素菇醬和雞肉的配合，讓這份飯更添滋味。要是愛人向你抱怨了“清湯寡水”，不妨用它來“安撫”一下，也不會太長肉哦！', '30分鐘', '1人'),
(35971, '雞蛋沙拉杯', '2015-09-08', '雞蛋不但營養豐富，而且還有多種吃法。今天就教大家一個造型特別，很適合在聚會時做的雞蛋杯沙拉。', '20分鐘', '3人'),
(35981, '微甜軟滑紫薯蓉', '2015-09-11', '紫薯是一種健康的天然食材，有抗氧化、補血、抗衰老等作用，好處非常多，而且紫薯是最近流行的食材，不少餐廳均推出用紫薯製作的甜品，要製作香甜軟滑的紫薯蓉其實好簡單，各位紫薯控快點動手試試吧！', '20分鐘', '2人'),
(35991, '梅子紅薯球', '2015-09-11', '誰說兩個人在一起就一定要門當戶對？梅子和紅薯，一個埋在土裏，一個長在樹上。這一對就好像愛上魚兒的飛鳥一般，但卻奇妙地搭配在了一起，並碰撞出絕妙滋味，一道讓人在休閒時光中愛不釋手的可口小食，一番下午茶點中不可錯過的酸甜感受。和愛的人一起分享這份美味，也一起享受輕鬆時光吧。', '20分鐘', '2人'),
(36001, '蝦仁牛油果', '2015-09-11', '發揮想像，讓常見的食材“凹”出不同的造型，即使是夜宵也能變得“顏值杠杠”。用熱量低的鮮蝦搭配牛油果醬。造型好看，口味清新又不用擔心長胖。用這道玉米片蝦仁牛油果，和愛人一起進入“夜宵模式”吧！', '20分鐘', '2人'),
(36011, '水晶芒果卷', '2015-09-14', '誰說芒果是橢圓的？誰又規定芒果一定有核？卷成長條的芒果卷超級像小時候吃的山楂卷，伴隨著兩個人晚飯後的愜意時光，和這盤水晶芒果卷一起回憶童年時光的美食，酸甜好吃不長胖，絕對是調節心情的甜蜜利器。空閒下來的時候做一些冰在冰箱裏，隨時拿出來就可以享受這一份愜意了。', '1.5小時', '2人'),
(36021, '鳳梨檸檬紙杯蛋糕', '2015-09-14', '讓鳳梨變身一朵花，這不是幻境，這是現實。這是一個神奇的“紙杯蛋糕”，用一朵“鳳梨花”將自身與那些“平庸之輩”區分開，向傳統“Say No”，和新奇“Say Hi”。這樣的一個顛覆傳統造型之物，對決是招待另一半好友的面子貨，讓Ta誇讚你的巧手和巧心思！', '1.5小時', '2人'),
(36031, '迷你披薩', '2015-09-14', '大披薩太過浮誇？小披薩再合適不過！一口一口吃掉的不是憂愁，而是無趣和傳統。這樣的個頭太適合在一個慵懶的午覺之後，和心愛的人一起製作。既不會耽誤晚飯的好口味，又可以一起享受烹飪的樂趣。', '1.5小時', '2人'),
(36051, '瑤柱蝦仁冬瓜環', '2015-09-16', '', '1小時', '2人'),
(36061, '法式燴雞肉盤子料理', '2016-09-04', '本地創作品牌Fluffy House創辦人之一Sam和太太Silvia，婚後建立幸福安樂窩，Silvia更投入她的創意入廚生活，她喜歡炮製不同國家的料理並將它們拼合在一起，並命名為「盤子料理」，菜式配搭可以是中、日、韓、意、法菜等，進一步發揮她的創意料理風格。\r\n\r\n按此了解更多Silvia & Sam的廚房故事', '1小時', '2人'),
(36091, '牛油果烤雞蛋', '2015-09-18', '高冷的牛油果怎樣吃才夠時尚？味道獨特的牛油果果肉柔軟似乳酪，有核桃的香味，可以說是水果界的神奇百搭果。百搭界新秀牛油果和當仁不讓的百搭元老雞蛋如今強強合一，聯手呈上一道簡單美味高顏值的精緻小食。', '20分鐘', '2人'),
(36101, '芝士焗明蝦', '2015-09-18', '烤蝦端出烤箱的瞬間香味溢滿房間，明亮如暖陽的色彩讓人眼前一亮，食欲大增，芝士的香滑膩柔配上蝦肉的酥軟彈牙，甜鹹交替縈繞齒間。簡單的配料輕鬆的步驟，在家中就可以為心愛的TA呈現出浪漫西式大餐的奢華即視感。', '1小時', '2人'),
(36111, '香菇蒸鱈魚', '2015-09-18', '蒸食能最大限度的保留食物原有的營養成分，尤其對於魚肉來說。鱈魚刺少肉質鮮美，香菇素來有“菇中之王”的美譽，當菌類搭配海鮮，加上傳統的蒸菜工藝，讓兩種食材的味道調和到極限。如此一道簡單易學的滿漢全席菜式可是展示自己高逼格廚藝的不二選擇。', '30分鐘', '2人'),
(36131, '黃瓜白肉卷', '2015-09-18', '肥肉太油膩，不妨配點清爽的黃瓜再做一個簡單的卷的造型，白綠相間，五花肉上道道紅線掩映其中，擺盤配上精心的小裝飾，立馬讓平民的食材綻放出華麗麗得高貴日式風。不論你的Ta愛吃素還是無肉不歡，這道美美的小食都可以討得Ta的歡心！', '30分鐘', ''),
(36141, 'Xo醬菌菇南瓜盅', '2015-09-18', '南瓜盅是一道漢族名點，南瓜蒸透後噴散出的香味配以菌菇類大薈萃，淋上醬料裏的頂級調味品鮮中帶辣的XO醬，古老與現代的味蕾碰撞出最時尚健康的新中式頂級佳餚。無論是賣相還是內涵都是滿滿的高端大氣上檔次喔！', '30分鐘', '2人'),
(36161, '彩虹冰皮月餅', '2015-09-23', '冰皮月餅源自香港，如今是大多數香港人中秋節月餅的首選。白滑Q彈的小巧外形經典之餘少了一絲多變，然而多花一點點心思就可以使冰皮月餅擁有繽紛的五彩外衣。當可愛的糖果彩虹色蔓延上冰皮，加上果醬配黃油蛋糕的創意餡料，Norma獨家彩虹冰皮月餅在這個中秋節帶給你不一樣的視覺及味覺雙重美味體驗~更有美美的月餅小禮盒DIY貼心教程喔~', '30分鐘', '1人'),
(36171, '杏仁藍莓麵包杯', '2015-09-24', '單調的吃塗醬吐司麵包片太乏味？加一點堅果，添一點水果，塗一點果醬，換一種切法，發揮你的想像力，美美得在烤碗中排出一朵花的形狀，放入烤箱來個大變身，營養美味又有創意的早餐就是這麼簡單~', '20分鐘', '2人'),
(36301, '臺灣鹵肉飯', '2015-09-25', '當我們提到臺灣美食，最不能錯過的就是這道人盡皆知，看似簡單卻又無比考驗廚藝的鹵肉飯了！五花肉爆出的濃香搭配紅洋蔥的甜味，彌漫在舌尖的是經典的臺灣味道，肥而不膩，甜鹹適口，香濃四溢。帶有厚重口感的鹵肉，配上一碗蒸的不軟不硬的原香有機臺灣白米飯，每一粒米都吸透濃稠的湯汁，散發著最誘人的味道。', '1.5小時', '2人'),
(36311, '臺灣鳳梨酥', '2015-09-25', '凡是到臺灣觀光的遊客必然會帶回的特色伴手禮非鳳梨酥莫屬。小小的鳳梨酥，色澤金黃，外皮酥松化口，內餡甜而不膩，如此賞心悅目的可口點心是臺灣行的必選美味小食，更是下午茶的不二之選。與自己心愛的人在一個愜意的週末，花時間來親手製作一下這道經典臺灣小食也不失為一件醉心美事。', '1.5小時', '2人'),
(36331, '臺式蜂蜜吐司盒', '2015-09-25', '原味吐司方包配以醇香蜂蜜烘烤後是沁入心田的甜蜜，明媚的火龍果及奇異果散發著夏日少有的斑斕色彩，可愛的外形足以融化每一位少女的心。這不僅是一道臺式甜品，更是無數戀人記憶中最粉紅的初戀回憶。讓愛情永遠保鮮，讓這道臺式蜂蜜土司盒來做戀人甜蜜愛情的永恆見證。', '30分鐘', '3人'),
(36341, '蚵仔面線', '2015-09-25', '蚵即是小牡蠣，具有重鎮安神，潛陽滋陰的作用，雖然臺灣北部以紅面線為主，南部以白麵線為主，而且做法各異口味也稍加不同，但都無法掩蓋蚵仔面線的濃郁口感，十足香味以及沉浸於口中並一直延伸到喉嚨的鮮香。在週末或晚上為Ta下廚做一碗正宗蚵仔面線，足以在夜深人靜時回味起在臺北夜市人間美味的流連忘返。', '30分鐘', '2人'),
(36351, '軟殼蟹手卷', '2015-09-29', '眾多款式的壽司手卷中，軟殼蟹手卷口感最為特別，因為暖暖的壽司飯包裏炸至香脆的軟殼蟹，一軟一脆的口感特別美味。', '1小時', '2人'),
(36361, '金沙軟殼蟹', '2015-09-29', '由於鹹蛋黃別具風味，用鹹蛋黃做出來的金沙菜式失敗率比較低，將鹹蛋黃炒至起泡後加入炸脆的軟殼蟹，讓蟹沾上滿滿的金沙，怎能不好呢？', '1小時', '1人'),
(36371, '泰式咖哩軟殼蟹', '2015-09-29', '炸至金黃色又脆身的軟殼蟹，在外面掛上一層醬汁就更為惹味，這次配搭濃味的泰式黃咖哩汁，醬汁用來配麵包吃也一流。', '1小時', '2人'),
(36381, '泡菜軟殼蟹漢堡', '2015-09-29', '吃膩了牛肉漢堡，不如來個海鮮漢堡吧！炸至香脆鬆化的軟殼蟹，配以泡菜、番茄、牛油果、西生菜既能中和軟殼蟹的油膩感，又能增加漢堡材料的層次感。', '30分鐘', ''),
(36391, '軟殼蟹薄餅', '2015-09-29', '想吃薄餅也不一定要懂得搓薄餅皮，只要在超市買來墨西哥薄餅，就可以在家做個簡單薄餅，炸軟殼蟹配搭酸酸甜甜的芒果沙律醬，周末做這道菜和朋友一起分享吧！', '30分鐘', '1人'),
(36401, '意大利黑醋蜜糖排骨', '2015-09-29', '外國人吃中菜必點生炒排骨，酸酸甜甜味道的確是中菜特色之一，酸甜品味的來源不一定只有是茄汁、白醋和砂糖，用意大利黑醋和蜜糖一樣得。', '30分鐘', '2人'),
(36421, '煎豬扒配蜜糖黑醋汁', '2015-09-29', '煎豬扒可以是很家常的菜式，但只要配菜和擺盤花點心思，立即可變成高級西餐！今次教大家自製薯蓉及蜜糖黑醋汁，配杯紅酒，與情人來個燭光晚餐吧！', '30分鐘', '2人'),
(36431, '黑醋柚子炒雞球', '2015-09-29', '韓式柚子蜜平日要來沖茶感覺滋潤，用來入饌亦有其獨特甜味，配搭微酸的意大利黑醋用來炒雞球，來個西韓配搭。\r\n\r\n<十五分鐘懶人版｜醋香酸辣雞丁>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：醋香酸辣雞丁', '30分鐘', '2人'),
(36441, '日式炸黑醋豬柳', '2015-09-29', '炸物感覺比較油膩，意大利黑醋的酸味正好用來中和油膩感，這道日式炸黑醋豬柳，用來配飯或麵也可以啊。', '30分鐘', '2人'),
(36451, '蜜糖芥末黑醋雞鎚', '2015-09-29', '意大利黑醋味道濃郁，食沙律加少少已很足夠，結果黑醋用不完怎麼辦？用來入饌都可以呀，這款蜜糖芥末黑醋雞鎚，做餸菜或者Party food都很適合。', '30分鐘', '2人'),
(36461, '芝士焗軟殼蟹', '2015-09-29', '最近芝士菜式非常流行，看來大家都為了美味而毋懼致肥，這次做的芝士汁用料簡單但非常美味，這個芝士汁更是用途廣泛，用來拌麵都可以啊。', '1小時', '2人'),
(36471, '紫薯豆腐粥', '2015-09-29', '', '1小時', '2人'),
(36481, '南瓜雞蓉青豆粥', '2015-09-29', '', '1小時', ''),
(36501, '煉奶香蕉燕麥球', '2015-09-30', '燕麥有益，但嫌加奶煮粥的食法好悶？不如用來做小食吧！香蕉和燕麥都高纖易有飽肚感，適合要Keep Fit的你品嚐，而且做法簡單，一口一粒，做下午茶就最適合了。', '30分鐘', '3人'),
(36511, '不敗南瓜湯', '2016-09-05', '廚房，理應是每間屋必備的一個煮食空間，但香港地少人多，能有個小小的蝸居已很不錯，有個大廚房算是奢侈品吧！想不到這個問題能觸發商機，愛吃愛煮的Calanthia想到「出租廚房」的概念，在工廠大廈搭建起她的夢想廚房RENT-A-KITCHEN，希望大家都可以享受入廚樂。', '30分鐘', '2人'),
(36521, '莫薩卡', '2015-10-05', '莫薩卡作為希臘的國菜，茄子肉和土豆泥的混合配以精心調味的牛肉餡，一層層碼起來，以橄欖油調味，再覆以香濃芝士，放入烤箱裏烤成金黃誘人的類似千層餅的方形小塔。表層微焦的金黃芝士有了脆香的口感，切一小塊放入口中，數種食材的混合在口中漸漸產生了極愉悅的快感，不禁對那方古老文明的迷人勝景及人文建築心生嚮往。', '30分鐘', '3人'),
(36531, '希臘卷餅', '2015-10-05', '希臘卷餅是雅典當地的特色美食之一 ，在雅典四處可以見到它的身影。羊肉經過醃制和烘烤，散發了中和後的誘人香味，配上洋蔥、青椒和番茄等繽紛蔬果，視覺的讓吸引讓人心笙搖曳，澆上地道的希臘優酪乳，用卷餅卷起來宛如霜淇淋甜筒，葷素搭配的餡料加上優酪乳的獨特調味，配以卷餅後的口感讓你一口難忘，從此對於雅典有了一份更深的留戀。', '1.5小時', '2人'),
(36541, '釀番茄球', '2015-10-05', '聖托裏尼，這個浪漫又美麗的島嶼，是最適合情侶和吃貨去遊玩的地方。釀番茄是聖托裏尼的經典小食，可愛圓滾滾的紅色外殼讓人眼前一亮，米飯和牛肉在烤制的過程中混合了雞蛋、番茄以及芝士的特有香味，在蔥末及百里香碎等香料的作用下更加清甜誘人。濃濃的地中海風味讓你在藍白交錯的天堂般的美景中無限留戀在這裏的每一刻。', '1小時', '3人'),
(36551, '希臘式沙拉', '2015-10-05', '希臘特有的地理位置和氣候環境使希臘的橄欖油和香料聞名世界。希臘溫和的氣候孕育了味道鮮美的蔬菜水果，像葡萄、萵苣、桃子、咖喱、草莓、西瓜等。希臘式沙拉就地取材，看似雜亂，其實美味無比。特有的羊奶芝士塊口感爽滑甘甜，點綴在斑斕的紅黃綠之間，簡單清爽的醬汁讓這道開胃菜充盈了希臘人一日早餐的愉悅。', '10分鐘', ''),
(36561, '希臘風味甜甜球', '2015-10-05', 'Loukoumades 是希臘的著名甜食，可以說是希臘人民的大愛。輕巧可愛的外形，簡單的食材準備，如果你還是一個廚房菜鳥，不要緊，趕快來試一下這道地中海血統的美味甜食吧！傳統的loukoumades是中筋麵粉團油榨後加上蜂蜜、桂皮粉、芝麻，熱乎乎的時候食用。隨著世界飲食口味的不斷變化，蜂蜜可以換成巧克力醬、草莓醬、加各種堅果等，再配上各種口味的冰激淋，夏天食用更是一絕，冰火兩重天～', '1.5小時', '2人'),
(36571, '鷹嘴豆泥苞', '2015-10-08', '鷹嘴豆作為一種高營養豆類植物，富含多種植物蛋白和多種氨基酸、維生素、粗纖維及鈣、鎂、鐵等成分，有“粗糧中的粗糧”的美譽。這道小小的鷹嘴豆泥點心，富含板栗的香味，入口即溶，回味悠長。', '30分鐘', '2人'),
(36591, '豉椒炒蟶子', '2015-10-09', '豉椒炒是經典的廣東菜煮法，豆豉的香味加上燈籠椒的甜味，配搭海鮮或肉類都惹味非常，這次用來炒蟶子，更可帶出蟶子的鮮甜味呢。', '30分鐘', ''),
(36601, '蒜蓉粉絲蒸蟶子', '2015-10-09', '蒜蓉粉絲蒸蟶子是簡單易做的家常菜式，蒜蓉味道滲入蟶子之中，而蟶子的鮮味被粉絲充份吸收。', '30分鐘', ''),
(36611, '金沙脆炸蟶子', '2015-10-09', '蟶子煮法一般都是蒸，有沒有想過也可以炸？將蟶子起肉後炸脆，再加上鹹蛋黃的金沙質感，吃起來啖啖肉很美味。', '30分鐘', '2人'),
(36631, 'XO醬炒蟶子', '2015-10-09', '如果想煮海鮮，蟶子是比較易處理的選擇，買新鮮的話就浸鹽水吐沙，急凍的話更方便，解凍洗乾淨後就可以煮了，今次就用蟶子煮XO醬炒蟶子。', '30分鐘', '2人'),
(36671, '舒芙蕾', '2015-10-10', '舒芙蕾是於中世紀誕生於法國的著名甜點，法文的“Souffle”就是吹氣的意思，將鮮奶和蛋白隔水烘烤到蛋白瞬間膨脹，嘴唇觸碰的瞬間就會融化，留下滿嘴的乳香。宛如初吻般的天旋地轉，櫻花雨般的灑落心田，溫暖又浪漫，永生難忘。', '1小時', '2人'),
(36681, '歌劇蛋糕', '2015-10-10', 'Opera的視覺和味覺都讓人聯想到歌劇院，九層的蛋糕，內芯的層層疊疊，咖啡和巧克力的綿柔醇香，夾雜杏仁蛋糕的鬆軟，在嘴裏層層化開，如夢如幻，每一層都足以引爆強烈的味覺衝擊。方正的外形似乎不是法國甜點的做派，但不論是呈現在蛋糕盤還是精緻碟子裏，她內斂的外表自有一種富貴優雅的氣場環繞。當一份愛情經歷了風雨的考驗走向了婚姻的殿堂，用歌劇院蛋糕用作婚禮的壓軸甜點蛋糕是再合適不過的選擇。', '1.5小時', '2人'),
(36691, '朱古力瑪德琳', '2015-10-10', '瑪德琳蛋糕在世人的印象中有一種濃濃的文藝氣息，她是大文豪普魯斯靈感的觸發點。在《追憶似水年華》普魯斯寫到“當帶著心渣的那一勺茶碰到我的上顎，頓時使我渾身一震，我注意到我身上發生了非同小可的變化，一種舒坦的快感傳遍全身，我感到超凡脫俗。”瑪德琳呈現精緻小巧的貝殼狀，甜度極高，或許可以像大文豪一樣搭配清淡的紅茶來享用。', '30分鐘', '2人'),
(36701, '拿破崙蛋糕', '2015-10-10', '拿破崙法語的意思是“一千層”，所以也叫千層酥。一共三層焦黃色的千層酥皮，夾層塗滿馥鬱香甜的香草奶油，入口松化香脆。牙齒上下擠壓酥皮，夾層蛋奶餡料橫向外溢，層疊口味帶來最混搭的味覺革命。每當叉子插下去，酥皮便應聲裂開，發出清脆的聲音，每吃一口，都像敲響一個音符，帶來最愉悅的心情。就像熱戀期的甜膩，我的眼裏只有你。', '1.5小時', '2人'),
(36711, '法式栗子蛋糕', '2015-10-10', '法式栗子蛋糕這道甜點早在13世紀的義大利廚藝書中就已經出現。栗子在秋天結果，冬季成熟，作為一件口感綿密的營養食材，天然的美味、特別的融合性、健康的特性，栗子的身影遍佈甜品界的各處，備受青睞。濃滑甜蜜、餘味純香，栗子獨有的樸素色彩無需任何修飾就足夠誘人。最後鑲上的一整枚栗子更成為點睛之筆。如果你的Ta也是一枚栗子控，就一定要帶Ta來品嘗這道來自法國經典的栗子甜品。', '1.5小時', '2人'),
(36721, '西班牙海鮮飯', '2016-09-06', '西班牙海鮮飯', '1小時', '3人'),
(36731, '加州烤土豆碗', '2015-10-15', '土豆風靡半個地球，無論國內還是海外，人們都對土豆情有獨鐘。即使簡單做成烤土豆、蒸土豆，土豆的健康價值以及美味程度也從來沒有令人失望過，烤土豆還是法國人和德國人的常見主食。烤土豆做法花樣繁多，此次日日煮為你呈現一道簡單美味的美式烤土豆。', '30分鐘', ''),
(36741, '涼拌秋葵木耳百合', '2015-10-16', '', '10分鐘', '2人'),
(36751, '土耳其肉丸', '2015-10-16', '土耳其肉丸是一道用羊肉做成的土耳其傳統主食，常常做成球狀或餅狀。出爐後濃郁的肉香勾起人的食欲，肉汁上冒湧出小氣泡，用餐刀切開，肉汁就迫不及待的順著刀口流向盤子。將一小塊送到嘴裏，頓感肉香灌頂，只要對的香料遇到對的肉，不但不會遮蓋原本的肉味，反而會將其昇華的更為濃郁，咬下去彈性十足，肉碎的大小恰到好處， 它既可以搭配三明治，也可以搭配沙拉，還可以搭配鹹香的土耳其優酪乳。', '30分鐘', '3人'),
(36761, '土耳其披薩', '2015-10-16', '只知道披薩是義大利的經典美食，殊不知土耳其也是披薩大國。土耳其披薩不僅種類繁多還創意十足。土耳其披薩通常是用船型的面餅做成的，肉餡的食材豐富，充分混合後充滿異域的風情，由優酪乳調味的披薩醬奶香味十足，披薩竟然還分為多層，外層淺黃鬆脆，內層綿軟白皙，略帶甜味，嚼起來層次豐富，一軟一脆，口感對比強烈，嚼過之後，齒頰留芳。不論是驚豔奇異的外形還是難以抵擋的香味誘惑，總會抓住你的心！', '1小時', ''),
(36771, '土耳其烤蝦翅', '2015-10-19', '如果你想在一道菜中既吃到雞又吃到蝦那麼一定不能錯過這道土耳其烤蝦翅。將醃好的蝦肉塞到雞翅裏配以烤肉醬，經過烤箱的烘焙，將蝦肉的鮮味滲透進雞肉的美味，一道地中海風格的烤肉大餐給你視覺上的第一衝擊，絕對讓你忍不住有大快朵頤的衝動，一口咬下去，雞肉蝦肉混合的風味溢滿口腔，回味無窮。', '30分鐘', ''),
(36781, '土耳其烤肉卷餅', '2015-10-19', '在土耳其街頭巷尾都很親民和火爆的流行外帶食品非烤肉卷餅莫屬。土耳其烤肉醃料能使烤肉香味濃郁，口感細膩，肉質鮮嫩，聞者口水欲出，食者口味留香，其醬紅肉色，烤出一種獨特的焦香味和濃郁的料香味，讓人吃過不忘。一張薄薄的餅皮卷上烤好的醃肉以及多樣的蔬菜，咬上一口軟糯的餅皮和脆香肥美的烤肉，葷素結合，搭配出絕妙的滋味，讓你吃了還想吃，欲罷不能。', '1.5小時', '2人'),
(36791, '土耳其散蛋飯', '2015-10-19', '土耳其烹飪把希臘、波斯、阿拉伯和巴爾幹半島的豐富元素融會貫通，發展出了自己多姿多彩的美食文化。土耳其散蛋飯是傳統的土耳其早餐，打散的雞蛋與各類蔬菜混合後煮成香濃蘸料，雞蛋配以甜椒及番茄後讓各自的酸甜發揮到極致，配上香酥的土耳其麵包，一道濃情的土耳其特色早餐為你開啟土耳其美食之旅。', '10分鐘', ''),
(36801, '沙嗲雞肉串燒', '2015-10-20', '', '1.5小時', '1人'),
(36811, '三分鐘芝士脆片', '2015-10-22', '包裝零食含有很多添加劑，多吃無益，其實自己用簡單材料都可以做到好吃的小食，好像這款芝士脆片，每塊焗成金黃色，脆卜卜，還有香濃芝士味，真的會讓人吃個不停！', '10分鐘', '2人'),
(36821, '【Norma X 趙海珠】- 時蔬釀竹笙', '2015-10-23', '', '30分鐘', ''),
(36831, '【Norma X 趙海珠】- 無麩質朱古力蛋糕', '2015-10-23', '', '30分鐘', '2人'),
(36841, '【Norma X 陳爽】- 二人世界花膠扒', '2015-10-23', '', '1.5小時', '2人'),
(36851, '【Norma X 陳爽】- 燕窩南瓜粥', '2015-10-23', '', '1.5小時', '2人'),
(36861, '【Norma X 鍾舒漫 】- 鮮茄牛筋腩', '2015-10-23', '', '1.5小時', '2人'),
(36871, '【Norma X 鍾舒漫 】- 味噌煎銀鱈魚', '2015-10-23', '', '30分鐘', '1人'),
(36881, '【Norma X 泳兒】－ 家庭版越南牛河', '2015-10-23', '', '1.5小時', '1人'),
(36891, '【Norma X 泳兒 】 － 香檳酒法國青口', '2015-10-23', '', '30分鐘', '2人'),
(36901, '熱狗鬆餅', '2015-10-23', '花一點心思，讓鬆餅華麗變身！熱狗和鬆餅的結合絕對是你想不到的野餐美味哦！', '20分鐘', '2人'),
(36911, '香煎鱈魚配牛油芥末汁', '2015-10-26', '鱈魚扒是方便又滋味的食材，白鱈魚扒肉色雪白，肉質嫩滑，不想吃肉的日子，煎一塊鱈魚扒，配搭微酸微辛的牛油芥末汁，口感清爽又飽肚', '20分鐘', '2人'),
(36921, '丹麥蝦肉單片三文治', '2015-10-26', '從小認知的三文治都是兩片麵包中間夾著餡料，長大了就知道三文治也千變萬化，Open Sandwich單片三文治不單是純粹醫肚的食物，豐富的餡料排列在單片麵包上，兼具視覺享受。', '20分鐘', '2人'),
(36931, '蟹腳肉涼拌雙色瓜', '2015-10-26', '皇帝蟹有「蟹中之王」的稱號，體型龐大，肉質鮮味亦有別於其他螃蟹，蟹腳是皇帝蟹最飽滿的部份，肉質彈牙結實，這次用來做涼拌菜式，配搭青瓜和木瓜的清甜味，為海鮮大餐揭開序幕。', '10分鐘', '2人'),
(36941, '焗挪威三文魚伴蔬菜薯蓉', '2015-10-26', '提到北歐美食，一定有挪威三文魚的份兒，因為挪威是三文魚的出口大國，味美的三文魚煮法多變，三文魚肉厚，先煎一煎再放入焗爐焗熟是最受歡迎的煮法，伴以炒蔬菜及薯蓉，滿嘴都是挪威風味。', '30分鐘', ''),
(36951, '北歐海鮮忌廉湯', '2015-10-26', '北歐海鮮種類繁多，哪一道菜可以把海鮮鮮味一網打盡？來個北歐海鮮忌廉湯吧！海鮮可按你個人口味選擇，配以蔬菜的清甜和忌廉的香滑，加上滿滿的海鮮材料，怎能不滿足？', '20分鐘', ''),
(36961, '檸香煙三文魚意粉沙律', '2015-10-26', '三文魚新鮮吃固然美味，經煙燻加工過後的煙三文魚又是另一種滋味，既可配搭三文治、沙律、意粉等等，是方便又好用的食材！這次配搭檸檬調味，讓意粉沙律有更清新的感覺。', '10分鐘', '2人'),
(36971, '蔬菜蛋卷', '2015-10-28', '', '30分鐘', ''),
(36981, '蒜香橄欖油意粉', '2015-10-28', '吃甚麼東西可以令愛情升溫？不一定要紅酒、朱古力、生蠔這些典型具催情成份的食材，簡單如蒜頭也可以的，這次就用它來教大家煮一個非常簡單又經典的蒜香橄欖油意粉，簡單快捷又美味。', '30分鐘', '2人'),
(36991, '印度難得意粉', '2016-09-07', '藝術與下廚看似沒有甚麼關係，但對於多媒體設計師 Sam Chan 而言，兩者卻有著不少相似的地方。身為 Outsign Lab 的創辦人，Sam 非常注重創作上的新嘗試；在家，他是一位注重溝通並十分好客的丈夫及爸爸，常常邀請一大班朋友在家聚餐聊天，笑談身邊所發生的大小事。\r\n\r\n按此了解更多 Sam Chan 的廚房故事', '30分鐘', ''),
(37011, '鬼馬芝心多士', '2015-10-30', '日日煮哪有那麼多創意？其實創意就在生活細節裡，烘一件多士很簡單，但從造型方面改變一下，變成有趣的形狀圖案，就可以令多士更有生氣了。', '20分鐘', '2人'),
(37021, '芋蓉泡菜香酥鴨', '2015-10-30', '芋頭與鴨肉可謂是天生絕配，煮熟後綿軟的芋頭蓉配搭鴨肉的微微酥香，炸至酥脆，夾在中間的微酸泡菜中和一下油膩感，未放入口已香氣四溢。', '30分鐘', '2人'),
(37031, '紅酒燉羊膝', '2015-10-30', '紅酒燉羊膝是經典的法國菜，在高級餐廳裡品嚐，美食和上美景當然情調怡人，這道菜自己煮的話亦沒有想像中的難，羊肉更是冬天不可多得的滋補美食。', '1.5小時', '2人'),
(37041, '酥炸黑椒洋蔥花', '2015-10-30', '如果你有去過香港一間著名澳洲扒房，應該吃過它們的招牌菜炸洋蔥花，炸好的洋蔥呈現盛放的花瓣狀態，吃這道菜必定要用手！用手指一條一條花瓣抽出來吃最滋味。', '20分鐘', ''),
(37051, '日式燒汁生蠔', '2015-10-30', '生蠔向來被視為催情美食，不少外國人在約會時都有吃生蠔的習慣，自己入廚的話不如炮製不同做法的生蠔美食，例如加上日本燒汁，既惹味又可以帶出生蠔鮮味。', '20分鐘', ''),
(37061, '合桃蘆筍意大利飯', '2016-05-09', '合桃以補腎功能著名，但不一定要來燉湯才見功效，用來煮意大利飯，配搭翠綠爽口的蘆筍，煮一頓清新的晚餐，美味之餘同樣可以吸收到合桃的養份。', '10分鐘', '2人'),
(37071, '蜂蜜芥末焗無骨雞脾', '2016-09-28', '秋冬時份最喜歡用蜂蜜入饌，喜歡吃那份滋潤的甜味，不說不知原來蜂蜜也有催情的功能，甜蜜的滋味由嘴裡甜到心裡去，這道焗無骨雞脾以蜜糖及芥末調味，讓你品嚐甜蜜中帶點刺激的味道。', '30分鐘', '2人'),
(37081, '韭菜豬潤杞子湯', '2015-10-30', '豬潤補血，韭菜補腎，杞子明目又滋潤，冬天來一碗韭菜豬潤杞子湯，不單滋潤腸胃，親手煮一碗熱湯給一半，讓他/她感受到你的體貼和溫暖，冬天不再怕冷了。', '20分鐘', '2人'),
(37091, '咖啡烤豬肋排', '2015-11-02', '當咖啡的香濃遇到豬肋排的鮮嫩會有什麼神奇的化學反應？快看下Norma是如何烹調出這道美味的咖啡料理咖啡烤豬肋骨的吧！', '1.5小時', ''),
(37101, '迷你布丁碗', '2015-11-03', '不是只有順滑Q彈的才叫布丁哦！深受小朋友及女生青睞的布丁搖身一變，以米飯為主要食材，迷你中式布丁也是營養又美味的早餐新寵喔！', '10分鐘', '2人'),
(37111, '培根南瓜意面', '2015-11-03', '秋天天氣比較乾燥，如果你想保持皮膚濕潤的話，那不妨多吃一點含有豐富維生素的南瓜。今天為大家帶來一道味道香甜，簡單健康的培根南瓜意面。', '20分鐘', '1人'),
(37151, '蝦醬豆卜炒豬頸肉', '2015-11-04', '豆卜吸收了惹味的蝦醬，配上肥瘦混雜的豬頸肉，想起都流晒口水！\r\n\r\n<十五分鐘懶人版｜蝦醬豆卜蒸豬頸肉>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：蝦醬豆卜蒸豬頸肉', '30分鐘', '2人'),
(37181, '英式雜莓布甸杯 Trifle', '2015-11-06', '電影Love’s Kitchen原名為No Ordinary Trifle，可想而知Trifle這款英式經典甜品是戲中主角，Trifle這款甜品多用玻璃器皿盛載，蛋糕、忌廉和水果層層相間，品嚐它前先來視覺享受，繼而享受多種食材融合的美妙口感。', '1.5小時', '1人'),
(37191, '黑朱古力慕絲', '2015-11-06', '電影《西洋古董洋菓子店》中，女主角因為品嚐了一口精緻的黑朱古力慕絲而帶來陣陣幸福感，從而開始她甜品師的生涯，朱古力就是有這股魔力令人著迷，這款黑朱古力幕絲希望也能令你著迷。', '1.5小時', ''),
(37201, '朱古力忌廉批', '2015-11-06', '電影《美味關係》中，主角在生活上遇到不如意的事情，只要下廚就能拋開煩惱。如果你遇上煩惱，試做這款朱古力忌廉批，甜蜜的味道或者也能令你一解煩憂。', '1.5小時', ''),
(37211, '蛋白檸檬撻', '2015-11-06', '電影《知味人生》中，主角愛讀烹飪書及流連不同店舖，媽媽的離世令他傷心不已，當他遇上卜太太的蛋白檸檬撻就牽起一連串故事。蛋白檸檬撻的酸甜清香，莫說是甜品迷，連不怎麼愛甜的人都很受落，自己做的話更可調校自己喜歡的酸甜品。', '1.5小時', '1人'),
(37221, '香濃熱朱古力', '2015-11-06', '電影《濃情巧克力》中，主角在一個小鎮開了間朱古力店，以各種朱古力喚醒居民對幸福追求的慾望。朱古力一直代表著幸福的味道，冬天沖一杯特濃朱古力，試試感受這股幸福感。', '10分鐘', '1人'),
(37231, '法式牛油麵包 Brioche', '2015-11-06', '電影《滋味旅程》中主角廚師Carl因為一次經歷失去大廚之職，轉而開快餐車重拾入廚的熱情。電影當中出現的Brioche是著名的法國麵包款式，需要以大量雞蛋及牛油製作，因為充滿香味，比一般麵包更為可口吸引。', '1.5小時', '1人'),
(37241, '朱古力泡芙塔', '2015-11-06', '電影《布達佩斯大酒店》的夢幻甜品Courtesan au Chocolat給不少人留下深刻印象，是甜品師專門為這齣電影而設計的甜品，由不同大小的泡芙組合而成。泡芙一口一個，加上內裡擠滿甜美的餡料，真是人見人愛。', '1.5小時', ''),
(37251, '花雕蛋白蒸蟹', '2015-11-07', '秋天又是蟹迷出動的時候，當造的不止有大閘蟹，其他蟹也一樣肥美多膏，用蒸的方法來表現蟹的鮮甜味道，簡單配搭花雕酒及蛋白已經很美味。', '30分鐘', '3人'),
(37261, '鴨胗菜乾湯', '2015-11-09', '', '1.5小時', '2人'),
(37271, '迷迭香紅酒小羊排', '2015-11-10', '天氣涼了，許多朋友開始選擇吃羊肉來滋補身體，如果你吃膩了中式的家常羊肉做法，那就來試試今天我們推薦的這道迷迭香紅酒小羊排吧！', '20分鐘', '2人'),
(37281, '南乳燒雞扒配拌泡菜五色沙律 (1人份)', '2016-09-08', '喜歡研究自己食譜的職業插畫師工千芊曾在餐廳吃這味南乳燒雞，但外面所吃到的一般是吊燒雞，略嫌太油膩，所以她決定要在家中做出適合自己口味的南乳燒雞扒！自家製時用上無油炸鍋，沒有了油膩口感之餘，更能去除雞身的多餘油份。而伴在旁邊的拌泡菜五色沙律亦非常健康，運用了五色蔬菜的營養理論，含豐富營養價值。南乳燒雞扒味道較重，拌泡菜五色沙律則為這餸加添了一點清新感，是絕配的味道呢！\r\n\r\n按此了解職業插畫師工千芊的詳細故事', '30分鐘', '1人'),
(37291, '鮮橙蒸蛋', '2015-11-12', '鮮橙，一食兩用的寶貝，我們吃完酸甜的柳丁後，不要把柳丁皮扔掉哦.在這樣美好的清晨，為自己和家人做一道鮮橙蒸蛋吧，淡淡的橙香，嫩滑的雞蛋，迎來橙色生香的一天。濃濃的橙香完全滲入到了蛋羹之中，舀上一口含在嘴裏，立刻覺得滿口生香呐！', '30分鐘', '2人'),
(37331, '藍莓紙杯蛋糕', '2015-11-13', '', '1小時', '2人');
INSERT INTO recipes (id, title, date, description, cooking_time, serving_size) VALUES
(37341, '意式菠菜煎蛋餅', '2015-11-13', '', '30分鐘', '2人'),
(37351, '牛油果吐司', '2015-11-13', '', '10分鐘', '2人'),
(37371, '鱈場蟹腳天婦羅', '2015-11-13', '到日本料理店吃到鱈場蟹腳天婦羅，感覺非常滿足，因為鱈場蟹腳肉質豐厚，吃下去啖啖肉的感覺實在美妙，自己在家煮一樣可以，今個周末不如約朋友來個天婦羅派對，大啖肥美的鱈場蟹腳吧！', '1小時', '2人'),
(37381, '年糕炒蟹', '2015-11-13', '毛蟹炒年糕是著名的上海菜，用濃油赤醬把蟹和年糕都炒得入味可口，自己煮的話不一定用選用毛蟹，到街市看看哪一種蟹新鮮及你喜歡的，今晚就試煮惹味的海鮮菜式吧！', '20分鐘', '2人'),
(37391, '四川香辣蟹', '2016-09-28', '想起四川風味就想到刺激的麻辣風，其中一道香辣蟹因教人魂牽夢縈，因為它結集了香、辣、鮮脆的味道，這次除了醬料和蟹的鮮味，還加入了薯仔、萵筍和鮮淮山，小編覺得這些煮得入味的蔬菜配料更是精華所在呢！', '1小時', '3人'),
(37401, '紫菜蟹粥', '2015-11-13', '蟹粥是其中一種吃蟹的滋味食法，蟹的鮮甜味完全融入於粥裡面，吸啜蟹肉又能吃到米香，加上薑蔥用來提味，還加入了紫菜熬煮，用來做晚餐或宵夜感覺都非常幸福。', '30分鐘', '2人'),
(37411, '啤酒蟹', '2015-11-13', '曾經在越南菜餐廳吃過美味的啤酒蟹，其實用中菜方法烹調也同樣味美！配搭提味的蒜頭、薑和紹興酒，將讓蟹浸沒在啤酒之中，之後再倒入更多啤酒一起燴煮，酒精蒸發掉，餘下是滋味麥香和蟹鮮味。', '1小時', '4人'),
(37421, '韓式辣蟹湯', '2015-11-13', '秋天遊韓國少不了品嚐美味的辣蟹湯，秋蟹肥美，加上鮮甜的蔬菜，配搭韓式泡菜、大豆芽、韓式辣醬的經典韓國菜味道，讓人一吃難忘，簡單配以白飯，就成為豐富的一頓晚餐，你也試試在家烹調這道經典的韓國菜式吧！', '1小時', '2人'),
(37431, '番茄茄子千層麵', '2015-11-16', '', '1小時', '1人'),
(37451, '泰式海鮮粉絲湯', '2015-11-16', '', '30分鐘', '2人'),
(37461, '椰香咖喱炆雞', '2015-11-17', '', '1小時', '2人'),
(37471, '玫瑰蘋果派', '2015-11-17', '秋天是吃蘋果的好季節，蘋果不僅可以直接吃，做成甜品也很美味哦。今天Norma就教大家一道做法非常簡單，造型很漂亮的玫瑰蘋果派。', '30分鐘', '2人'),
(37481, '火腿蛋玫瑰花', '2015-11-19', '', '10分鐘', '2人'),
(37491, '紅燒肉', '2015-11-19', '', '1小時', '3人'),
(37501, '韓式豬肉卷', '2015-11-19', '', '10分鐘', ''),
(37511, '小雞燉蘑菇', '2015-11-20', '小雞燉蘑菇是一道知名的東北菜，東北地區的冬天蔬菜供應不多，於是農家人採摘野生榛蘑用來炆雞，加上吸汁的粉條，濃濃的醬汁味道最好下飯，找不到榛蘑也可以用其它菇菌代替。', '1小時', ''),
(37521, '番茄炆牛肋骨', '2015-11-20', '番茄和牛肉輕易能配搭出好菜式，冬天就最愛用番茄來炆牛肋骨，牛肋骨最適合用來炆煮，因為不用高超的烹調技巧，就能煮得入味又軟腍。番茄的酸甜味道滲入牛肋骨之中，配飯或意粉都一定胃口大開。', '1.5小時', ''),
(37551, '豪氣東北亂燉', '2015-11-20', '第一次接觸東北亂燉這道菜，是在一間賣餃子的東北菜館裡，原來亂燉就是大雜燴的意思，是中國東北的知名菜式，把多種蔬菜、肉類放在一起燴煮，充份表現到東北人豪邁的性格。', '1.5小時', '2人'),
(37571, '栗子紅蘿蔔炆豬手', '2015-11-20', '冬天是栗子當造的時候，除了街頭小食炒栗子，炆栗子的菜式亦很受歡迎，這次用來炆搭充滿骨膠原的豬手，加上紅蘿蔔的甜味，又是一道美味的下飯菜式。', '1.5小時', '2人'),
(37581, '海鮮一品鍋', '2015-11-20', '冬天的炆燉菜式，食材選擇也不只限於蔬菜和肉類，其實海鮮也可以用快炆的方式，煮出濃郁的冬日味道，煮出來的湯汁更是散發著濃濃海鮮香味，短短時間就能煮出一道色香味俱全的菜式。', '1.5小時', '2人'),
(37591, '足料雜蔬XO醬炒烏冬面', '2015-11-23', '冬天為了儲存能量抵抗寒冷，很多朋友都會食欲大增，這樣肥胖難免找上身來。而且容易讓體內堆積毒素，導致精神不振。這時候低卡健康的排毒瘦身餐就必不可少了。今天Norma就跟我們分享了她的排毒瘦身秘笈，雜蔬XO醬炒烏冬和蜂蜜柚子茶，讓你在這個冬天既可以吃的滿足，又能減輕身體負擔，美麗輕鬆過冬天！', '30分鐘', '2人'),
(37611, '韓式泡菜餅', '2015-11-24', '白菜是秋冬季節首選的蔬菜，不僅味道鮮美，營養也很豐富，不少朋友也對韓劇中經常出現的辣白菜很感興趣。那今天就教大家一道做法十分簡單的韓式泡菜餅。', '30分鐘', '2人'),
(37632, '芝心牛油果火腿多士', '2016-05-11', '平日趕返工，在外面買到的三文治不外乎腿蛋治、餐蛋治，同樣是三文治，自己準備的會更健康亦更多元化，在腿蛋治的基礎上加上鮮打牛油果蓉，滋味立即升級。', '10分鐘', '1人'),
(37634, '早晨粟米粉班戟', '2016-04-11', '早餐一般都有澱粉質食物，讓我們有飽足感之餘，亦為身體提供所需能量，班戟是其中一款熱門選擇，自己做的話也不困難，享用時配搭水果、乳酪、蜜糖等等就更美味了。', '10分鐘', '2人'),
(37635, '極速七彩多士薄餅', '2015-05-11', '想自己在家做薄餅的話，工序頗繁複，最困難是薄餅麵糰部份，想做簡易版的話不如用白麵包取代，加上五顏六色的食材配搭，七彩多士薄餅可以極速完成。', '10分鐘', '2人'),
(37636, '美白奇異果杏仁燕麥粥', '2016-05-11', '講究健康的話，燕麥是早餐的最佳選擇，如果早上趕著上班連煮燕麥的時間都沒有的話，不如抽晚上的時間預早準備吧！前一晚把做好把它放在雪櫃冷藏，早上起來加入新鮮水果就可以了，奇異果和杏仁都有美白作用，美味同時美肌。', '10分鐘', '2人'),
(37637, '醒神煙肉蘑菇奄列', '2015-11-30', '蛋是早餐必不可少的食材，除了簡單的煎蛋、炒蛋，看看你雪櫃裡有甚麼食材，不如煮個豐富的奄列吧！金黃的雞蛋加上色彩繽紛的餡料，為你的早晨帶來活力。', '10分鐘', '1人'),
(37638, '元氣番茄蝦仁烏冬', '2015-11-30', '不同人對早餐的口味各異，有人覺得一定要熱食才舒服，不如來一碗簡易烏冬吧！加入番茄、大蝦、蘑菇等食材營養十足的，亦為湯底帶來鮮甜味。', '20分鐘', '1人'),
(37639, '日式味噌蘿蔔', '2016-10-21', '日式味噌蘿蔔', '1小時', ''),
(37640, '濃香炆羊肋骨', '2015-12-07', '羊肋骨位置肥瘦相間，肉嫩而羶味較輕，是初嚐羊肉人士的最佳選擇，用多種中式香料炆煮的羊肋骨，做法簡單，煮出來的濃香味道卻讓你欲罷不能。', '20分鐘', ''),
(37642, '雙冬炆羊腩', '2016-10-21', '羊腩煲是冬天必吃的暖身菜式，這次不加入常見的枝竹、馬蹄，換上「雙冬」即鮮冬菇和冬筍去炆煮，別有一番風味。鮮冬菇高纖低脂，而冬筍含多種維生素及豐富纖維素，可以平衡一下羊腩的油膩感。', '30分鐘', ''),
(37644, '冬瓜紅棗羊肉湯', '2015-12-07', '冬天除了吃羊腩煲，羊肉湯也是不可少的暖身之寶，暖暖一口喝下去，立即暖遍全身。大家都知道羊肉滋潤暖身，但同時亦比較燥熱，配搭屬性寒涼的冬瓜即能互補不足。', '30分鐘', '2人'),
(37645, '泰式紅咖喱羊肉', '2015-12-07', '除了中式的羊腩煲、西式的煎焗羊扒煮法，加入咖喱去炆的泰式煮法也是冬日的暖笠笠之選，味道微辣的咖喱滲入羊肉中，令人胃口大開，炆煮時記得多加一些洋蔥、薯仔等配菜，非常下飯。', '1.5小時', '2人'),
(37646, '迷迭香焗羊扒', '2015-12-07', '吃羊肉的西式煮法，焗羊扒是經典菜式之一，而迷迭香是必不可少的香草配搭，簡單配搭薯仔和蔬菜，就可以與情人撐枱腳，配一杯紅酒，慢慢享用一頓冬日的浪漫晚餐吧！', '1小時', ''),
(37647, '西西里香橙蛋糕', '2016-10-21', '柳丁的維生素C含量很高，是冬天非常健康的水果，清新香甜的味道也讓它深受烘焙愛好者的喜愛。今天就帶給大家一道可愛溫暖的西西里柳丁蛋糕。', '20分鐘', '1人'),
(37648, '牛肉蒸釀白蘿蔔', '2015-12-14', '牛肉與白蘿蔔的配搭最常見於炆牛腩，如果沒有太多時間炮製炆煮菜式，不如試試蒸釀的方法，不但造型美觀，味道亦鮮香，牛肉醃料更可按個人喜好再加入馬蹄等材料豐富口感。', '1小時', ''),
(37649, '白蘿蔔大蔥炆排骨', '2015-12-15', '炆肉類菜式時最喜歡加入吸汁的白蘿蔔，白蘿蔔既釋放自身的鮮甜味，又能吸入醬汁的濃郁味道。這次加入大量薑、蒜、八角、桂皮等辛香料，令排骨味道更為惹味。', '1小時', '2人'),
(37650, '茄汁白蘿蔔丸子', '2016-10-21', '蘿蔔要不是炆就是煮，有沒有想過可以做到像肉丸的效果？這道白蘿蔔丸子適合吃素菜的人，蘿蔔絲混合雞蛋、麵粉等材料，炸起來外表就像肉丸一樣，加上酸酸甜甜的茄汁，更加開胃。', '30分鐘', ''),
(37651, '白蘿蔔瑤柱甫', '2016-11-01', '瑤柱甫一般配節瓜烹調，但其實其它蔬菜也可以，就試試冬天當造的白蘿蔔吧！清甜的白蘿蔔吸收了瑤柱的鮮味，令整道菜味道清甜可口，而且賣相得體，用來宴客也不失禮呢！', '30分鐘', '2人'),
(37652, '白蘿蔔鯽魚湯', '2016-10-21', '鯽魚含豐富蛋白質，而白蘿蔔含豐富礦物質、維他命C等營養，兩者配搭起來煮湯，有補水養顏的功效，而且魚鮮加上蘿蔔的甜味，令湯清甜可口，冬天記得多喝兩碗呢。', '30分鐘', ''),
(37653, '韓式蘿蔔泡菜', '2016-10-21', '看韓國電視劇集，韓國人吃飯的桌上少不了幾碟泡菜，泡菜種類繁多，除了普遍的大白菜泡菜，蘿蔔泡菜也是很常見的選擇，趁著冬天白蘿蔔當造，就買來醃蘿蔔泡菜吧！做法不難，只要醃製1-2天，就有美味的蘿蔔泡菜享用了。', '1小時', ''),
(37654, '香煎蘿蔔絲餡餅', '2016-10-21', '冬天當造的白蘿蔔，皮薄肉嫩多汁，用來做餡餅的材料，蘿蔔鮮甜多汁，再配搭適量的免治豬肉、薑、蔥等材料，令鮮味更為豐富。這個餡餅用煎的做法，不油膩而做到餅皮酥脆效果，用來做早餐或下午茶都很適合。', '20分鐘', ''),
(37655, '蜂蜜芝士烤紅薯', '2016-10-21', '冬天很多人都喜歡吃上一份暖暖的烤紅薯，為了讓紅薯吃起來更甜蜜香濃，今天就和大家分享一個獨特的蜂蜜芝士烤紅薯。', '1小時', '2人'),
(37656, '零失敗小雞蛋糕', '2016-02-11', '零失敗小雞蛋糕', '30分鐘', '3人'),
(37657, '聖誕樹頭蛋糕', '2016-10-21', '樹頭蛋糕可說是聖誕甜品的代表之一，法國人在20世紀中葉有個傳統，在聖誕節前12日選一條大木頭放在壁爐燒燒至聖誕當天，寓意來年豐收，後來變成美味的聖誕甜點。', '30分鐘', '2人'),
(37658, '聖誕紅帽芝士蛋糕', '2016-10-21', '芝士味香濃又軟滑的芝士蛋糕有誰不愛？來到聖誕，花點心思將芝士蛋糕變身，切成小正方形，加上士多啤梨作帽，化身成一個個可愛的聖誕紅帽小精靈！聖誕派對準備這道甜點，小朋友一定很開心呢！', '1.5小時', '2人'),
(37659, '立體雪人核桃曲奇', '2016-10-21', '除了聖誕老人，雪人是另一個聖誕代表性公仔，利用圓形的核桃曲奇，砌成栩栩如生的雪人曲奇，既甜美又可愛，今年的聖誕派對絕不能少得它。', '1.5小時', '2人'),
(37660, '聖誕星星肉桂曲奇', '2016-10-21', '聖誕燈飾星光閃爍，在家也可以做到，將肉桂曲奇造成星星形狀，讓你的餐桌充滿星光，甚至用來做聖誕樹裝飾，更添節日氣氛。', '30分鐘', '2人'),
(37663, '三色松露朱古力', '2016-10-21', '松露朱古力因為外形像剛被挖出的松露相像而命名，自己製作難度不高，還可以添加你喜歡的裝飾食材口味，用黑朱古力製作味道苦中帶甜，齒頰留香。', '30分鐘', ''),
(37664, '簡易聖誕烤雞', '2016-10-21', '耶誕節就要到了，餐桌上當然需要一只烤雞才更有聖誕的氣氛。火雞在國內比較難買到，所以今天我們就用三黃雞做一道簡單美味的簡易聖誕烤雞。', '1小時', ''),
(37665, '奶油紙杯蛋糕', '2016-10-21', '雞蛋 250克\r\n糖 170克\r\n鹽 0.5克\r\n低筋粉 197克 \r\n玉米澱粉 60克\r\n黃油 170克\r\n泡打粉 6克\r\n甜奶油 30毫升\r\n糖珠 適量', '30分鐘', '1人'),
(37666, '煎和牛扒配三式汁', '2016-10-21', '在家煎牛扒，每次都是配薯菜？如何能加點新意呢？今次不妨從醬汁方面入手，自製三款簡單易做卻有特色的醬汁，這樣一塊和牛扒就可以吃出三種味道。', '1小時', '1人'),
(37667, '黑松露蜜糖排骨', '2016-10-21', '黑松露醬只適宜煮西餐？未必！用來煮中式排骨也可以，黑松露醬再加上蜜糖、黑醋的配合，滋味度倍增。', '1小時', '1人'),
(37668, '英倫風情早餐', '2015-12-30', '英國人很重視早餐，認為早餐是一天中最重要的一頓飯。傳統英式早餐因其菜點豐富而享負盛名，為英國人所驕傲。而各種英式早餐中，焗豆、番茄、薯仔、香腸、雞蛋和英式紅茶是最必不可少的。假日的早晨，和你的另一半一起享受一個豐富而完美的早晨，給早餐來點花樣，做個英式早餐吧！', '30分鐘', ''),
(37669, '照燒汁三文魚', '2016-10-21', '簡單、有營養又下飯的一道菜，啖啖肉的三文魚柳配以照燒汁份外惹味，如果用現成照燒汁，更可以縮短烹調時間。', '1小時', '2人'),
(37670, '香薯雞翅鍋', '2016-02-06', '雞翅的神奇在於N種不同的烹調技術都無法掩蓋它百搭美味的本質屬性。薯條配雞翅的肯德基經典招牌搖身一變，以中式醃制及大火烹調的方式，賦予薯條及雞翅鹹香糯軟入口即化的口感。如果你的Ta也是一枚雞翅薯條控，這次就呈上一道顛覆性的美味吧！', '30分鐘', '3人'),
(37671, '百香果蟹肉塔', '2016-10-21', '百香果也叫做愛情果。相信用百香果做出來的料理，應該是一份最有味道的告白吧！濃郁的水果香味加上新鮮的蟹肉，一定會讓這一餐表達出你的愛意。', '30分鐘', '2人'),
(37672, '士多啤梨忌廉可麗餅', '2016-07-07', '可麗餅(Crepes)是源起於法國布列塔尼省(Brittany)，據說可麗餅是布列塔尼居民的救命糧食，因為布列塔尼是個石頭城鎮，幾乎是寸草不生、貧瘠荒蕪，有一年遇到饑荒島上沒有任何食物，布列塔尼人只好將收藏在地窖的麵粉拿出來，烤成薄薄的煎餅解決了那年的饑荒的困頓，後來這薄薄煎餅成了當地的主食，如今卻成為布列塔尼最具代表性的特色美食。士多啤梨忌廉可麗餅是人氣口味，酸甜鮮紅的士多啤梨搭配忌廉可麗餅，好吃又養眼。', '20分鐘', ''),
(37673, '暖心海派羅宋湯', '2015-12-30', '寒冷的冬天喝上一碗暖暖的湯最好不過了。今天推薦一道最適合冬天喝的海派羅宋湯，裏面有很多營養的食材，牛肉也能幫我們禦寒哦。', '1小時', '2人'),
(37674, '戚風蛋糕', '2016-02-20', '戚風是個音譯詞，Chiffon字意指一種質料輕柔的雪紡薄紗，戚風蛋糕因質感輕柔綿軟，因此而得名。戚風蛋糕香味濃郁，吃起來香甜不膩，鬆軟有彈性，是平時休閒小零食的良好選擇。', '30分鐘', '3人'),
(37675, '紅棗黃豆豬手湯', '2016-01-04', '豬手湯向來都被視為美顏湯水，因為豬手含豐富骨膠原，能養顏並且增加肌膚的彈性，再加上含豐富蛋白質的黃豆，以及有補氣養血作用的紅棗，女士們多喝一碗吧！', '1.5小時', '2人'),
(37676, '黃芪烏雞湯', '2016-10-21', '烏雞又名竹絲雞，相比普通雞，烏雞入饌更具滋補作用，適合體質較弱的人士進補之用；黃芪則能增強身體免疫能力；這款湯做法簡單而有補氣補血之效。', '1.5小時', ''),
(37677, '蟲草花淮山杞子雞湯', '2016-01-06', '蟲草花是近年流行的保健食材，是人工培植的菌類，可以補肺、益腎、養肝，增強人體免疫功能，提高抗病能力，而且價錢相宜，用來配搭淮山杞子煲雞湯可以增強體質。\r\n\r\n<十五分鐘懶人版｜花膠紅棗杞子雞湯>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：花膠紅棗杞子雞湯', '1.5小時', ''),
(37678, '沙參玉竹雪耳豬腱湯', '2016-10-21', '沙參、玉竹是很常用來煲湯的材料，而且經常一起出現，沙參養胃生津，玉竹養陰潤燥，再配搭滋潤的雪耳，最適合於秋冬乾燥天氣享用。', '1.5小時', '2人'),
(37679, '山藥栗子排骨湯', '2016-10-21', '山藥是一種很有益的食材，甚至有「神仙之藥」之稱，它含豐富維他命有助皮膚美白，亦有健脾之效調節身體抵抗力，加上有補腎功效的栗子，這鍋湯不但令你冬天裡添暖意，多喝亦有益健康。', '1.5小時', ''),
(37680, '蘋果百合雞湯', '2016-01-09', '百合是適合秋冬天享用的滋潤養生食材，配合清甜的蘋果煲湯效果就更顯著，蘋果有生津潤肺、健脾開胃的作用，加上雞的鮮味就更可口了。', '1.5小時', ''),
(37681, '當歸杞子鯽魚湯', '2016-01-10', '當歸具補血活血的作用，杞子則有延緩衰老、調節血脂的功效，配搭含豐富蛋白質的鯽魚，這款湯尤其適合女士飲用。', '1小時', '2人'),
(37682, '白菜菜乾豬腱湯', '2016-10-21', '冬天有甚麼比在吃飯時喝碗熱湯溫暖呢？廣東人煲湯有不少種類和款式，不同湯水有不同功效，今次示範的白菜菜乾豬展湯，可以清熱潤肺，補脾健胃，多喝湯水，皮膚都水潤一點！', '1.5小時', ''),
(37683, '芝士焗年糕', '2016-10-21', '新年吃年糕是傳統習俗，年糕寓意我們的工作和學習一年比一年提高，今天介紹的是中西結合的菜式，讓大家吃年糕吃出披薩味。', '30分鐘', '2人'),
(37684, '脆炸薯片雞米花', '2016-04-05', '如果妳喜歡炸雞，那就千萬不能錯過這期節目。超簡單的自制DIY薯片雞米花，雞肉和薯片在一起碰撞出美味驚喜。一塊雞胸肉兩用，不僅能做雞米花小食，還可以制作美味雞肉漢堡哦！', '30分鐘', '1人'),
(37685, '番茄帶子煮豆腐', '2016-01-11', '一個人自煮晚餐想食得簡單有營？試試番茄帶子煮豆腐吧！帶子是簡單易處理又營養價值高的海鮮，豆腐更不用多說是健康的食材，配搭番茄酸甜的味道，這裡菜式健康、美味又下飯。', '20分鐘', ''),
(37688, '蘆筍鮮蝦豬肉卷', '2016-02-11', '簡單煮一碟菜做晚餐，也不一定要隨便將材料炒在一起就算的，簡單晚餐也可以做得精緻一點，那麼吃起來心情也愉快一點！這款蘆筍鮮蝦豬肉卷，將爽脆的蝦肉蘆筍用豬肉包起來，一啖可以吃到多種口感，給味蕾大滿足。\r\n\r\n<十五分鐘懶人版｜黑松露蘆筍豬肉卷>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：黑松露蘆筍豬肉卷', '20分鐘', '2人'),
(37689, '香辣牛肉炒西芹', '2016-01-15', '想簡單炒個菜送飯？西芹炒牛肉是很家常又營養均衡的選擇，牛肉含豐富鐵質、蛋白質，可預防貧血及加速新陳代謝；西芹含維他命、鉀質及鈣質，能促進血液循環及消除疲勞，喜歡爽口質感的話，加入西芹後快炒一會就可以上碟了。', '20分鐘', '2人'),
(37690, '惹味肉碎炒薯條', '2016-02-11', '一講到薯仔就覺得它含大量澱粉質容易致肥，其實只要控制油份得宜，它是非常有益的食材，其營養成份具美容和抗衰老功能，還可增強體質及記憶力，今晚就煮一道惹味的肉碎炒薯條吧！', '20分鐘', ''),
(37691, '杏鮑菇蘆筍炒雞丁', '2016-02-23', '杏鮑菇因為質感有點像鮑魚而得名，這種低熱量、高纖維的食材用來炒很方便，配搭爽脆的蘆筍和嫩滑的雞丁，輕輕鬆鬆就炒出一道色香味俱全的小菜了。\r\n\r\n<十五分鐘懶人版｜醋香酸辣雞丁>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：醋香酸辣雞丁', '20分鐘', ''),
(37692, '芋頭西芹炒肉丁', '2016-01-12', '香港人生活節奏忙碌，晚餐經常出外吃，多吃會悶之餘亦不健康，其實自己在家煮些簡單菜式，有營養又合自己胃口，就像這道芋頭西芹炒肉丁，配一碗白飯就是完美的一餐了。\r\n\r\n<十五分鐘懶人版｜XO醬西芹腰果炒肉丁>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：XO醬西芹腰果炒肉丁', '20分鐘', ''),
(37694, '金槍魚夾心餅乾', '2016-01-14', '可愛小巧的外形，加入土豆、胡蘿蔔、等食材，既營養又美味，讓你在家可以自己做出不一样夾心餅乾的美味，是平時零食的美味選擇哦。', '10分鐘', ''),
(37695, '鹹味臘八粥', '2016-01-15', '臘八是中國的傳統節氣，在這一天家家戶戶都會吃一款臘八粥，為了教育年輕人節約，中國的古人在打掃廚房的時候都會用家裏剩下的雜糧和蔬菜放在一起煮成臘八粥，所以臘八粥不得不說是一款不經意得到的美味哦。', '30分鐘', '2人'),
(37696, '糖醋鮮蔬紹菜卷', '2016-01-24', '原產自中國的大白菜，香港人稱之為紹菜、黃芽白，由於耐放易儲存，特別受冬天寒冷的北方人歡迎。紹菜含豐富維他命C、鉀、鎂等營養素，具養顏美容、消除身體浮腫，其纖維又可促進腸胃蠕動。這次配搭一款輕盈的糖醋汁，全素材料令人吃得更健康。\r\n\r\n<十五分鐘懶人版｜糖醋豬腩卷>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：糖醋豬腩卷', '30分鐘', ''),
(37697, '蜂蜜檸檬豬肋骨', '2016-03-28', '蜂蜜含有大量氨基酸及維他命，極具美容護膚的作用；而檸檬含有大量維他命C，可促進新陳代謝及增強免疫力，用這兩種材料來為排骨調味，酸甜開胃。\r\n\r\n<十五分鐘懶人版｜綜合香草焗豬肋骨>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：綜合香草焗豬肋骨', '1小時', ''),
(37698, '黑木耳萵筍炒鮮淮山', '2016-02-08', '鮮淮山又名山藥，製乾的常用來煲湯，而新鮮的用來入饌亦非常有益健康，因為它滑潺潺的黏液蛋白能夠滋潤皮膚，其豐富纖維素幫助腸胃蠕動。配搭黑木耳及萵筍同炒，令菜式更色香味俱全。\r\n\r\n<十五分鐘懶人版｜味增雜菜煲>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：味增雜菜煲', '30分鐘', ''),
(37699, '香辣蓑衣青瓜', '2016-10-21', '眾多蔬菜之中，青瓜是含水量最高的蔬果，高達約97%，用來敷臉有美容功效，用來吃就更加可以養顏美肌，因為青瓜含豐富維他命C，可預防黑色素沉澱令你更美白，維他命E則能保持肌膚青春有活力，今晚就試做這款做法有趣的蓑衣青瓜吧！', '20分鐘', ''),
(37700, '冬瓜薏米鯽魚湯', '2016-01-21', '冬瓜含大量水份及豐富維他命C，可以給肌膚飲飽水之餘，還可以令皮膚更有彈性；含有蛋白質及氨基酸的薏米亦有強大美白功效，配合鯽魚熬製成鮮味魚湯，貪靚的你一定不能錯過。', '1小時', ''),
(37701, '鮮百合絲瓜炒雞片', '2016-01-22', '爽脆的鮮百合含有不少維他命及黏液質，對皮膚細胞更新甚有幫助；絲瓜亦是美容聖品，它含防止皮膚老化的維他命B；兩種食材配搭健康的雞胸肉同炒，健康有益。', '30分鐘', ''),
(37702, '木瓜蘋果雪耳豬骨湯', '2016-01-23', '木瓜除了豐胸效果，其美容功效亦不容忽視，它的營養素具有抗氧化功能，而且木瓜酶有助排毒。配搭蘋果、雪耳及鮮百合這些滋潤食材一起熬湯，讓湯味道更香甜之外，亦更具美容功效。', '1.5小時', ''),
(37703, '海鮮兩面黃', '2016-10-21', '冬天天氣乾燥，只是在表面塗抹潤膚霜治標不治本，不妨從飲食著手，多選擇有補水功能的食材入饌，例如這道海鮮兩面黃，加入了紅蘿蔔、芹菜，補水之餘還增加食用纖維。', '1小時', '1人'),
(37704, '暖心羊肉濃湯', '2016-10-21', '轉眼就是一年中最冷的節氣大寒了，什麼食材最適合用來抵禦嚴寒呢？羊肉當然是最好的選擇，今天Norma就和大家分享一款暖心冬日靚湯——暖心羊肉濃湯，一起做起來吧。', '1小時', '2人'),
(37705, '岩鹽芝士奶蓋奶茶', '2016-03-18', '岩鹽芝士奶茶，做法獨特，聞起來飄香四溢，加入全脂牛奶和奶油、紅茶包、鹽等食材，融合鹽淡淡的鹹味，牛奶的絲滑，使奶茶喝起來口感更加的絲滑，回味香甜，卻甜而不膩。', '10分鐘', '1人'),
(37706, '秘製川味麻辣雞', '2017-01-30', '無雞不成宴，吃農曆新年飯又怎能沒有雞的份兒？除了常吃的白切雞、蔥油雞，今年試做惹味的四川風味麻辣雞吧，紅噹噹的顏色更配合賀年氣氛。', '30分鐘', ''),
(37707, '紅燒鱸魚', '2016-01-27', '每到新年都會祝賀別人「年年有餘」，吃賀年飯當然不能缺少魚，趁著冬季的鱸魚特別肥美，魚肉鮮嫩可口，就用煮鱸魚最常用的煮法——紅燒來炮製，令它更入味可口。', '1小時', ''),
(37708, '金元寶蛋角湯', '2016-01-31', '不少人新年都喜歡自製蛋角(上海人稱之為蛋餃)，因為漲卜卜的蛋餃外形就像金元寶一樣，意頭好之餘亦合一家大小的口胃。蛋角可預先做起一批放入雪櫃冷藏，想吃的時候取出加入其它材料一起煮，隨時都嚐到新年的味道。', '30分鐘', ''),
(37709, '酸菜粉條炆排骨', '2016-10-21', '酸菜燉排骨是很有東北地區特色的菜餚，一鍋熱氣騰騰的酸菜燉排骨在寒冷的春節裡更顯得珍貴，酸菜的酸香令排骨肉質更腍滑，配以吸汁的粉條同煮，非常下飯吧！', '1小時', ''),
(37710, '團年圓蹄', '2017-01-26', '圓蹄是上海、湖南等地方必備的賀年菜，因為圓蹄有團團圓圓的意思，加上賣相色澤紅潤油亮，一端上枱必成為晚餐的焦點！要將一大隻圓蹄煮得入味軟腍要花一點時間，但當你將皮滑肉腍的圓蹄放進口中時，就覺得所以時間是值得的。', '1.5小時', ''),
(37711, '山西過油肉 (蒜芯木耳炒豬柳肉)', '2016-10-21', '過油肉是山西地區的特色菜餚，先將豬肉油炸至金黃色，再配以蒜芯、木耳等材料去炒，配以黑醋為主的調味料，鹹鮮中帶點酸醋香。', '30分鐘', ''),
(37712, '蒜苗炒臘肉', '2016-10-21', '不少人都會買臘肉過年，尤其四川重慶等地，甚至有人保留醃臘肉送禮自用的傳統，醃至鹹鮮味十足的臘肉簡單配蔬菜一起炒，不用調味已經很好吃。', '30分鐘', ''),
(37713, '冬瓜蝦膠卷', '2017-01-29', '每逢農曆新年與家人在家吃團年飯感覺最溫暖，今次示範煮一道健康又賣相得體的賀年菜，用冬瓜、蝦配搭冬菇、紅蘿蔔，全都是低脂肪、高蛋白質及纖維的食材，那就不會在新年吃膩了。', '30分鐘', '3人'),
(37714, '蒜烤芝士薯角', '2016-10-21', '土豆含有豐富的維生素C和優質的澱粉，常常被做成美味可口的薯片和薯條，可是炸過的土豆太油膩，今天Norma和大家分享一款用烤箱做出的創意芝士薯角，降低油膩，香味濃郁，美味又健康。', '30分鐘', ''),
(37715, '簡易韓式年糕', '2016-01-28', '對於韓劇迷的姑娘們，看著韓劇裏的美食有沒有流口水呢，今天我們做的韓式芝士炒年糕，加入魚餅，胡蘿蔔，韓式辣醬，色澤鮮亮，看起來就很有食欲，讓我們在家也能享受到不一樣的韓國美味。', '10分鐘', '1人'),
(37718, '香烤雜菜磨菇串', '2016-10-21', '不少肉食者都覺得吃素很悶，都以為只有菜炒菜，但其實烹調蔬菜也有很多方法，加上配搭不同色彩的蔬菜烹調，視覺效果亦滿足到，這次教大家做的雜菜磨菇串，可挑選你喜歡的蔬菜入饌，30分鐘就輕鬆做出一碟色香味俱全的素菜了。', '30分鐘', ''),
(37720, '蒜香花生炒豆角', '2016-10-21', '一年四季在街市都找到豆角的蹤影，這種蔬菜清洗和烹調方法簡單容易，炒是最常用的煮法，因為可以保持豆角的爽脆感，就算不加入肉類，單以蒜頭、油蔥酥和豆豉醬做主要調味料，已是下飯的一道菜。', '20分鐘', ''),
(37721, '雙色椒炒椰菜仔', '2016-10-21', '椰菜仔(Brussels sprouts)味道帶點苦澀，所以比較不受歡迎，但只要在調味上花點心思，加入白酒、蜂蜜等調味，煮出來的菜式味道也很吸引。而且椰菜仔營養價值高，具防癌功效，多吃有益。', '20分鐘', ''),
(37722, '麻醬蕎麥麵青瓜卷', '2016-04-11', '蕎麥麵是日本料理的代表之一，它含豐富膳食纖維及蛋白質，加上低脂低卡路里，是清淡料理的最佳食材之一。這次我們做得精緻一點，做成一口一個的青瓜卷，用來做派對小食都不錯。', '20分鐘', ''),
(37723, '彩蔬西蘭花', '2017-01-30', '西蘭花包圍著色彩繽紛的粟米粒、燈籠椒粒和西芹粒，是大魚有肉菜式以外的素淨選擇，為餐桌增加一點團圓的氣氛，卻沒有吃肉油膩感的負擔，盡情多吃一點吧！', '20分鐘', '3人'),
(37724, '甜酸玉子豆腐', '2016-02-08', '咕嚕肉是著名的廣東菜式，轉換成素食的話，將豬肉換成玉子豆腐就可以了，煎至金黃色香脆的玉子豆腐，沾滿酸酸甜甜的醬汁，加上燈籠椒和菠蘿的配搭，是一道清新開胃的菜式。', '20分鐘', ''),
(37729, '香菇板栗燉雞', '2016-02-03', '今天Norma和大家分享一款冬季的暖心燉菜——香菇板栗燉雞。香菇有“素中之肉”之稱，是預防冬季疾病的食材之一，板栗含有豐富的維生素Ｃ，雞肉含有豐富的蛋白質，採用燉煮的烹飪方式，保留食材的營養價值，雞肉更加鮮嫩軟滑，板栗更加的香甜，而且更容易消化吸收。', '30分鐘', ''),
(37739, '氣球布丁', '2016-02-05', '在日本人氣爆燈的氣球布丁，進食前將氣球刺穿，圓滾滾的布丁就會走出來，原來自己在家也可以做到！', '10分鐘', ''),
(37741, '抹茶紅豆白玉杯', '2016-10-21', '情人節這個甜蜜的日子少不了甜品的份兒，除了常見的心太軟和焦糖布甸，今年不如試做大熱日式抹茶甜品，把喜歡的材料以層層疊形式排列，單是看賣相已很吸引。', '1小時', '2人'),
(37743, '心形牛扒配芥末薯蓉', '2016-10-21', '情人節給伴侶煮一頓飯，最佳主菜選擇必定是心形牛扒，把你對他/她的心意透過牛扒去表達，更能滿足味覺享受。', '30分鐘', ''),
(37744, '豆沙貓爪湯圓', '2016-02-10', '湯圓來來去去都是圓形白色球狀？未必！加點創意和想像力，就可以變成可愛的貓爪湯圓啊！', '30分鐘', '2人'),
(37747, '白汁巴馬火腿蘆筍螺絲粉', '2016-10-21', '煮情人節大餐，菜式不一定要複雜，但心機就要十足，好像這款意粉，食材看似簡單，但細味之下就感受到自煮意大利白汁的心機和與別不同，對方一定感受到你的心意。', '30分鐘', '2人'),
(37749, '抹茶朱古力湯圓', '2016-02-13', '元宵節少不了湯圓，寓意甜蜜又團圓，吃厭了一般的花生芝麻口味，不如試試創新做法，抹茶配搭朱古力，不少年輕人應該也會搶著吃。', '烹飪時間', '1人'),
(37750, '抹茶千層蛋糕', '2016-04-11', '抹茶因其清新的綠色融合淡淡的茶香俘獲了很多女孩的心，喜歡抹茶口味的人尤其不能錯過這道不需要烤箱的抹茶千層蛋糕，用平底鍋就能煎出的薄薄的抹茶可麗餅，加上濃郁香甜的奶油，每一口都細軟香濃，入口即化。', '1小時', ''),
(37753, '格仔蝦仁蘋果杯', '2016-10-21', '不少瘦身人士都喜歡吃蘋果，尤其青蘋果，含有不少果膠和鉀質，瘦身又具排水作用。這次將青蘋果做寶盒，加入蝦仁焗成蘋果杯，賣相有趣又有益。', '30分鐘', '2人'),
(37754, '香檸焗三文魚', '2016-02-11', '想吃得清淡的話，魚類是很好的主菜選擇，其中三文魚含有大量不飽和脂肪酸，所以被視為健康有營食材。三文魚簡單加調味料烘焗味道已很好好，這次加入檸檬，更可以減低三文魚油脂的油膩感。', '30分鐘', '2人'),
(37755, '西蘭花甘筍薯仔餅', '2016-12-27', '炸薯餅多油又高脂肪，但只要換一換煮法，多加一點有益食材，就可做出一款健康又有營的另類薯餅，用來做正餐或小食都很合適。', '20分鐘', ''),
(37757, '牛油果醬墨西哥薄餅', '2016-10-21', '想吃薄餅但怕肥？可以健康的墨西哥薄餅代替，煎薄餅時亦無下油，中間加入牛油果和車厘茄兩大健康蔬果，車打芝士增添適量的蛋白質和鈣質，美味與健康兼顧。', '30分鐘', '1人'),
(37758, '菠菜醬螺絲粉大蝦沙律', '2016-10-21', '想吃得清淡？沙律是熱門選擇，但要注意選擇沙律醬，一般現成買回來的都含不少脂肪。今次教大家自製菠菜醬，相對低脂之餘又含更多纖維，用來拌意粉成沙律，好味又健康。', '20分鐘', '1人'),
(37759, '馬騮仔曲奇', '2016-10-21', '猴年到，身邊充滿了各種可愛萌猴的元素。作為烘焙愛好者，當然不能錯過這款大聖曲奇了！可愛的猴子造型，配上酥松香脆的口感，無論是自己DIY度過一個童趣的時光還是送給心愛的朋友，都是今年的首選烘焙單品。', '30分鐘', '2人'),
(37761, '南瓜雜糧飯', '2016-10-21', '粗糧中保存了許多細糧中沒有的營養成分。常吃粗糧可以促進腸胃的蠕動，利於營養的吸收。今天就和大家介紹粗糧新做法——南瓜雜糧飯。', '30分鐘', '2人'),
(37767, '一口榛子酥', '2016-10-21', '你最常吃到榛子的時候，是不是正在吃朱古力呢？榛子是很有益的堅果，有「堅果之王」的美譽，具明目健腦、增強記憶的功效。將榛子壓碎加入牛油、麵粉等材料就能焗出酥脆濃香的小吃。', '30分鐘', '2人'),
(37768, '蓮藕合桃腰果湯', '2016-10-21', '一般煲湯都會加豬肉或煲湯骨增加鮮味，如果吃素的話，很常見會下腰果取代肉類，因為果仁含豐富油脂，其香味更可以豐富湯的味道，更能添加不少營養素。這款蓮藕合桃腰果湯清甜鮮味，養顏潤膚。', '1.5小時', '2人'),
(37769, '香煎花生豆腐餅', '2016-02-27', '花生又名長壽果，小小的一顆含有不少營養素，營養不亞於雞蛋、牛奶，其香脆口感更得人喜愛。配搭杏仁與豆腐混合煎香，即成可口又有營養的小食，甚至做送飯的菜式也可以。', '20分鐘', '2人'),
(37770, '楓糖花生扭扭餅乾條', '2016-10-21', '平日做曲奇餅乾常要用到曲奇模造型，如果家中沒有曲奇模的話，亦可以試試這種扭扭餅乾條的做法，將麵糰輕扭就做能造出獨特形狀，楓糖香加上花生香，讓你吃到一口接一口。', '1小時', '1人'),
(37771, '雲朵蛋多士', '2016-05-11', '晨早吃一份有心思的早餐，令全日工作都充滿衝勁，早餐最常用的食材是雞蛋和麵包，這次花點心思，將雞蛋做成雲朵狀，配搭甜美的藍莓醬，做法簡單賣相又漂亮，那就全日都有好心情啦！', '20分鐘', ''),
(37773, '椰汁芒果黑糯米', '2016-03-11', '黑糯米又叫做補血米，因為它含有豐富營養價值，有補氣養血的功效，其黏糯的質感很適合做甜品，做一款椰汁芒果黑糯米，無論冬夏天都適合享用。', '1小時', ''),
(37774, '黑木耳菜脯煎蛋餅', '2016-02-12', '黑木耳是養顏又養生的食材，它具有活血益胃、潤燥滋補的功效，而且有助身體排毒，清掉廢物，令肌膚提升亮麗感覺。煎蛋餅時加入黑木耳和菜脯，帶來雙重爽脆口感。', '30分鐘', ''),
(37775, '紅豆羊羹', '2016-03-11', '羊羮是日本和菓子的其中一種，日本人品茶時必備的甜點，經典的紅豆口味羊羮，用上大量滋補養生的紅豆蓉製作，是最適合女生多吃的甜品。', '1.5小時', '3人'),
(37776, '桶仔荷葉蒸糯米飯', '2016-03-03', '煮食常用到的糯米，其實具有很高的營養價值，它能溫補脾胃，具滋潤、禦寒作用。這款桶仔荷葉蒸糯米飯，讓糯米吸引荷葉香味，最後加上海鮮，令吸引度大增。', '1.5小時', ''),
(37777, '紅棗蓮子雪耳蛋茶', '2016-03-04', '媽媽們愛給女兒煲紅棗水，皆因紅棗有補氣養血的功效，這次在紅棗水中加入養心安神的蓮子和滋陰潤肺的雪耳，令紅棗蛋茶具更多的養生功效。', '1小時', ''),
(37778, '玫瑰蜂蜜薑茶', '2016-03-05', '玫瑰除了漂亮和代表愛情，其食用功效亦不容忽視，因為它有調經止痛、補血氣和美顏護膚的作用，再配搭驅寒的薑和滋潤的蜂蜜沖茶，讓你散發戀愛般的好氣息。', '20分鐘', ''),
(37779, '黑芝麻雪芳蛋糕', '2016-03-06', '黑芝麻小小的一顆，其實是優質鐵質的來源，具有養血、潤燥、烏髮和美容功效，多吃更能打造紅潤好氣色。這款用上黑芝麻粉和黑芝麻醬炮製的雪芳蛋糕，讓你享受濃濃的芝麻香。', '1.5小時', ''),
(37780, '雪頂士多啤梨杯', '2016-08-21', '春天是士多啤梨的收成季，當造士多啤梨又甜又多汁，最適合用來做甜品。這個雪頂士多啤梨杯造型有趣，如何做到啫喱打斜呢？今次就跟你分享這個小秘訣！賣相如此吸引的甜品，做好記得先影相放上網呃Like啊！', '20分鐘', ''),
(37781, '羅漢果燉雪梨', '2016-03-02', '最近天氣忽冷忽熱，不少朋友都有咳嗽的問題。今天Norma就和大家分享又好吃又有止咳功效的——羅漢果燉雪梨。', '1小時', ''),
(37782, '芝士肉丸焗飯', '2016-03-03', '如何快捷方便地做出溫暖香濃的一餐，不妨嘗試一下這道芝士肉丸焗飯。充滿彈性的肉丸混合著濃郁奶香芝士，口感濃香飽滿，每一勺吃到口中，都彌漫著暖暖的幸福感。', '30分鐘', ''),
(37783, '泡菜湯餃子', '2016-03-07', '世界各地菜式中都會找到餃子的踨影，而且每家每戶都有自己的配方，不少人都覺得媽媽包的餃子是最美味的，因此餃子總帶著溫暖的感覺。情人節不想千篇一律給另一半煎牛扒，不如試試包餃子，享受家的溫馨味道。', '1小時', ''),
(37784, '焦糖洋蔥芝士熱狗', '2016-03-08', '問男生們最愛吃甚麼？最快浮現腦海的都是漢堡包、熱狗這些重口味食物，享受啖啖肉的快感。這款焦糖洋蔥芝士熱狗，有香甜的焦糖洋蔥和熱溶的芝士，令平凡的熱狗味道升級。', '30分鐘', ''),
(37785, '流心芝士漢堡扒伴蘑菇汁', '2016-03-09', '大多數男生愛吃肉多於菜，每次想煎牛扒給他吃，但總是掌握不了生熟度？不如試做入門版的漢堡扒吧，把它煎熟就可以了，製作時中間夾入芝士，讓他切開時有驚喜。', '30分鐘', ''),
(37786, '忌廉蘑菇雞湯', '2016-03-10', '湯，無論是中式湯或者西式湯，都給人溫暖窩心的感覺，煮湯不一定是媽媽做的事，給另一半煮湯，既甜蜜又溫馨。這款忌廉蘑菇雞湯，要比罐頭湯好喝一百倍，他/她一定感受到你的心意。', '1小時', ''),
(37787, '咖喱牛肉芝士焗飯', '2016-03-11', '給情人煮一頓飯，有甚麼菜式是零失敗的呢？日式咖喱是其中一個選擇，因為現成咖喱磚味道有一定保證，只要加入適量材料，就可以煮出一碟美味的咖喱飯，這次來個進階版，灑上芝士焗，未吃已令一室充滿咖喱香。', '1小時', ''),
(37788, '芝士肉醬煎蛋飯', '2016-03-12', '數到男生最愛吃的飯，肉醬煎蛋飯應該榜上有名，很多人都喜歡吃這種一隻匙羮就可解決的飯，在白飯上淋上味道濃郁的肉醬，放上芝士，蓋上熱辣辣的煎蛋，多種滋味混和在一起，轉眼就把整碟飯吃光了。', '1小時', '1人'),
(37789, '沙嗲牛肉麵漢堡', '2016-03-13', '沙嗲牛肉麵是港式茶餐廳的代表食物之一，沾滿惹味沙嗲和牛肉的麵條，換個煮法，加上煎至金黃色的太陽蛋，其實可以成為漢堡包餡料！為另一半做這款甚有創意的漢堡包，他一定意想不到吧！', '30分鐘', ''),
(37790, '爪爪雪條', '2016-03-08', '看完《優獸大都會》，想不想來一打激萌的爪爪雪條？新鮮士多啤梨混合紅莓汁，做成可愛爪爪造型，神還原的同時也給你絕對甜蜜好味～！', '1小時', '3人'),
(37798, '免焗抹茶芝士蛋糕杯', '2016-12-26', '芝士蛋糕向來是甜品界的女王，就算是怕胖的女生都忍不住它的香濃芝士誘惑，更何況加入誘人的抹茶味道？想自己做抹茶芝士蛋糕其實不難，這次教大家做一個免焗版，不用焗爐都可以輕鬆做到。', '30分鐘', ''),
(37800, '抹茶紅豆雪糕', '2016-03-15', '「宇治金時」是一款日本傳統刨冰，宇治是指著名出產抹茶的宇治縣，金時是指名為「金時豆」的紅豆，現時這個完美配搭已擴展至任何抹茶紅豆製做的美食，這次教你做抹茶紅豆雪糕的簡易做法，不用雪糕機，只需雪櫃就可以了。', '1小時', '1人'),
(37801, '抹茶窩夫', '2016-03-16', '窩夫又稱鬆餅或華夫餅，配搭雪糕和生果做甜品很受歡迎，窩夫上的格子正好用來盛載更多雪糕。這款抹茶窩夫甜度適中，用來做甜品甚至配搭鹹食成為All day breakfast亦可。', '30分鐘', '1人'),
(37803, '抹茶林明頓', '2016-10-21', '林明頓(Lamington)這種甜品來自澳洲，很常見於各大小咖啡店，一般林明頓都是朱古力口味，這次我們換成抹茶，微微甘苦的抹茶味道配以香甜的蛋糕，最適合配咖啡或茶享用。', '30分鐘', ''),
(37804, '邪惡多士', '2016-03-16', '普通的一片麵包也能化身美味早餐？今天就教你如何5分鐘搞定這款好吃到邪惡的邪惡多士。邪惡多士有多邪惡？4種簡單食材，加上5分鐘，就可以做出味道超犯規的美味多士，因為材料超簡單，所以不少人喜歡做來當早餐，今日買齊材料，明天就試做吧！', '10分鐘', ''),
(37805, '翡翠菜心', '2016-03-16', '', '20分鐘', ''),
(37806, '韓式炸醬麵', '2016-03-17', '韓國人喜歡吃麵，他們有一種黑色醬汁的炸醬麵被喻為國民美食，想自己煮的話，也不一定要特地買韓式炸醬，用甜麵醬都可以的。', '20分鐘', '1人'),
(37808, '抹茶奶凍', '2016-03-18', '屬於甜品界治癒系的甜品抹茶奶凍，質感滑不溜口，微甜加上抹茶香，無論冬夏天都一樣受歡迎。自己做抹茶奶凍其實不難，確保每種材料和步驟攪拌均勻，冷藏足夠時間即可，快來試試看。', '1.5小時', ''),
(37810, '抹茶紫薯銅鑼燒', '2016-03-19', '銅鑼燒又稱為豆沙包，即是哆啦A夢最喜歡吃的點心，是和菓子的一種，用兩片餅皮夾著豆沙餡。這次做的紫薯抹茶口味，無論顏色和味道都比豆沙味更吸引，而且立體造型更有新意呢。', '1小時', ''),
(37812, '抹茶格子曲奇', '2016-03-20', '這裡有抹茶控和格子控嗎？將原味曲奇和抹茶曲奇麵糰結合起來，花少少時間拼成格子狀，曲奇賣相的吸引度立即提升不少，而且同時品嚐到兩種味道。', '1小時', '3人'),
(37813, '芝心蛋多士', '2016-03-21', '雞蛋、芝士、麵包都是早餐常見的配搭食材，如何做到與別不同的組合？試試這款芝心蛋多士吧！將麵包挖洞，雞蛋藏在麵包中，加上熱溶了的芝士餡，一片多士就有多重滋味了。', '10分鐘', '1人'),
(37814, '迷你蘇格蘭蛋', '2016-03-22', '蘇格蘭蛋(Scotch Egg)是英國著名菜式，用香腸肉包裏著雞蛋，這次我們做迷你版，用鵪鶉蛋代替雞蛋，賣相更精緻。', '30分鐘', ''),
(37816, '樽仔蛋早餐', '2016-03-23', '吃All-day breakfast常見的食材配搭有雞蛋、蘑菇、香腸、番茄等等，有沒有想過全部材料用玻璃瓶就可以盛載？這款樽仔蛋早餐可以啊！', '40分鐘', ''),
(37817, '煙肉芝士雲朵蛋', '2016-03-24', '雲朵蛋(Egg in a cloud)是一道見到就叫人心動的早餐小吃，利用蛋白的特性把它打至鬆發，就像白雲的模樣，將它烘成金黃色後，入口就像棉花般輕柔，感覺非常夢幻。', '30分鐘', ''),
(37818, '焗雞蛋南瓜圈', '2016-03-25', '利用食材的形狀特性，配合雞蛋就可以做出有趣的菜式，好像把南瓜打橫切開，挖掉瓜囊，中心部份正好能放入雞蛋一起煮，輕輕鬆鬆就做出漂亮又有營養的早餐。', '1小時', ''),
(37819, '台式腸仔蛋餅', '2016-03-26', '去台灣必吃蛋餅做早餐，餅皮沾上雞蛋煎香再夾進不同餡料，簡單而美味，其實自己製作亦很簡單，這次還教大家自製醬汁，味道吃起來就像台灣的醬油膏，令這蛋餅更具台味。', '30分鐘', ''),
(37820, '焗芝士煙肉薯中蛋', '2016-03-27', '雞蛋和薯仔同樣是煮法變化多端的食材，薯仔除了切片、切粒，亦可以挖空做器皿，就好像這道菜，利用薯仔做器皿，盛載煙肉薯蓉，再加上雞蛋焗香，就成為一道賣相別緻的小吃。', '1小時', ''),
(37821, '朱古力蛋糕棒', '2016-03-22', '甜品控一般都喜歡吃朱古力，這款朱古力蛋糕棒，賣相很吸引，但做法是你意想不到的簡單，開派對或用來做小禮物送給朋友都適合，小朋友見到一定很喜歡。', '20分鐘', ''),
(37822, '香脆鮮菇', '2016-03-23', '菌菇味道鮮美，營養豐富，而且還有抗氧化的作用。所以多吃一點菌菇可以讓我們變美哦。今天Norma就和大家分享一道創意香脆鮮菇，讓你享受全新口感。', '20分鐘', ''),
(37823, '韓式辣雞腳', '2016-03-25', '韓式炸雞配啤酒曾經一度成為飲食潮流，其實要配啤酒還有很多美味的下酒菜選擇，今次推薦一款送酒一流的韓式辣雞腳做法，微辣味道口感勁爽，配啤酒和韓劇簡直一流！', '30分鐘', ''),
(37825, '韓式芝士炸雞', '2016-03-28', '以前提起炸雞就會想到美式連鎖店，現在提起炸雞只會想到韓式炸雞吧！韓式炸雞其中一款最令人著迷的是芝士炸雞，在外脆內嫩的炸雞外裹上一層溶化了的芝士漿，美味到連你的心也能溶化呢！', '30分鐘', ''),
(37826, '提拉米蘇盆栽', '2016-03-28', '飯後甜品竟然是一盆盆栽？看真一點其實是貌似盆栽的Tiramisu，一層一層意大利軟芝士、手指餅、特濃咖啡、Kahlúa咖啡酒味道互相交織，咖啡香醉人。', '1.5小時', ''),
(37827, '芝士肉醬薯條', '2016-03-29', '薯條直接點茄汁吃已經很美味，但當試過更多外國人喜歡的薯條吃法後，就會發現食法其實有很多！其中一種最令人著迷的是加芝士和肉醬烘焗，每條薯條都沾滿美味的肉醬和芝士，小心吃上癮！', '1.5小時', ''),
(37828, '雙重芝心餃子', '2016-03-30', '中式餃子和西式芝士加在一起會產生甚麼效果？就是美味的效果！餃子餡內的車打芝士與豬肉混為一體，餃子皮外的水牛芝士則焗至溶化牽絲，帶來雙重滋味效果！', '1小時', '2人'),
(37829, '芝士釀雞翼配飛魚籽汁', '2016-03-31', '很多朋友都不愛吃有骨的食物，但對雞翼卻沒有免疫能力，如果將雞翼骨也去掉，釀入爽彈的蝦膠和味道濃郁的芝士，相信無論誰都會忍不住口吧！配以酸酸甜甜的飛魚籽汁，你吃過後一定愛上！', '1小時', ''),
(37830, '韓式芝士年糕鍋', '2016-04-01', '到韓國必吃的芝士年糕鍋，做法其實不難，而且可以加入自己喜歡的材料製作，最適合大班朋友一起分享，惹味的芝士辣醬汁最後更可以用來炒飯吃呢！', '20分鐘', '3人'),
(37831, '香煎芝士蝦餅', '2016-12-30', '煎至兩面金黃色的蝦餅，既鮮味又彈牙，本身已經滋味滿分，一口咬下去發現中間流出濃郁的芝士餡，更是驚喜！', '30分鐘', ''),
(37832, '雞蛋芝士麵包碗', '2016-04-03', '如果你喜歡下廚卻討厭洗碗，不如直接用食材做碗吧！這個麵包碗只要挖空中心，就可以放入雞蛋火腿等材料，最後加點芝士在表面烘焗，方便快捷，用來做早午晚餐都可以啊。', '30分鐘', ''),
(37833, '水果魔方', '2016-03-29', '如何將普通的水果沙拉做到令人歎為觀止？這道水果魔方就是答案。五顏六色的水果加上強迫症一般的魔方造型，絕對讓它成為聚會餐桌上的焦點。配上優酪乳享用，味道也非常受歡迎哦。', '1小時', ''),
(37834, '紅袍銀鱈魚', '2016-03-30', '鱈魚在北歐被稱為是餐桌上的營養師。它的營養價值非常高，同時它的熱量也超級低。絕對是我們愛美愛健康的女生的首選食材。今天Norma就用川菜的做法來料理這一個遠道而來的食材。', '30分鐘', '2人'),
(37835, '冬陰功湯', '2016-03-31', '冬陰功湯，是泰國一道富有特色的酸辣口味湯品。因為加入了香茅、檸檬、咖喱等多種泰式香料，而五味俱全。一碗湯端上桌來，香辣皆有，口感嫩滑。', '30分鐘', ''),
(37836, '沙茶醬雜錦炒烏冬', '2016-04-04', '吃火鍋剩下最多的食材往往是各式丸類，如果還有少許蔬菜、烏冬和醬料的話，就可以來個雜錦炒烏冬，一次過將火鍋剩料變成第二天的午餐或晚餐。', '20分鐘', '2人'),
(37837, '宮保蜂巢豆腐', '2016-04-05', '宮保雞丁是著名的四川菜，以花生、辣椒、香辛料炒雞丁，惹味下飯。除了雞丁，這種做法用來煮其他材料亦可，例如吃火鍋剩下的蜂巢豆腐，亦很適合這種宮保煮法。\r\n\r\n<十五分鐘懶人版｜宮保雞丁>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：宮保雞丁', '20分鐘', '2人'),
(37838, '日式南瓜雞肉雜菇炊飯', '2016-04-06', '炊飯是每個日本媽媽都會做的料理，在煮飯的時候加進新鮮有益的食材，簡單又美味。火鍋吃剩的食材正好用來煮這種飯，好像這款南瓜雞肉雜菇炊飯，菇香撲鼻，是簡單晚餐之選。', '30分鐘', '1人'),
(37840, '涼拌香辣麻醬豬肉片', '2016-04-07', '火鍋吃剩的豬肉片用途多多，這道涼拌香辣麻醬豬肉片做法簡單，配以自己調配的香辣醬，轉間眼就做好一道顏色吸引又惹味的涼菜。', '20分鐘', '2人'),
(37841, '鮮冬菇粟米墨魚餅', '2016-12-28', '吃火鍋總會準備鯪魚滑、墨魚滑之類，吃不完的話，加入其它吃剩的食材煎成餅，立即變身成為第二晚的下飯菜式。', '30分鐘', '2人'),
(37842, '鯪魚肉豆卜串燒', '2016-04-09', '在小食店買到的鯪魚肉釀豆卜是用炸的方式處理，在家不想開油鑊，不如試做鯪魚肉豆卜串燒吧！先煎後焗更健康，要處理吃火鍋剩下的鯪魚肉和豆卜無難度。', '30分鐘', '2人'),
(37843, '簡易菠蘿牛肉薄餅', '2016-04-10', '吃火鍋後肥牛肉剩下了很多怎麼辦？用來做個創意薄餅吧！用現成的彼得包做餅底，令做薄餅變得簡單快捷又有趣，菠蘿、酸薑食材的配搭想不到和牛肉是如此匹配。', '30分鐘', '2人'),
(37844, '無水海鮮粉絲鍋', '2016-04-06', '最近非常流行吃無水海鮮鍋，因為它食材豐富，步驟簡單，是一個非常好的宴客菜。今天Norma就和大家一起做一道無水海鮮粉絲鍋，讓你可以輕輕鬆松完成一道大菜。', '30分鐘', '2人'),
(37848, '黑椒大蝦炒粉絲', '2016-04-11', '每次煮黑椒炒大蝦，廚房都傳來陣陣香氣令人食指大動，這次加入粉絲一起煮，粉絲吸盡大蝦和黑椒的味道，大蝦頓時成了配角呢！', '20分鐘', '1人'),
(37849, '創意雞肉包飯', '2016-04-11', '利用去骨雞腿肉搭配臺灣簡單油飯做法, 替代了繁瑣的雞翅去骨的方式, 讓你也能享受傳統的雞翅包飯的風味,試試我們的創意新吃法！', '1小時', '2人'),
(37850, '三色豆腐粉絲蒸蛋', '2016-04-12', '豆腐、粉絲和雞蛋，無論顏色和味道都較為清淡的食材，加入黑木耳、粟米和紅蘿蔔三種顏色的材料，就可以製成賣相甚為精緻的蛋餅，既下飯又有營養。', '30分鐘', '2人'),
(37851, '榨菜肉碎炒粉絲', '2016-04-13', '簡單的家常小炒，往往是最令人回味的下飯菜，這道榨菜肉碎炒粉絲，粉絲充份吸收榨菜、豬肉和調味料的味道，單靠這一道菜就可以吃下一碗飯了。', '30分鐘', '1人'),
(37852, '油鹽水粉絲煮蜆', '2016-12-30', '油鹽水是漁家菜常見的煮法，簡單的調味最能突顯出食材的鮮味，這道油鹽水粉絲煮蜆材料和做法都很簡單，味道卻令人讚口不絕，今晚就試試吧。', '1小時', '1人'),
(37853, '芝士汁粉絲焗扇貝', '2016-04-15', '扇貝和粉絲的配搭很常見，不外乎用蒸的方法處理，想不到配搭芝士汁來焗味道也很出色，粉絲沾滿芝士的香濃味道，這款西式煮法一定能給你驚喜。', '30分鐘', '5人'),
(37854, '螞蟻上樹', '2016-04-16', '螞蟻上樹是一道很經典的中菜，其實是免治豬肉炒粉絲，豬肉粒掛在粉絲上的樣子就像螞蟻爬上樹的一樣，因而得名，名字有意境，惹味又下飯。\r\n\r\n<十五分鐘懶人版｜螞蟻上樹>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：螞蟻上樹', '30分鐘', '2人'),
(37855, '泰式粉絲沙律', '2016-04-17', '在春天細雨紛紛又潮濕的日子，來一道酸酸辣辣的泰式粉絲沙律，不但為味蕾帶來新鮮感，連心情也會好起來，酸辣味道更可自己調節，春睏的日子用辣來叫醒自己吧！', '30分鐘', '2人'),
(37856, '韓式烤肉', '2016-04-13', '最近幾年非常流行吃韓國烤肉，不過出去外面吃常常需要排隊等位元。所以你如果嫌麻煩，那就趕快來嘗試下今天Norma的分享。教大家做一個不出家門也可以簡單做得到的韓式烤肉方法。', '30分鐘', '2人'),
(37862, '酸甜京都骨', '2016-04-18', '豬肋骨是豬腹腔靠近肚腩部位的肋骨，多肉少骨，甚至帶有白色軟骨，用來油炸、炆煮就最適合。起源自無錫的京都骨，早就成為酒樓的經典菜式，酸酸甜甜的味道，加上濃厚的肉香非常下飯。', '1.5小時', '2人'),
(37867, '豬紅韭菜蘿蔔', '2016-04-19', '提到豬的不同部位，有想到豬紅嗎？豬血價錢相宜，但營養價值一點也不低，能補充鐵質。豬紅韭菜蘿蔔是一道香港人很喜歡的小吃，價廉物美的豬紅蘿蔔煮得入味，勝過不少山珍海錯。', '30分鐘', '2人'),
(37868, '朱古力軟糖', '2016-04-19', '想親手做禮物給朋友又不知道做甚麼？試一下這款手工朱古力軟糖！材料和做法都超級簡單，最後用靚靚花紙包起，一份簡單又有心思的小禮物就做好了！你也一起做吧！', '1.5小時', '2人'),
(37870, '雪菜豆乾肉絲炒麵', '2016-04-20', '赤肉即豬後腿肉，由於腿部活動量大，肌肉多，是豬肉中脂肪含量最少的部份，宜切細烹煮，就好像切成肉絲，用來炒雪菜豆乾肉絲炒麵就最適合了。', '1小時', '1人'),
(37871, '柴魚花生菜乾豬骨粥', '2016-04-21', '中國人常用豬骨煲湯，因為有以形補形之說，相信能強健筋骨，姑勿論能否補骨，豬骨煲湯的確非常美味，這次用在燒味店買來的燒豬骨煲菜乾粥，令粥美味之餘亦有下火之效。', '1.5小時', '1人'),
(37873, '自製蜜汁叉燒炒蜜糖豆', '2016-04-22', '脢頭肉(又寫作梅頭)，即豬的上肩部份，肌肉較多，脂肪相對少，吃起來口感有脆度，因此常選用來做叉燒。在家做叉燒用焗爐焗方便快捷，味道不遜於燒味店啊。\r\n\r\n<十五分鐘懶人版｜蜜汁燒叉燒>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：蜜汁燒叉燒', '1.5小時', '2人'),
(37874, '酸菜蓮藕炒豬頸肉', '2016-04-23', '雖知豬頸肉脂肪含量比較高，但豬肉和脂肪分佈均勻，吃起來有爽脆的口感，實在很難叫人忍口吧！這次利用鹹酸菜中和一下油膩感覺，配搭爽口蓮藕，非常滋味。', '30分鐘', '2人'),
(37875, '話梅炆豬手', '2016-04-24', '豬手即豬前腿上部連骨帶肉的部份，由於皮厚含豐富膠質，因為向來被視為具養顏功效的食材，膠質豐富的豬手最宜用來炆煮，這道菜配以酸酸甜甜的話梅，味道非常開胃。', '1.5小時', '2人'),
(37876, '伯爵茶香檸檬布朗尼', '2016-04-21', '搭配清爽檸檬汁的創意配方，試試看有別於傳統的巧克力布朗尼的做法', '1.5小時', '2人'),
(37877, '經典越南香茅雞肉三明治配自製爽泡菜', '2016-04-23', '越南三明治是種文化結合的產物,美國人說越南人趕走了法國人, 卻保留的法國麵包,造就了世界上最美味的三明治, 成為越南經典街邊小吃之一~帶有殖民主義色彩。在越南芽莊,人們用了法國的特色的的麵包放入了各種美味的肉類和新鮮蔬菜, 這種蔬菜在越南很受人們喜愛,也變成了當初常規的早餐或是午餐的選擇了！', '1.5小時', '2人'),
(37879, '莎莎醬凍豆腐', '2016-04-25', '莎莎醬(Salsa sauce)是墨西哥菜餚裡經常出現的醬料，以番茄為主要材料，味道清新開胃，簡單配以豆腐就可以成為清新開胃的涼拌菜。', '10分鐘', '2人'),
(37880, '梅漬蜂蜜車厘茄', '2016-04-26', '酸酸甜甜的車厘茄既可生吃又可熟食，小小一顆做涼拌菜式更是適合，簡單用話梅和蜂蜜來醃漬，即成為酸甜可口的開胃菜。', '1.5小時', '2人'),
(37881, '香醋青瓜海蜇頭', '2016-04-27', '海蜇頭比切成條狀的海蜇皮肉厚，用來做涼拌菜式口感更爽脆可口，以鎮江醋為主的調味醬汁醒胃惹味，預先做定放在雪櫃冷藏更入味。', '1.5小時', '2人'),
(37882, '涼拌青瓜皮蛋塔', '2016-04-28', '青瓜是涼拌菜常用到的食材，除了簡單的拍青瓜，這次配搭玉子豆腐和皮蛋，同時享受軟滑和清爽口感，還有溏心皮蛋的滋味，令人難以抗拒。', '10分鐘', '2人'),
(37883, '香醋涼拌杏鮑菇', '2016-04-29', '杏鮑菇菌肉肥厚，而且低脂低膽固醇低熱量，用來做涼拌菜式，吃起來清爽無負擔，配搭口感爽脆的蜜糖豆、紅蘿蔔，以鎮江醋調味，令人胃口大開。', '1小時', '2人'),
(37884, '涼拌辣魷魚', '2016-04-30', '魷魚口感煙韌有嚼勁，配搭爽脆的洋蔥、青瓜和車厘茄，用上韓式辣醬及蜜糖等調味，立即有韓式前菜的感覺。', '30分鐘', '2人'),
(37885, '四川棒棒雞', '2016-05-01', '棒棒雞這道菜起源自四川，名字由來是因為製作時要用棍(棒)將雞肉捶鬆，方便入味，用上麻醬、辣椒油等調味料炮製，麻香辣香四溢，冬夏天吃都適合啊。', '1小時', '2人'),
(37887, '滋補燉肉汁', '2016-04-26', '如果你喜歡吃肉，而且是一個真正的食肉一族，今天你就有福啦！Norma這次會教你做一道豬肉料理，而且只用到豬肉這一個主要食材，是不是很有意思呢~讓我們一起做吧！', '1.5小時', '2人'),
(37895, '自製冬甩', '2016-12-23', '冬甩你一定吃過，但你知不知道美國人把6月第一個星期五定為「國際冬甩日」？這天，不少美國的麵包店會提供免費的冬甩，我們應應節，一齊做冬甩吧！', '1.5小時', '2人'),
(37898, '經典肉丸佐奶油蛋黃沙司意麵', '2016-05-01', '一學就會的經典意大利蛋奶醬,配上經典自製肉丸, 屬於小倆口的晚餐約會', '1小時', '2人'),
(37900, '苦白菜龍蝦沙律船', '2016-05-02', '想吃得豪氣一點，不妨選用龍蝦來做沙律，鮮味十足，利用苦白菜的花瓣狀葉塊來盛載，上碟時排成花形，既得體又好吃。', '30分鐘', '2人'),
(37902, '蝦滑釀小棠花', '2016-05-03', '要菜式能登大雅之堂，食材可以花點心思去處理，例如平凡的小棠花經修剪後可以變身小棠花，釀入鮮味的蝦膠，作為宴客菜絕不失禮。', '30分鐘', '2人'),
(37903, '煙三文魚花黑松露意大利飯', '2016-05-04', '煮意大利飯並不複雜，多練習就能煮出軟硬適中合自己口味的意大利飯，初學者不妨用零失敗的黑松露醬調味，再將煙三文魚扭成花狀伴碟，色香味俱全。', '1小時', '1人'),
(37905, '千層紹菜肉片鍋', '2016-05-05', '這個菜式做法簡單，但效果甚為驚喜，因為食材與紹菜層層相間，煮熟後就如盛放的花朵，更可以原鍋上桌，方便快捷。', '30分鐘', '2人'),
(37907, '士多啤梨花抹茶奶昔', '2016-05-07', '大多數女士都愛花，在平凡的抹茶奶昔上擺放一朵雕成花形的士多啤梨，裝飾簡單卻討好。', '30分鐘', '1人'),
(37908, '三文魚青瓜花壽司卷', '2016-05-08', '一般壽司卷物都是圓形的，其實只要把食材擺位改變一下，把卷物做成水滴狀，拼起來就變成漂亮的花狀壽司。', '30分鐘', '2人'),
(37911, '韓式檸檬醬', '2016-05-04', '去餐廳吃韓國菜都會叫一杯韓國柚子茶，別少看它，它以前在韓國是進貢去宮庭的傳統茶！我們參考韓國柚子茶，用檸檬自製一樣養顏的韓式檸檬醬。加到有氣礦泉水，不單好喝，而且充滿維他命C，可以預防感冒呢！', '10分鐘', '2人'),
(37914, '手工精燉鮮蝦麵', '2016-05-04', '吃蝦面～舊時，閩南地區立夏吃蝦面，把蝦摻入面條中煮食，蝦熟後變紅，為吉祥之色，而蝦與夏諧音，以此表達對夏季的祝願。今天教你用港式經典的蝦子麵條來搭配長時間熬煮的蝦頭高湯的創意又帶有閩南風味的新吃法。', '1.5小時', '2人'),
(37915, '捲心菜豬肉蒸餃', '2016-05-05', '吃膩了傳統的豬肉餃子餡料, 今天教你試試看用捲心菜,黑豬肉配生薑調出的簡單又美味的餃子餡料,母親節到來為自己的媽媽親手包個餃子給她吧～', '30分鐘', '4人'),
(37920, '豬肉花番茄雞絲飯', '2016-05-06', '怎樣能讓平凡的番茄雞絲飯更有特色？擅用食材用來裝飾吧！在飯上面加上灼熟的豬肉片，堆砌成花狀，簡單的碟頭飯立即充滿生氣。', '10分鐘', '1人'),
(37921, '白巧克力榴槤酸奶慕斯', '2016-05-06', '白巧克力配上濃郁榴槤創意搭配,今年夏天具有濃烈南洋風的創意甜品。', '1.5小時', '5人'),
(37922, '豉椒味菜炒鮮魷', '2016-05-08', '在廣東俗語中「炒魷魚」是遭解僱的意思，實際上炒魷魚是一道很受歡迎的家常菜，配搭惹味的豉椒和味菜，無論顏色和味道配搭都很完美。', '20分鐘', '2人'),
(37927, '蒼蠅頭', '2016-05-10', '首次聽「蒼蠅頭」這道菜名，感覺有點不衛生，其實因為韭菜、豬肉等材料全都切成小粒，而黑色的豆豉像蒼蠅的樣子，這道菜又可叫做「白飯殺手」，因為微辣的味道非常下飯。', '30分鐘', '2人'),
(37930, '繽紛鮭魚小米團', '2016-03-11', '鲑鱼的營養價值高,搭配了好吃彈牙的大米,搭配不同素材可以讓視覺呈现更加豐富,選擇自己喜爱的沾酱搭配吃,無論小型派對或是给親爱的作可口的愛心便當都是非常適合的喔~', '1小時', '2人'),
(37931, '韭菜蛋餅', '2016-05-11', '按照中醫養生的理論，我們只要把肝養好就能保持活力，擺脫疲倦。而養肝首選食物就是韭菜，今天Norma分享一個西式做法來做一份小巧可愛的韭菜蛋餅。', '20分鐘', '2人'),
(37932, '沙茶醬通菜炒羊肉', '2016-05-11', '不少朋友抗拒羊肉是因為怕羊肉的羶味，這道快炒羊肉加入惹味的沙茶醬同炒，把羊羶味遮蓋掉，怕羊羶的朋友亦可一試啊！\r\n\r\n<十五分鐘懶人版｜蝦醬通菜炒牛肉>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：蝦醬通菜炒牛肉', '20分鐘', '2人'),
(37933, '三色蛋炒苦瓜', '2016-05-12', '三色蛋即是雞蛋、鹹蛋和皮蛋的配搭，最常見用來做蒸蛋，其實用來炒亦可以，配搭苦中帶甜的苦瓜，三數分鐘就炒好碟下飯菜式。', '30分鐘', '2人'),
(37934, '醬爆豆腐乾炒肉絲', '2016-05-13', '炒肉絲是一道用料和煮法簡單的家常菜，只要配搭不同材料，就可以煮出無窮變化，這次加入甜麵醬和豆腐乾同炒，味道濃郁，記住多煮一點白飯啊！', '10分鐘', '2人'),
(37935, '泰式打拋豬', '2016-05-14', '「打拋」是一種泰國香草，音譯為打拋，是為羅勒的一種，打拋豬就是用這種香草來炒豬肉，配搭番茄，這道菜做法簡單而味道非常下飯，充滿泰國風味。', '30分鐘', '2人'),
(37936, '彩椒鮮百合炒雞柳', '2016-05-15', '快炒菜式由於烹調時間短，宜選用快熟的食材，這道菜中的燈籠椒和鮮百合，正是快熟的蔬菜，配搭多汁的雞肉，營養均衡又美味。', '30分鐘', '2人'),
(37937, '美式馬鈴薯千層派', '2016-05-11', '最簡單的食材～「馬鈴薯」做出洋氣的派點，生手也不怕做西餐了，野餐或派對的最佳選擇！', '1小時', '2人'),
(37939, '韓式干烹雞', '2016-05-12', '這道料理源自於中國的干烹雞,早期韓國人調整成當地偏好的口味後,放入蒜香辣味的元素,以及酸甜的口味醬汁,就變成韓國的“中華炸雞料理”,甚至在美國的韓國餐廳盛行,嘗試過韓式炸雞的你,快來試試看新口味！', '1小時', '2人'),
(37941, '覆盆子檸檬莫西多', '2016-05-13', '每到夜店常見飲品, 周末在家與閨蜜小聚，不如自己動手來一杯，小編今天教你用新鮮的水果搭配自製糖漿，來自製一款養顏無酒精的紅桑子檸檬莫西多。', '10分鐘', '2人'),
(37942, '香辣三文魚雞肉米薄餅', '2016-05-16', '吃剩的白飯除了用來炒飯，不如用來做米薄餅吧！焗好的米飯餅底軟糯又香脆，配搭三文魚、雞腿肉及日式風味的調味料，口感非常豐富。', '1小時', '2人'),
(37949, '忌廉海鮮意粉薄餅', '2016-10-21', '意粉也可以做薄餅？可以啊！開派對時做這款意粉薄餅，將意粉切開成薄餅形狀，給朋友帶來驚喜。', '1小時', '2人'),
(37950, '煙肉蘑菇薯片薄餅', '2016-05-18', '薯仔的食法有很多，用來做薄餅又試過未呢？將薄薄的薯仔片鋪好成為餅底，加上豐富的餡料，將薯仔片煎到香脆，做正餐或小食都很適合。', '1小時', '2人'),
(37951, '水波蛋牛油果醬麵包薄餅', '2016-05-19', '白麵包是很百搭的食材，用來做薄餅也可以，這款水波蛋牛油果醬麵包薄餅最適合用來做早餐。', '30分鐘', '2人'),
(37952, '意式香腸彼得包薄餅', '2016-05-20', '彼得包又名中東包或口袋包，用小麥粉及鹽製造，是比較健康的麵包選擇，用來做薄餅餅底亦非常適合和方便。', '1小時', '2人'),
(37953, '椰香芒果咖喱雞薄餅', '2016-05-21', '墨西哥薄餅是用粟米粉或小麥粉烙製而成的薄餅，即買即用也適合用來做簡易薄餅，餡料加入紅咖喱、檸檬葉及青檸，充滿泰國風味。', '30分鐘', '2人'),
(37954, '鮮果乳酪薄餅', '2016-10-21', '水果如何做薄餅？發揮你的創意小宇宙吧！用西瓜橫切面做餅底，加上你喜歡的鮮果，切成薄餅形狀，立即成為有創意又健康的鮮果甜品。', '20分鐘', '2人'),
(37956, '自製手工柳橙果醬', '2016-05-17', '自制風味健康無添加果醬配方, 可以搭配英式紅茶享用也可以配上美味的司康餅,周末的午茶優雅搞定!', '20分鐘', '2人'),
(37958, '椰香燕麥餅乾', '2016-05-19', '選用天然健康的椰子油來搭配高纖燕麥的手工餅乾,有嚼勁帶有淡淡橙皮香味的創意搭配！', '30分鐘', '2人'),
(37966, '黑森林蛋糕', '2016-05-20', '濃郁的OERO風味的可可粉搭配橄欖油，濃郁不甜膩的風味絕對是你沒有吃過的黑森林蛋糕的口感！！簡單易學，快來試試看～', '1.5小時', ''),
(37968, '香茅青檸蒸蝦', '2016-05-23', '蝦是快熟的海鮮材料，用電飯煲來蒸煮很快便可完成，加入香茅、青檸和魚露來調味，為鮮蝦增添泰國風味。', '20分鐘', '2人'),
(37970, '手工身體磨砂糖', '2016-05-23', '夏天即將到來了! 你準備好展現你的性感肌膚了嗎? 如果每周定期保養自己的肌膚透過天然有機的素材, 跟著我一起動手做屬於自己有機天然肌膚保養品~終於学会了享受那些安静幸福时刻,懷念曾经享受長達一个小时的按摩。每天在享受沐浴時刻,簡單的利用这些手工磨砂糖塊給自己肌膚寶貝一下或是分享給你的閨蜜！', '30分鐘', '2人'),
(37971, '味噌玉子豆腐蒸豬肉片', '2016-05-24', '味噌不只用來煮味噌湯，鹹香的麵豉味道用來做菜亦很適合，用味噌來醃豬肉片，放在玉子豆腐上面一起蒸，味噌味道同時滲進玉子豆腐之中。', '30分鐘', '2人'),
(37972, '雙菇粟米牛肉飯', '2016-05-25', '電飯煲最經常用來煮白飯，其實煮飯時把材料一起加進去，煮一鍋有味飯是近年的流行做法，適合懶人之餘食材又充滿營養。', '1小時', '2人'),
(37973, '鴛鴦蘿蔔冬菇牛腱湯', '2016-05-26', '電飯煲除了用來煮飯，也可以用來煲湯啊！加入紅白蘿蔔一起熬煮的牛腱湯增添一份清甜味道。', '1小時', '2人'),
(37976, '鹹酸菜雲耳燴鴨肉', '2016-05-27', '蒸鴨的配搭來來去去都是梅子，有點悶吧？這次換上味道同樣帶酸的鹹酸菜，配搭健康有益的雲耳一起蒸，給你耳目一新的感覺。', '1小時', '2人'),
(37977, '電飯煲滷水雞脾', '2016-05-28', '滷水雞脾最重要是入味，做法會很複雜嗎？其實用電飯煲也可以做到啊！同一鍋滷水更可以用來滷雞翼、鴨舌、牛腱等等食材。', '1小時', '2人'),
(37979, '電飯煲日式芝士蛋糕', '2016-12-28', '焗蛋糕一定要用焗爐？未必！家中有普通電飯煲也可以做到，實在是懶人福音，這個周末你也試做一個吧！', '1.5小時', '2人'),
(37981, '泰式鹽烤牛肉沙律', '2016-05-25', '教你經典的泰式打拋沙律的作法可以搭配不同的肉類涼拌，酸甜辣的東南亞風味一次打開夏天的胃口！', '1小時', '2人'),
(37984, '經典台灣麻油雞', '2016-05-25', '在台灣做月子必吃美食之一～今天用紅標米酒以及一些簡單的材料就能讓你輕輕鬆鬆做成一道麻油雞。', '1小時', '2人'),
(37985, '創意忌廉咖哩雞肉燴飯', '2016-05-27', '給童心未泯的你回味一下美味又卡哇伊的大餐吧！今天搭配了酸忌廉來烹製這款咖哩雞肉飯，讓你回味無窮～', '30分鐘', '2人'),
(37988, '香菇肉燥飯', '2016-05-27', '台灣飲食小吃花樣繁多，今天教大家做一款台灣常見，而且很經典的人氣美食，做法又簡單哦～', '1小時', '2人'),
(37990, '咖喱漢堡扒伴椰菜沙律', '2016-05-30', '咖喱和漢堡扒都是很有家庭風味的日本菜，兩者除了配搭白飯吃，在夏天不妨伴以味道清新的椰菜沙律，給你耳目一新的感覺。', '1小時', '2人'),
(37991, '椰香咖喱雞伴薄餅', '2016-05-31', '吃印度咖喱一般伴有薄餅同吃，其實煮日本咖喱都可以啊！這款椰香咖喱雞加入椰汁、椰糖、檸檬葉等材料，增添一點亞洲風味。', '30分鐘', '2人'),
(37992, '咖喱吞拿魚飛碟', '2016-06-01', '用麵包夾餡料而成的飛碟三文治最適合做下午茶，然而沒有三文治機怎麼辦？用煎鍋也可輕鬆做到啊！記得把餡料塞得滿滿，吃下去大滿足。', '30分鐘', '2人'),
(37994, '咖喱芝士蟹肉醬', '2016-06-02', '日本咖喱磚煮成的菜式只能伴飯或意粉吃？不一定，香甜的咖喱味道也可以做小吃，例如這款咖喱芝士蟹醬，用梳打餅沾來吃，即成為受歡迎的派對小吃。', '30分鐘', '2人'),
(37995, '咖喱海鮮炒烏冬', '2016-06-03', '每一條烏冬均勻沾上味道濃郁的咖喱汁，加上多種海鮮的鮮味，這款咖喱海鮮炒烏冬的美味令人難以抗拒。', '30分鐘', '2人'),
(37997, '黃金咖喱薯球', '2016-06-04', '香脆可口的炸薯餅，小朋友尤其愛吃，除了在超市買現成的來翻炸，自己做的更有益健康，加入咖喱磚調味令味道更豐富。', '1小時', '2人'),
(37999, '和風咖喱豬肉飯', '2016-06-05', '日本咖喱味道偏甜，是因為他們喜歡加入蘋果調味，香甜的咖喱味道連小朋友也能接受，這款和風咖喱豬肉飯一家大小都會喜歡。', '1小時', '2人'),
(38002, '自製雪糕三文治', '2016-05-31', '小時候吃雪糕的時光總感覺是奢侈的，現在隨手一處都是雪糕！今天一起回味餅乾夾著雪糕的滋味，為你帶來最經典的美式大餅乾以及教你怎麼利用家裡常備的雪糕簡單快手做出雪糕三文治。', '30分鐘', '2人'),
(38003, '腰果花生焦糖脆片', '2016-05-31', '喜歡自製手工禮物送給朋友的你一定不能錯過的食譜，你可以隨意變化你喜愛的堅果類來搭配這個食譜，沒有烤箱也能做出美味甜點,，簡單的素材就讓你體驗不同的甜食領域。', '1.5小時', '2人'),
(38005, '瑤柱滑雞粥', '2016-06-08', '論到粥品，廣東人尤其有研究，五花百門的粥品中，雞粥最容易令人念念不忘，因為經熬煮後雞的鮮味與粥互相融合，加上淡淡的瑤柱香，用來做早午晚餐甚至宵夜都適合。', '1.5小時', '2人'),
(38006, '瑞士汁炒牛河', '2016-06-06', '瑞士汁並非源自瑞士，當年的文化差異令這種顏色深褐的甜醬汁，誤譯為瑞士汁，其實它是一款用途百搭的醬汁，用來做炒牛河，味道非常夾。', '1小時', '2人'),
(38007, '香菇肉碎銀針粉', '2016-06-09', '銀針粉是一種頭尾尖、中間圓形的粉條，滑嫩有嚼勁，加香菇肉碎湯一起煮是最經典和令人回味的煮法，吃的時候只需一隻匙羹就足夠了。', '30分鐘', '2人'),
(38008, '豉油皇炒麵', '2016-06-07', '豉油皇炒麵是經典的麵食，既出現於粥店配搭粥品享用，又會出現於酒樓之中，它用料看似簡單，但要做乾身彈牙鹹度適中並不簡單啊。', '30分鐘', '2人'),
(38009, '牛柳絲炒即食麵', '2016-06-11', '即食麵一般煮成湯麵，但自從茶餐廳出現炒即食麵後，即成為香港一道代表性的茶餐廳美食，加入多種顏色的蔬菜和牛柳絲同炒，即成為色香味俱全的豐富晚餐。', '30分鐘', '2人'),
(38010, '雪菜火鴨絲炆米', '2016-06-10', '雪菜火鴨絲炆米是酒樓必有的經典麵食，火鴨即再度烹調的燒鴨，本身無味的米粉吸收燒鴨和雪菜的味道，令人回味無窮。', '1小時', '2人'),
(38011, '茄汁焗豬扒飯', '2016-06-12', '焗豬扒飯是港式茶餐廳和快餐店的經典美食，濃香的茄汁味道，配搭鬆軟的豬扒和香口炒飯，美味得讓人一口接一口停不下來。', '1小時', '2人'),
(38012, '蜂蜜蓮子綠豆羹', '2016-06-02', '綠豆味甘，性涼，入心胃經，具有清熱解毒、消暑除煩的功效；蓮子味甘澀、性平，具有健脾補腎、養心安神的功效。夏日炎炎，教你用綠豆及蓮子來做出一款消暑滋潤的甜湯。', '1小時', '2人'),
(38021, '人魚線西蘭花烤雞芝士三文治', '2016-06-04', '炎炎夏日，搭配蔬菜、芝士與雞肉的豐富口感，清新卻不失單調！', '30分鐘', '2人'),
(38022, '經典台南肉糭', '2016-06-04', '市面上有各種不同的糭子，但是台灣風味的肉糭後最令人念念不忘，在台灣有南北2種不同做法的糭子，今天就来分享来自南部糭子做法～', '1.5小時', '2人'),
(38027, '經典炸魚薯條', '2016-06-07', '英國的經典美食除了農舍批，就是炸魚薯條 了！今天就分享炸魚用的特製啤酒炸漿以及簡單又好吃的香脆風琴薯仔做法！', '1小時', '2人'),
(38028, '勃艮第牛肉', '2016-06-07', '誰說法國大餐要大陣仗才能做得到，今天教你如何在家裡沒有焗爐也能做出經典法式紅酒燉牛肉。', '1.5小時', '2人'),
(38031, '義式炸飯糰配牛油果他他醬', '2016-06-08', '雖然意大利的麵非常出名，但是米也是他們的主要糧食之一，而意大利更是歐洲稻米產量最大的國家。另外，意大利製造了450種不同的芝士，有些還享有盛名。用這兩種意大利「特產」製作出來的意大利芝士炸飯糰，剛開始看起來還以為是金黃酥脆的炸肉丸，咬下去才知道是傳統的意大利米飯口感，味道討好，而且外層香脆。', '30分鐘', '2人'),
(38034, '唐揚炸雞', '2016-06-19', '唐揚即是日本用醬汁醃漬入味的炸物。鹹酥香脆的外皮，下面就是充滿醬汁香氣的鮮嫩雞肉。不只可當主菜，也可以是下酒菜！', '1.5小時', '2人'),
(38037, '鹽焗火雞腎', '2016-06-18', '鹽焗雞腎是一道做法簡單，又非常受歡迎的家常美食。這次選用了火雞腎，香口的沙薑味加上爽嫩的火雞腎，爽脆入味，夏天下酒必備！', '1小時', '2人'),
(38040, '酥皮腸卷', '2016-06-13', '只需用酥皮捲起香腸便可以焗成金黃鬆脆的小食，相信沒有人可以抗拒它！簡單的材料及做法，更可以一家大小一起煮。配上啤酒汽水，趁熱享用！', '10分鐘', '2人'),
(38044, '磯煮鮑魚', '2016-06-15', '磯煮是日本一種煮海鮮的方法，意思是用醬汁及昆布慢火去炆，不用煮太長時間，令肉質保持鮮嫩彈牙，又可讓濃郁的湯汁裹住鮑魚，是夏日必備的下酒菜！', '1.5小時', '2人'),
(38047, '椒鹽雞軟骨', '2016-06-16', '椒鹽雞軟骨是經典的家常下酒菜。外酥內脆的雞軟骨，口感豐富，加上椒鹽樸實簡單的調味，減輕了油膩感，是很棒的下酒菜！\r\n\r\n<十五分鐘懶人版｜椒鹽雞軟骨>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：椒鹽雞軟骨', '1小時', '2人'),
(38048, '蕃薯片配日式莎莎醬', '2016-06-17', '不一定是用薯仔做的，用紫薯及蕃薯也可以做到香脆的「薯片」！蘸著酸酸辣辣的日式莎莎醬，再配上一罐冰涼的啤酒，簡直一流！', '10分鐘', '2人'),
(38049, '美式辣肉腸蕃茄芝士醬', '2016-06-09', '看歐洲杯怎可以少了零食？！今天教你快手製作美味的芝士醬，配薯片也可以！', '30分鐘', '2人'),
(38050, '鮮蝦牛油果蔬果沙律', '2016-06-10', '富含高蛋白鮮蝦，配上優選的希臘乳酪，搭配牛油果的特製沙律醬，給你享受悠閒的週末早午餐～', '20分鐘', '2人'),
(38051, '香辣蒜蓉蜜糖雞翼尖', '2016-06-14', '雞翼尖既是美味的下酒菜，也是不错的小零食。香甜鹹辣，味道非常豐富，讓人食慾大增。雖然沒甚麼吃頭但非常有滋味，喝啤酒配著吃超過瘾！', '1.5小時', '2人'),
(38058, '香辣蜂蜜烤雞', '2016-06-14', '看歐洲杯，當然要準備小食邊看邊食！這個香辣蜂蜜烤雞不用油鍋，就可以輕易做到！煮一碟跟朋友一起看世界杯吧！', '1小時', '2人'),
(38059, '炸芝士香蕉', '2016-06-15', '炸香蕉在中美洲是很普遍的配菜，外皮鬆脆，裡面粉粉的，不會很甜。做法也十分簡單，首先將香蕉去皮切片，讓後放入少許油炸兩遍，最後淋上蜜糖就完成！', '20分鐘', '2人'),
(38060, '豬油叉燒飯', '2016-06-16', '父親節快到來，不如親自下廚為爸爸做一碗飯。即使是最簡單的料理，都可以表達你的心意，今天就用五花腩配上簡單材料煮一碗美味的叉燒飯！', '1小時', '2人'),
(38061, '酒糟鳳爪', '2016-06-17', '父親節很多人都在為爸爸準備禮物，其實再好的禮物也比不上在家陪爸爸。給他做上一頓美味的下酒菜——酒糟鳳爪！', '1.5小時', '2人'),
(38062, '意大利薯仔丸子', '2016-06-14', '這是意大利的一個經典傳統美食，其實就是用薯蓉做成的丸子。傳統的做法會在上面印有特別的花紋，還會配上不同的醬汁。這個食譜除了教你製作意大利薯仔丸子，還有經典的辣味西西里式番茄醬，一起動手試試看！', '30分鐘', '2人'),
(38063, '自家製炸醬', '2016-06-20', '肉香醬濃的炸醬，搭配有煙韌的麵，在家裡自己都可以做出香濃美味的港式炸醬麵！香辣的炸醬淋在彈牙的麵上，每吃一口，都是味蕾的享受。', '30分鐘', '2人'),
(38064, '雙重蔥油醬', '2016-06-21', '用了蔥和幹蔥，經油爆香後，味道香濃帶點辛辣味，只要加入一小匙的蔥油醬，在平凡的食材都會能變成五星級的美食！', '1小時', '2人'),
(38065, '蝦米豆豉辣醬', '2016-06-22', '惹味的豆豉，再以香口的蝦米增添鮮味，這個醬香辣可口，用來拌麵不但非常美味，更令人食慾大增！', '20分鐘', '2人'),
(38066, '韓式吞拿魚香辣醬', '2016-06-23', '只需要簡單的材料，就算新手可以輕鬆做出惹味的韓式香辣醬！韓國的泡菜酸香辛辣又開胃，加入罐頭吞拿魚增加口感，今個夏天不能錯過！', '20分鐘', '2人'),
(38069, '蒜香芝麻醬', '2016-06-24', '香濃的芝麻醬中和了蒜頭的辛辣味，兩者結合，就變成了拌麵一流的醬汁。甜辣的味道帶出你的食慾，天氣再熱也不怕！', '10分鐘', '2人'),
(38070, '香菇酸辣醬', '2016-06-25', '腍滑的冬菇，加入不同香料醬汁炒香，口感一流之餘，更滿口冬菇的香味。味道酸酸辣辣，非常醒胃！', '20分鐘', '2人'),
(38071, '花生蝦米醬', '2016-06-26', '鮮香的蝦米非常提味，打碎了的花生香脆可口，提升了醬汁的口感，加上茄汁令醬汁酸酸甜甜，非常開胃！', '20分鐘', '2人'),
(38075, '水果乳酪雪條', '2016-06-21', '誰說雪條只能高熱量！教你做養顏又不發胖的健康雪條！', '1.5小時', '2人'),
(38076, '抹茶生朱古力', '2016-06-21', '這種朱古力是冷藏的，放入嘴裡瞬間融化，這種口感讓許多朱古力的愛好者無法抵擋，教你在家如何簡單操作！', '1.5小時', '2人'),
(38078, '美式朱古力豆軟曲奇', '2016-06-23', '愛吃朱古力的你，不要錯過這款口感偏濕軟，而且味道濃郁的美式軟曲奇，吃一口就能讓幸福滿瀉！', '1.5小時', '2人'),
(38079, '波爾多可麗露', '2016-06-24', '可麗露是由波爾多的修女們創造的法國甜點，外皮脆中帶嚼口，內裡如布丁般香軟。今天透過這個經典的法國甜點來介紹銅質模具對於這個甜點的意義及重要性。', '1.5小時', '2人'),
(38080, '榨菜肉絲蒸豆腐', '2016-06-27', '蒸出來的豆腐非常嫩滑，有種淡淡的豆香。 味道主要來自榨菜，不需要太多的調味，味道就已經非常豐富了！\r\n\r\n<十五分鐘懶人版｜榨菜木耳豆卜蒸牛肉>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：榨菜木耳豆卜蒸牛肉', '1小時', '2人'),
(38081, '糯米蒸肉丸', '2016-06-28', '這個糯米肉丸，蒸出來後軟軟糯糯的，肉餡加了蝦米、冬菇及馬蹄等香口爽脆的材料，一口一個，大小剛剛好。', '1.5小時', '2人'),
(38082, '苦瓜鹹蛋蒸肉餅', '2016-06-29', '苦瓜是夏天養生飲食最常見的一種食物，用蒸這個方式就可以保留食材的營養，加入鹹蛋及豬肉做成肉餅，好吃又健康！\r\n\r\n<十五分鐘懶人版｜咸蛋肉餅 >\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：咸蛋肉餅', '30分鐘', '2人'),
(38083, '榨菜豆卜粉絲蒸牛肉', '2016-06-30', '蒸牛肉非常嫩滑不老，豆卜及粉絲吸收了牛肉汁及榨菜的鹹辣味，做法簡單，下飯一流！\r\n\r\n<十五分鐘懶人版｜榨菜木耳豆卜蒸牛肉>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：榨菜木耳豆卜蒸牛肉', '1小時', '2人'),
(38084, '陳皮蒸牛肉餅', '2016-07-01', '拌入陳皮的牛肉，肉味濃郁，而且鮮味十足，蒸牛肉肉質嫩滑不老，加入爽口的馬蹄，是一個很好下飯的家常菜。', '30分鐘', '2人'),
(38085, '金銀蒜百合蒸絲瓜', '2016-07-02', '金銀蒜即是生的蒜蓉及炸至金黃色的蒜頭，生的蒜蓉蒜味比較濃烈，炸蒜則有焦香的味道，用來蒸清爽的絲瓜，非常好吃又下飯。', '30分鐘', '2人'),
(38086, '腐乳蒸雞', '2016-07-03', '不少人家中都會有一罐腐乳留作小菜或是粥品佐料，它的味道鮮美獨特，配上嫩滑的蒸雞，便可以做出簡單美味的家常小菜了。\r\n\r\n<十五分鐘懶人版｜酒香薑汁腐乳蒸雞>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：酒香薑汁腐乳蒸雞', '1小時', '2人'),
(38096, '香煎羊肋骨配古斯米沙律', '2016-06-28', '古斯米是一種摩洛哥的小米飯，雖然叫做米，但其實是一種粗麥製品。香嫩的羊肋骨配上營養豐富又健康的古斯米沙律，你一定不能錯過！', '1.5小時', '2人'),
(38097, '美式藍莓鬆餅', '2016-12-22', '教你做鬆軟的鬆餅，再配上新鮮藍莓，給你夏日一個優雅的美式早午餐！', '30分鐘', '2人'),
(38098, '鮮蝦牛油果乳酪沙律配烘法國麵包', '2016-06-29', '含高蛋白質的鮮蝦，配上優質的希臘乳酪做成的牛油果特色沙律醬，作為早餐或是下午茶都非常適合！', '20分鐘', '2人'),
(38105, '經典芝加哥薄餅', '2016-06-30', '芝加哥超厚餅底薄餅，用家裡的蛋糕模就可以做到！', '1.5小時', '2人'),
(38106, '香草酸牛奶英式鬆餅', '2016-07-01', '用自製酸牛奶及新鮮香草做出美味的英式鬆餅，為你的早餐帶來不同的風味，可以隨意配上果醬或火腿一起享用！', '30分鐘', '2人'),
(38115, '泰式和牛木瓜紫洋蔥沙律', '2016-07-04', '紫洋蔥口感較脆，鮮豔的顏色也令食物賣相更加吸引人，用來做沙律就最適合了。沖洗乾淨後切絲，拌勻材料，就成為一道美味的沙律了！', '30分鐘', '2人'),
(38116, '芝士洋蔥焗大啡菇', '2016-07-05', '牛排菇的菇味浓郁，用来烤焗就最适合。加了水牛芝士及香甜的洋葱一起焗，做法简单又好吃！\r\n幫你買埋餸，即開即煮！\r\n馬上選購： https://bit.ly/2J5yOfU', '30分鐘', '2人'),
(38118, '沙茶醬洋蔥炒魚片頭', '2016-07-06', '這道菜色真的是相當配飯，有炒得香甜的洋蔥，又加入了沙茶醬，令魚片頭的味道非常豐富，而且簡單又易煮！', '30分鐘', '2人'),
(38119, '黑椒洋蔥炆豬手', '2016-07-07', '濃郁的黑椒汁，再加上香甜的洋蔥，將豬手炆至稔滑，味道一流，醬汁更可以用來撈飯！', '1.5小時', '2人'),
(38120, '沙嗲洋蔥煎雞翼', '2016-07-08', '沒有誰能抗拒雞翼的魅力，再加上香辣的沙嗲、爽甜的洋蔥，煎得香嫩的雞翼就是你的最愛！', '1小時', '2人'),
(38121, '洋蔥蝦仁炒蛋', '2016-07-09', '看似很簡單的餸菜，但要炒得好吃其實相當有難度！秘訣是加入洋蔥，讓洋蔥的甜味帶出蝦的鮮味！', '30分鐘', '2人'),
(38122, 'XO醬洋蔥炒牛肉', '2016-07-10', '炒牛肉的材料和做法都非常簡單，配上惹味XO醬及軟甜的洋蔥，就成為一道非常下飯的家常菜！', '30分鐘', '2人'),
(38128, '土耳其番茄焗蛋', '2016-07-05', '經典的中東菜！常常在早餐裡出現，通常配麵包一起吃，在家裡一樣可以做出西餐廳級數的中東風情美食！', '20分鐘', '2人'),
(38129, '比利時窩夫配蘋果糖漿', '2016-07-08', '窩夫起源於比利時，中世紀在歐洲開始盛行，通常在早餐出現，鹹甜皆可。配上自製的蘋果糖漿，早餐就吃這個窩夫吧！', '1.5小時', '4人'),
(38140, '派對雪糕蛋糕', '2016-03-07', '家裡吃剩的雪糕還可以做什麼呢？今天只要買到簡單的材料就可以變身成一個派對甜品！', '1.5小時', '2人'),
(38165, '韓式泡菜豬肉炒長通粉', '2016-10-21', '', '30分鐘', '2人'),
(38190, '紙包海鮮意粉', '2016-07-11', '每條意粉都有香濃的番茄味，配上爽口的鮮蝦及魷魚，令人難以抗拒！', '1小時', '2人'),
(38191, '紙包冬蔭香茅烏頭', '2016-07-12', '用牛油紙包起肥美的烏頭，然後焗出油份，與青檸汁混合，味道甘香，加入冬蔭醬及香茅去除泥味，鮮美嫩滑的魚肉一定令你吃不停口！\r\n\r\n<十五分鐘懶人版｜香茅鹽焗烏頭>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：香茅鹽焗烏頭', '1小時', '2人'),
(38193, '焗香草紙包雞', '2016-07-13', '紙包雞是一個簡單又別緻的小菜，雖然材料簡單，但加入香草及香料，一打開牛油紙就香氣四溢，味道鎖在雞肉裡，每啖都是一次享受！', '1.5小時', '2人'),
(38219, '紙包韓式蜜糖辣雞', '2016-07-14', '簡單煮法做出韓國風味！少許辣味加上炸至酥香的雞肉，包你一試愛上！', '1小時', '2人'),
(38222, '無油紙包鯛魚', '2016-07-15', '不想吃得太油膩，不妨試試這個食譜。滴油不加，都可以煮出美味特色的紙包魚。', '10分鐘', '2人'),
(38224, '紙包蛋糕', '2016-07-16', '紙包蛋糕相信是不少人的童年回憶。軟綿綿，簡單又美味！在家做也很容易，真材實料之餘充滿蛋香味，超鬆軟！', '1小時', '2人'),
(38229, '蒜香紙包骨', '2016-07-17', '一撕開牛油紙就聞到排骨的香味，上面粘滿蒜粒，一口咬下去，汁多肉嫩，夾雜著蒜香味！', '1小時', '2人'),
(38256, '夏日Smoothie三重奏', '2016-07-12', '用各式的花樣玻璃杯去配搭你的飲料！自己試試動手做飲品，用超市買得到的新鮮食材及漂亮的杯子就可以做到！', '30分鐘', '2人'),
(38286, '芒果薄荷雪葩蘇打', '2016-07-14', '沒有雪糕機器也無所謂，今年夏天用攪拌機也可以做出透心涼的雪葩，配上清爽的薄荷，暑氣全消！', '1.5小時', '2人'),
(38302, '自製冷泡咖啡 + 越式凍咖啡', '2016-07-15', '不用昂貴的咖啡器材也可以做出好喝的自製冰釀咖啡！再加上簡單的材料，就可以有美味的越式咖啡陪著你過今個夏天！', '1.5小時', '2人'),
(38303, '苦瓜黃豆無花果豬骨湯', '2016-07-18', '帶苦味的蔬菜有清熱袪火的作用，最適合夏天食用，這款湯品配搭苦瓜常見的拍檔黃豆，再加入無花果乾，令湯更清甜可口。', '1.5小時', '2人'),
(38304, '冬瓜薏米豬腱湯', '2016-07-19', '冬瓜含水量高達九成，能消暑利水，是夏天清熱食材的好選擇，加上具祛濕作用的生熟薏米一起煲湯，功效就更相得益彰。', '1.5小時', '2人'),
(38305, '節瓜章魚雞腳湯', '2016-12-27', '幫你買埋餸，即開即煮！\r\n馬上選購： http://bit.ly/2K635vC\r\n節瓜是冬瓜的變種，所以有小冬瓜之稱，同樣有利水清熱功效，但性質較冬瓜平和，加上章魚滋陰健脾，雞腳強健筋骨，多喝有益。', '1.5小時', '2人'),
(38308, '涼拌香辣蒜蓉茄子', '2016-07-21', '屬性寒涼的茄子最適合夏天食用，具清熱活血之功效，茄子味道較為清淡，配搭濃香的香辣蒜蓉醬煮就最惹味了。', '30分鐘', '2人'),
(38333, '綠豆蕃薯糖水', '2016-07-23', '綠豆具清熱解毒的功效，最常配搭海帶臭草煮糖水，怕太寒涼的話，不妨改為配搭蕃薯，別有一番滋味。', '1.5小時', '2人'),
(38334, '雙色意瓜雲耳炒蝦仁', '2016-07-24', '意大利青瓜比一般青瓜皮厚水份少，煮熟來吃清甜爽脆，配搭同樣爽口的雲耳，以及味道清新的蝦仁，成為適合夏天的下飯小菜。\r\n\r\n<十五分鐘懶人版｜翠肉瓜金沙蝦仁>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：翠肉瓜金沙蝦仁', '30分鐘', '2人'),
(38343, '炭燒蜜汁豬扒三文治', '2016-07-19', '夏天總是想吃宵夜，不如自己做這個台灣很出名的炭燒豬扒三文治，還可以自己調配醬汁！', '1.5小時', '2人'),
(38354, '雞肉雜菜鍋', '2016-07-21', '晚上肚子餓？用雪櫃裡剩下的蔬菜就可以煮出一鍋美味的宵夜！', '30分鐘', '2人'),
(38367, '印度咖哩燒雞配自製百搭風味醬汁', '2016-07-22', '不需要到印度餐廳，都可以享受到經典的印度風味大餐！', '1.5小時', '2人'),
(38379, '冬菇百合炒蜜糖豆', '2016-07-25', '素食中常用到菇菌，鮮冬菇、百合和蜜糖豆同炒，不但顏色吸引，更嚐到各種材料清新鮮甜的味道。\r\n\r\n<十五分鐘懶人版｜百合豆干炒蘆筍>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：百合豆干炒蘆筍', '30分鐘', '2人'),
(38381, '蒸釀冬菇豬肉', '2016-07-27', '將冬菇反轉就像一隻小碟，釀入豬肉、馬蹄、蝦米等材料，蒸好後就像迷你肉餅，肉汁滿瀉。', '1.5小時', '2人'),
(38382, '冬菇雞肉餃子', '2016-07-28', '冬菇獨有的香味，配搭雞肉、馬蹄來做餃子餡，口感既滑且爽，除了做煎餃，放湯一樣可以啊。', '1小時', '2人'),
(38384, '節瓜瑤柱粉絲炆冬菇', '2016-07-29', '炆冬菇是屬於媽媽的味道，每個家庭都有自己的煮法，這次分享加入節瓜、瑤柱及粉絲一起炆的食譜，冬菇味道滲入節瓜之中，濃香惹味。', '1.5小時', '2人'),
(38385, '冬菇肉絲煎米粉', '2016-07-30', '將煎米粉做成薄餅狀，堆上煮得入味的冬菇肉絲，用手拿著吃的惹味煎米粉，你試過了沒有？', '1.5小時', '2人'),
(38387, '甜椒冬菇炒牛柳絲', '2016-07-31', '炒三色椒常配搭豬肉，這樣改用牛柳絲，加上味道濃香的冬菇，簡單快捷就煮好一碟色香味俱全的小菜。\r\n\r\n<十五分鐘懶人版｜雜菌牛柳粒>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：雜菌牛柳粒', '1.5小時', '2人'),
(38406, '三色雪糕冬甩', '2016-07-26', '夏天最好當然是吃凍入心的甜品，教你一次過做出3款造型超夢幻的雪糕冬甩！', '30分鐘', '2人'),
(38433, '台南鹵冬菇', '2016-07-26', '', '20分鐘', '2人'),
(38434, '豆醬醃漬西瓜皮', '2016-07-26', '', '20分鐘', '4人'),
(38435, '法式紙包焗三文魚', '2016-07-26', '', '30分鐘', '2人'),
(38436, '焗洋蔥花', '2016-07-26', '', '30分鐘', '2人'),
(38443, '自製雲呢拿波本威士忌雪糕＋創意新地杯', '2016-07-29', '沒有雪糕機，也不需辛苦重複攪拌，也可以做出香濃口感的雪糕，還可以用自己做的新地杯盛著吃！', '1.5小時', '2人'),
(38467, '鹽麴牛扒配和風沙律', '2016-08-01', '醃牛肉不宜用鹽，想增添鹹味不妨加入鹽麴，鹽麴不但是調味料，更能令肉質鬆軟。配搭味道清新的和風沙律，就成為豐富晚餐。', '1小時', '2人'),
(38468, '三色椒炒鹽麴蜜糖豬頸肉', '2016-08-04', '用鹽麴醃肉不但令肉質鬆軟，更可以肉質多一份甘甜味，這道三色椒炒鹽麴蜜糖豬頸肉色彩豐富吸引，味道亦非常下飯。\r\n\r\n<十五分鐘懶人版｜豉椒香蒜炒豬頸肉>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：豉椒香蒜炒豬頸肉', '1.5小時', '2人'),
(38469, '鹽麴麵豉煎三文魚飯', '2016-08-03', '鹽麴取代鹽用來醃三文魚，會多一份甘甜的味道。煎好的三文魚配搭日本醃蘿蔔，輕輕鬆鬆就做好一份和風晚餐了。', '1.5小時', '2人'),
(38470, '鹽麴南瓜蒸肉餅', '2016-08-05', '蒸肉餅好吃又下飯，但多做幾次就覺得很悶？不如試試加入鹽麴調味，做法不但方便快捷，亦令肉餅味道更有層次。\r\n\r\n<十五分鐘懶人版｜南瓜粟米蒸肉丸>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：南瓜粟米蒸肉丸', '30分鐘', '2人'),
(38471, '奶滑芝士蘑菇鹽麴雞', '2016-08-06', '鹽麴是日本調味料，其實用來做西菜亦可，配合牛奶芝士用來煮雞髀肉，令雞肉更加滑溜。', '1小時', '2人'),
(38476, '鹽麴咖喱牛腩', '2016-08-02', '煮牛腩當然要軟腍入味才好吃，用鹽麴醃牛腩就可以讓牛腩更軟腍了。惹味的咖喱牛腩，配白飯、意粉或者麵包都可以啊！', '1.5小時', '2人'),
(38479, '鹽麴蝦仁椰菜炒意粉', '2016-08-07', '鹽麴的甘醇味道用來醃海鮮，別有一番風味，這道鹽麴蝦仁椰菜炒意粉屬西日風格菜式，試過你一定會愛上。', '1小時', '2人'),
(38524, '清蒸椰菜海老卷', '2016-08-02', '選用天然的蔬菜，不同顏色的配搭，少油的做法，在炎熱夏天帶給你一道輕食蔬菜料理，即使挑食的小孩也會愛上的海老卷。', '1.5小時', '2人'),
(38525, '香煎茄子配火箭菜', '2016-08-05', '茄子是蔬菜中的抗癌高手，其含有的龍葵鹼可以抑制消化系統腫瘤增生，對防治胃癌有一定效果。茄子的做法非常多，這次用了西餐的做法，而且零失敗！', '1小時', '2人'),
(38551, '榴槤奶凍', '2016-08-08', '奶凍是有名的意大利甜品之一，這次加了「東南亞果王」榴槤，試一試這道的簡易奶凍食譜！', '1.5小時', '2人'),
(38552, '榴槤千層班戟蛋糕', '2016-08-09', '這個免焗的甜品不但容易做，而且賣相亦很吸引，只要有耐性就能輕鬆做到。榴槤之友絕對不能錯過！', '1.5小時', '2人'),
(38553, '榴槤糯米糍', '2016-08-08', '口感煙韌軟糯的糯米糍，再配上香濃榴槤蓉餡，每一口都是夏日的味道！', '1小時', '2人'),
(38560, '蒜香牛油雞翼', '2016-04-30', '', '30分鐘', '2人'),
(38573, '焗榴槤西米布甸', '2016-08-08', '加入煙韌的西米，配上香濃的榴槤，表面焗得金黃香脆的布甸，榴槤愛好者一定要試的足料榴槤甜品！', '1小時', '2人'),
(38576, '夏日夢幻特飲', '2016-08-05', '陽光明媚的夏天又是喝飲料的好時機！教你只用蜜糖及藍莓汁就可以做出夢幻的紫色飲品！喝著這個口感冰爽、色調清新的特飲渡過這個炎熱的夏天～', '10分鐘', '2人'),
(38581, '榴槤曲奇', '2016-08-12', '作為烘焙新手食譜，曲奇的做法絕對簡單易做。想做出別具風格的曲奇？不如試一試這款味道獨特的榴槤曲奇！', '1.5小時', '2人'),
(38582, '榴槤慕絲蛋糕', '2016-08-13', '夏天，盛產榴槤的季節，榴槤是必備的季節水果。就用它做一個簡單又好吃慕絲蛋糕，即使討厭榴槤的人也會一試愛上！', '1.5小時', '2人'),
(38584, '榴槤雪糕', '2016-08-14', '想吃榴槤雪糕，不一定要去買，自己在家也可以做得到！只要有攪拌機就可以吃到香濃幼滑的自製榴槤雪糕！', '1.5小時', '2人'),
(38627, '意大利青瓜菠菜濃湯', '2016-08-09', '西式濃湯也可以低卡你知道嗎？配搭多種綠色蔬菜，想同時養顏又減肥，一定要試試看！', '20分鐘', '2人'),
(38629, '士多啤梨多多冰', '2016-08-12', '最近韓國大熱的益力多沙冰香港還未可以買，不如在家自己做！用大家由細喝到大的益力多，輕鬆做出夏天必備的消暑飲品。', '1.5小時', '4-5人'),
(38630, '泰式青咖哩大蝦', '2016-08-12', '運用各種新鮮的食材及泰式的香料，自製健康的青咖哩料理！', '20分鐘', '2人'),
(38645, '香蒜豆豉炒蜆', '2016-08-15', '蒜頭和豆豉是調味界的最佳配搭，用來炒蜆更是百吃不厭的組合，上街市買到新鮮蜆的話，不妨用這個食譜煮吧，包你回味無窮！\r\n\r\n<十五分鐘懶人版｜金不換豉椒炒蜆>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：金不換豉椒炒蜆', '1小時', '2人'),
(38646, '蒜香麻油蝦', '2016-08-16', '蝦快熟易煮，簡單用蒜頭和麻油調味，香氣已叫人垂涎三尺，沒有太多時間下廚的話，這道菜是快靚正之選。', '30分鐘', '2人'),
(38647, '香濃蒜頭粉絲雞湯', '2016-08-17', '台灣人喜歡在煲雞湯時加入蒜頭，視之為簡單的進補湯水，的確蒜頭具殺菌保健作用，這道充滿濃郁蒜香的粉絲雞湯，做法簡單，今晚就試試吧！', '1.5小時', '2人'),
(38648, '蒜香牛油番茄焗法包', '2016-08-18', '蒜蓉包是很多人喜愛的菜式，牛油和蒜香交織在一起實在是一大味覺享受，再加上番茄、芝士等材料，這道蒜香牛油番茄焗法包可會成為你的新寵？', '1.5小時', '2人'),
(38650, '蒜頭飯釀燒汁魷魚筒', '2016-08-19', '釀魷魚的菜式總是叫人充滿驚喜，這次釀入蒜頭飯做餡，軟滑米飯中帶蒜香，再配搭掃在魷魚筒上的燒汁，你又怎能錯過呢？', '1小時', '2人'),
(38652, '蒜片蜜糖炸排骨', '2016-08-19', '蒜頭作為百搭的調味食材，配搭肉類就最出色，因為能提食肉香，這道蒜片炸排骨再加上蜜糖的甜味，叫人欲罷不能。\r\n\r\n<十五分鐘懶人版｜蒜味蜜糖香烤五花肉>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：蒜味蜜糖香烤五花肉', '30分鐘', '2人'),
(38653, '蒜頭橙香焗雞', '2016-08-21', '生蒜味道刺激難聞，焗熟了卻香氣宜人，蒜香、橙香再混合雞油香，真的令人難以抗拒。', '1.5小時', '2人'),
(38693, '經典美式蕃薯批', '2016-08-16', '吃甜品也可以抗氧化！經典的美式自製烘培點心，讓你一邊享用甜品，一邊讓肌膚補充養分！', '1.5小時', '2人'),
(38708, '早餐車厘茄火雞肉丸', '2016-08-19', '選用不同種類的香料，番茄及自製的健康火雞肉丸完美配合，不用焗爐也可以做出美味又健康的創意的早餐肉丸料理！', '1小時', '2人'),
(38717, '芝心紫菜蛋卷', '2016-08-22', '煎蛋卷(玉子燒)是經典的日本料理菜式，將煎熟的蛋漿一層一層捲起來做成，這次我們加入紫菜和芝士做餡料，讓芝士溶化做成流心效果。', '30分鐘', '2人'),
(38718, '日式蕎麥麵卷', '2016-08-23', '壽司是日本美食的代表之一，紫菜卷下除了壽司飯，用來捲蕎麥麵同樣可口，而且口感更清爽，最適合在沒甚胃口的炎炎夏日享用。', '30分鐘', '2人'),
(38719, '牛油果雞蛋煙肉卷', '2016-08-24', '雞蛋、牛油果、煙肉三種材料讓你想起甚麼？早餐？土司餡料？試試將這三種食材合起來做一個切開時有驚喜的煙肉卷吧！', '30分鐘', '2人'),
(38720, '香辣蝦仁椰漿飯卷', '2016-08-25', '當墨西哥薄餅遇上馬拉椰漿飯，加上帶著甜辣香味的爽口蝦仁，拼湊出滋味的Fusion飯卷，再配合清爽的芒果蛋黃醬，是夏日的午餐之選。', '1.5小時', '2人'),
(38721, '黑芝麻卷', '2016-12-29', '黑芝麻卷是以前在酒樓常見的甜點，香港人喜歡叫它做「菲林卷」，因為其賣相與菲林很相似，小小的卷充滿芝麻香，做法不難，你也試試吧！', '30分鐘', '2人'),
(38722, '韓式粉絲雞蛋卷', '2016-08-27', '到韓國菜餐廳必吃的炒粉絲，用來做卷物同樣滋味！而且吃起來更加方便，配以充滿韓國風味的香辣蛋黃醬，一邊看韓劇一邊吃就最夾了。', '1小時', '2人'),
(38723, '蒸豬肉蛋卷', '2016-08-28', '蒸肉餅吃膩了嗎？不妨用來做蒸豬肉卷吧！混入多種材料，加上蛋皮捲起來，造型有趣可愛，小朋友也會喜歡吃啊！', '30分鐘', '2人'),
(38738, '蜂蜜菊花普洱茶凍', '2016-08-19', '茶不一定要趁熱飲！加一點創意，就可以做出晶瑩剔透的香濃普洱茶凍！', '1.5小時', '3人'),
(38769, '潮州滷水鴨髀', '2016-08-23', '潮州其中一個特色菜就是滷味，運用不同的香料，煮出簡單美味又好吃的滷水鴨髀！', '1.5小時', '2人'),
(38780, '菠菜蘑菇焗蛋', '2016-08-26', '新手都做到！怕油煙怕油彈？試試這道輕食主義的最愛，週末來一份美味的早餐！', '20分鐘', '2人'),
(38789, '燒牛肉三文治配番茄乾芝士醬', '2016-08-29', '燒牛肉三文治是美式三文治的代表，厚厚的燒牛肉滿足食肉獸的胃口，配搭味道微酸的番茄乾芝士醬和蔬菜，中和牛肉的油膩感。', '30分鐘', '2人'),
(38790, '蝦沙律牛角包', '2016-08-30', '用上不少牛油做成酥皮層的牛角包，本身已鬆化好吃，再加上豐富的蝦仁沙律餡料，賣相和味道同樣吸引。', '20分鐘', '2人'),
(38794, '麵包卷三重奏', '2016-12-26', '三文治就是上下兩片麵包夾著餡料嗎？其實捲起來也可以啊！這種麵包卷造型可愛，最適合做小朋友的午餐/小食便當。', '20分鐘', '2人'),
(38795, '焗蒜香番茄三文治配南瓜芝士醬', '2016-09-01', '做三文治常用到生番茄片，這款連同蒜頭焗香的番茄，別有一番風味，加上自製的足料南瓜芝士醬，你怎能錯過？', '1.5小時', '2人'),
(38799, '豬扒菠蘿包配蘋果芥末醬', '2016-09-02', '菠蘿包因為焗好的酥皮貌似菠蘿而得名，其實並沒有菠蘿成份，這款三文治加入真菠蘿，配搭豬扒和蘋果芥末醬，吃過的都無不讚好。', '30分鐘', '2人'),
(38805, '香辣龍蝦三文治', '2016-09-03', '近年在紐約和東京大熱的龍蝦三文治，自己在家做也可以啊！龍蝦和配菜的比例可自行調節，配搭甜中帶微辣的醬汁，海鮮迷必試！', '30分鐘', '2人'),
(38806, '叉燒炒蛋三文治', '2016-09-04', '叉燒炒蛋是一道家常菜，有想過它可以變成三文治餡料嗎？配搭創新的豉油蛋黃醬，讓你一試就愛上。', '30分鐘', '2人'),
(38808, '簡易夏日特飲', '2016-08-26', '只需要簡單材料，連攪拌機都不用，就可以做出2款特色飲品！趕快跟著食譜，配上漂亮的玻璃杯，捉住夏天的尾巴！', '1小時', '1人'),
(38818, '海南雞翼飯', '2016-08-26', '海南雞飯是一道新加坡的國菜。主要食材是雞肉和大米，主要烹飪工藝是燙煮。海南人會以白切雞的做法，同時配以雞油和浸雞水烹煮的米飯，所以在海南島俗稱為文昌雞飯。', '1小時', '2人'),
(38832, '日式味噌肥牛蓋飯', '2016-08-30', '吃剩的火鍋肉片，配上簡單的蔬菜就可以變成美味的日本風蓋飯！', '20分鐘', '2人'),
(38840, '印式咖哩鷹嘴豆燴飯', '2016-09-02', '印度特色風味，簡單快手配白飯的一人晚餐，原來印度也有「蓋飯」食譜！', '20分鐘', '2人'),
(38843, '白朱古力紅桑莓芝士蛋糕', '2016-09-26', '', '1.5小時', '4人'),
(38844, '玫瑰花奶凍', '2016-10-10', '', '1.5小時', '2人'),
(38845, '士多啤梨西柚雪條', '2016-10-24', '', '1.5小時', '4人'),
(38846, '火紅莓果雪糕', '2016-11-14', '', '1.5小時', '4人'),
(38847, '士多啤梨英式鬆餅', '2016-11-28', '', '1小時', '6人'),
(38858, '香草牛肉粒新薯串燒', '2016-09-05', '香草牛扒配薯仔除了可以是西餐主菜，有想過亦可以是BBQ的美食嗎？將牛扒粒和新薯相間串起來，兩種滋味交織起來更美味。', '1.5小時', '2人'),
(38859, '燒蛋糕伴蜜桃士多啤梨', '2016-09-06', '想為BBQ準備飯後甜品？這款燒蛋糕是小編的最愛啊！把牛油蛋糕燒到外脆內軟，配搭入口即溶的水蜜桃和香甜士多啤梨，再飽也忍不住一吃再吃。', '20分鐘', '2人'),
(38861, '墨魚蝦滑香茅串燒', '2016-09-07', '串燒不一定要用竹籤，用香茅也可以把食物串起來啊！這款墨魚蝦滑香茅串燒包含清爽、彈牙、香甜口感，讓你一試愛上。', '30分鐘', '2人'),
(38862, '咖喱三寶串燒', '2016-09-08', '香港人熟悉的咖喱三寶──魚蛋、豬皮和魷魚，是從小吃到大的小食，用來BBQ把它燒到乾身，變成另一種風味食法。', '1.5小時', '2人'),
(38863, '燒冬蔭單骨雞翼', '2016-09-09', 'BBQ怎能沒有雞翼？仍然是吃蜜糖雞翼那麼悶嗎？快來試試加入泰式元素的冬蔭口味，單骨做法讓你吃得更方便。', '1.5小時', '2人'),
(38864, '菠蘿豬肉車厘茄串燒', '2016-09-10', 'BBQ只吃肉的話很快會膩，適量加入蔬菜，口味既清新又健康，這款菠蘿豬肉車厘茄串燒，酸甜的味道很醒胃呢！', '1小時', '2人'),
(38865, '蜜糖啤酒汁雞肉串燒', '2016-09-11', '啖啖肉的雞肉串燒配啤酒，是與朋友歡聚時的最佳美食，到燒鳥店吃價錢不便宜？自己做也不難啊！加入啤酒醃製，可以令雞肉更鬆化。', '1.5小時', '2人'),
(38870, '自製三式牛油', '2016-09-02', '', '30分鐘', ''),
(38901, '韓式芝麻花生水果糖', '2016-09-06', '如果你喜歡水果甜品，你就一定要試這款韓國傳統的芝麻糖。特別添加了流行的冷凍乾燥水果，不但提升了味道及口感，還可以包成禮物盒，跟同事及朋友分享！', '20分鐘', '2人'),
(38902, '快手助眠小食', '2016-09-09', '壓力大的你，長期睡眠不足，只能藉用藥物來調整。這幾款簡單又快捷的小食，可以有助睡眠，現在就快手動手做啦！', '20分鐘', '2人'),
(38915, '抹茶紅豆缽仔糕', '2016-09-09', '', '30分鐘', '2人'),
(38921, '紅菜頭沙津配蜜糖芥末黑醋汁', '2016-09-12', '初嚐紅菜頭，用來做沙律是最受歡迎的做法，清甜的味道與其他蔬菜很易配搭。', '30分鐘', '2人'),
(38922, '紅菜頭蟹肉飯卷', '2016-09-13', '紅菜頭顏色艷麗，可以將平凡的菜式變得搶眼奪目，就好像這款紅菜頭蟹肉飯卷，賣相吸引，又多一份紅菜頭清甜的味道。', '30分鐘', '2人'),
(38923, '紅菜頭桑莓雪條', '2016-09-14', '夏天吃雪條的確透心涼，如果擔心坊間買到的雪條含色素、防腐劑，不妨自己做純天然的紅菜頭桑莓雪條，顏色和味道同樣吸引。', '1.5小時', '2人'),
(38924, '紅菜頭忌廉湯', '2016-09-15', '煮西餐來來去去都是粟米忌廉湯？你要試試這款顏色和味道都會帶給你驚喜的紅菜頭忌廉湯了。如果你想炮製素食版本，將雞湯轉成素湯就可以了。', '1.5小時', '2人'),
(38925, '朱古力紅菜頭蛋糕', '2016-09-16', '紅菜頭一般多用來做沙律或者煮湯，做甜品可以嗎？試試跟著這個食譜做朱古力蛋糕，你就知道紅菜頭做甜品也可以啊！', '1.5小時', '2人'),
(38926, '香煎帶子紅菜頭扁意粉', '2016-09-17', '紅菜頭獨有的紫紅色，是因為含有天然抗氧化物甜菜紅，具抗氧化、抗衰老的功效，亦令到這款意粉更奪目吸引。', '30分鐘', '2人'),
(38927, '紅菜頭素湯', '2016-12-29', '用紅菜頭煲中式湯水有很多變化，可以配搭不同食材，加入粟米、紅蘿蔔及腰果，既清甜，又有消脂排毒之效。', '1小時', '2人'),
(38934, '西班牙水果酒', '2016-09-13', '想喝酒又懶得出門？沒關係，快來學習一下在家也可以做出的清新怡人的自製汽酒吧~', '20分鐘', '2人'),
(38935, '自製紅石榴茶醬', '2016-09-16', '紅石榴被稱為「超級」水果。它可以幫助緊緻皮膚，加強肌肉，控制身體脂肪。亦能增強免疫系統和降低膽固醇。除了當水果吃之外，也可以自製一個沒有添加劑的健康紅石榴茶醬飲品。', '20分鐘', '2人');
INSERT INTO recipes (id, title, date, description, cooking_time, serving_size) VALUES
(38963, '三式滋味熱狗', '2016-09-16', '', '30分鐘', ''),
(38988, 'Cajun大蝦意粉', '2016-09-09', '旅遊記者Gloria Chung對於美食有強烈求知慾，從飲食記者轉做旅遊記者，從吃遍香港食店到遊歷各國搜羅更多美食故事。工作之餘，亦順道為自己的廚房添置更多工具、食材和調味料，每到一個地方就先了解當地最值得買的食材，逛逛當地的街市，把最值得買的捧回家，打開廚櫃，隨手拈來都是各國的優質食材調味料。', '1.5小時', ''),
(38990, '五彩免握飯糰', '2016-09-19', 'Onigirazu(免握飯糰)是近年流行的飯糰做法，不用模具不用特別技巧，就可以做出如三文治般的飯糰，餡料可以按個人口味轉換呢。', '30分鐘', '2人'),
(38991, '金菇豬肉卷配煎南瓜', '2016-09-20', '金菇和牛肉是經典的配搭，其實金菇配搭豬肉同樣美味呢！再加上煎南瓜做出來的便當，賣相、味道和營養兼備。\r\n\r\n<十五分鐘懶人版｜燒汁金菇豬肉卷>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：燒汁金菇豬肉卷\r\n\r\n 幫你買埋餸，即開即煮！\r\n馬上選購： https://bit.ly/2RIdWit', '30分鐘', '2人'),
(38992, '三文魚和風意粉沙律', '2016-09-21', '每到午飯時間，公司茶水間等著翻熱飯盒的人龍可長呢，下次不如準備沙律做午餐吧，省掉翻熱的時間，可以用來小睡片刻啊！', '30分鐘', '2人'),
(38993, '鮮茄燴雞扒', '2016-09-22', '番茄是很適合做便當的食材，因為經過高溫烹調，番茄會釋放更多具抗氧化功能的茄紅素，用來煮鮮茄燴雞扒，簡單又美味。', '30分鐘', '2人'),
(38994, '咖喱番茄肥牛', '2016-09-23', '要準備便當的話，家裡必定常備日式咖喱磚，因為只要加入任何蔬菜和肉類，就能煮出豐富美味的菜餚。', '30分鐘', '2人'),
(38995, '泡菜海鮮炒飯', '2016-09-24', '韓國泡菜微酸微辣的味道，無論配搭甚麼食材都很好吃，用來炒飯非常方便快捷，加上蝦仁、帶子、雞蛋及洋蔥等食材令味道更豐富。', '30分鐘', '2人'),
(38996, '壽喜燒牛肉飯', '2016-09-20', '聽到壽喜燒牛肉這道菜，感覺很專業啊！其實做法簡單得很，20分鐘就可以完成，香甜的醬汁還很下飯呢！', '30分鐘', '2人'),
(38997, '咖哩素漢堡扒', '2016-09-20', '自製素食的漢堡扒，不但高纖，又含有豐富的蛋白質。就算減肥的你，也不會流失營養啦。', '1小時', '2人'),
(38998, '經典牙買加燒雞', '2016-09-23', '經典的牙買加燒雞，雞肉加入不同的新鮮香料和柑橘類的果汁去醃製。這個別具風味的燒雞，亦可成為一道健康的菜式。', '1.5小時', '2人'),
(39034, '泡菜芝士拌飯窩夫', '2016-09-26', '近來泡菜芝士溶漿飯掀起一陣熱潮，今次將泡菜芝士拌飯從鐵板轉移到窩夫機上，烘出香脆窩巴之餘，咸香十足！', '30分鐘', '2人'),
(39038, '芝士煙肉蘑菇通心粉窩夫', '2016-09-27', '芝士通粉堪稱邪惡美食，今次用來製作外脆內軟的芝士通粉窩夫，外層金黃香脆，夾雜濃香芝士、蘑菇和煙肉，芝士迷必定對這個芝士通粉窩夫毫無抵抗力！', '30分鐘', '2人'),
(39039, '蟹餅窩夫伴牛油果醬', '2016-09-28', '蟹餅一向是極受歡迎的派對小食，有了窩夫機，更可即時在派對上跟朋友一起動動手，烘出熱辣辣的美味蟹餅窩夫，配上清新的牛油果醬，必定吃個不停！', '30分鐘', '2人'),
(39040, '大蝦窩夫棒伴芒果乳酪醬', '2016-10-02', '除了長方形窩夫，花點心思更可以窩夫機製作一口小食。將大蝦以香草炒熟後沾上麵糊，烘出一口窩夫棒，酸酸甜甜的芒果乳酪醬更襯托出蝦味！', '30分鐘', '2人'),
(39041, '格格大阪燒', '2016-09-30', '大阪燒擠上絕配的大阪燒醬和蛋黃醬，再撒上鰹魚片本來已是人間美食，一改傳統用窩夫機烘出格格紋更令大阪燒吸晴度大大提升。', '30分鐘', '2人'),
(39042, '麻婆豆腐窩夫', '2016-10-01', '今次將麻婆豆腐這道家常小菜大變身，將豆腐與惹味肉醬壓成窩夫，做法簡單又滋味，入口非常鬆軟！', '30分鐘', '2人'),
(39044, '特濃抹茶紅豆布朗尼窩夫', '2016-09-29', '平常吃到的布朗尼蛋糕多為朱古力味，今次特別為抹茶迷送上抹茶布朗尼窩夫，布朗尼口感濕潤，窩夫機烘出香脆外層，最後淋上冰凍抹茶醬，一冷一熱，層次豐富！', '30分鐘', '2人'),
(39045, '油炸鬼配煎餅蔬菜卷', '2016-09-27', '想吃油炸鬼但又怕肥膩？不如試下自己做？只需簡單材料就可以輕鬆做到，又可以控制油的份量。再配上一個蔬菜卷，可以更加解膩！早餐一於是它！', '1.5小時', '2人'),
(39047, '鐵鍋煎餃', '2016-09-30', '懷念台灣風味的餃子餡，經典的椰菜，配上薑蓉和豬肉的餡料，教你一個零失敗的技巧去煎出美味的金黃鍋貼啦！', '1小時', '2人'),
(39048, '台灣家常滷肉', '2016-09-10', '工商管理碩士出身，又是會計師，來自台灣的蘇發福曾在香港從事金融業。從一個工作狂變成全職主婦後，她發現自己對烹飪的熱情，愛上煮飯。偶然開始寫部落格經營社交網站專頁，分享當晚的晚餐和每天的生活趣事。', '1.5小時', '2人'),
(39056, '營火薯仔', '2016-09-23', '', '30分鐘', '2人'),
(39057, '惹味八爪魚炒薯仔', '2016-10-08', '甜椒粉是西班牙菜常用的調味料之一，更為美食天然染上點點紅色。炒至外脆內軟的薯粒和爽口八爪魚加入甜椒粉和檸檬汁調味，風味十足又開胃。', '30分鐘', '2人'),
(39061, '西班牙海鮮沙律', '2016-10-09', '除了熱食，西班牙下酒菜亦不乏開胃沙律。將鮮甜海鮮以檸檬及橄欖油稍腌再炒，配上各種色彩繽紛的蔬果，輕易做出清新怡人沙律。', '30分鐘', '2人'),
(39063, '蒜片蝦配脆法包', '2016-10-03', '西班牙人烹調非常喜愛用橄欖油和蒜頭。這道蒜片蝦非常易煮，巧妙地利用蝦頭逼出蝦油，再以慢火浸出蒜味，令白裏透紅的大蝦充滿陣陣蒜香，配上脆法包十分惹味！', '30分鐘', '2人'),
(39064, '西班牙芝士牛肉餡餅', '2016-10-05', '西班牙半圓餡餅源於西班牙西北部的加利西亞，餡料非常多變，由免治肉類、惹味辣肉腸至各種海鮮不等，配上各種蔬菜。這個食譜選用牛肉和芝士，濃濃肉香與芝士融和在一起，必定成為餐桌上受歡迎的佐酒小食。', '1小時', '2人'),
(39065, '西班牙辣肉腸釀蘑菇', '2016-10-04', '說到西班牙經典美食，必不可忽略味道鹹香的辣肉腸。將辣肉腸混入洋蔥和芝士，配上多汁蘑菇，口感豐富，是非常易做的一口小食。', '30分鐘', '2人'),
(39067, '早餐能量棒', '2016-09-23', '來自新加坡的Calista，從小便立志長大後要成為一位律師，卻在追夢的途中出現了嚴重的健康問題，幸而治療加上飲食上的調理令身體日漸康復。從法律系畢業後，她卻毅然放棄夢想到香港發展，推廣健康飲食——生機食物。', '1.5小時', '3人'),
(39070, '8號風球薄餅 (羅勒醬蔬菜薄餅)', '2016-09-24', '咖啡店老闆Felix Wong早就視咖啡店為第二個家，而咖啡店的廚房用具設備比真正的家要齊全得多，他甚至在這裡遇上他的太太蚊，拍拖、求婚、結婚派對，這個廚房也扮演著重要角色，這次示範的8號風球薄餅包含著他與太太的難忘回憶。', '1小時', '2人'),
(39071, '大阪燒', '2016-09-24', '設計出身的Edchi和Kelv一有空就會拍住拖四出搜尋遍佈香港各種美食，受到「相機先吃」的文化啟發，創辦了専畫美食的插畫品牌「小不啦嘰」，除了會把手繪的食評分享到社交平台，後來更為餐廳繪製餐牌或其他產品。識飲識食的倆人平日也會入廚煮餸，亦會邀請朋友一起分享美食。', '1小時', '1人'),
(39072, '台灣瓜仔肉', '2016-09-01', '鳳凰衛視主持Ivy竹幼婷，工作忙碌的她原來熱愛下廚，把廚房裝飾得猶如遊樂場一樣，再忙的日子她也不忙下廚，因為唯有自己煮的菜，才有那種叫她忘不了的台灣味。', '30分鐘', '3人'),
(39098, '車厘茄火腿芝士意式焗麵包', '2016-10-04', '經典意式風味前菜，只要40分鐘就可以做好的派對小食！廚房新手都做得到～', '40分鐘', '2人'),
(39099, '快手迷你派對漢堡', '2016-10-07', '廚房新手都做到的派對小食，只用焗爐輕鬆煮好！一個讓你避免油煎的料理～', '30分鐘', '2人'),
(39115, '一鍋熟菠菜煙肉螺絲粉', '2016-09-30', '', '30分鐘', ''),
(39140, '芝士火腿蛋奄列', '2016-10-07', '', '30分鐘', '1人'),
(39156, '一口早午餐拼盤', '2016-10-10', '一份美觀又豐富的早餐必定為新的一天注入能量。這個一口早餐拼盤就一次過滿足你三個願望，而且色彩繽紛，令人特別醒神！', '30分鐘', '2人'),
(39165, '迷你抹茶豆腐芝士凍餅', '2016-10-11', '鬆餅模不但能放入焗爐烤出各種美食，其實同樣能用作凍餅餅模，輕易做出造型滴骰的小蛋糕。抹茶的清香配上日本絹豆腐濃郁的豆味，夾雜輕盈忌廉芝士味，層次豐富！', '1.5小時', '2人'),
(39167, '芝心雞肉餅', '2016-10-15', '用鬆餅模做外國非常流行的「西式肉餅」其實既簡便又吸引！雞肉混入洋蔥和蘑菇令肉餅更多汁，包裹著半溶水牛芝士粒，配上與雞肉特別搭的龍蒿，進一步提升肉餅味道層次。', '30分鐘', '2人'),
(39169, '楓糖法式多士杯', '2016-10-16', '用鬆餅模製作這個法式多士杯令它的外型更可愛，法式多士口感軟綿綿又充滿蛋香，非常適合當午後茶點。', '30分鐘', '2人'),
(39170, '焙茶蛋撻', '2016-10-12', '除了抹茶，焙茶同樣非常受歡迎！今次特別研究出這個焙茶蛋撻食譜，用鬆餅模造型更方便，充滿牛油香的酥皮注入香濃焙茶吉士，各位甜品狂迷快來動手試試！', '30分鐘', '2人'),
(39172, '創意台灣蝦卷', '2016-10-11', '台灣各個城市都有不同風味蝦卷做法～簡單容易操作的家庭版蝦卷，體驗一下台灣經典的小食風味～', '30分鐘', '2人'),
(39174, '鹹牛肉三文治配椰菜沙律', '2016-10-14', '經典紐約的美食之一——鹹牛肉三文治。在家用焗爐都可以輕鬆做到美味的鹹牛肉，快來動手試試看，你都可以開店啦～', '1小時', '2人'),
(39200, '南瓜蓉芝士釀蜆殼粉', '2016-10-23', '這個釀蜆殼粉又精緻又易做，將甜甜的南瓜蓉混合兩種芝士釀入巨型蜆殼粉，配上經典意式番茄醬，一口一個，多重口感，必定成為極受歡迎派對食物。', '1小時', '2人'),
(39202, '奶燉鮮蔬雞肉', '2016-10-14', '', '30分鐘', '2人'),
(39216, '白汁煮青口', '2016-10-14', '', '30分鐘', '2人'),
(39256, '南瓜蘋果雞肉意大利飯', '2016-10-17', '南瓜蒸熟後口感軟綿綿，最適合加入意大利飯，更代替淡忌廉令入口更濃厚。加上蘋果和雞肉，香甜美味，充滿秋天的氣息。', '1小時', '2人'),
(39272, '南瓜芝士盅', '2016-10-18', '今次用南瓜做個傳統瑞士芝士火鍋的變奏版，在南瓜內煮溶的芝士帶陣陣白酒香氣，夾雜南瓜的香甜，用法國麵包沾著吃，別具風味。', '1.5小時', '2人'),
(39274, '南瓜糯米糍', '2016-10-19', '不用任何色素，用南瓜就可以造出造型可愛、顏色鮮豔的糯米糍，包裹著香甜南瓜蓉，是個非常健康又易做的小點心。', '1小時', '2人'),
(39275, '南瓜芝士蛋糕', '2016-10-22', '除了各種主食，南瓜更可以用來做出各種甜品，與芝士更尤其搭配。這個南瓜芝士蛋糕加入多種香料調味，提升南瓜的味道層次，酸忌廉面更令口感更豐富呢！', '1.5小時', '2人'),
(39292, '蟹黃豬肉割包', '2016-10-21', '大閘蟹季來了，想好準備自己的大閘蟹大餐了嗎？用蟹黃做一道台灣創意小吃！', '1小時', '2人'),
(39296, '三文魚五目飯', '2016-10-24', '除了可以疊煮方式製作鍋物，亦能煮炊飯。將珍珠米及糯米混合，加入昆布煮飯，口感份外軟糯，而且充滿昆布獨特的香味，令人一碗接一碗地吃。', '1小時', '2人'),
(39304, '大蜆味噌蘿蔔煮', '2016-10-25', '大蜆每年七至十月當造，趕快抓緊十月的尾巴，到街市購買肥美的大蜆，加入兩種味噌與蘿蔔同煮，是個非常好的下飯菜。\r\n\r\n<十五分鐘懶人版｜胡椒蘿蔔煮蜆>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：胡椒蘿蔔煮蜆', '1小時', '2人'),
(39306, '忌廉野菌燉雞肉', '2016-10-26', '平日煮忌廉雞肉用現成醬汁固然方便，原來用疊煮方式更能讓雞肉掛滿濃濃的忌廉，各種食材在鍋內互相調和，比一般煮忌廉的方法更香甜!', '1小時', '2人'),
(39312, '彩蔬泡菜海鮮鍋', '2016-10-29', '利用疊煮方式將海鮮與各種蔬菜互相搭配，大量洋蔥和番茄釋放水分，再加入泡菜和清酒，令味道的層次更豐富，零調味食得更健康！', '1小時', '2人'),
(39314, '簡易雪糕糯米糍', '2016-10-21', '', '1小時', '3人'),
(39316, '日式豚肉豆腐鍋', '2016-10-30', '選用蘿蔔和娃娃菜的豚肉鍋特別鮮甜，加入鰹魚高湯燉煮，帶出蔬菜和豬肉的美味。', '1小時', '2人'),
(39317, '泰式脆皮燒豬配南瓜芫茜沙律', '2016-10-25', '為萬聖節做個大餐！教你如何善用焗爐做料理，不擅長燒菜的你也可以做出美味的南瓜主菜料理！', '1.5小時', '2人'),
(39360, '雲石紋蒸蛋糕', '2016-10-28', '用蒸的方法也能做出好吃的蛋糕！蒸蛋糕口感一般比焗蛋糕鬆軟，不會像焗蛋糕那麼乾。這次教大家做出有雲石紋路作裝飾的蒸蛋糕，賣相精緻吸引，製法既方便又快捷，你都來試試！', '30分鐘', '4-5人'),
(39371, '三式腐皮壽司', '2016-10-31', '甜甜的腐皮壽司是不敗的野餐料理！花點心思放上不同的配料，吸睛之餘味道更特別，叫人心花怒放。', '30分鐘', '2人'),
(39382, '蟹子蘆筍竹輪玉子燒', '2016-11-02', '製作玉子燒其實沒那麼難！甜甜的玉子燒夾著蟹子、大竹輪和蘆筍，口感非常豐富，享用時唧上蛋黃醬份外美味。', '30分鐘', '2人'),
(39383, '豚肉生薑燒飯糰配水果串', '2016-11-01', '豚肉生薑燒是經典日本家庭菜，放在飯糰裏同樣非常美味，鮮嫩的肉香與薑汁十分搭配。吃過飯糰後來串健康的水果，更是滿足。', '30分鐘', '2人'),
(39384, '經典三式腸粉', '2016-11-01', '只要簡單的家用蒸鍋就可以快手做出三種口味經典腸粉！', '30分鐘', '2人'),
(39393, '樽仔三色冷麵', '2016-11-04', '秋風起，又是出郊外野餐的時候了。想吃清爽冷麵但怕攜帶麻煩？那便要製作這個三色芝麻冷麵了。用玻璃瓶裝起來，既衛生又方便，今個週末便嘗試一下吧！', '30分鐘', '1人'),
(39396, '清酒醉雞翼', '2016-11-05', '用清酒製作醉雞翼，散發獨特的香氣。去野餐前一晚用好放在雪櫃，第二天就可以馬上帶去跟朋友分享了，方便又快捷！', '10分鐘', '2人'),
(39397, '芥末雞絲粉皮', '2016-11-06', '除了常見的飯糰和三文治，野餐食物亦有其他選擇！日本芥末與蛋黃醬一比三的黃金比例，令這道雞絲粉皮帶點刺激的辛辣而不會嗆喉，做法簡單而且色彩繽紛，帶去野餐必定大受朋友歡迎。', '20分鐘', '2人'),
(39398, '印度羊肉燉飯', '2016-11-04', '一道非常經典的印度風味燉羊肉飯，善用琺瑯鑄鐵鍋，就可以做出美味的異國料理！', '1小時', '2人'),
(39401, '冬菇滷肉飯', '2016-11-07', '自製滷肉其實非常簡單，花生醬更是其中一個秘方，令你可以快速煮完滷肉，更散發出陣陣獨特的花生香味，非常適合「單身寡佬」藉此享受下廚樂。', '20分鐘', '2人'),
(39404, '冬蔭功炒飯', '2016-11-08', '用冬陰功醬來炒飯，加入香茅及青檸汁，十分開胃，而且一個鍋就能煮好，方便快捷，單身一族快來試這個「陰公」炒飯應應節！', '20分鐘', '2人'),
(39406, '芝士豬頸肉公仔麵', '2016-11-09', '公仔麵是不少人家中的常備糧食，今次教大家自製香濃芝士汁撈公仔麵，配上肉汁豐富的煎豬頸肉，一「芝」公也吃得開懷暢快。', '20分鐘', '2人'),
(39410, '孜然單骨雞翼配炒薯粒', '2016-11-12', '用孜然粉來醃雞翼非常惹味，將雞翼一分為二食得更方便，配上炒薯粒就成為簡單又豐富的一人晚餐，再來杯冰凍啤酒，「孜然」一身同樣食得滿足！\r\n\r\n<十五分鐘懶人版｜孜然雞翼>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：孜然雞翼', '1小時', '1人'),
(39411, '雙菇鰻魚炒烏冬', '2016-11-13', '光棍節當然不會要大家虧待自己，加入鰻魚與雙菇炒烏冬，做一份豪華又易煮的晚餐，不再「菇」伶伶！', '20分鐘', '1人'),
(39415, '甜羅勒醬燒忌廉蘑菇', '2016-11-08', '忌廉創意搭配印度尼西亞甜醬油，加上了牛油的濃郁風味烹製一道創意料理，讓你的蘑菇不再單調，一起動手試試看～', '1小時', '2人'),
(39427, '薑汁檸檬梳乎厘', '2016-11-10', '特別用了薑及香茅2種香料，製作了一款健康的梳乎厘，就算家裡沒有焗爐也可以做的一道甜品！', '1小時', '4人'),
(39430, '紫薯鮮奶撻', '2016-11-11', '新出的紫薯鮮奶再加一點創意，就可以做出美味香濃的紫薯鮮奶撻！紫薯控一定不能錯過！', '1小時', '2人'),
(39445, '南乳燒雞脾', '2016-11-14', '燒雞脾可謂無男人不愛，用南乳來醃更是惹味十足，做法非常簡單，肉嫩又多汁！', '30分鐘', '3人'),
(39457, '鑊仔薯仔牛肉粒', '2016-11-15', '除了炒蜆、西檸雞和中式牛柳等，到大排檔必點美食一定少不了薯仔牛肉粒，牛肉粒肉味香濃，配上香口薯粒，「佬味」十足！\r\n\r\n<十五分鐘懶人版｜薯仔蜜椒炒牛柳>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：薯仔蜜椒炒牛柳', '1小時', '2人'),
(39458, '部隊鍋', '2016-11-16', '看了一堆韓劇，最常見的經典菜餚——部隊鍋！你知道它的由來嗎？經典的味道吃過嗎？', '30分鐘', '4人'),
(39460, '乾炒牛肉腸粉', '2016-11-16', '說到男人的浪漫，乾炒牛河定是象徵之一。今次搞搞新意思，用腸粉代表河粉，同樣鑊氣十足，均勻地沾滿醬汁，絕對比得上茶餐廳的乾炒牛河！', '1小時', '2人'),
(39462, '枝竹火腩煲', '2016-11-19', '枝竹吸盡醬汁和火腩的精華，火腩炆煮後更腍更香，位列男人的浪漫榜上，實在當之無愧。\r\n\r\n<十五分鐘懶人版｜時菜枝竹炆豆腐>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：時菜枝竹炆豆腐', '30分鐘', '4人'),
(39465, '脆皮德國豬手配蜜糖芥末醬', '2016-11-20', '幾個男人聚頭時，德國豬手與啤酒簡直是首選美食。其實要令到豬手皮脆並不難，只須在烤焗期間不斷掃上啤酒，就能保證焗到皮脆肉嫩了。', '1小時', '3人'),
(39472, '滋味雙色薯脆片', '2016-11-18', '想輕鬆在家製作薯片？現在你也可以！用微波爐就可以把蕃薯和紫薯變成鹹香薄脆的滋味雙色薯脆片，味道讓人雙倍驚喜。你們也可以按個人喜好灑上鹽、糖或甜椒粉調味！', '30分鐘', '1人'),
(39478, '經典韓式海鮮煎餅配醃洋蔥', '2016-11-18', '（Haemul Pajeon해물파전만들기＆ Yangpa Jangajji 양파장아찌만들기）\r\n韓國街頭常見的파전，也就是煎餅的意思，會配上很多不同配料一起吃，這一款最適合送酒的海鮮煎餅，自製的麵漿配上新鮮食材，再來一杯瑪格利酒，今年的初冬就這樣犒賞自己一下吧～', '1小時', '2人'),
(39508, '韓式羽衣甘藍海鮮煎餅', '2016-11-21', '將羽衣甘藍加入韓式煎餅，不但大大減低其青澀味，吃起來香脆可口，做法十分簡單！', '1小時', '4人'),
(39511, '海鹽香醋羽衣甘藍脆片', '2016-11-22', '這個羽衣甘藍非常易做，裹上橄欖油、海鹽和白醋，無須油炸口感卻十分香脆，當作零食代替薯片適合不過。', '20分鐘', '1人'),
(39516, '沙茶牛肉炒羽衣甘藍', '2016-11-23', '用羽衣甘藍同樣可以煮出家常小菜！加入牛肉及沙茶醬同炒，非常惹味。', '30分鐘', '2人'),
(39517, '經典胡桃批', '2016-11-22', '感恩節的經典菜色之一，不過也是一個考驗你的烘焙技術的食譜，手把手教你自製批點技巧～', '1小時', '6人'),
(39526, '羽衣甘藍豬肉餃', '2017-01-28', '將羽衣甘藍加入豬肉和蝦仁來包餃子，口感豐富又多汁，營養價值特別高，與微辣的蘸醬非常合配。', '1小時', '2人'),
(39530, '羽衣甘藍煙肉炒飯', '2016-11-27', '將羽衣甘藍與煙肉配搭來炒飯，帶點咸香之餘，非常方便快捷。', '20分鐘', '2人'),
(39531, '燒烤火雞髀', '2016-11-25', '感恩節經典菜色之一——火雞大餐！擔心沒有豪華焗爐來做全雞大餐，還是擔心吃不掉一隻火雞？教你最簡單的做法煮出應節料理！', '1.5小時', '5人'),
(39536, '手打奶泡玫瑰奶茶', '2016-11-25', '', '30分鐘', ''),
(39544, '蜜桃沙律豬扒', '2016-11-28', '沙律豬扒最重要在於用黃金比例調出的沙律醬。蛋黃醬加入香甜的煉奶，酸酸甜甜，好開胃！', '30分鐘', '2人'),
(39545, '蘋果酒烤黑豚豬扒', '2016-11-29', '黑豚豬扒比起一般豬扒脂肪較多，肉質更軟腍，掃上蘋果酒醬來烤，香甜又帶酒香。', '1小時', '2人'),
(39546, '鹽麴厚切豬扒伴炒雜菜', '2016-11-30', '鹽麴的鹹味較溫和，而且含有酵素，用來醃肉肉質特別鬆軟，味道層次更豐富。', '30分鐘', '2人'),
(39554, '糖醋洋蔥豬扒', '2016-12-03', '糖醋排骨吃得多，其實用來煮豬扒同樣美味無窮，吃起來啖啖肉，最適合下飯！\r\n\r\n<十五分鐘懶人版｜鮮茄洋蔥豬扒>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：鮮茄洋蔥豬扒', '30分鐘', '2人'),
(39555, '乾炒黑椒豬扒意粉', '2016-12-04', '乾炒豬扒意粉必定出現在茶餐廳餐牌，充滿鑊氣，加入黑胡椒同炒更香！', '30分鐘', '2人'),
(39563, '日式風味牛扒粒', '2016-11-29', '超級市場琳瑯滿目的日式調味料，你認識哪幾款？又會用哪幾款？這款經典的日本燒肉汁，讓你快手做出美味的骰子牛扒粒～', '30分鐘', '2人'),
(39582, '黑松露脆條', '2016-12-02', '', '30分鐘', '1人'),
(39584, 'Biangbiang麵', '2016-12-02', '自製無添加的陕西麻辣香料辣椒油，加上一碗功架十足的「Biangbiang麵」！', '1小時', '2人'),
(39599, '一口牛油果帶子多士', '2016-12-05', '清香的菠菜葉鋪上滿滿的牛油果泥，豐滿的扇貝丁，一口一個吐司是不是給你不一樣的味覺體驗呢~', '20分鐘', '3人'),
(39600, '流心芝士煙肉薯波', '2016-12-06', '香脆的土豆泥包裹著流心芝士煙肉，配上富肉香的培根，金黃色的薯球在派對中也非常惹人愛哦，愛吃芝士的你快來試試吧~', '30分鐘', '4人'),
(39602, '黑啤蜜糖燒豬肋骨', '2016-12-07', '燒豬肋骨是必備的不敗派對食物！派對前一晚用黑啤醃過夜，肉質更軟腍，易做又方便。\r\n\r\n<十五分鐘懶人版｜綜合香草焗豬肋骨>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：綜合香草焗豬肋骨', '30分鐘', '2人'),
(39603, '香辣蝦春卷', '2016-12-10', '派對上當然少不了香口小食！彈牙蝦滑包住微辣中蝦，造型可愛又美味。', '1小時', '3人'),
(39604, '聖誕花圈抹茶曲奇', '2016-12-11', '濃香抹茶曲奇入口鬆化，沾上白朱古力裝飾，灑上果仁碎及紅莓乾，吸睛之餘口感及豐富。', '1小時', '4人'),
(39609, '薯蓉芝士麵包卷配蜜糖肉桂牛油', '2016-12-07', '自己搓揉、焗製的麵包，加入了香甜的薯蓉及濃郁的水牛芝士，再配上完全自製的蜜糖肉桂牛油，今個週末一於吃它做早餐！', '1.5小時', '8人'),
(39623, '八爪魚香腸', '2016-12-09', '', '10分鐘', '1人'),
(39639, '泰式辣炒肉碎蓋飯', '2016-12-12', '這道泰式辣炒肉碎蓋飯非常易煮，而且香氣十足，用上九層塔葉及各種調味料，令人吃個不停！\r\n\r\n<十五分鐘懶人版｜泰式香葉炒肉碎>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：泰式香葉炒肉碎', '30分鐘', '2人'),
(39646, '蝦肉餅蓋飯', '2016-12-13', '蝦肉餅肉汁鮮甜，加入蝦仁粒及洋蔥碎令口感更豐富，配上甜豉油汁，易做又美味！', '30分鐘', '2人'),
(39648, '沖繩塔可飯', '2016-12-14', '說到塔可飯，大家可能會想起墨西哥，但其實它的起源地是沖繩。將免治牛肉炒香，鋪上白飯，加上番茄、牛油果和蛋黃醬，十分開胃。', '30分鐘', '2人'),
(39654, '韓式辣炒豬肉蓋飯', '2016-12-17', '將豬肉片及配料預先加入韓式辣醬、蜜糖及辣椒粉等醃，直接下鍋炒熟就可以上碟，簡單之餘非常惹味！', '30分鐘', '2人'),
(39655, '月見蔥花牛蓋飯', '2016-12-18', '「月見」，即料理內的溫泉蛋和特色醬汁。配上香濃多汁的牛肉和蔥花，就成為簡單又美味的蓋飯了！', '30分鐘', '2人'),
(39676, '簡易焦糖醬', '2016-12-16', '', '30分鐘', '1人'),
(39696, '忌廉薯仔濃湯', '2016-12-19', '這道薯仔濃湯入口非常幼滑，加入炒香的洋蔥碎煮更香甜美味，帶點煙肉的咸香，十分暖胃。', '30分鐘', '2人'),
(39699, '蟹肉牛油果他他', '2016-12-19', '車厘茄、蟹肉和牛油果的三層他他非常易做又開胃，顏色配搭更充滿聖誕氣氛！', '20分鐘', '2人'),
(39701, '檸檬蜜糖烤春雞', '2016-12-20', '將混合檸檬皮及香草的牛油塗勻整隻春雞，令味道分佈更均勻，肉嫩皮香。蔬菜吸盡雞肉的精華，份外美味。', '1小時', '2人'),
(39703, '焗海鮮闊條麵', '2016-12-20', '白汁其實非常易煮，配上掛汁的闊條麵和炒香的海鮮，就是個不敗的主菜！', '30分鐘', '2人'),
(39704, '紅莓麵包布甸', '2016-12-21', '完美的聖誕大餐當然要以一道溫暖的甜品作結，麵包充分吸收蛋汁，焗出來入口軟綿綿，甜度適中。', '30分鐘', '2人'),
(39737, '香草風琴焗薯', '2016-12-23', '', '30分鐘', ''),
(39753, '霸王煎餅', '2016-12-27', '來自經典德國傳統的煎餅，傳統原味只需配上牛油、雜莓及糖粉就可以享用。今次加了朱古力，喜歡朱古力的你也可以享受這道煎餅料理！', '30分鐘', '4人'),
(39787, '南乳蓮藕燜豬手', '2017-01-02', '南乳的香味，爽口的蓮藕，腍滑的豬手，結合在一起真是絕配！蓮藕去燥滋陰，豬手的膠原蛋白豐富，既美容又營養均衡。\r\n\r\n<十五分鐘懶人版｜南乳蓮藕炆排骨>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：南乳蓮藕炆排骨', '1.5小時', '2人'),
(39822, '黃耳淮山舞茸菇湯', '2017-01-03', '黃耳，又稱桂花耳，有豐富膠質，能潤肺養顏；而舞茸菇則可以提高身體免疫能力。這個湯水有抗衰老、養顏潤膚及防癌等功效！', '1.5小時', '3~4人'),
(39831, '瑤柱雞肉栗子飯', '2017-01-04', '栗子不僅美味，還是冬季養生的佳品！板栗味甘性溫，有「益氣補脾、厚腸胃、補腎強筋、活血止血」的作用。冬天氣溫漸降，吃個暖呼呼的瑤柱雞肉栗子飯就最好了！', '1小時', '2-3人'),
(39835, '鮮淮山蒸肉丸', '2017-01-05', '秋冬季節，早晚溫差變化大，天氣乾燥，吃淮山就能補脾養胃、滋陰養燥，增強抵抗力，最適合經常熬夜、少眠、皮膚乾燥的人。嫌淮山味道略為清淡，用來做肉丸就再適合不過了。\r\n\r\n<十五分鐘懶人版｜南瓜粟米蒸肉丸>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：南瓜粟米蒸肉丸', '30分鐘', '2~3人'),
(39843, '桃膠燉鮮奶', '2017-01-07', '桃膠其實是桃樹分泌的樹脂，有豐富的植物蛋白，滋陰養顏。只需要簡單幾個步驟，就能享用滋補又養顏的甜品了！', '30分鐘', '2~3人'),
(39849, '棉花糖花生醬撻', '2017-01-06', '想焗撻又怕搓皮麻煩？教你用棉花糖及方包輕鬆做出美味的甜品！', '30分鐘', '2人'),
(39852, '杞子蟲草花蒸排骨', '2017-01-08', '蟲草花性平、味甘，有補肺腎、止咳嗽、益虛損、養精氣的功效。杞子蟲草花蒸排骨，做法簡單，既滋補，味道又鮮美！\r\n\r\n<十五分鐘懶人版｜蟲草花姬松茸蒸雞>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：蟲草花姬松茸蒸雞', '30分鐘', '2人'),
(39861, '白蘿蔔炆雞翼', '2017-01-09', '先將雞翼醃過及炒香以保留肉汁，再與蘿蔔及甘筍一同炆煮，雞翼份外入味，令人吃個不停。', '1小時', '2~3人'),
(39868, '白蘿蔔魚鬆粉絲煲', '2017-01-10', '煎香的魚鬆配上香甜白蘿蔔，加上粉絲吸盡湯汁精華，煮法簡單又美味！\r\n\r\n<十五分鐘懶人版｜魚腐勝瓜粉絲煲>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：魚腐勝瓜粉絲煲', '30分鐘', '2~3人'),
(39873, '醬油燉白蘿蔔', '2017-01-11', '想去除白蘿蔔的苦澀味，原來非常簡單！只要先將白蘿蔔與白米一同滾煮，白米的澱粉能中和白蘿蔔澀味。再加入各種調味料燉煮，就成為一道暖心的家常菜了！', '30分鐘', '2~3人'),
(39877, '柚香白蘿蔔蓉冷麵', '2017-01-12', '蘿蔔除了用來炆煮，其實刨成蓉亦有很多變化！加入柚子醋調味，特別開胃，非常適合做冷麵的醬汁。', '20分鐘', '1~2人'),
(39898, '泡菜芝士釀蝦卜', '2016-03-07', '', '1小時', '2人'),
(39899, '番薯鱸魚湯', '2016-03-14', '', '1小時', '2人'),
(39900, '粟米熱狗', '2016-03-21', '祖堯教煮', '1小時', '2人'),
(39904, '綠茶瑞士卷', '2016-04-11', '祖堯教煮', '1.5小時', '1人'),
(39927, '涼拌烤紅菜頭', '2016-08-15', '祖堯教煮', '30分鐘', ''),
(39944, '沙嗲白蘿蔔牛柏葉', '2017-01-14', '先將牛柏葉汆水再過冷河，最後才加入白蘿蔔拌勻，既能保持牛柏葉爽口，又能吸盡沙嗲汁和白蘿蔔的香味，十分惹味又好下飯。', '20分鐘', ''),
(39945, '溏心蛋', '2017-01-13', '很人吃拉麵都會加溏心蛋，除了賣相更好看，味道也會豐富很多！', '1.5小時', '1人'),
(39946, '韓式辣牛肉白蘿蔔湯', '2017-01-15', '這道辣牛肉蘿蔔湯是韓國家庭冬天常煮的料理，辣味溫和，加上牛肉濃濃的肉香及蘿蔔的香甜，十分滋味。', '30分鐘', '3人'),
(39951, '吉祥炆長壽伊麵', '2017-01-16', '喜慶日子少不了會有伊麵登場；加上蠔油、叉燒、乾冬菇及韭黃的這個組合可真是親民得來又好意頭的賀年家常菜呢！', '10分鐘', '2人'),
(176894, '富貴炒飯', '2017-01-17', '幫你買埋餸，即開即煮！\r\n馬上選購： http://bit.ly/2K4OoZF\r\n相信很多人都認同健康就是財富吧？！這次的食譜為了更健康，特意只用上蛋白，並加入了大量菜心莖，不知這版本又合不合你的心水呢？', '10分鐘', '1人'),
(176897, '竹報平安雲腿卷', '2017-01-18', '這一道看似酒樓才會有的菜式，原來在家中煮亦非常簡單容易。五個步驟就能做出這精緻的賀年菜，要跟著試試嗎？', '10分鐘', '2人'),
(176901, '韓式三文治', '2018-01-22', '早餐只會吃多士、火腿通、炒麵？讓Norma教你做美味韓式三文治！以後的早餐一於是它！', '20分鐘', '1人'),
(176902, '風生水起撈得喜', '2017-01-16', '', '30分鐘', '2人'),
(176912, '腐皮福袋', '2017-01-19', '腐皮福袋有種神秘魔力，是男女老幼都喜愛的賀年菜！又精緻又美味，新年做給親友吃的話一定令人倍感窩心！', '20分鐘', '3人'),
(176973, '香蒜牛油黃金蝦', '2017-01-21', '新年又有甚麼能比一家人聚在一起歡笑迎新更開心？快來跟我們一起當「大廚」，為家人送上這道又好意頭又好味的菜式，齊齊「笑蝦蝦」吧！', '20分鐘', '3人'),
(176974, '桂花蜜糖煎金蠔', '2017-01-22', '中菜一般都讓人聯想到是鹹味的菜式；假如想轉轉口味或來一點甜的，不妨可以試試這個加入了蜜糖的煎金蠔，相信定能為你和家人帶來驚喜！', '10分鐘', '2人'),
(176976, '奶油啤酒（無酒精）', '2017-01-20', '主題樂園推出的一款奶油啤酒極受歡迎，現在就教你輕鬆做出熱和冰的奶油啤酒！', '30分鐘', '2人'),
(176983, '淮山小米藜麥粥', '2017-01-23', '', '1小時', '2人'),
(176988, '五行蔬菜粥', '2017-01-23', '大時大節難免會吃得太多，想清清腸胃時就會想到要吃粥！這個時候「五行蔬菜粥」是個很好的選擇，健康得來又不肥膩！', '1小時', ''),
(176989, '泡菜豬肉粥', '2017-01-24', '平時吃的粥都是比較清淡一點的，這次為大家介紹一款味道較濃的「泡菜豬肉粥」。這個食法在韓國也很常見，每一啖都充滿了泡菜的獨特味道，叫人難忘。', '1小時', '2人'),
(176990, '瑤柱螺頭瘦肉粥', '2017-01-25', '讓瑤柱粥升級！在瑤柱粥中加入螺頭和瘦肉，除了可以令味道變得更有層次，同時也提供了多種不同的口感呢！', '1.5小時', '2人'),
(176991, '南瓜鮮蜆粥', '2017-01-26', '平時常見的南瓜其實也是超級食物呢！能抗老、防癌又好味。這次用它來煮蜆粥，鮮甜口味定能為你帶來驚喜呢！', '1小時', ''),
(176992, '雪耳蘋果瘦肉粥', '2017-01-28', '名字聽起來就很滋補了！養陰補肺的雪耳加上蘋果豐富的礦物質和維生素，是女生們必試之選！', '1小時', ''),
(176993, '金銀帶子粥', '2017-01-29', '帶子粥做法一點也不難；留起帶子，把全部材料都倒進鍋裡煮30分鐘，最後加入帶子稍稍煮一下，幾個步驟就完成啦～要試試嗎？', '1小時', ''),
(176994, '木瓜燉雪燕', '2017-01-30', '木瓜燉牛奶就聽得多，這次轉一轉材料，來燉雪燕！被譽為「平民燕窩」的雪燕，滋陰潤肺又排毒養顏，加上營養豐富的木瓜，絕對是小資女的美肌良品。', '30分鐘', ''),
(176995, '黑糖紅棗糕', '2017-01-31', '飲出好氣色！黑糖可以健脾暖胃，紅棗就補血調經，女生們適量地飲的話氣息會越來越好呢！', '1.5小時', ''),
(176996, '粟米魚肚羹', '2017-02-01', '粟米魚肚羹跟美肌看似沒有關係，其實不然！有「平價花膠」之稱的魚肚含有豐富膠原蛋白，讓小資女也能輕輕鬆鬆地養顏護膚！', '30分鐘', ''),
(176997, '秋葵滑蛋炒雜菌', '2017-02-02', '一個對美肌很有幫助的家常菜！所有的材料都看似平平無奇，但其實每一樣都暗藏玄機！就如秋葵，它那滑潺潺的果膠其實對皮膚很好呢！\r\n\r\n<十五分鐘懶人版｜秋葵炒雜菌 >\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：秋葵炒雜菌', '20分鐘', ''),
(176998, '紅豆薏仁牛奶粥', '2017-02-04', '想要美白的朋友不妨可以試試這個牛奶粥，其中的薏仁不但可美白，更有助消水腫。另外，牛奶亦能讓皮膚更有光澤呢！', '1.5小時', '2人'),
(176999, '蘋果雪梨雪耳素湯', '2017-02-05', '通便潤膚的雪梨和有美白功效的雪耳加在一起，這湯女生們常喝對美肌很好喔！', '1.5小時', '1人'),
(177055, '韓式海鮮墨汁粉絲', '2017-01-29', '', '30分鐘', '1人'),
(177056, '五平餅', '2017-01-27', '五平餅是日本中部的著名小食，焦香的米餅，配以醬汁和核桃的味道，你一定不能錯過！', '30分鐘', '2人'),
(177057, '香煎帶子配杏仁檸檬牛油', '2016-02-22', '', '30分鐘', '2人'),
(177089, '朱古力即食麵脆脆', '2017-02-03', '食即食麵食到悶？不如搞搞新意思，加朱古力做個口味獨特的小食脆脆！', '30分鐘', '2人'),
(177104, '泰式黃咖哩炒大蜆伴蒜蓉法包', '2017-02-06', '香濃的咖哩配上大蜆，單單是氣味和賣相上都已經很吸引。加入了紅和青兩種尖椒，定能為你的味覺帶來不一樣的刺激！', '30分鐘', '2人'),
(177108, '士多啤梨裡的芝士蛋糕', '2016-04-04', '', '1小時', '2人'),
(177109, '日式和牛漢堡扒蛋包飯', '2017-02-07', '不少人也喜歡吃日式蛋包飯，這次升級加入日式和牛漢堡扒，絕對是男生女生都一定喜歡的菜式啊！', '20分鐘', '2人'),
(177110, '韓式炆牛腩', '2017-02-08', '', '1.5小時', '2人'),
(177111, '花雕雞煲', '2017-02-09', '就是喜歡吃中式！誰說情人節一定要吃西餐？兩個人橕檯腳食雞煲也是很不錯的選擇呢～', '1小時', ''),
(177112, '蒜片韓國韓牛蘆筍炒意粉', '2017-02-10', '蒜片韓國韓牛蘆筍炒意粉', '1小時', '1人'),
(177113, '法式煎鴨胸配紅莓汁', '2017-02-11', '情人節到法式餐廳吃晚餐的話，不但要早早訂位，價格更是昂貴得叫人心痛。其實想吃法式大餐便宜又簡單，今年就跟著我們，齊來在家裡煮這個「法式煎鴨胸」吧！', '30分鐘', ''),
(177169, '日式味噌牛肉鍋', '2017-02-13', '到日式居酒屋時也會點的味噌牛肉鍋，在家中做其實超簡單。豐盛的材料不但為賣相加分，吃下肚後的滿足感更是10分滿分的10分呢！', '20分鐘', '1人'),
(177170, '咖哩豚肉湯烏冬', '2017-02-14', '香濃咖哩配上彈牙烏冬；做法超級方便，係懶人必備嘅食譜首選！', '30分鐘', ''),
(177171, '酒蒸花甲', '2017-02-15', '名字聽起來好像很難煮是吧？其實只需5個步驟，就能做出鮮味十足的「酒蒸花甲」，就是這麼簡單～', '10分鐘', ''),
(177172, '煙肉蔥花蛋飯卷', '2017-02-16', '簡簡單單用煙肉和蛋做成飯卷，味道卻是令人如此滿足。', '10分鐘', ''),
(177173, '肉碎蒸豆腐', '2017-02-18', '一道簡單又有營養的家常菜！香滑的豆腐配上肉碎的肉汁，下飯一流！', '20分鐘', '2人'),
(177174, '番茄豆腐鮮魚湯', '2017-02-19', '快速滾碗湯～城市人生活繁忙，想喝一口自家湯都不容易呢！這次帶來的番茄豆腐鮮魚湯是不錯的滾湯選擇，快捷又有「營」！', '30分鐘', '2人'),
(177182, '玫瑰花煎餃', '2018-01-23', '下星期就是情人節，還做朱古力焗蛋糕給另一半？跟Norma一起煮浪漫滿分的玫瑰花煎餃，做情人節禮物最驚喜！', '30分鐘', ''),
(177223, '魚肉碗仔翅', '2017-02-20', '生菜魚肉和碗仔翅相信令不少有選擇困難症的朋友很苦惱吧？兩溝就是最好！快來看看這個「落足料」的港式美食做法吧！', '30分鐘', '2人'),
(177224, '芝麻蝦多士', '2017-02-21', '口感一流的蝦膠，配上脆脆的白麵包；聽起來已經很吸引，再加上炒香的白芝麻，成了不得不試的港式小食。', '30分鐘', '2人'),
(177225, '咖哩蒸魷魚', '2017-02-22', '提到咖哩大家也許會馬上聯想到日式或泰式，但其實港式的咖哩味道在香港人和外國人眼中也是別有一番風味吧？！這次帶來有懷舊港式小食－咖哩蒸魷魚。', '10分鐘', '2人'),
(177226, '蛋花大菜糕', '2017-02-23', '市面上舊式的糖水鋪越來越少了，大菜糕也越來越難買到了。不要緊，讓我們來跟大家分享這經典港式甜品食譜，令大家下次想吃的時候可以自己動手做。', '1.5小時', '2人'),
(177227, '糖不甩', '2017-02-25', '「糖不甩」這一詞發音很盞鬼，據說意思是黏上糖而不會甩掉。是大人細路都很喜愛的一道傳統中式甜品。不但好食更是非常易做，不妨試試！', '20分鐘', '2人'),
(177228, '鵪鶉蛋燒賣', '2017-02-26', '買少見少的鵪鶉蛋燒賣，自己在家中做其實不難！4個步驟教你做出經典茶樓「鵪鶉蛋燒賣」。', '1小時', ''),
(177291, '焦糖牛奶燉蛋', '2017-02-24', '多款西式甜點，有不少都是長青的熱門之選。為你介紹的這款，在家中都能輕鬆做到！', '1小時', '1人'),
(177294, '手工抹茶牛奶軟糖', '2017-03-03', '軟糖不一定要買，自己做一樣可以！看看這款材料和做法都十分簡單的手工抹茶牛奶軟糖。', '30分鐘', ''),
(177307, '川貝百合燉雪梨', '2017-02-27', '川貝有化痰止咳、清熱潤燥作用，配上百合和雪梨，滋養潤肺。', '1.5小時', ''),
(177308, '桂花酒釀丸子', '2017-02-28', '甜酒釀的酒香與桂花的清香完美融合，配上口感軟糯的小丸子，成為一道經典的上海甜點。', '10分鐘', '2人'),
(177309, '百合腐竹雞蛋糖水', '2017-03-01', '將腐竹煮至溶化，如豆漿般幼滑，與雞蛋和清心安神的百合同煮，易煮又美味。', '30分鐘', '2人'),
(177310, '玫瑰花水晶糕', '2017-03-02', '這個玫瑰花水晶糕做法非常簡單，只需幾種材料，就能做出散發淡淡玫瑰花香的甜點。', '1小時', '2人'),
(177311, '桂花蜜金沙骨', '2017-03-04', '塗上桂花蜜再烤焗的金沙骨，吃罷齒頰留香，令人回味不已。', '1小時', ''),
(177312, '櫻花水信玄餅', '2017-03-05', '水信玄餅晶瑩剔透，加入櫻花，感覺更加夢幻和浪漫，配上黑糖蜜和黃豆粉享用，令人一試愛上。', '1小時', ''),
(177322, '蘆筍百合炒蝦仁', '2017-02-26', '上班一族放工後想煮一餐慰勞自己，但又怕麻煩？Norma教你煮快手好餸！\r\n\r\n<十五分鐘懶人版｜百合豆干炒蘆筍>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：百合豆干炒蘆筍', '30分鐘', '2人'),
(177328, '紅棗杮餅糖水', '2016-03-28', '祖堯教煮', '30分鐘', '2人'),
(177372, '蒟蒻素涼麵', '2017-03-06', '蒟蒻低卡又高纖，配上各種色彩繽紛的蔬菜，淋上開胃柚子芝麻沙律醬，有營又易煮。', '10分鐘', ''),
(177373, '白松露薯蓉焗大啡菇', '2017-03-07', '將白松露加入香滑薯蓉，釀入大啡菇，菌味香濃！', '20分鐘', '2人'),
(177374, '蒸木耳素餃', '2017-03-08', '不加任何肉類的餃子都一樣好吃！這個木耳素餃混合多種蔬菜及豆類製品，更加入雪菜及乾冬菇，口感和味道都非常豐富。', '30分鐘', '2人'),
(177375, '芋頭西米露', '2017-03-09', '芋頭香甜而且口感細軟，煮至溶化後與西米融合在一起，令人吃個不停。', '30分鐘', '2人'),
(177376, '焗素蛋批', '2017-03-11', '這個材料豐富的素蛋批最適合在派對餐桌上出現，除了賣相吸引，更啖啖帶有蔬菜鮮甜味。', '30分鐘', '3人'),
(177377, '素雜菜湯', '2017-03-12', '這個素雜菜湯健康又易煮，加入月桂葉及羅勒令味道更有層次，吃罷一大碗就非常飽肚。', '30分鐘', '2人'),
(177386, '燒牛扒配蒜蓉香草青汁', '2017-03-04', 'by Charmaine So', '1.5小時', '2-3人'),
(177412, '迷你薄餅', '2017-03-10', '薄餅通常都是一大班人分享，但想自私食其實也可以！試做這款迷你薄餅，最適合做下午茶小食。', '30分鐘', '2人'),
(177415, '雞肉蕎麥麵沙律', '2017-03-12', 'by Charmaine So', '1小時', '1人'),
(177423, '茶香豬手', '2017-03-13', '紅茶香氣獨特，將紅茶加入豬手一同燉煮，減低膩感，洋蔥則令醬汁更香甜。', '1.5小時', ''),
(177424, '普洱茶燻乳鴿', '2017-03-14', '除了將茶葉加入食材一同燉煮，亦可以利用茶葉的香氣做燻鴿，令菜式色、香、味俱佳。', '30分鐘', ''),
(177425, '香片炒斑球', '2017-03-15', '香片又名茉莉花茶，既帶茶味，又有花香，與石斑的鮮甜十分配搭。將石斑加入蛋白稍醃，吃起來更滑。', '30分鐘', '2人'),
(177426, '烏龍茶滷豆腐乾', '2017-03-16', '除了用來做果凍，烏龍茶還可以加入滷水做滷菜！帶有陣陣烏龍茶香的滷豆腐乾香嫩美味，非常好下飯。', '1.5小時', ''),
(177427, '梅子茶漬飯', '2017-03-18', '玄米茶有獨特的烘炒米香，用來做茶漬飯十分合適，而梅子酸酸甜甜，令茶漬飯味道更有層次。', '20分鐘', ''),
(177428, '烏龍茶香東坡肉', '2017-03-19', '用慢火燉煮五花肉，入口即溶，淡淡茶味齒頰留香。', '1.5小時', ''),
(177439, '西京燒銀鱈魚', '2017-03-12', '西京燒其實是醬料的名稱，主要用白味噌做成醃料。燒好後的銀鱈魚表面金黃，魚肉帶有淡淡白味噌的甘甜味，配白飯一流！', '30分鐘', '1人'),
(177452, '蛋白蛋黃蛋蛋卷', '2016-04-18', '祖堯教煮', '30分鐘', ''),
(177486, '芝士蒜蓉包', '2017-03-17', '香濃的蒜味，溶化的牛油，配合酥脆的麵包，要吃到美味的蒜蓉包，自己做都可以，而且非常簡單！', '30分鐘', '1人'),
(177494, '烤三文魚蔬菜藜麥沙律', '2017-03-18', 'by Charmaine So', '1小時', '1-2人'),
(177507, '台式蔥花煙肉蛋餅', '2017-03-20', '蛋餅是台灣非常經典的早餐食物，餅皮軟軟糯糯，加上蔥花特別香。', '20分鐘', '1人'),
(177508, '港式沙嗲牛肉通粉', '2017-03-21', '跟著這個食譜就能煮出茶餐廳風味的沙嗲牛肉通粉，無須加梳打粉，就能煮到惹味又肉嫩的牛肉，配上忌廉雞湯湯底，十分滿足。', '30分鐘', ''),
(177509, '美式香蕉榛子鬆餅', '2017-03-22', '用低筋麵粉做的美式鬆餅特別鬆軟，配上香蕉、香濃榛子醬和楓糖，香甜美味。', '30分鐘', '1人'),
(177510, '煙三文魚牛油果班尼迪蛋', '2017-03-23', '班尼迪蛋的精髓除了水波蛋外，香滑的荷蘭醬亦十分重要，配上健康的煙三文魚和牛油果，其實在家也能煮出咖啡店質素的早餐。', '30分鐘', '1人'),
(177511, '忌廉薯仔焗法包', '2017-03-25', '法國麵包本來就香脆可口，今次來個變奏，釀入忌廉薯仔，灑上水牛芝士，外脆內軟又惹味。', '30分鐘', ''),
(177512, '日式三文魚烤飯糰', '2017-03-26', '這個做法十分簡單，不用焗爐，只須平底鍋就能做出熱騰騰的烤飯糰。', '20分鐘', ''),
(177537, '芝士煙肉薯角', '2016-04-25', '祖堯教煮', '1小時', ''),
(177582, '水果乳酪塊', '2017-03-24', '乳酪不一定只用匙羹食，還可以切成一塊塊來吃！快來學做這款水果乳酪塊，還可以選擇不同口味和配料。', '1.5小時', '2人'),
(177583, '三文魚石狩鍋', '2017-03-26', '其實日本人也吃火鍋，加了三文魚的就是叫「石狩鍋Ishikari-Nabe」，是北海道的鄉土料理。做法簡單、味道鮮甜不油膩，最適合愛吃又怕肥的你！', '30分鐘', '1人'),
(177595, '香濃周打粟米湯', '2017-03-25', 'by Charmaine So', '1小時', '2-4人'),
(177599, '苦瓜眉豆排骨湯', '2017-03-27', '苦瓜具清熱祛濕之功，加入化濕的眉豆，令這個湯水祛濕功效更為顯著。', '1.5小時', '3人'),
(177600, '薏米綠豆沙', '2017-03-28', '綠豆和薏米是祛濕好幫手，加入果皮同煮，吃起來份外甘香。', '1.5小時', '2人'),
(177601, '檸檬薏米水', '2017-03-29', '這個檸檬薏米水清熱利尿，能改善水腫和排毒，自己煮簡單又經濟。', '1.5小時', '3人'),
(177602, '沖繩風苦瓜炒豬肉', '2017-03-30', '這道日式家庭菜特別用了味醂、清酒及日本豉油調味，苦瓜甘甘甜甜，配上豬肉片，吃起來清爽又美味。', '20分鐘', '2人'),
(177603, '金銀蒜瑤柱蒸絲瓜', '2017-04-01', '絲瓜性平味甘，能祛濕健脾、清熱去火，鋪上炒香的蒜蓉、蝦乾及瑤柱，特別惹味。', '20分鐘', '2人'),
(177604, '金針雲耳蒸排骨', '2017-04-02', '金針花性味甘平，可以清熱祛濕和去水腫，更有美肌功效，加入雲耳與排骨做蒸菜，健康又美味。\r\n\r\n<十五分鐘懶人版｜白胡椒鮮淮山蒸排骨>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：白胡椒鮮淮山蒸排骨', '1小時', ''),
(177659, '鮮奶抹茶', '2017-03-31', '抹茶的味道總令人難以抗拒，把它混入牛奶，再呷一口軟綿綿的奶泡。你都來做這款簡單又好喝的鮮奶抹茶吧！', '30分鐘', '1人'),
(177664, '魔鬼薯仔', '2017-04-03', '覺得魔鬼蛋太普通？來個變奏，跟著這個食譜來做魔鬼薯仔吧！', '1小時', '2人'),
(177665, '龍脷柳露筍卷', '2017-04-04', '用香嫩龍脷柳卷著爽脆的露筍來煎，非常易做，口感豐富。', '20分鐘', '2人'),
(177666, '法式蘑菇汁雞扒', '2017-04-05', '將經典的香濃蘑菇汁淋上嫩滑雞扒，賣相精緻又美味。', '30分鐘', '2人'),
(177667, '芝士煙肉風琴法包', '2017-04-06', '將田園法包切成風琴狀，塗上自製的香草牛油，釀入煎香的煙肉和芝士片，一出爐就香氣逼人！', '20分鐘', '2人'),
(177668, '火雞紅莓墨西哥薄餅', '2017-04-08', '甜甜酸酸的紅莓果醬與咸香的布利芝士非常相襯，加上健康的火雞胸肉，成為非常美味的墨西哥薄餅。', '20分鐘', '1人'),
(177669, '香草蜜糖芥末籽焗羊架', '2017-04-09', '這道焗法式羊架外層香脆，肉嫩多汁，做法簡單，吃起來充滿芥末和香草的香氣。', '1小時', '3人'),
(177680, '南瓜忌廉意粉', '2017-04-01', 'by Charmaine So', '1小時', '2人'),
(177689, '粉絲釀雞翼', '2016-05-09', '祖堯教煮', '30分鐘', '2人'),
(177727, '牛奶布甸', '2017-04-07', '棉花糖除了烤的好吃，做甜品一樣美味。試試把它混合牛奶，做一道美味可口的牛奶布甸。', '1.5小時', '2人'),
(177728, '冬陰功海鮮湯', '2017-11-20', '只要用上冬陰功醬，在家也能輕鬆煮到充滿泰式風味的冬陰功海鮮湯，可以媲美九龍城泰國餐館的質素！', '30分鐘', '2人'),
(177729, '參巴蝦球', '2017-11-22', '用參巴醬來炒蝦球，惹味又快捷，10分鐘內就能上桌！', '30分鐘', '2人'),
(177730, '星州辣椒蟹煲', '2017-11-24', '辣椒螃蟹醬集甜、酸、辣於一身，用來炒蟹就最適合不過，十分惹味。', '1小時', '3人'),
(177738, '香煎四季豆豆腐餅', '2017-04-17', '將四季豆切粒，加入豆腐，做成素食豆腐餅，香口又美味。', '20分鐘', '2人'),
(177739, 'XO醬豬頸肉炒荷蘭豆', '2017-04-18', '豬頸肉肉質爽口，與香脆荷蘭豆同炒特別配，XO醬令這道小菜味道更有層次。\r\n\r\n<十五分鐘懶人版｜秘製醬炆豬豬頸肉>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：秘製醬炆豬豬頸肉', '20分鐘', '2人'),
(177740, '汁燒四季豆牛肉卷', '2017-04-19', '四季豆富含蛋白質和多種氨基酸，用牛肉捲起賣相吸引，簡單又美味。', '20分鐘', ''),
(177741, '雲耳蜜糖豆炒帶子', '2017-04-20', '雲耳有很多種，其中以老鼠耳為最上乘，特別爽脆，與香甜蜜糖豆及帶子同炒，健康又易煮。', '20分鐘', '2人'),
(177742, '蝦醬荷蘭豆炒鮮魷', '2017-04-22', '荷蘭豆香甜爽脆，與新鮮魷魚加入蝦醬同炒，是一道十分惹味的家常小炒。', '20分鐘', '2人'),
(177743, '欖菜蜜糖豆炒雞柳', '2017-04-23', '其實將欖菜炒四季豆換為蜜糖豆亦可，蜜糖豆更香甜，加入雞柳就成為一道很好下飯的家常小菜。', '20分鐘', '2人'),
(177745, '青咖哩雞肉炒飯', '2017-04-10', '先將青咖哩醬和配料一同炒香，再加入白飯炒散，香辣之餘又帶椰香。', '30分鐘', '1人'),
(177746, '秋葵豬肉卷', '2017-04-11', '秋葵營養價值豐富，用豬肉片捲起，沾上自家調製、甜甜的燒汁，就成為易煮又美味的便當配菜了。\r\n\r\n<十五分鐘懶人版｜燒汁秋葵豬肉卷>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：燒汁秋葵豬肉卷', '20分鐘', '1人'),
(177747, '鰻魚散壽司', '2017-04-12', '散壽司做法十分簡單，賣相卻格外精緻，午飯時間打開便當一定令同事羨慕不已！', '20分鐘', '1人'),
(177748, '鹽麴燒鯖魚', '2017-04-13', '已去骨的鯖魚吃起來十分方便，用鹽麴和白味噌來醃健康又美味，早上只花15分鐘就能做好。', '20分鐘', '1人'),
(177749, '日式照燒雞扒', '2017-04-15', '日式照燒雞扒飯是非常易煮的日式家庭料理，放入便當亦十分合適，更可以提前醃好雞扒，早上起來花15分鐘就能做好了！\r\n\r\n<十五分鐘懶人版｜藜麥芝麻烤雞扒>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：藜麥芝麻烤雞扒', '20分鐘', ''),
(177750, '三杯牛肋條', '2017-04-16', '覺得三杯雞太普通，換做牛肋條亦很好下飯，十分惹味！\r\n\r\n<十五分鐘懶人版｜燒汁牛肋條>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：燒汁牛肋條', '30分鐘', '2人'),
(177751, '番紅花薄荷焗紅衫魚', '2017-04-08', 'by Charmaine So', '1小時', '1-2人'),
(177779, '香草烤杏鮑菇', '2017-04-14', '熱量低、纖維高的杏鮑菇，最適合做餐前小食。只要在杏鮑菇上灑上各種調味料，放入焗爐烤已經十分惹味！', '30分鐘', ''),
(177781, '意式芝士菠菜雞肉卷', '2017-04-15', 'by Charmaine So', '1小時', '2-4人'),
(177782, '月亮蝦餅', '2017-04-16', '月亮蝦餅是一種台灣小食，經油炸後，金黃色的香脆春捲皮就好像月亮一樣，所以叫做月亮蝦餅。', '30分鐘', '2人'),
(177783, '芝心釀豬扒卷', '2016-05-16', '祖堯教煮', '1小時', '2人'),
(177816, '雙重芝士烤竹輪卷', '2017-04-21', '竹輪卷除了可以來做火鍋料，更可以配合不同小食。把芝士放入竹輪卷焗至香脆，最適合用於派對或下午茶小食。', '30分鐘', '2人'),
(177818, '味噌蜜糖番薯沙律配香草沙律醬', '2017-04-22', 'by Charmaine So', '1小時', '2人'),
(177824, '淮山紅棗桂圓糖水', '2017-04-24', '紅棗味甘性溫，有護肝作用；淮山健脾益氣，加上桂圓杞子，這個糖水清甜又養肝。\r\n鳴謝：北京同仁堂', '20分鐘', '2人'),
(177825, '番薯蓮子雪耳糖水', '2017-04-25', '番薯味道香甜又養肝，加上潤肺的雪耳，是一道十分簡單的糖水。\r\n鳴謝：北京同仁堂', '1小時', '2人'),
(177826, '木耳芽菜炒肉絲', '2017-04-26', '芽菜口感爽甜，營養豐富，加入補血的木耳及豬肉同炒，就是一道簡單的家常小菜。', '20分鐘', '2人'),
(177827, '紅莓松子燕麥曲奇', '2017-04-27', '燕麥有護肝功效，加入松子製作曲奇特別健康，而這個食譜牛油比例較低，亦選用較健康的黃糖。', '30分鐘', '2人'),
(177828, '瑤柱金菇扒菠菜', '2017-04-29', '菠菜疏肝養血，春天特別適宜多吃，淋上瑤柱金菇芡汁，特別美味。', '10分鐘', '2人'),
(177829, '猴頭菇牛蒡瘦肉湯', '2017-04-30', '牛蒡養肝，猴頭菇益腸和胃，兩者都是常用湯料，加入粟米及無花果令這道湯十分清甜。\r\n鳴謝：北京同仁堂', '1.5小時', ''),
(177834, '酸辣炒三絲', '2017-11-27', '用香菇酸辣醬來炒三絲，開胃又簡便，口感豐富之餘，非常好下飯！', '40分鐘', ''),
(177835, '蝦米豆豉雞煲', '2017-11-30', '用帶微辣又充滿的鹹香的蝦米豆豉醬來醃雞髀特別惹味，豆卜吸盡醬汁精華，令人吃個不停。', '40分鐘', ''),
(177837, '雙蝦菜脯蛋炒飯', '2017-11-29', '吃膩了揚州炒飯和西炒飯，不如試試用櫻花蝦菜脯醬炒飯，爽口的菜脯令口感更有層次！', '30分鐘', ''),
(177839, '涼拌皇帝菜', '2016-05-23', '祖堯教煮', '10分鐘', ''),

(177885, '法式芝士焗扇貝', '2017-05-01', '將配料炒香後煮成香濃白醬，淋在鮮甜扇貝上，滋味無比。', '10分鐘', '2人'),
(177886, '里昂沙律', '2017-05-02', '里昂沙律調味簡單，風味卻非常傳統，是十分受歡迎的地方菜。', '10分鐘', ''),
(177887, '法式煎比目魚', '2017-05-03', '比目魚肉質細嫩，配上清新的白酒醋汁，特別開胃。', '20分鐘', '1人'),
(177888, '紅酒燉雞', '2017-05-04', '紅酒燉雞是一道十分經典的法國鄉村料理，陣陣紅酒香氣撲來，香濃美味。', '1小時', '法式,西式,晚餐,聚餐,聚会,鸡腿,培根,蘑菇,洋葱,胡萝卜,红酒,肉类人'),
(177889, '法式火腿芝士三文治', '2017-05-06', '這道香烤過的法式三文治源自法國咖啡店，通常夾著格魯耶爾芝士、白醬和火腿，是十分經典的小食之選。', '10分鐘', '1人'),
(177890, '法式焗薯批', '2017-05-07', '薄薄的薯仔片用牛奶和忌廉煮過後特別美味，加入格魯耶爾芝士更是令人吃個不停。', '1小時', '2人'),
(177900, '泰式酸辣冷麵', '2018-01-25', '天氣開始濕熱了，吃酸酸辣辣的料理最適合！ 冷麵配上自製的泰式醬料，口感清爽，非常開胃！', '30分鐘', '1人'),
(177903, '花花法式蔬菜蛋批', '2016-05-30', '祖堯教煮', '1小時', '3人'),
(177951, '茄汁煎蝦', '2017-05-08', '想逗得媽媽哈哈大笑，就為她煮這道茄汁煎蝦吧，簡單又開胃！', '20分鐘', ''),
(177952, '桑寄生蓮子蛋茶', '2017-05-09', '桑寄生性味苦平，具養顏作用，加入片糖、蓮子及雞蛋就成為一道媽媽最愛的糖水。', '1.5小時', '2人'),
(177953, '海底椰粟米紅蘿蔔湯', '2017-05-10', '海底椰具滋潤作用，這個湯水清熱潤肺，最適合用來慰勞媽媽。', '1.5小時', '2人'),
(177954, '免炸椒鹽豆腐', '2017-05-11', '平常吃到的椒鹽豆腐都經過油炸，其實只要花多一點花思和時間，就能煮出少油版本，卻同樣香口的椒鹽豆腐！', '20分鐘', '1人'),
(177955, '麻婆茄子', '2017-05-13', '相信有不少媽媽的拿手好菜都是麻婆豆腐，今次將豆腐轉成茄子，同樣惹味！', '30分鐘', '2人'),
(177956, '蒜香南乳煎雞翼', '2017-05-14', '加入南乳和蒜蓉醃雞翼，帶陣陣咸香，令人難以抗拒。', '30分鐘', '2人'),
(177963, '迷迭香提子豬扒', '2017-05-06', 'by Charmaine So', '1.5小時', '2人'),
(177971, '西班牙香辣蒜片大蝦', '2017-05-13', 'by Charmaine So', '30分鐘', '2人'),
(177974, '燕窩蛋白燉鮮奶', '2017-05-10', '母親節想不到送甚麼禮物去感謝媽媽？讓Norma教你用矜貴的燕窩，為媽媽炮製滋補又養顏的美味甜品！', '30分鐘', ''),
(178022, '泰式秋葵肉碎生菜包', '2017-05-15', '將秋葵與肉碎同炒，加入檸檬葉和魚露做成泰式風味，惹味又健康。\r\n\r\n<十五分鐘懶人版｜泰式香葉炒肉碎>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：泰式香葉炒肉碎', '20分鐘', '1人'),
(178023, '日式涼拌秋葵', '2017-05-16', '只須將秋葵略煮，加入柚子芝麻醬調味，就成為簡單的前菜了。', '10分鐘', ''),
(178024, '秋葵豆腐三文魚頭湯', '2017-05-17', '將秋葵加入三文魚頭味噌湯，令這道湯的營養價值進一步提升，賣相也份外吸引。', '30分鐘', ''),
(178025, '鹽焗秋葵小食', '2017-05-18', '若怕秋葵黏液潺潺的口感，不妨試試跟著這個食譜焗秋葵，香脆又美味。', '20分鐘', '1人'),
(178026, '秋葵釀蝦滑', '2017-05-20', '將秋葵切半釀入蝦滑，口感豐富，是一道十分易做的家常菜。\r\n\r\n<十五分鐘懶人版｜燒汁百花釀秋葵>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：燒汁百花釀秋葵', '20分鐘', ''),
(178027, '黃金秋葵', '2017-05-21', '將秋葵與鹹蛋黃同炒，為秋葵添上一份鹹香，十分好下飯。', '10分鐘', ''),
(178034, '芒果咖喱蝦', '2016-06-06', '祖堯教煮', '30分鐘', '2人'),
(178081, '紅酒燉梨', '2017-05-19', '紅酒不一定配肉類，好像這道法式甜點，只需簡單材料，就能做出賣相吸引又好吃的甜品。', '1小時', '2人'),
(178082, '彩虹米紙卷', '2017-05-21', '清爽的米紙卷裡有各種蔬菜，不但有豐富的維他命，還可以自己隨意配合喜歡的蔬果，健康又美味！可以當開胃菜或者正餐，帶去野餐也好哦～', '30分鐘', '1人'),
(178083, '燕麥朱古力曲奇', '2017-05-20', 'by Charmaine So', '1小時', '2人'),
(178092, '鮑汁雞腳', '2017-05-22', '鮑汁雞腳是中式酒樓常見的餐前小食，其實自己做亦十分簡單，快來試試看！', '1.5小時', '1人'),
(178094, '尖椒皮蛋', '2017-05-24', '這道川式小食甚受港人歡迎，其實在家也能輕鬆煮到！將青尖椒和蒜蓉炒香後加入各種調味煮成醬汁，就是米線店吃到的味道了！', '30分鐘', '2人'),
(178095, '日式涼拌茄子', '2017-05-25', '在煮茄子時加入白醋，就能令茄子保持鮮紫色，令這道前菜賣相更吸引。', '10分鐘', '2人'),
(178096, '棒棒雞青瓜卷', '2017-05-27', '將棒棒雞改頭換面，用上青瓜片捲起，再淋上香濃芝麻醬，十分開胃。', '10分鐘', '2人'),
(178097, '蒜泥白肉粉皮', '2017-05-28', '酸酸辣辣的蒜蓉醬汁，淋上煮得剛好的五花肉片和粉皮，令人吃個不停。', '10分鐘', '1人'),
(178115, '茄子素菜薄餅', '2016-06-13', '祖堯教煮', '30分鐘', '2人'),
(178123, '韓式涼拌鮑貝', '2017-05-23', '將鮮甜鮑貝加入自家調配的韓式辣醬，清甜青瓜及洋蔥，10分鐘就能做好這道小食了！', '30分鐘', '2人'),
(178126, '蜜漬檸檬', '2017-05-26', '沖飲品除了加入檸檬或青檸，還有甚麼選擇？不如試試這款蜜漬檸檬，檸檬加上蜜糖的酸酸甜甜，令人無法抗拒！', '1.5小時', ''),
(178132, '電飯煲日式蠔飯', '2016-06-20', '祖堯教煮', '1小時', '2人'),
(178135, '雙重享受咖喱飯', '2016-06-27', '祖堯教煮', '30分鐘', '2人'),
(178141, '牛油果雞肉藜麥沙律', '2017-05-29', '用牛油果做沙律能最直接吸收到它的營養，加上健康的藜麥和甜甜的紅桑子乾，令口感更豐富。', '20分鐘', '1人'),
(178142, '牛油果白桃奶昔', '2017-05-30', '熟牛油果口感幼滑，加入香甜白桃及牛奶打成奶昔，健康又美味。', '10分鐘', '1人'),
(178143, '牛油果虎蝦青醬意粉', '2017-05-31', '用牛油果來做青醬更香滑美味，拌入意粉就成為簡單的主餐了。', '20分鐘', '1人'),
(178144, '牛油果雞肉春卷', '2017-06-01', '將牛油果醬混合雞肉和各種材料包成春卷，口感豐富之餘，充滿墨西哥風味。', '20分鐘', '2人'),
(178145, '煙三文魚焗牛油果', '2017-06-03', '將牛油果切半去核，放上帶咸香的煙三文魚及雞蛋焗，就成為簡單的早餐美食了。', '20分鐘', '2人'),
(178146, '焗番薯條伴牛油果醬', '2017-06-04', '甜甜的番薯條伴以幼滑的牛油果醬，是非常受歡迎的派對小食，小朋友也會一試愛上!', '40分鐘', ''),
(178155, '滋味鹹西多', '2017-05-27', 'by Charmaine So', '30分鐘', '2人'),
(178187, '香蒜九層塔帆立貝', '2017-06-02', '海鮮是不少人的心頭好，除了清蒸，加入不同配料炒香，立即成為一道美味可口的小食。', '30分鐘', ''),
(178196, '豉油王雞翼', '2017-06-05', '這道豉油王雞翼做法簡單，而且用的豉油份量較少，卻已非常入味和上色。\r\n\r\n 幫你買埋餸，即開即煮！\r\n馬上選購： https://bit.ly/2XBqBcA', '20分鐘', ''),
(178197, '明太子蝦膠釀雞翼', '2017-06-06', '釀雞翼其實一點也不難做，只需幾個步驟就能輕易拆骨，釀入明太子蝦膠，就是完美的居酒屋小食。', '20分鐘', ''),
(178198, '單骨五香雞翼', '2017-06-07', '單骨雞翼吃起來更方便，加入五香粉醃，十分惹味。', '40分鐘', '2人'),
(178199, '韓式辣醬雞翼', '2017-06-08', '這道韓式辣醬雞翼集甜、酸、辣於一身，雞翼又多汁，令人吃得起勁。', '30分鐘', '2人'),
(178200, '芝士蒜香雞翼', '2017-06-10', '將雞翼加入蒜粉、迷迭香等香料醃，焗完非常多汁，趁熱灑上巴馬臣芝士碎，十分吸引。', '30分鐘', '2人'),
(178201, '黑啤雞翼', '2017-06-11', '雞翼用黑啤醃過後肉質特別嫩滑，更散發陣陣麥香，簡單又美味。', '1小時', ''),
(178211, '忌廉檸檬意粉', '2017-06-03', 'by Charmaine So', '30分鐘', '1人'),
(178233, '餃子皮熱狗卷', '2017-06-09', '熱狗不一定是麵包加熱狗腸，換上餃子皮，配上芝士片及熱狗腸，放入焗爐焗至香脆，最適合用作下午茶。', '30分鐘', '2人'),
(178234, '自製肉丸伴番茄醬', '2017-06-10', 'by Charmaine So', '30分鐘', ''),
(178236, '素麥樂雞', '2017-06-11', '你有多久沒和爸爸坐下來好好吃飯、聊天了？就算工作再忙、事情再多也別忘了珍惜和家人相處的時間。趁著父親節，讓Norma跟大家分享一道萬能美味下酒菜，配上啤酒，好好享受難得的親子時光吧！', '30分鐘', '2人'),
(178281, '北芪黨參烏雞湯', '2017-06-12', '黨蔘能補中益氣，健脾養心；北芪則補氣固表，加入烏雞煲湯，營養豐富。', '1小時', '2人'),
(178282, '鮮淮山蓮子排骨湯', '2017-06-13', '這個湯水十分清甜，加上鮮淮山健脾益腎，十分適合工作忙碌的爸爸進補。\r\n\r\n<十五分鐘懶人版｜鮮淮山圓肉瘦肉湯>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：鮮淮山圓肉瘦肉湯', '1.5小時', '2人'),
(178283, 'XO醬韭菜花小炒王', '2017-06-14', '韭菜花味辛性溫，有補腎的作用，加入蝦乾、魷魚等食材做小炒王，鑊氣十足！\r\n\r\n<十五分鐘懶人版｜XO醬小炒皇 >\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：XO醬小炒皇', '30分鐘', '2人'),
(178285, '廣島蠔土手鍋', '2017-06-15', '土手鍋是廣島著名的鋪鍋物，即在鍋邊塗上一層味噌，再鋪上廣島蠔及各種配料，美味又健康。', '20分鐘', ''),
(178286, '孜然烤羊肉串', '2017-06-17', '羊肉能補中益氣，開胃強身。加入孜然粉調味，特別惹味。', '40分鐘', '2~3人'),
(178287, '宮保蝦球', '2017-06-18', '蝦味甘性溫，有補腎壯陽的功效。這道宮保蝦球微辣開胃，很好下飯。\r\n\r\n<十五分鐘懶人版｜宮保雞丁>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：宮保雞丁', '20分鐘', '2人'),
(178305, '冬蔭功魚蛋', '2016-07-04', '祖堯教煮', '30分鐘', ''),
(178329, '鹽焗鵪鶉蛋', '2017-06-16', '提起香港的街頭小食，怎少得鹽焗鵪鶉蛋？只要準備一個鍋，在家一樣可以製作這款可口的街頭小食。', '1小時', '1人'),
(178338, '清雞湯底', '2017-06-19', '只需到街市買雞骨和幾種蔬菜，就能煮成雞湯，隔去油分後更可冷藏成冰粒，用於不同菜式。', '1.5小時', '3~4人'),
(178339, '海皇冬瓜盅', '2017-06-20', '趁夏日煮個消暑冬瓜盅，味道鮮甜又健康。', '1小時', '2~3人'),
(178340, '雞肉雜菌意大利飯', '2017-06-21', '煮意大利飯常常會用到雞湯，用自家製的就更健康了。雜菌香氣逼人，令人一口接一口地吃。', '40分鐘', '2人'),
(178341, '金銀蛋浸莧菜', '2017-06-22', '這道家常小菜十分易煮，加上莧菜營養豐富，快來試試看吧。\r\n\r\n<十五分鐘懶人版｜金銀蛋時菜>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：金銀蛋時菜', '10分鐘', '2人'),
(178342, '芝士雞煲', '2017-06-24', '近來許多火鍋店都推出芝士雞煲，其實自己在家煮亦不難，更可隨個人喜好調整不同芝士的比例。', '30分鐘', '2人'),
(178343, '上海菜飯', '2017-06-25', '用雞湯來煮飯特別鮮味，加入炒香過的金華火腿和爽甜的小棠菜拌勻，就煮好經典的上海菜飯了。', '20分鐘', '2~3人'),
(178351, '蘋果金寶', '2017-06-17', 'by Charmaine So', '1小時', ''),
(178352, '梅子綠茶冰鎮番茄配蕎麥麵', '2016-07-11', '祖堯教煮', '1小時', '1人'),
(178379, '麵包布甸', '2017-06-23', '用軟綿綿的麵包，來做三文治也太悶了吧？今次就用麵包，浸上蛋液，即變身成一道美味的甜品。', '1小時', ''),
(178380, '香烤水蜜桃沙律伴蜜糖青檸沙律汁', '2017-06-24', 'by Charmaine So', '40分鐘', ''),
(178382, '水果三文治', '2017-06-25', '雪櫃只有水果和麵包？直接吃又總覺得缺了什麼？不如做一份超適合夏天的「水果三文治」，清爽又開胃，口感層次多。既然要吃，就吃得精緻一點！', '10分鐘', ''),
(178398, '鹹蛋節瓜湯', '2017-06-26', '30分鐘內就能煮好這道鹹蛋節瓜湯，瘦肉鮮甜，加上鹹蛋的鹹香，不用加鹽已經十分美味。\r\n\r\n 幫你買埋餸，即開即煮！\r\n馬上選購： https://bit.ly/2NjhsSd', '30分鐘', '2~4人'),
(178399, '蒜蓉拍青瓜', '2017-06-27', '青瓜清甜爽脆，用來做涼拌菜就最適合不過，加上特調的酸辣醬汁，十分開胃。\r\n\r\n 幫你買埋餸，即開即煮！\r\n馬上選購： https://bit.ly/2XejmIi', '10分鐘', '2人'),
(178400, '冬瓜魚腩煲', '2017-06-28', '冬瓜是消暑食材之選，加入魚腩和芹菜炆煮，冬瓜吸盡醬汁精華，更是美味。', '40分鐘', '2~3人'),
(178401, '百花釀節瓜脯', '2017-06-29', '將蝦膠混合豬肉和冬菇碎釀入節瓜，成為賣相討好的宴客菜，同時是健康之選。\r\n\r\n<十五分鐘懶人版｜蒸節瓜脯 >\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：蒸節瓜脯', '20分鐘', '2~3人'),
(178402, '苦瓜櫻花蝦煎蛋', '2017-07-01', '苦瓜煎蛋是十分易做的家常菜，加入櫻花蝦更有特色，添了一份蝦的鮮香。', '10分鐘', '1~2人'),
(178403, '絲瓜鮮蜆湯', '2017-07-02', '絲瓜配上新鮮活蜆和粉絲，湯頭十分鮮甜。\r\n\r\n<十五分鐘懶人版｜蜆肉豆腐味噌湯>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：蜆肉豆腐味噌湯', '20分鐘', '2人'),
(178423, '蒸番薯藜麥飯配黑松露醬', '2016-07-18', '祖堯教煮', '1小時', ''),
(178446, '辣芽菜拌青瓜', '2017-06-30', '正餐之前，酸辣口味的東西令人特別開胃，這道辣芽菜拌青瓜最合心意，你都來學做菜這道惹味可口的前菜！', '30分鐘', ''),
(178447, '烤羊架伴雜菜配清新薄荷醬', '2017-07-01', 'by Charmaine So', '1.5小時', '2人'),
(178451, '藜麥素漢堡扒', '2017-07-03', '用藜麥和豆腐來做漢堡扒，加入番茄乾、洋蔥、芝士和意大利香草等食材，吃起來同樣十分惹味。', '40分鐘', '2人'),
(178452, '自製健康穀麥片', '2017-07-04', '怕市面上買到的穀麥不合口味？其實自己做非常簡單，更可選擇自己喜歡的堅果和乾果組合和甜度。', '30分鐘', '2~3人'),
(178453, '芒果藜麥虎蝦沙律', '2022-01-18', '藜麥煮法簡單又多變，拌入沙律配以水果和海鮮等即可，這道虎蝦沙律更是充滿夏日氣色。', '20分鐘', '2人'),
(178454, '香草野米蘑菇飯', '2017-07-06', '野米含豐富蛋白質，口感外韌內軟，混合白米，加入香草、洋蔥、甘筍同煮，健康又美味。', '30分鐘', ''),
(178455, '士多啤梨香蕉奇亞籽奶昔', '2017-07-08', '奇亞籽原為鼠尾草的種子，有助降低膽固醇，浸泡在飲品中就會發脹。這杯奶昔顏色討好，加入奇亞籽更健康。', '10分鐘', '1人'),
(178456, '彩椒藜麥焗釀番茄', '2017-07-09', '除了做沙律，可將藜麥混合色彩繽紛的燈籠椒釀入番茄，賣相更吸引。', '30分鐘', '2~3人'),
(178485, '焗洋蔥花', '2016-07-25', '祖堯教煮', '30分鐘', ''),
(178497, '日式烤飯糰', '2017-07-07', '飯糰簡單易做又快手，只要準備日本豉油、飯素等簡單材料，在家都可以做出美味的烤飯糰。', '30分鐘', '1人'),
