(178659, '合掌瓜馬蹄無花果湯', '2017-07-30', '合掌瓜疏肝解熱，配上清甜馬蹄和紅蘿蔔，就成為一道簡單下火的湯水了。', '1.5小時', '2人'),
(178665, '台式豆乳雞', '2017-07-21', '台灣高雄的豆乳雞很有代表性的料理！想吃不一定要飛去台灣，跟著Norma就可以了～', '1.5小時', ''),
