(179127, '南棗杞子桂圓茶', '2017-09-03', '此飲品具補肝腎、益脾長智之效，而且非常方便。', '20分鐘', '2人'),
(179160, '涼拌豬耳', '2018-04-30', '下酒菜之選！', '40分鐘', '2人'),
(179190, '菠菜豬膶肉片湯', '2017-09-04', '菠菜和豬膶含有豐富鐵質，而杞子則明目，是滾湯健康之選。', '30分鐘', '2人'),
