(180839, '焗早餐大啡菇', '2017-09-11', '大啡菇鮮味多汁，加上巴馬火腿的鹹香和雞蛋，就是營養豐富的早餐了。', '20分鐘', ''),
(180840, '芝士蘑菇酥皮卷', '2017-09-12', '將蘑菇和洋蔥炒香，再用酥皮捲起，灑上水牛芝士焗，是一道簡易又美味的下午茶小吃。', '20分鐘', ''),
(180841, '舞茸蟲草花素湯', '2017-09-13', '這道素湯菇味濃郁，用腰果取代肉類更健康！', '1小時', ''),
(180842, '南乳冬菇炆排骨', '2017-09-14', '用冬菇來炆排骨就最適合不過，加上南乳和酒香，很好下飯。\r\n\r\n<十五分鐘懶人版｜南乳蓮藕炆排骨>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：南乳蓮藕炆排骨', '1小時', ''),
(180843, '三杯杏鮑菇', '2017-09-16', '吃膩了三杯雞？就來做個素食版本的三杯杏鮑菇吧，同樣多汁又美味！\r\n\r\n<十五分鐘懶人版｜三杯茄子 >\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：三杯茄子', '10分鐘', ''),
(180844, '野菌濃湯', '2017-09-17', '這道野菌濃湯特別加入牛肝菌，味道更濃香！', '40分鐘', ''),
(180978, '口水雞', '2018-04-09', '集麻、辣、鮮、香於一身，肉質滑嫩，滋味勁爽，不流口水都不行。', '30分鐘', ''),
(180979, '蒜香排骨', '2017-09-21', '金黃酥脆，焦香撲鼻，外酥里嫩，叫人如何不愛它。', '20分鐘', ''),
(180996, '煙三文魚花芝士米餅', '2017-09-15', '充滿鹹香的煙三文魚，配上脆卜卜的米餅，還有味道濃郁的芝士，就成為一道創意滿分的派對小食！', '30分鐘', ''),
(180997, '清新檸檬橄欖油蛋糕', '2017-09-16', 'by Charmaine So', '1.5小時', ''),
