(181001, '馬蹄木耳蒸肉餅', '2017-09-21', '這個肉餅沒有加入肥肉同樣多汁嫩滑，加上馬蹄木耳口感豐富，是秋天必備定家常菜。\r\n\r\n<十五分鐘懶人版｜蝦米馬蹄蒸肉餅 >\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：蝦米馬蹄蒸肉餅', '1.5小時', ''),
(181002, '日式蓮藕燉肉', '2017-09-23', '蓮藕熟吃性味甘溫，能養肺滋陰、健脾益氣，加入軟腍的梅頭肉同燉，美味又健康。', '1小時', ''),
(181003, '麥冬無花果雪梨湯', '2017-09-24', '雪梨養陰潤肺，加入麥冬和無花果煲湯，就成為簡單又滋潤的湯水了。', '1小時', '4人'),
