(183994, '一鍋到底香煎羊扒', '2017-12-02', 'by Charmaine So', '30分鐘', ''),
(183995, '芝心菠菜燕麥煎蝦餅', '2017-12-02', 'by 專業營養師－高芷欣\r\n\r\n--------------------------------------------\r\n►更多\r\n新手媽媽食譜：goo.gl/oZpuwP\r\n更多育兒趣事心得小貼士：goo.gl/FfztfN\r\nDayDayCook Mom Facebook 專頁：goo.gl/grjzJ3', '40分鐘', ''),
(184021, '棉花糖摩卡', '2017-12-08', '冬天人人都喜歡手持一杯熱飲在手，既可暖身又可暖手！在家也可以調配到美味的摩卡，加上甜絲絲的棉花糖，簡單又好喝！', '10分鐘', ''),
(184031, '番茄牛腩米線', '2018-01-16', '酸甜可口的番茄加上肉慾滿滿的牛腩，這種搭配都沒有打動你的味蕾？', '1.5小時', ''),
(184061, '酥皮海鮮批', '2017-12-09', 'by Charmaine So', '1.5小時', ''),
(184095, '綠茶杏仁脆條', '2017-12-15', '臨近年尾， 少不免會在大大小小的派對製作一些小食招呼客人～這個綠茶杏仁脆條得體又易整，適合一家大細食！', '30分鐘', ''),
(184102, '棉花糖多士', '2018-02-28', '軟綿綿的棉花糖，趁熱吃還會有拉絲的效果！', '20分鐘', '');
INSERT INTO recipes (id, title, date, description, cooking_time, serving_size) VALUES
(184103, '冬至特別篇：南方湯圓 vs 北方水餃', '2017-12-19', '冬至，即是冬天到了。在這天，北方人會吃水餃，而南方人則會吃湯圓。這次一次過為你準備了水餃和湯圓，無論你喜歡吃哪種，都可以過一個愉快的冬至！', '烹飪時間', ''),
(184111, '冬菇炆鵝掌', '2017-12-18', '鵝掌吸盡冬菇和醬汁的香氣和精華，十分好下飯。', '1.5小時', ''),
(184112, '荷葉金華火腿蒸雞', '2017-12-20', '幫你買埋餸，即開即煮！\r\n馬上選購： http://bit.ly/2LQtWPw\r\n這道荷葉蒸雞賣相一流，雞件配上金華火腿和冬菇同蒸，味道更豐富。', '1.5小時', ''),
(184113, '西洋參螺片無花果湯', '2017-12-22', '這道湯滋陰潤燥，甘甜美味。\r\n\r\n<十五分鐘懶人版｜無花果海底椰瘦肉湯>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：無花果海底椰瘦肉湯', '2.5小時', ''),
(184115, '餃子皮千層麵', '2017-12-16', 'by 專業營養師－高芷欣\r\n\r\n--------------------------------------------\r\n►更多\r\n新手媽媽食譜：goo.gl/oZpuwP\r\n更多育兒趣事心得小貼士：goo.gl/FfztfN\r\nDayDayCook Mom Facebook 專頁：goo.gl/grjzJ3', '1小時', ''),
(184135, '聖誕楓糖紅莓鬆餅', '2017-12-23', 'by Charmaine So', '1小時', ''),
(184169, '冧酒生朱古力', '2017-12-22', '聖誕節快到，不少女生會製作甜品給情人，這個生朱古力只需4種簡單材料便可以在家製作得到。簡單甜品便令對方一試傾心！', '30分鐘', ''),
(184179, '柴犬丸子', '2018-02-26', '柴柴這麼可愛，當然要一口吃掉！', '30分鐘', ''),
(184270, '啫啫雞煲', '2018-01-01', '啫啫雞煲惹味而且非常好下飯，是冬天必食的煲仔菜！\r\n\r\n<十五分鐘懶人版｜啫啫雞煲>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：啫啫雞煲\r\n\r\n 幫你買埋餸，即開即煮！\r\n馬上選購： http://bit.ly/2KGmQwp', '1.5小時', ''),
(184271, 'XO醬茄子蝦乾煲', '2018-01-03', '茄子除了用來做魚香茄子煲，加入蝦乾和XO醬來煮個煲仔菜也十分惹味可口。\r\n\r\n<十五分鐘懶人版｜魚香茄子煲>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：魚香茄子煲', '1小時', ''),
(184272, '沙爹金菇肥牛粉絲煲', '2018-01-01', '這個肥牛粉絲煲是不少人到大排檔必點菜式，其實在家也能輕鬆煮到！\r\n\r\n<十五分鐘懶人版｜沙嗲金菇牛肉粉絲煲 >\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：沙嗲金菇牛肉粉絲煲 ', '30分鐘', ''),
(184277, '洋蔥牛肉鍋貼', '2018-03-20', '熱呼呼一口一個～', '30分鐘', ''),
(184283, '簡易烤焗豬柳', '2017-12-30', 'by Charmaine So\r\n\r\n--------------------------------------------\r\n►更多\r\nSo Time食譜：goo.gl/WHPmgz\r\nCharmaine的烹飪小貼士：goo.gl/wbyMgf', '1小時', ''),
(184309, '豆漿燉蛋白', '2018-01-05', '山水鮮豆漿', '30分鐘', ''),
(184318, '焙茶拿鐵', '2018-01-05', '天氣寒冷之下，喝一杯熱焙茶拿鐵立即暖入心窩。材料又簡單輕易調配，15分鐘就做好！', '10分鐘', ''),
(184319, '豆腐冬甩', '2018-03-05', '不需要複雜的技巧就能做出圓鼓鼓軟糯糯的冬甩～', '30分鐘', ''),
(184324, '海帶三文魚仙貝', '2018-01-06', 'by 專業營養師－高芷欣\r\n\r\n--------------------------------------------\r\n►更多\r\n新手媽媽食譜：goo.gl/oZpuwP\r\n更多育兒趣事心得小貼士：goo.gl/FfztfN\r\nDayDayCook Mom Facebook 專頁：goo.gl/grjzJ3', '40分鐘', ''),
(184325, '荷葉雞蒸飯', '2018-02-12', '鮮味四溢，糯米潤滑可口，雞肉的味道完全滲透到糯米之中！', '1小時', ''),
(184332, '泰式三文魚扒', '2018-01-08', '熟三文魚的奧米加-3脂肪酸有助減壓，用泰式的煮法令味道酸酸甜甜，特別開胃。\r\n\r\n<十五分鐘懶人版｜柚子蜜煎三文魚扒>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：柚子蜜煎三文魚扒', '20分鐘', ''),
(184333, '蒜香芝士香草薯角', '2018-01-11', '薯仔含有維他命 B6，有效安定神經，加入芝士和香草調味，特別惹味！', '40分鐘', ''),
(184334, '海鮮蒸蛋白', '2018-01-08', '雞蛋含有豐富蛋白質，鋪上海鮮，健康又美味。', '30分鐘', ''),
(184343, '椰菜花黃薑湯', '2018-01-06', 'by Charmaine So', '1小時', ''),
(184404, '簡易蘋果批', '2018-01-12', '平時大家都是食快餐店的蘋果批，通常經油炸而且用酥皮做，製作既繁複又不健康。今次教大家製作的蘋果批以麵包代替酥皮，方便又滋味！', '40分鐘', ''),
