(184565, '流心焦糖小蛋撻', '2018-01-26', '喜歡吃流心芝士撻的你，不如嚐試用焦糖牛奶糖製作流心焦糖小蛋撻。 無須搓蛋撻皮，方便又簡單！', '30分鐘', '6人'),
