(184602, '香烤雞軟骨', '2018-02-06', '好吃到停不下來的美味，一口一個香脆！\r\n\r\n<十五分鐘懶人版｜沙薑雞軟骨>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：沙薑雞軟骨', '30分鐘', ''),
