(184691, '蒜蓉牛油焗龍蝦', '2018-02-13', '不用到餐廳也能吃到鮮甜的焗龍蝦，易煮又吸引！\r\n\r\n<十五分鐘懶人版｜芝士焗龍蝦尾>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：芝士焗龍蝦尾', '20分鐘', ''),
(184692, '菠菜芝士焗生蠔', '2018-02-14', '生蠔鮮甜美味，忌廉醬汁十分濃香，這道焗生蠔無疑是情人節大餐頭盤之選！', '20分鐘', ''),
(184696, '日本紅豆年糕湯', '2018-02-26', '將紅豆煮至起沙，配上外脆內軟的煙韌年糕，材料簡單又美味。', '1.5小時', ''),
(184697, '紫米露小丸子', '2018-02-28', '紫米露香甜軟糯，與口感煙韌的小丸子同吃，口感更豐富！', '1小時', ''),
