(184708, '日式年糕窩夫', '2018-02-16', '平時日式年糕湯就經常吃，有沒有試過將它變成窩夫呢？做法非常簡單！', '20分鐘', '2人'),
(184717, '海鮮藜麥泡飯', '2018-02-17', 'by Charmaine So\r\n\r\n--------------------------------------------\r\n►更多\r\nSo Time食譜：goo.gl/WHPmgz\r\nCharmaine的烹飪小貼士：goo.gl/wbyMgf', '1小時', ''),
