(185245, '豆腐提拉米蘇', '2018-05-04', '零罪惡感又令人滿足的清新甜點！快來試試吧！\r\n\r\nSarah\r\n很多人認為健康飲食會令到食物變得淡而無味，Sarah則希望打破這個傳統思維。受不同的健康煮食節目啟發，Sarah致力將「健康」揉合於「美食」當中，令食物在營養均衡的同時可以保持風味，在追求健康飲食的同時平衡味覺上的享受。\r\n\r\n►更多日日煮播食譜：goo.gl/SUZWEG', '1.5小時', ''),
