(185256, '蒜片牛柳粒飯', '2018-05-09', '用蒜油的煎牛柳粒香氣逼人，牛柳肉汁豐富，很好下飯。\r\n\r\n<十五分鐘懶人版｜蒜片燒汁牛柳粒>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：蒜片燒汁牛柳粒', '30分鐘', ''),
