(185376, '豆豉辣烤五花肉', '2019-01-28', '把五花肉表面肥肉焗至顏色略焦，令肉質有嚼頭而不膩！\r\n\r\n<十五分鐘懶人版｜蒜味蜜糖香烤五花肉>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：蒜味蜜糖香烤五花肉', '30分鐘', ''),
