(185400, '瑪格麗特薄餅卷', '2018-05-25', '瑪格麗特薄餅是拿坡里的代表食物，傳統食法是捲起來食的，用餃子皮便可以製作出這個意大利傳統美食的簡易版！', '30分鐘', '3人'),
(185431, '鮮沙薑乾蔥炒雞', '2018-06-01', 'Gloria\r\n從小為家人入廚的Gloria，自小煮得一手好菜，聽到父親對她煮的菜式讚不絕口，使她更用心鑽研更多不同國家菜系的菜式，與親朋好友們一同分享美食。\r\n\r\n►更多日日煮播食譜：goo.gl/SUZWEG', '40分鐘', ''),
