(185595, '意式肉卷', '2018-06-19', '馳名的意式焗肉卷，用了肉醬做入門版，一個簡易的意大利主菜便誕生！\r\n\r\nStefanel\r\n曾居意大利超過十年，精通烹調傳統意大利菜，並透過烹飪班致力向學生推廣，多年來累積超過2000名學生，讓更多人了解意大利的飲食文化。\r\n\r\n►更多日日煮播食譜：goo.gl/SUZWEG', '1.5小時', ''),
