(185683, '健康高纖布朗尼', '2018-06-29', 'Sarah\r\n很多人認為健康飲食會令到食物變得淡而無味，Sarah則希望打破這個傳統思維。受不同的健康煮食節目啟發，Sarah致力將「健康」揉合於「美食」當中，令食物在營養均衡的同時可以保持風味，在追求健康飲食的同時平衡味覺上的享受。\r\n\r\n►更多日日煮播食譜：goo.gl/SUZWEG', '40分鐘', ''),
(185684, '蠔油炆冬菇', '2018-06-29', '冠珍蠔油皇', '30分鐘', ''),
(185686, '蟲草花蒸餃', '2018-06-30', 'by 註冊中醫師 錢穎儀\r\n\r\n--------------------------------------------\r\n►更多\r\n錢醫師的小貼士：goo.gl/9R6MkY\r\n育兒趣事心得小貼士：goo.gl/FfztfN', '40分鐘', ''),
(185704, '表情飯團', '2018-06-29', '在日常的食材中加點小新意，就可以變成一個個可愛的飯團啦！', '20分鐘', '2人'),
(185736, '香煎粟米雞肉餅', '2018-07-02', '將香甜的粒粒粟米加入香可彈牙的雞肉餅，小朋友亦會非常鍾愛！\r\n\r\n<十五分鐘懶人版｜蝦膠粟米餅>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：蝦膠粟米餅\r\n\r\n 幫你買埋餸，即開即煮！\r\n馬上選購： http://bit.ly/2NjeUU8', '1小時', ''),
(185738, '粟米紫菜蝦卷', '2018-07-02', '這道粟米紫菜蝦卷切件後賣相更吸引，粟米粒令口感十分豐富。', '30分鐘', ''),
