(185808, '虎皮鳳爪', '2018-11-05', '虎皮鳳爪是一道色香味俱全的地方名餚，屬於粵菜系。', '30分鐘', ''),
(185809, '避風塘排骨酥', '2018-10-08', '肉質鮮嫩多汁，港味十足。', '30分鐘', ''),
(185820, '榴蓮益力多班戟', '2018-08-20', '炎炎夏日，來一份榴蓮益力多班戟吧～一定能帶你享受夏日獨有的清新！', '30分鐘', ''),
(185840, '抹茶戚風三文治', '2018-07-06', '鬆軟的抹茶戚風蛋糕包裹著忌廉和紅豆蓉，一啖滿足你三個願望！\r\n\r\nAmy\r\n不單喜歡帶給身邊人歡笑，她同時喜歡將簡易食譜分享給所有人，只因她深信「笑容」和「美食」都是世界上不同人士之間的共同語言。為了與更多人分享如何運用簡易方法煮出好味道，Amy早年開設YouTube頻道，希望透過頻道令大家勇敢踏入廚房，感受煮食的樂趣。\r\n\r\n►更多日日煮播食譜：goo.gl/SUZWEG', '1小時', ''),
(185843, '意式燒肉', '2018-07-13', '意大利燒肉Porchetta，做法跟香港的大不同，通常會在市集或節日的食物車上賣，夾在三文治內同吃，配上杯啤酒就最夾啦！\r\n\r\nStefanel\r\n曾居意大利超過十年，精通烹調傳統意大利菜，並透過烹飪班致力向學生推廣，多年來累積超過2000名學生，讓更多人了解意大利的飲食文化。\r\n\r\n►更多日日煮播食譜：goo.gl/SUZWEG', '1.5小時', ''),
(185847, '櫻花蝦扒絲瓜', '2018-07-07', 'by 註冊中醫師 錢穎儀\r\n--------------------------------------------\r\n►更多\r\n錢醫師的小貼士：goo.gl/9R6MkY\r\n育兒趣事心得小貼士：goo.gl/FfztfN\r\n\r\n<十五分鐘懶人版｜蝦乾蒜蓉粉絲蒸勝瓜 >\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：蝦乾蒜蓉粉絲蒸勝瓜', '30分鐘', ''),
(185848, '雙色番薯水晶包', '2018-07-14', 'by 註冊中醫師 錢穎儀\r\n\r\n--------------------------------------------\r\n►更多\r\n錢醫師的小貼士：goo.gl/9R6MkY\r\n育兒趣事心得小貼士：goo.gl/FfztfN', '40分鐘', ''),
