(186065, '梅子香橙炆鴨', '2018-07-17', 'Lagostina Domina Vitamin 7L高速煲', '1.5小時', '3-4人'),
(186074, '芒果雙色小丸子西米露', '2018-07-18', 'Cherry\r\n不論是中西菜式或甜點，Cherry 都熱愛鑽研。雖身為90後，卻笑稱自己是名「小師奶」，愛逛超市、買餸煮飯和洗碗。在當大廚的外公和一家之「煮」的父親薰陶下，令Cherry從小便埋下了對烹飪的情意結。Cherry開設了小煮婦的個人網站和YouTube頻道，分享不同的食譜，入廚心得和經驗。在兩位煮得之父的薰陶下，Cherry學習到如何從烹飪中找到快樂。明白到簡單的「親自下廚」，是可維繫到人與人之間的感情。\r\n\r\n►更多日日煮播食譜：goo.gl/SUZWEG', '1小時', ''),
(186086, '卡通慕絲撻', '2018-07-20', 'Joanna\r\n由OL轉職到全職媽媽，Joanna最大的願望就是令家中兩個小朋友可以吃得健康快樂。在煮食過程中，她發現只要將創意注入食物當中就能增強小朋友的食慾。Joanna不但擅長製作不同卡通造型的小食甜點，亦喜歡創作新食譜，希望透過分享煮食經驗，讓更多父母樂意為小朋友煮食。\r\n\r\n►更多日日煮播食譜：goo.gl/SUZWEG', '1.5小時', ''),
(186125, '家鄉魚鰾湯', '2018-07-24', 'Gloria\r\n從小為家人入廚的Gloria，自小煮得一手好菜，聽到父親對她煮的菜式讚不絕口，使她更用心鑽研更多不同國家菜系的菜式，與親朋好友們一同分享美食。\r\n\r\n►更多日日煮播食譜：goo.gl/SUZWEG', '1.5小時', ''),
(186126, '黑啤牛肉配蘋果薯蓉', '2018-07-25', '在Lagostina高速煲（7公升）', '1小時', '3-4人'),
(186127, '涼拌手撕雞', '2018-07-27', 'Judy\r\n在職媽媽Judy從小喜愛入廚，她喜於運用不同食材研發各種食譜，除了中西菜式，多國融合菜也是她的拿手菜系之一。Judy曾在酒店當廚師學徒，並從中學習到很多有用的煮食技巧，運用在日常生活烹調當中，與家人朋友享用美食。\r\n\r\n►更多日日煮播食譜：goo.gl/SUZWEG', '1小時', ''),
