(186212, '涼拌素雞茄子', '2018-07-30', '軟腍的茄子配搭彈牙的素雞，加上酸辣的涼拌醬汁，是一道口感有層次又開胃的素菜。', '30分鐘', ''),
(186213, '皮蛋怪味雞', '2018-07-30', '怪味雞是一道四川特色冷盤，加入皮蛋後味道更加豐富，非常適合配飯或湯麵吃。', '30分鐘', ''),
(186245, '蜜桃芭菲', '2018-08-03', '做法簡單的蜜桃芭菲，不但外形美觀，而且層次豐富，是一道清新的夏日甜點。', '20分鐘', '1人'),
