(186287, '千層啤梨蘋果蛋糕', '2018-08-10', '千層啤梨蘋果蛋糕比大家，平時我哋食既蛋糕大部份係粉漿，而今日呢個蛋糕百分之80都係水果，最啱D平時冇乜時間食生果既人啦！方法超間單！\r\n\r\nStefanel\r\n曾居意大利超過十年，精通烹調傳統意大利菜，並透過烹飪班致力向學生推廣，多年來累積超過2000名學生，讓更多人了解意大利的飲食文化。\r\n\r\n►更多日日煮播食譜：goo.gl/SUZWEG', '1小時', ''),
