(186390, '低脂香蕉芒椰雪糕', '2018-08-31', 'Sarah\r\n很多人認為健康飲食會令到食物變得淡而無味，Sarah則希望打破這個傳統思維。受不同的健康煮食節目啟發，Sarah致力將「健康」揉合於「美食」當中，令食物在營養均衡的同時可以保持風味，在追求健康飲食的同時平衡味覺上的享受。\r\n\r\n►更多日日煮播食譜：goo.gl/SUZWEG', '2小時', ''),
(186393, '簡易芝士蝴蝶粉', '2018-09-07', '只要用三種材料、十五分鐘便可以完成的芝士蝴蝶粉，濃濃的芝士和奶香讓人無法抗拒！', '20分鐘', '1人'),
(186394, '琥珀糖', '2018-08-31', '能吃下的寶石！琥珀糖是日本傳統的和菓子，風乾後的口感特別。想製成不同的口味，也可將水替換成果汁、牛奶等。', '大於3小時', '2人'),
(186410, '鮮肉月餅', '2018-09-19', '剛烤好的鮮肉月餅，趁熱，拿著小碟兜著吃，一定要再配上一杯清茶，兩三塊下肚，香得連碟裡的渣也能給舔乾淨。', '1小時', ''),
(186411, '蓮蓉蛋黃月餅', '2018-09-19', '中秋---合家團圓的節日，對於一個愛烘焙的人來講，中秋還有著特殊的意義除了家人團聚，這也是表達心意的好時候，中秋節--月餅季，玩烘焙的朋友都在熱火朝天的做月餅，烘焙的樂趣就在於此，讓家人吃到安全健康的食物，與朋友一起分享手做月餅的快樂，走親訪友，家人團聚，品嚐自已親手做的月餅', '1小時', ''),
(186412, '桃山皮月餅', '2018-09-19', '咬一口猶如置身雲朵之間，今年月亮也會格外的圓', '1.5小時', ''),
