(186470, '薑蔥雞煲', '2018-09-17', '將料頭爆香再加入雞件炒香，十分惹味！', '1小時', ''),
(186471, '蟲草花雞腳螺片湯', '2018-09-17', '這道螺片湯清甜又健康，是入秋湯水之選。', '2小時', ''),
(186476, '溫泉蛋冷烏冬', '2018-09-14', '簡易做出溫泉蛋冷烏冬，夏日消暑必食～\r\n\r\nAmy\r\n不單喜歡帶給身邊人歡笑，她同時喜歡將簡易食譜分享給所有人，只因她深信「笑容」和「美食」都是世界上不同人士之間的共同語言。為了與更多人分享如何運用簡易方法煮出好味道，Amy早年開設YouTube頻道，希望透過頻道令大家勇敢踏入廚房，感受煮食的樂趣。\r\n\r\n►更多日日煮播食譜：goo.gl/SUZWEG', '40分鐘', ''),
(186478, '番茄士多啤梨特飲', '2018-09-15', 'by 營養師－Sofia Lei\r\n\r\n--------------------------------------------\r\n►更多\r\n育兒趣事心得小貼士：goo.gl/FfztfN', '10分鐘', ''),
(186481, '卡通冰皮月餅', '2018-09-18', 'Joanna\r\n由OL轉職到全職媽媽，Joanna最大的願望就是令家中兩個小朋友可以吃得健康快樂。在煮食過程中，她發現只要將創意注入食物當中就能增強小朋友的食慾。Joanna不但擅長製作不同卡通造型的小食甜點，亦喜歡創作新食譜，希望透過分享煮食經驗，讓更多父母樂意為小朋友煮食。\r\n\r\n►更多日日煮播食譜：goo.gl/SUZWEG', '1小時', ''),
(186494, '滑蛋牛肉粥', '2018-10-08', '加入醃過的鮮牛肉片，再拌入蛋花，美味又滿足。', '1.5小時', ''),
(186495, '瑤柱豬骨粥', '2018-10-08', '加入瑤柱和唐排煲出來的粥特別香甜。', '2小時', ''),
(186496, '南瓜百合瘦肉粥', '2018-10-08', '這個南瓜百合粥非常健康，味道清甜又健脾。', '2小時', ''),
(186497, '家鄉鹹湯丸', '2018-09-21', 'Gloria\r\n從小為家人入廚的Gloria，自小煮得一手好菜，聽到父親對她煮的菜式讚不絕口，使她更用心鑽研更多不同國家菜系的菜式，與親朋好友們一同分享美食。\r\n\r\n►更多日日煮播食譜：goo.gl/SUZWEG', '1小時', ''),
(186498, '無麵粉抹茶蛋糕', '2018-09-21', '簡單易做的無麵粉抺茶蛋糕，你也能做到！', '1小時', '2人'),
(186504, '綜合蔬菜泥', '2018-09-22', 'by 營養師－Sofia Lei\r\n\r\n--------------------------------------------\r\n►更多\r\n育兒趣事心得小貼士：goo.gl/FfztfN', '30分鐘', ''),
(186505, '扭紋腸仔包', '2018-09-25', 'Iris\r\n熱愛進行烘焙實驗，由從前不斷嘗試製作不同種類的曲奇，到現在醉心於麵包和蛋糕烘焙。她一直享受入廚樂，也樂於將心得分享給同樣熱愛烘焙的朋友。\r\n\r\n►更多日日煮播食譜：goo.gl/SUZWEG', '1小時', ''),
(186511, '速食學堂 - 焗薯 4 in 1', '2018-09-25', '', '烹飪時間', ''),
(186513, '自製白汁雜菌松露螺絲粉', '2018-09-28', '煮白汁其實好簡單，不需一分鐘時間，知道如果自製便不用再買罐頭忌廉湯做飯或意粉！\r\n\r\nStefanel\r\n曾居意大利超過十年，精通烹調傳統意大利菜，並透過烹飪班致力向學生推廣，多年來累積超過2000名學生，讓更多人了解意大利的飲食文化。\r\n\r\n►更多日日煮播食譜：goo.gl/SUZWEG', '40分鐘', '2人'),
(186516, '藍色富士山梳打', '2018-10-05', '藍藍的富士山梳打解掉一日的煩惱。', '20分鐘', '1人'),
(186523, '甜醋豆腐肉餅', '2018-10-01', '混入豆腐的肉餅軟滑而不膩，配搭酸甜開胃的甜醋汁，是一道非常適合做便當的菜式。', '1小時', '3人'),
(186524, '酸溜薯絲', '2018-10-01', '打開雪櫃發現只有薯仔？用常備的調味料就可以做出這道酸辣爽口的炒薯絲！', '1小時', '2人'),
(186526, '紅酒醋車厘茄烤法包', '2018-10-01', '用紅酒醋做沙律汁拌車厘茄，放上外脆內軟的法包，是聚餐的不二之選！', '30分鐘', '3人'),
(186546, '蔬菜米薄餅', '2018-10-06', 'by 營養師－Sofia Lei\r\n\r\n--------------------------------------------\r\n►更多\r\n育兒趣事心得小貼士：goo.gl/FfztfN', '30分鐘', ''),
(186553, '萬聖節眼球啫喱', '2018-10-19', '萬聖節快到了！想到怎樣嚇人嗎？試試整這個萬聖節眼球啫喱吧！', '30分鐘', '1人'),
(186554, '日日煮 x 一田 菠蘿子薑炒牛肉', '2018-10-24', '日日煮 x 一田「Home Gourmet餸菜盒」', '10分鐘', '2人'),
(186555, '日日煮 x 一田 柚子蜜煎三文魚', '2018-10-24', '日日煮 x 一田「Home Gourmet餸菜盒」系列', '10分鐘', '2人'),
(186556, '日日煮 x 一田 燒汁金菇豬肉卷', '2018-10-24', '幫你買菜調味火全都準備好，即開即煮！ \r\n為了令你能更輕鬆日日煮，我們跟一田超市誠意推出了餸菜包系列！專人準備食材，清洗處理，調味並醃好。一包二人份，即開即煮！一田超市(沙田，觀塘，旺角及北角店店) 限定發售', '10分鐘', ''),
(186557, '日日煮 x 一田 麻香醉雞翼', '2018-10-24', '日日煮 x 一田「Home Gourmet餸菜盒」系列', '10分鐘', ''),
(186569, '速食學堂 - 雞翼醃料4重奏', '2018-10-04', '', '烹飪時間', ''),
