(186575, '鮮百合木耳炒時蔬', '2018-12-15', 'by 註冊中醫師 錢穎儀\r\n\r\n--------------------------------------------\r\n►更多\r\n錢醫師的小貼士：goo.gl/9R6MkY\r\n育兒趣事心得小貼士：goo.gl/FfztfN', '40分鐘', ''),
(186576, '香煎蓮藕餅', '2018-10-27', 'by 註冊中醫師 錢穎儀\r\n\r\n--------------------------------------------\r\n►更多\r\n錢醫師的小貼士：goo.gl/9R6MkY\r\n育兒趣事心得小貼士：goo.gl/FfztfN', '40分鐘', ''),
(186584, '煎焗蓮藕夾', '2018-10-16', 'Gloria\r\n從小為家人入廚的Gloria，自小煮得一手好菜，聽到父親對她煮的菜式讚不絕口，使她更用心鑽研更多不同國家菜系的菜式，與親朋好友們一同分享美食。\r\n\r\n►更多日日煮播食譜：goo.gl/SUZWEG', '40分鐘', ''),
(186590, '極速藍莓鬆餅', '2018-10-19', 'Iris\r\n熱愛進行烘焙實驗，由從前不斷嘗試製作不同種類的曲奇，到現在醉心於麵包和蛋糕烘焙。她一直享受入廚樂，也樂於將心得分享給同樣熱愛烘焙的朋友。\r\n\r\n►更多日日煮播食譜：goo.gl/SUZWEG', '40分鐘', ''),
(186596, '無花果米紙卷', '2018-10-22', '米紙卷面層透出無花果的原貌，再沾上酸辣的魚露汁，十分開胃！', '30分鐘', '3人'),
(186597, '無花果煙肉芝士長通粉', '2018-10-22', '酸甜的無花果配上鹹香的煙肉和芝士，是味道和口感均具層次的菜式。', '40分鐘', '3人'),
(186598, '無花果香蕉乳酪特飲', '2018-10-22', '香蕉中和了無花果的酸味，混合香甜的蜜糖，是味道平衡的簡易特飲！', '10分鐘', '1人'),
(186610, '輕盈青醬虎蝦扁意粉', '2018-10-23', '青醬Pesto清新又惹味，但通常也要用很多油，但打出來的份量很少，這次加入翠玉瓜做一個輕盈版本，少油又足夠一家人份量！\r\n\r\nStefanel\r\n曾居意大利超過十年，精通烹調傳統意大利菜，並透過烹飪班致力向學生推廣，多年來累積超過2000名學生，讓更多人了解意大利的飲食文化。\r\n\r\n►更多日日煮播食譜：goo.gl/SUZWEG', '30分鐘', '2人'),
(186618, '南瓜乳酪忌廉卷蛋', '2018-11-03', 'by Charmaine So and Sarah', '2.5小時', ''),
(186628, '香辣蘑菇芝士素漢堡', '2018-10-28', 'Sarah\r\n很多人認為健康飲食會令到食物變得淡而無味，Sarah則希望打破這個傳統思維。受不同的健康煮食節目啟發，Sarah致力將「健康」揉合於「美食」當中，令食物在營養均衡的同時可以保持風味，在追求健康飲食的同時平衡味覺上的享受。\r\n\r\n►更多日日煮播食譜：goo.gl/SUZWEG', '1小時', ''),
(186633, '薯仔薄餅', '2018-10-30', '用平底鑊就整得到嘅PIZZA！金黃色嘅外圍超香脆可口～', '30分鐘', ''),
(186647, '紫蘇葉豚肉年糕串', '2018-11-05', '充滿肉汁的豚肉包裹著煙韌的年糕，加上紫蘇葉更香口。', '30分鐘', '3人'),
(186651, '日式揚出豆腐', '2018-11-05', '柴魚汁中和了揚出豆腐的油膩感，是配啤酒的宵夜之選。', '30分鐘', ''),
(186652, '明太子芝士烤法包', '2018-11-05', '做法簡易的明太子醬抹上法包，撒上芝士再烘焙，香氣滿溢。', '30分鐘', ''),
(186657, '數字雞翼配滋味薯角', '2018-11-06', 'Judy\r\n在職媽媽Judy從小喜愛入廚，她喜於運用不同食材研發各種食譜，除了中西菜式，多國融合菜也是她的拿手菜系之一。Judy曾在酒店當廚師學徒，並從中學習到很多有用的煮食技巧，運用在日常生活烹調當中，與家人朋友享用美食。\r\n\r\n►更多日日煮播食譜：goo.gl/SUZWEG', '大於3小時', ''),
(186669, '蘿蔔芹香煮魚', '2018-11-09', '►關於Gloria\r\n從小為家人入廚的Gloria，自小煮得一手好菜，聽到父親對她煮的菜式讚不絕口，使她更用心鑽研更多不同國家菜系的菜式，與親朋好友們一同分享美食\r\n\r\n►更多日日煮播食譜：https://bit.ly/2qGMlCm', '1小時', '2-4人'),
(186681, '蕃茄乾翠玉瓜玉棋', '2018-11-13', '►關於Stefanel\r\n曾居意大利超過十年，精通烹調傳統意大利菜，並透過烹飪班致力向學生推廣，多年來累積超過2000名學生，讓更多人了解意大利的飲食文化。\r\n►更多日日煮播食譜：https://bit.ly/2qGMlCm', '1.5小時', '2人'),
(186684, '日日煮 x 一田 芭堤雅雞扒（煎／焗皆可）', '2018-12-04', '幫你買埋餸準備好，即開即煮！\r\n為了令你能更輕鬆日日煮，我們跟一田超市誠意推出了餸菜包系列！專人準備食材，清洗處理，調味並醃好。一包二人份，即開即煮！一田超市(沙田及觀塘店) 限定發售', '10分鐘', ''),
(186692, '一次發酵吐司', '2018-11-16', 'Iris\r\n熱愛進行烘焙實驗，由從前不斷嘗試製作不同種類的曲奇，到現在醉心於麵包和蛋糕烘焙。她一直享受入廚樂，也樂於將心得分享給同樣熱愛烘焙的朋友。\r\n\r\n►更多日日煮播食譜：goo.gl/SUZWEG', '烹飪時間', '2人'),
(186697, '野餐三文治4口味', '2018-10-25', '', '10分鐘', ''),
(186699, '惹味拌麵4口味', '2018-10-29', '', '10分鐘', ''),
(186707, '免搓麵包', '2018-11-21', 'Amy\r\n不單喜歡帶給身邊人歡笑，她同時喜歡將簡易食譜分享給所有人，只因她深信「笑容」和「美食」都是世界上不同人士之間的共同語言。為了與更多人分享如何運用簡易方法煮出好味道，Amy早年開設YouTube頻道，希望透過頻道令大家勇敢踏入廚房，感受煮食的樂趣。', '大於3小時', '2人'),
(186713, '可愛卡通便當', '2018-11-23', 'Joanna\r\n由OL轉職到全職媽媽，Joanna最大的願望就是令家中兩個小朋友可以吃得健康快樂。在煮食過程中，她發現只要將創意注入食物當中就能增強小朋友的食慾。Joanna不但擅長製作不同卡通造型的小食甜點，亦喜歡創作新食譜，希望透過分享煮食經驗，讓更多父母樂意為小朋友煮食。\r\n\r\n►更多日日煮播食譜：goo.gl/SUZWEG', '2小時', ''),
(186732, '焗燈籠椒配吞拿魚醬', '2018-11-27', '我們常吃的燈籠椒以口感爽脆，但在意大利做法就喜歡用焗至軟滑，還散發著焦糖化的甜味，配上自製吞拿魚醬做一道前菜，這道傳統菜式，你一定要試！\r\n\r\n►關於Stefanel\r\n曾居意大利超過十年，精通烹調傳統意大利菜，並透過烹飪班致力向學生推廣，多年來累積超過2000名學生，讓更多人了解意大利的飲食文化。\r\n►更多日日煮播食譜：https://bit.ly/2qGMlCm', '40分鐘', ''),
(186744, '炸沙律蟹丸', '2018-12-03', '', '30分鐘', '2人'),
(186748, '明太子忌廉雞扒意粉', '2018-11-30', 'Cherry\r\n不論是中西菜式或甜點，Cherry 都熱愛鑽研。雖身為90後，卻笑稱自己是名「小師奶」，愛逛超市、買餸煮飯和洗碗。在當大廚的外公和一家之「煮」的父親薰陶下，令Cherry從小便埋下了對烹飪的情意結。Cherry開設了小煮婦的個人網站和YouTube頻道，分享不同的食譜，入廚心得和經驗。在兩位煮得之父的薰陶下，Cherry學習到如何從烹飪中找到快樂。明白到簡單的「親自下廚」，是可維繫到人與人之間的感情。\r\n\r\n►更多日日煮播食譜：goo.gl/SUZWEG', '1小時', ''),
(186757, '意式焗杏仁蛋白', '2018-12-04', '聖誕節及新年快到了！ 有沒有想過親手製造伴手禮去派對跟友人分享呢?這個食譜是意大利北部傳統的聖誕節甜品便最適合了！\r\n\r\n►關於Stefanel\r\n\r\n曾居意大利超過十年，精通烹調傳統意大利菜，並透過烹飪班致力向學生推廣，多年來累積超過2000名學生，讓更多人了解意大利的飲食文化。\r\n\r\n►更多日日煮播食譜: https://bit.ly/2qGMlCm', '1小時', ''),
(186767, '台式鹵肉飯', '2018-12-07', '►關於Gloria\r\n從小為家人入廚的Gloria，自小煮得一手好菜，聽到父親對她煮的菜式讚不絕口，使她更用心鑽研更多不同國家菜系的菜式，與親朋好友們一同分享美食\r\n\r\n►更多日日煮播食譜：https://bit.ly/2qGMlCm', '1.5小時', ''),
(186771, '聖誕鹿仔林明頓', '2018-12-08', '►Sarah\r\n很多人認為健康飲食會令到食物變得淡而無味，Sarah則希望打破這個傳統思維。受不同的健康煮食節目啟發，Sarah致力將「健康」揉合於「美食」當中，令食物在營養均衡的同時可以保持風味，在追求健康飲食的同時平衡味覺上的享受。\r\n\r\n►更多日日煮播食譜：goo.gl/SUZWEG', '1.5小時', ''),
(186792, '免焗焦糖布丁', '2018-12-14', '►Amy\r\n不單喜歡帶給身邊人歡笑，她同時喜歡將簡易食譜分享給所有人，只因她深信「笑容」和「美食」都是世界上不同人士之間的共同語言。為了與更多人分享如何運用簡易方法煮出好味道，Amy早年開設YouTube頻道，希望透過頻道令大家勇敢踏入廚房，感受煮食的樂趣。\r\n\r\n►更多日日煮播食譜：goo.gl/SUZWEG', '1小時', ''),
(186793, '番茄香草芝士濃湯', '2018-12-17', '由多個新鮮番茄和香草製作而成的濃湯，味道酸甜開胃，最適合作為晚餐的頭盤。', '1.5小時', '6人'),
(186799, '倫伯多杏仁酥', '2018-12-18', '意大利有種甜品叫做 Sbrisolona，它比曲奇更鬆脆，但比曲奇的製作方法簡單！\r\n\r\n►關於Stefanel\r\n曾居意大利超過十年，精通烹調傳統意大利菜，並透過烹飪班致力向學生推廣，多年來累積超過2000名學生，讓更多人了解意大利的飲食文化。\r\n\r\n►更多日日煮播食譜：https://bit.ly/2qGMlCm', '1小時', ''),
(186809, '朱古力半熟蛋糕', '2018-12-21', '►關於Iris\r\nIris熱愛進行烘焙實驗，由從前不斷嘗試製作不同種類的曲奇，到現在醉心於麵包和蛋糕烘焙。她一直享受入廚樂，也樂於將心得分享給同樣熱愛烘焙的朋友。\r\n\r\n►更多日日煮播食譜：https://bit.ly/2qGMlCm', '40分鐘', ''),
(186821, '三文魚海帶味噌湯', '2018-12-29', 'by 營養師－Sofia Lei\r\n\r\n--------------------------------------------\r\n►更多\r\n育兒趣事心得小貼士：goo.gl/FfztfN', '30分鐘', ''),
(186824, '黑糖豆乳布甸', '2019-01-04', '黑糖可以補血養氣，而豆乳又可以美顏，是個滋潤的低糖甜點！', '2.5小時', '3人'),
