(187059, '日日煮 x 一田 燒汁秋葵豬肉卷', '2019-06-03', '幫你買埋餸準備好，即開即煮！\r\n為了令你能更輕鬆日日煮，我們跟一田超市誠意推出了餸菜包系列！專人準備食材，清洗處理，調味並醃好。一包二人份，即開即煮！一田超市(沙田及觀塘店) 限定發售\r\n\r\n依加上網都有得賣啦！\r\n<十五分鐘懶人版｜燒汁秋葵豬肉卷>\r\n立即落單：燒汁秋葵豬肉卷', '10分鐘', ''),
