(187226, '醬香梅子蒸魚雲', '2019-07-31', '', '烹飪時間', ''),
(187244, '大蜆', '2019-08-02', '►關於Douglas\r\n愛吃愛煮的人夫。煮食是兩夫妻間的話題，萬事離不開食，將食融入生活每一部份，亦熱衷於動手炮製於將旅行時嚐到的美食。\r\n\r\n►更多日日煮播食譜：goo.gl/SUZWEG', '烹飪時間', ''),
(187252, '抹茶朱古力瑪德蓮', '2019-08-09', '抹茶朱古力的組合本身就好吸引...加上貝殼造型，有感受到心動的感覺嗎？～\r\n跟足步驟，法式小點心也能在家自己做！\r\n\r\nIris\r\n熱愛進行烘焙實驗，由從前不斷嘗試製作不同種類的曲奇，到現在醉心於麵包和蛋糕烘焙。她一直享受入廚樂，也樂於將心得分享給同樣熱愛烘焙的朋友。\r\n\r\n►更多日日煮播食譜：goo.gl/SUZWEG', '30分鐘', '2人'),
