(187272, '荷香蓮子雞肉飯', '2019-08-17', 'by 註冊中醫師 錢穎儀\r\n\r\n--------------------------------------------\r\n►更多\r\n錢醫師的小貼士：goo.gl/9R6MkY\r\n育兒趣事心得小貼士：goo.gl/FfztfN', '烹飪時間', ''),
