(187339, '薑汁豚肉燒', '2019-09-13', 'Judy\r\n在職媽媽Judy從小喜愛入廚，她喜於運用不同食材研發各種食譜，除了中西菜式，多國融合菜也是她的拿手菜系之一。Judy曾在酒店當廚師學徒，並從中學習到很多有用的煮食技巧，運用在日常生活烹調當中，與家人朋友享用美食。\r\n\r\n►更多日日煮播食譜：goo.gl/SUZWEG', '30分鐘', ''),
(187346, '海鹽牛油卷', '2019-09-20', 'Iris\r\n熱愛進行烘焙實驗，由從前不斷嘗試製作不同種類的曲奇，到現在醉心於麵包和蛋糕烘焙。她一直享受入廚樂，也樂於將心得分享給同樣熱愛烘焙的朋友。\r\n\r\n►更多日日煮播食譜：goo.gl/SUZWEG', '大於3小時', '8人'),
