(187351, '赤小豆冬瓜蓮藕排骨湯', '2019-09-21', 'by 營養師－Sofia Lei\r\n\r\n<十五分鐘懶人版｜粉葛赤小豆豬骨湯>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：粉葛赤小豆豬骨湯', '2小時', ''),
