(187383, '無油雙豉蒸排骨', '2019-10-21', '►關於Simon\r\n沉迷煮食的會計師。褪下專業身份，回到家中的他，只想醉心於研究一道道多國菜，用有限食材煮出國際美食，走一趟舌尖上的旅行。\r\n\r\n►更多日日煮播食譜：goo.gl/SUZWEG\r\n\r\n<十五分鐘懶人版｜蒜豉蒸排骨>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：蒜豉蒸排骨', '烹飪時間', ''),
