(187395, '西班牙海鮮飯', '2019-10-18', '關於Marquez\r\n煮食新力軍，曾修讀香港西廚學院課程，鍾愛西餐的精緻擺盤，務求睇得又食得，扼like亦得，得左！\r\n►更多日日煮播食譜：https://bit.ly/2qGMlCm', '烹飪時間', ''),
