(187426, '日日煮 x 一田 荷葉雲耳蒸雞', '2020-01-06', '幫你買埋餸準備好，即開即煮! \r\n為了令你能更輕鬆日日煮，我們跟一田超市誠意推出了餸菜包系列！專人準備食材，清洗處理，調味並醃好。一包二人份，即開即煮！一田超市(沙田，觀塘店，旺角及北角) 限定發售\r\n\r\n依加上網都有得賣啦！\r\n<十五分鐘懶人版｜荷葉雲耳蒸雞>\r\n立即落單：荷葉雲耳蒸雞', '10-20 分鐘', '2人'),
(187427, '日日煮 x 一田 酒香薑汁腐乳蒸雞', '2020-01-06', '幫你買埋餸準備好，即開即煮! \r\n為了令你能更輕鬆日日煮，我們跟一田超市誠意推出了餸菜包系列！專人準備食材，清洗處理，調味並醃好。一包二人份，即開即煮！一田超市(沙田，觀塘店，旺角及北角) 限定發售\r\n\r\n依加上網都有得賣啦！\r\n<十五分鐘懶人版｜酒香薑汁腐乳蒸雞>\r\n立即落單：酒香薑汁腐乳蒸雞', '10-20 分鐘', '2人'),
