(187998, '猴頭菇海底椰花生木瓜煲排骨', '2020-11-16', '這是一個海底椰滋陰潤肺, 猴頭菇則含豐富蛋白質，是個非常滋補的菜式。\r\n\r\n<十五分鐘懶人版｜蘋果海底椰蜜棗瘦肉湯>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：蘋果海底椰蜜棗瘦肉湯', '烹飪時間', ''),
