(188032, '栗子紅棗炆雞翼', '2021-02-08', '經典家常菜，老少咸宜！\r\n\r\n<十五分鐘懶人版｜栗子炆雞>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：栗子炆雞', '烹飪時間', ''),
(188037, '椒絲腐乳芥蘭炒鮮魷', '2021-03-01', '椒絲腐乳這不敗組合，加上芥蘭和鮮魷，讓晚餐變得更完美～\r\n\r\n<十五分鐘懶人版｜椒絲腐乳炒時菜>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：椒絲腐乳炒時菜', '烹飪時間', ''),
(188038, '麻油雞煲', '2021-03-01', '', '烹飪時間', ''),
(188047, '香脆蔥油素豬扒撈有機烏冬', '2021-07-05', '', '1小時', '2人'),
(188048, '葱爆牛肉', '2021-05-25', '家常必煮好菜，大蔥香味再配搭爆炒的牛肉，非常惹味。步驟亦非常簡單，是適合新手挑戰的菜色', '30分鐘', '2人'),
(188049, '酸辣土豆絲', '2021-05-25', '土豆通常用於燘，烘烤或用作烹調肉類的配菜。不妨嘗試把它作為主菜吧！炒土豆絲也可以煮成爽脆的口感，與烘烤時的口感不同！', '30分鐘', '2人'),
(188051, '超級港風沙嗲醬', '2021-06-17', '沙嗲醬充滿香濃嘅花生味，無論整燒肉串或者金菇肥牛煲都一樣咁惹味，好食到停唔到口！', '10-20 分鐘', ''),
(188052, '超級港風沙嗲牛麵', '2021-06-17', '惹味香濃嘅沙嗲牛肉麵，係茶餐廳必嗌菜式之一。其實在家亦可輕鬆做出，簡單又美味！', '烹飪時間', '1-2人'),
(188053, '蘑菇濃湯', '2021-08-06', '去食西餐時，蘑菇湯都係餐湯常客，但唔同餐廳唔同做法，有啲好濃但有啲好淡。自己煲就可以調較味道濃淡度，如果你都係濃湯愛好者，可以自己係屋企試吓煲依款蘑菇濃湯。', '1小時', '2人'),
(188054, '茄汁蝦', '2021-08-06', '茄汁蝦都算是常見家常菜，因為大人小朋友都愛吃酸酸甜甜的醬汁，非常開胃且惹味。煮法不太複雜，新手下廚都較易掌握。', '30分鐘', '2人'),
(188055, '沙爹炒牛肉', '2021-07-07', '晚餐唔一定要餸多，只需一個餸夠惹味就可以送晒成碗飯，沙嗲炒牛肉正正就係。濃香惹味，令人一嚐再嚐。', '1小時', '2人'),
(188056, '棗泥山藥糕', '2021-07-07', '曾出現在《紅樓夢》的棗泥山藥糕，其實是漢族傳統糕點小食。綿滑的棗泥好吃又可以補血行氣，你都快啲試吓整啦～', '30分鐘', '2人'),
(188057, '草莓大福', '2021-07-07', 'Q軟的大福外皮配上一整個新鮮酸甜的草莓令人垂涎三尺。這種豐富的口感和滋味當然不能錯過!', '30分鐘', '2-3人'),
(188058, '紫薯團子', '2021-07-08', '軟糯Q彈嘅紫薯糯米皮加上惹味鹹蛋黃，又睇得又食得！', '1小時', '2人'),
(188059, '簡易歐式奄列', '2021-07-07', '早餐唔知食乜好…？不如試吓整呢個質地嫩滑又有香濃蛋味嘅嘅歐式奄列啦！', '20分鐘', '1-2人'),
(188060, '薯仔章魚燒', '2021-07-07', '有冇人係薯仔控呢！香濃蛋黃醬加埋薯仔泥，唔覺唔覺就食哂啦~', '40分鐘', '2-3人'),
(188061, '香菇炒飯', '2021-07-07', '美味又健康嘅香菇炒飯，會顛覆你的味蕾，包你食完一碗又一碗！', '30分鐘', '2人'),
(188062, '宮保杏鮑菇', '2021-07-07', '杏鮑菇可以降血脂，幫助胃腸消化，口感彈牙，配上辣椒香氣，超好送飯！', '40分鐘', '4人'),
(188063, '酸湯金針菇肥牛', '2021-07-07', '', '40分鐘', '4人'),
(188064, '臨沂辣雞', '2021-07-07', '', '1.5小時', '4人'),
(188066, '微波薯仔牛腩', '2021-07-20', '想快快趣趣整個飽肚的幸福料理？試下用壓力鍋整薯仔牛腩啦！牛腩鮮嫩又不韌，加上軟綿綿的薯仔，口感一流！', '1小時', '3-4人'),
(188067, '麻醬火雞麵', '2021-07-20', '惹味的火雞麵加上香味濃郁的麻醬，包你一試上癮！', '20分鐘', '1人'),
(188068, '家常烤雞翼', '2021-07-20', '燒雞翼個個都鐘意食，皮脆肉嫩超juicy，幾時係屋企整都冇難度！', '1小時', '3人'),
(188069, '芝士忌廉焗番薯', '2021-07-20', '甜甜的番薯與牛油和忌廉完美融合，再配上香濃的芝士，極度邪惡！', '20分鐘', '2人'),
(188070, '百頁豆腐皮包子', '2021-07-20', '外型精緻，餡料鮮香的百頁豆腐皮包子是飯桌上最受歡迎的菜式之一。', '1.5小時', '2人'),
(188071, '牛油果益力多', '2021-07-20', '口感軟滑的牛油果加上酸甜益力多，輕輕鬆鬆便能製成美味可口又營養豐富的冰沙！', '20分鐘', '1人'),
(188072, '日式肉鬆飯糰', '2021-07-20', '美味又簡單的日式肉鬆飯團能當早餐也能放在便當盒內，快來試試吧！', '20分鐘', '1-2人'),
(188073, '上湯蝦米娃娃菜', '2021-07-23', '簡單的食材和煮法也能烹調出絕佳料理。上湯蝦米娃娃菜－懶人必學的一道家常菜。', '40分鐘', '2人'),
(188074, '家常炒粉絲', '2021-07-23', '超簡單家常炒粉絲，手殘也能輕鬆完成的零失敗料理！', '40分鐘', '2人'),
(188075, '高蛋白低熱量豆漿冷麵', '2021-07-23', '有沒有想過豆漿亦可製作成冷麵呢？豆漿冷麵是韓國傳統庶民美食之一，是一款清涼又美味的料理！', '30分鐘', '1-2人'),
(188076, '椒麻雞絲冷麵', '2021-07-28', '濃濃的花椒香，拌上一口雞絲涼麵，在家亦能做簡單美味的料理，滋味滿滿！', '30分鐘', '1-2人'),
(188077, '仲夏芒果高蛋白乳酪雪糕', '2021-07-27', '', '大於3小時', '2人'),
(188078, '芝士奶蓋烏龍茶', '2021-07-27', '香滑奶蓋咸中帶甜，令人一試上癮 ！平日愛飲台式手搖飲料的你，可以嘗試自家製，更健康無添加糖精、化學物質。', '1小時', '1人'),
(188079, '炸雪糕', '2021-07-26', '金黃酥脆的外皮配上軟滑雪糕，加上外熱內冰的口感，十分邪惡！', '1小時', '2人'),
(188080, '雪米糍多士', '2021-07-26', '', '30分鐘', '2人'),
(188081, '牛油果蟹肉雜糧沙拉球', '2021-07-26', '牛油果和黑米的營養價值都很高。兩種食材結合在一起，飽肚又健康。著重健康的你快來試試吧！', '1.5小時', '2人'),
(188082, '香菇肉粽', '2021-07-26', '呢款肉粽做法簡單又好味，自己包仲可以落足料，做出最啱自己口味的肉粽。', '2.5小時', '7-8人'),
(188083, '桂圓雞蛋糖水', '2021-07-26', '這款糖水不但經典、美味又養身，更有補氣活血、養顏、安神之效。', '30分鐘', '2人'),
(188084, '涼拌土豆絲', '2021-07-26', '爽脆香辣的涼拌土豆絲非常消暑開胃，原來只要簡單3個步驟就做好，容易做又好味，今天就試下做吧！', '30分鐘', '2人'),
(188085, '陳皮薏仁綠豆沙', '2021-07-26', '薏仁綠豆不但能清熱解毒又有健脾化濕之效，是消暑妙品。', '1.5小時', '2-3人'),
(188086, '香鍋黑魚', '2021-07-28', '嫩滑的黑魚片配上用辣椒和花椒熬成的麻辣湯汁會顛覆你的味蕾，熱愛麻辣的你不可以錯過！', '1.5小時', '3-4人'),
(188087, '岩燒芝士蜂蜜蛋糕', '2021-07-27', '超邪惡流漿芝士，淨看畫面已令口水直流，再配上蜂蜜味濃郁的蛋糕，當早餐或下午茶小點都會被秒殺喔！', '2小時', '2-3人'),
(188088, '一鍋到底燴飯', '2021-08-02', '雪櫃堆積太多食材唔知點煮？一於學整一鍋到底燴飯，一次過掃走雪櫃裏面擺得太耐嘅食材啦！', '1小時', '2人'),
(188089, '王子炒飯配番茄汁', '2021-08-04', '冷飯唔止得一個煮法！原來油炸鬼用來炒飯超惹味，配上酸甜番茄汁，不知不覺就將雪櫃裏面嘅冷飯清走哂！想要更多ideas？咁就請密切留意「雪櫃大掃除」系列啦！', '1小時', '2人'),
(188090, '剁椒蒸雞翼', '2021-08-04', '不知不覺買得太多急凍雞翼又唔想次次都係同一個煮法？不如學下呢道剁椒蒸雞翼啦！煮法簡單又好味！', '1.5小時', '2人'),
(188091, '味增雞胸肉飯', '2021-08-04', '雞胸肉除左白灼之外仲有其他健康食法！用味增來煮雞胸肉，健康好味又有新意。屋企雪櫃堆積太多雞胸肉嘅話，不妨試試！', '40分鐘', '2人'),
(188092, '酥脆香腸卷', '2021-08-04', '方包就嚟過期點算好？一道酥脆香腸卷幫到你燒滅一整袋方包！做法簡單又有創意，包你食到停唔到口！', '40分鐘', '2人'),
(188093, '照燒雞扒時蔬便當', '2021-08-04', '', '1.5小時', '2人'),
(188094, '豬肉燉粉條', '2021-08-04', '', '40分鐘', '2人'),
(188095, '鮮菇扒油菜', '2021-08-05', '', '40分鐘', '2人'),
(188096, '雜菜炒公仔麵', '2021-08-05', '', '30分鐘', '2人'),
(188097, '雜糧雞肉臘腸煲仔飯', '2021-08-05', '家中存放得太多雜穀不知如何處理？不如試試這款雜糧雞肉臘腸煲仔飯！嫩滑的雞肉和香味四溢的臘腸放在飯面上，讓米飯吸收了臘腸香和雞肉的鮮味，令人吃不停口！', '1.5小時', '2-3人'),
(188098, '番茄雞絲小麵糰', '2021-08-05', '前一晚吃剩的雞肉還可以這樣煮！小麵糰配上番茄雞絲湯底，滋味滿滿！', '40分鐘', '2人'),
(188099, '豬豬便當', '2021-08-05', '', '1小時', '1人'),
(188100, '川式豬耳花', '2021-08-25', '川式涼菜是不少人愛吃的前菜，甚至與酒相伴一起吃！一於備些在家隨時吃吧！', '2小時', ''),
(188101, '干鍋花菜', '2021-08-25', '菜不一定只能清炒，這款干鍋花菜深受愛吃味道重的朋友偏愛，帶一點微辣，吃來更爽！', '30分鐘', ''),
(188109, '蒜片燒汁牛柳粒', '2021-11-30', '<十五分鐘懶人版｜蒜片燒汁牛柳粒>\r\n唔駛買餸，日日煮免洗、免切、免醃餸菜包，直送上門\r\n立即落單：蒜片燒汁牛柳粒\r\n\r\n為了令你能更輕鬆日日煮，我們跟大昌食品專門店亦推出了餸菜包系列！專人準備食材，清洗處理，調味並醃好。一包二人份，即開即煮！五間大昌食品專門店：沙田第一城｜屯門卓爾居｜港島南海怡廣場｜牛頭角安基苑商場 ｜黃大仙中心', '10-20 分鐘', '1-2人'),
(188110, '燒汁秋葵豬肉卷 ', '2021-11-30', '為了令你能更輕鬆日日煮，我們跟大昌食品專門店誠意推出了餸菜包系列！專人準備食材，清洗處理，調味並醃好。一包二人份，即開即煮！五間大昌食品專門店：沙田第一城｜屯門卓爾居｜港島南海怡廣場｜牛頭角安基苑商場 ｜黃大仙中心\r\n\r\n依加上網都有得賣啦！\r\n<十五分鐘懶人版｜燒汁秋葵豬肉卷>\r\n立即落單：燒汁秋葵豬肉卷', '10-20 分鐘', '1-2人'),
(188111, '蒸節瓜脯', '2021-11-30', '為了令你能更輕鬆日日煮，我們跟大昌食品專門店誠意推出了餸菜包系列！專人準備食材，清洗處理，調味並醃好。一包二人份，即開即煮！五間大昌食品專門店：沙田第一城｜屯門卓爾居｜港島南海怡廣場｜牛頭角安基苑商場 ｜黃大仙中心\r\n\r\n依加上網都有得賣啦！\r\n<十五分鐘懶人版｜蒸節瓜脯 >\r\n立即落單：蒸節瓜脯', '10-20 分鐘', '1-2人'),
(188112, '蟲草花姬松茸蒸雞', '2021-11-30', '為了令你能更輕鬆日日煮，我們跟大昌食品專門店誠意推出了餸菜包系列！專人準備食材，清洗處理，調味並醃好。一包二人份，即開即煮！五間大昌食品專門店：沙田第一城｜屯門卓爾居｜港島南海怡廣場｜牛頭角安基苑商場 ｜黃大仙中心\r\n\r\n依加上網都有得賣啦！\r\n<十五分鐘懶人版｜蟲草花姬松茸蒸雞>\r\n立即落單：蟲草花姬松茸蒸雞', '10-20 分鐘', '1-2人'),
(188113, '螞蟻上樹 (好豬肉) *素菜', '2021-11-30', '為了令你能更輕鬆日日煮，我們跟大昌食品專門店誠意推出了餸菜包系列！專人準備食材，清洗處理，調味並醃好。一包二人份，即開即煮！五間大昌食品專門店：沙田第一城｜屯門卓爾居｜港島南海怡廣場｜牛頭角安基苑商場 ｜黃大仙中心\r\n\r\n依加上網都有得賣啦！\r\n<十五分鐘懶人版｜螞蟻上樹(植物豬肉)>\r\n立即落單：螞蟻上樹(植物豬肉)', '10-20 分鐘', '1-2人'),
(188114, '家鄉煎藕餅 (好豬肉) *素菜', '2021-11-30', '為了令你能更輕鬆日日煮，我們跟大昌食品專門店誠意推出了餸菜包系列！專人準備食材，清洗處理，調味並醃好。一包二人份，即開即煮！五間大昌食品專門店：沙田第一城｜屯門卓爾居｜港島南海怡廣場｜牛頭角安基苑商場 ｜黃大仙中心\r\n\r\n無時間買餸？可以試下我哋嘅免洗免切餸菜包，仲可以送埋上門，立即查看：家鄉煎藕餅懶人餸菜包\r\n\r\n依加上網都有得賣啦！\r\n<十五分鐘懶人版｜家鄕煎藕餅(植物豬肉)>\r\n立即落單：家鄕煎藕餅(植物豬肉)', '10-20 分鐘', '1-2人'),
(188120, 'XO醬粉絲蟹煲', '2021-12-13', '', '1小時', '2-4人'),
(188125, '濃蝦湯海鮮燴糯米飯', '2022-08-29', '', '1小時', '');

